registrarDetalhes({"SUS-001":{"cognitivo":{"motivo":"Fixar a conferência-marco da Reforma Sanitária.","palavraCritica":"8ª Conferência"},"comentario":{"resolucao":"ERRADO. O marco da Reforma Sanitária é a 8ª Conferência Nacional de Saúde, de 1986 — a primeira aberta à sociedade civil, cujo relatório firmou o conceito ampliado de saúde e as teses que a CF/88 encampou: saúde como direito de todos e dever do Estado, sistema único e participação da comunidade. A data está certa; o número da conferência, não.","fundamento":"Relatório Final da 8ª Conferência Nacional de Saúde (1986); CF/88, arts. 196 a 198.","macete":"8ª CNS, 1986 → CF, 1988 → Leis 8.080 e 8.142, 1990.","erroComum":"Lembrar o ano e não o número da conferência.","comoBancaPensa":"Mantém a data e troca o ordinal do evento."}},"SUS-002":{"cognitivo":{"motivo":"Contrastar o modelo contributivo anterior com a universalidade instituída em 1988.","palavraCritica":"contribuinte da previdência social"},"comentario":{"resolucao":"CERTO. O INAMPS era autarquia do Ministério da Previdência, e o atendimento seguia lógica de seguro: pagava-se pelo direito de ser atendido. Quem não tinha carteira assinada dependia de filantropia — as Santas Casas — ou do atendimento restrito do Ministério da Saúde, então voltado quase só a campanhas e endemias. É exatamente esse recorte que o art. 196 da CF derruba ao dizer 'direito de TODOS'. Entender isso explica por que universalidade é o primeiro princípio do SUS: ela nomeia o que existia antes.","fundamento":"Lei 6.439/1977 (SINPAS/INAMPS); CF/88, art. 196; Lei 8.080/1990, art. 7º, I.","macete":"Antes: seguro (quem contribui). Depois: seguridade (todos).","erroComum":"Supor que o atendimento público anterior a 1988 já era universal.","comoBancaPensa":"Item de contraste histórico: quem não sabe o 'antes' não entende por que universalidade é princípio."}},"SUS-003":{"cognitivo":{"motivo":"Cobrar que a Lei Orgânica da Saúde é um par de leis, não uma só.","palavraCritica":"exclusivamente"},"comentario":{"resolucao":"ERRADO. São duas leis, e a divisão entre elas tem razão de ser. A Lei 8.080/1990 saiu com vetos presidenciais justamente nos dispositivos sobre participação da comunidade e repasses financeiros; a Lei 8.142/1990 foi editada meses depois para repor esse conteúdo. Por isso o controle social — Conferências e Conselhos de Saúde — está na 8.142, não na 8.080. O item erra ao atribuir a participação da comunidade à 8.080.","fundamento":"Lei 8.080/1990; Lei 8.142/1990, art. 1º.","macete":"8.080 = organização e funcionamento. 8.142 = controle social e dinheiro.","erroComum":"Procurar Conselho e Conferência de Saúde na Lei 8.080.","comoBancaPensa":"Explora a origem histórica dos vetos, que separou o tema em duas leis."}},"SUS-004":{"cognitivo":{"motivo":"Distinguir o conceito ampliado do conceito biomédico restrito.","palavraCritica":"ausência de doenças"},"comentario":{"resolucao":"ERRADO. O item descreve o conceito biomédico restrito, que é justamente o que a Reforma Sanitária superou. O art. 3º da Lei 8.080 faz o contrário: elenca alimentação, moradia, saneamento básico, meio ambiente, trabalho, renda, educação, atividade física, transporte, lazer e acesso a bens e serviços essenciais como determinantes e condicionantes da saúde. E o parágrafo único acrescenta que também se destinam a garantir a saúde as ações que se voltem a assegurar as pessoas e à coletividade condições de bem-estar físico, mental e social. Saúde ali é produzida por condições de vida, não medida por ausência de sintoma.","fundamento":"Lei 8.080/1990, art. 3º e parágrafo único.","macete":"Se o item reduz saúde a 'não estar doente', é o conceito que o SUS abandonou.","erroComum":"Aceitar a definição por soar tecnicamente correta em contexto clínico.","comoBancaPensa":"Oferece o conceito intuitivo — e errado no marco legal — para punir leitura automática."}},"SUS-005":{"cognitivo":{"motivo":"Fixar o tripé da seguridade social (CF, art. 194).","palavraCritica":"assistência social"},"comentario":{"resolucao":"ERRADO. O art. 194 da CF fala em saúde, previdência e ASSISTÊNCIA SOCIAL. A educação é direito social, mas fica fora da seguridade. Lembre a lógica de acesso: só a previdência é contributiva; a saúde é universal; a assistência é para quem dela necessitar.","fundamento":"CF/88, art. 194, caput; arts. 196 e 203.","macete":"Tripé SAP: Saúde, Assistência, Previdência.","erroComum":"Incluir educação ou trabalho na seguridade social.","comoBancaPensa":"Reproduz o caput e troca a terceira perna do tripé."}},"SUS-006":{"cognitivo":{"motivo":"Cobrar o dispositivo mais transcrito da matéria, palavra por palavra.","palavraCritica":"universal e igualitário"},"comentario":{"resolucao":"CERTO. Transcrição fiel do art. 196 da CF. Duas palavras costumam ser adulteradas em item pseudo-literal: 'universal' vira 'universal para os hipossuficientes' e 'igualitário' vira 'equânime'. Repare também na tríade final — promoção, proteção e recuperação —, que a banca reduz a 'recuperação' para restringir o SUS ao tratamento e excluir a prevenção. Guarde as três: são elas que dão base constitucional à atuação preventiva do fisioterapeuta.","fundamento":"CF/88, art. 196.","macete":"Promoção, proteção e recuperação — as três, sempre.","erroComum":"Aceitar item que condiciona o acesso à carência econômica.","comoBancaPensa":"Artigo-âncora: cobra literal aqui para depois cobrar a alteração cirúrgica."}},"SUS-007":{"cognitivo":{"motivo":"Fixar as três diretrizes constitucionais, que a banca embaralha com os princípios da Lei 8.080.","palavraCritica":"prioridade para as atividades preventivas"},"comentario":{"resolucao":"CERTO. Transcrição do art. 198, caput e incisos I a III. Distinção que a banca explora: a CF traz TRÊS DIRETRIZES; a Lei 8.080, no art. 7º, traz quatorze PRINCÍPIOS. Universalidade e igualdade, por exemplo, são princípios legais, não diretrizes constitucionais — item que as chame de diretrizes do art. 198 está errado. Note ainda 'sem prejuízo dos serviços assistenciais': a prioridade à prevenção não autoriza desmontar a assistência, e suprimir essa ressalva é a alteração cirúrgica típica.","fundamento":"CF/88, art. 198, caput e incisos I a III.","macete":"CF = 3 diretrizes (DIP: Descentralização, Integral, Participação). Lei 8.080 = 14 princípios.","erroComum":"Listar universalidade entre as diretrizes constitucionais do art. 198.","comoBancaPensa":"Testa se o candidato separa o que é da Constituição do que é da lei ordinária."}},"SUS-008":{"cognitivo":{"motivo":"Cobrar a inversão exata do §2º do art. 199: a vedação alcança as COM fins lucrativos.","palavraCritica":"sem fins lucrativos"},"comentario":{"resolucao":"ERRADO. O §2º do art. 199 veda auxílios e subvenções às instituições privadas COM fins lucrativos — o item inverteu. As entidades sem fins lucrativos e filantrópicas estão no polo oposto: o §1º lhes dá PREFERÊNCIA na participação complementar ao SUS. Ou seja, o mesmo artigo que o item invoca para proibir é o que na verdade privilegia essas entidades. Atenção a um ponto que confunde: contratar serviço de entidade com fins lucrativos é permitido (é contrato, com contraprestação); o vedado é repassar auxílio ou subvenção, que é dinheiro sem contrapartida direta.","fundamento":"CF/88, art. 199, §§ 1º e 2º.","macete":"Sem fins lucrativos tem preferência; com fins lucrativos não recebe subvenção.","erroComum":"Ler 'privadas' e marcar CERTO sem conferir se é com ou sem fins lucrativos.","comoBancaPensa":"Troca uma única expressão do dispositivo e conta com a leitura apressada."}},"SUS-009":{"cognitivo":{"motivo":"Cobrar a ressalva final do §3º, suprimida pelo item.","palavraCritica":"em qualquer hipótese"},"comentario":{"resolucao":"ERRADO. O §3º do art. 199 veda a participação, mas encerra com 'salvo nos casos previstos em lei'. O item transformou uma vedação relativa em absoluta ao inserir 'em qualquer hipótese'. E a exceção é real, não teórica: a Lei 13.097/2015 autorizou expressamente a participação de capital estrangeiro em hospitais gerais e especializados, clínicas e ações de planejamento familiar, entre outras hipóteses. Regra constitucional com 'salvo em lei' é um convite a que a lei crie a exceção — e aqui ela criou.","fundamento":"CF/88, art. 199, § 3º; Lei 13.097/2015, art. 142.","macete":"Terminou em 'salvo nos casos previstos em lei'? Então não é absoluta.","erroComum":"Marcar CERTO por lembrar da vedação e esquecer a ressalva.","comoBancaPensa":"Suprime a ressalva e reforça com termo absoluto — o padrão mais frequente da banca."}},"SUS-010":{"cognitivo":{"motivo":"Cobrar que relevância pública não transforma a execução em monopólio estatal.","palavraCritica":"privativamente"},"comentario":{"resolucao":"ERRADO. O art. 197 separa dois planos, e o item confunde os dois. A regulamentação, a fiscalização e o controle são indelegáveis — esses sim competem sempre ao Poder Público. Já a EXECUÇÃO, diz o mesmo artigo, deve ser feita 'diretamente ou através de terceiros e, também, por pessoa física ou jurídica de direito privado'. A leitura do item ainda conflitaria com o caput do art. 199, segundo o qual a assistência à saúde é livre à iniciativa privada. Relevância pública significa sujeição a regime especial de fiscalização, não estatização do serviço.","fundamento":"CF/88, art. 197; art. 199, caput.","macete":"Regular e fiscalizar é só do Estado; executar pode ser de terceiro.","erroComum":"Deduzir de 'relevância pública' que a execução é monopólio estatal.","comoBancaPensa":"Aposta que o candidato associe relevância pública a exclusividade."}},"SUS-011":{"cognitivo":{"motivo":"Fixar as competências do art. 200 da CF.","palavraCritica":"saneamento básico"},"comentario":{"resolucao":"ERRADO. O inciso IV do art. 200 manda o SUS participar da formulação da política e da execução das ações de SANEAMENTO BÁSICO, não de habitação popular. A primeira parte — ordenar a formação de recursos humanos na saúde (inciso III) — está correta.","fundamento":"CF/88, art. 200, III e IV.","macete":"Art. 200: ordenar RH, participar do saneamento, fiscalizar alimentos, colaborar com o meio ambiente.","erroComum":"Aceitar política social vizinha no lugar do saneamento.","comoBancaPensa":"Mantém o verbo e troca o objeto da competência."}},"SUS-012":{"cognitivo":{"motivo":"Cobrar que a vedação à comercialização de órgãos é absoluta, sem válvula administrativa.","palavraCritica":"desde que autorizada"},"comentario":{"resolucao":"ERRADO. O §4º do art. 199 encerra com 'sendo vedado todo tipo de comercialização'. O item não só inverte a proibição em permissão, como inventa uma autorização administrativa que a Constituição não prevê — e nenhum órgão gestor poderia criá-la, porque a vedação é constitucional. Aqui o termo absoluto está do lado correto: é uma das hipóteses em que a regra é mesmo sem exceção, e marcar ERRADO por reflexo diante de 'todo tipo' levaria ao engano oposto.","fundamento":"CF/88, art. 199, § 4º; Lei 9.434/1997, art. 1º, parágrafo único.","macete":"Comercialização de órgãos: vedação absoluta, sem autorização que valha.","erroComum":"Aceitar a ressalva por soar razoável administrativamente.","comoBancaPensa":"Cria uma exceção plausível onde a norma não admite nenhuma."}},"SUS-013":{"cognitivo":{"motivo":"Fixar o caput do art. 2º, base do dever estatal na Lei Orgânica.","palavraCritica":"condições indispensáveis"},"comentario":{"resolucao":"CERTO. É o caput do art. 2º da Lei 8.080. O §2º completa com uma ressalva que a banca gosta de suprimir: o dever do Estado não exclui o das pessoas, da família, das empresas e da sociedade. Item que apresente a saúde como responsabilidade exclusivamente estatal contraria esse parágrafo — a lei distribui o dever, ainda que o Estado seja o garantidor principal.","fundamento":"Lei 8.080/1990, art. 2º, caput e §§ 1º e 2º.","macete":"Dever do Estado não é dever exclusivo do Estado (art. 2º, §2º).","erroComum":"Aceitar item que torna a responsabilidade pela saúde exclusiva do poder público.","comoBancaPensa":"Transcreve o caput e omite o parágrafo que relativiza a exclusividade."}},"SUS-014":{"cognitivo":{"motivo":"Cobrar o rol do art. 3º, incluindo a atividade física acrescentada em 2013.","palavraCritica":"atividade física"},"comentario":{"resolucao":"CERTO. É o rol do art. 3º da Lei 8.080. 'Atividade física' não constava da redação original — foi inserida pela Lei 12.864/2013, e por ser a mais recente é a que a banca costuma suprimir ou apontar como intrusa. O rol é exemplificativo, aberto por 'entre outros', então item que o apresente como taxativo estaria errado. Para o cargo de fisioterapeuta, é o dispositivo que ancora legalmente a atuação em promoção da saúde, não só em reabilitação.","fundamento":"Lei 8.080/1990, art. 3º, com redação da Lei 12.864/2013.","macete":"Atividade física entrou em 2013 — é a mais nova do rol e a mais cobrada.","erroComum":"Apontar 'atividade física' como item estranho ao artigo.","comoBancaPensa":"Alteração legislativa recente em rol conhecido: janela típica de cobrança."}},"SUS-015":{"cognitivo":{"motivo":"Cobrar a correspondência entre esfera de governo e órgão de direção.","palavraCritica":"Ministério da Saúde"},"comentario":{"resolucao":"ERRADO. O art. 9º atribui a direção estadual à respectiva Secretaria de Saúde ou órgão equivalente — o Ministério da Saúde dirige apenas o âmbito da UNIÃO. O item acerta o município e erra o estado. A lógica é a diretriz constitucional de direção única (CF, art. 198, I): cada ente dirige o SUS no seu território, e nenhum é subordinado ao outro. Guarde que 'direção única' não significa direção nacional centralizada — significa um só dirigente POR ESFERA.","fundamento":"Lei 8.080/1990, art. 9º, I a III; CF/88, art. 198, I.","macete":"União = Ministério; Estado/DF e Município = Secretaria.","erroComum":"Ler 'direção única' como comando nacional único.","comoBancaPensa":"Acerta metade do dispositivo para que a outra metade passe despercebida."}},"SUS-016":{"cognitivo":{"motivo":"Fixar a redação do inciso IV do art. 7º, frequentemente confundida com equidade.","palavraCritica":"igualdade"},"comentario":{"resolucao":"CERTO. É o inciso IV do art. 7º da Lei 8.080. Cuidado com a diferença entre o texto legal e a doutrina: a LEI escreve 'igualdade'; 'equidade' é construção doutrinária — tratar desigualmente os desiguais na medida de suas desigualdades — que não aparece com essa palavra no art. 7º. Se o item pedir o princípio 'previsto na Lei 8.080', a palavra é igualdade. Essa distinção entre o que está escrito e o que a doutrina elaborou é a armadilha mais comum da disciplina.","fundamento":"Lei 8.080/1990, art. 7º, IV.","macete":"Na letra da lei é IGUALDADE; equidade é doutrina.","erroComum":"Marcar ERRADO por esperar a palavra 'equidade'.","comoBancaPensa":"Explora a distância entre o vocabulário legal e o vocabulário de sala de aula."}},"SUS-017":{"cognitivo":{"motivo":"Fixar o caráter da participação privada no SUS.","palavraCritica":"complementar"},"comentario":{"resolucao":"CERTO. É o § 2º do art. 4º da Lei 8.080 e o § 1º do art. 199 da CF: caráter COMPLEMENTAR. Saúde 'suplementar' é outra coisa — o setor de planos e seguros, regulado pela ANS, fora do SUS.","fundamento":"Lei 8.080/1990, art. 4º, § 2º; CF/88, art. 199, § 1º.","macete":"Complementar = dentro do SUS. Suplementar = planos de saúde.","erroComum":"Trocar complementar por suplementar.","comoBancaPensa":"Item correto com o termo exato."}},"SUS-018":{"cognitivo":{"motivo":"Separar as definições legais de vigilância sanitária e epidemiológica.","palavraCritica":"mudança nos fatores determinantes e condicionantes"},"comentario":{"resolucao":"ERRADO. O texto transcrito é a definição de vigilância EPIDEMIOLÓGICA (§2º do art. 6º). A vigilância SANITÁRIA está no §1º e é outra coisa: conjunto de ações capaz de eliminar, diminuir ou prevenir riscos à saúde e de intervir nos problemas sanitários decorrentes do meio ambiente, da produção e circulação de bens e da prestação de serviços de interesse da saúde. O atalho: sanitária olha para PRODUTOS, SERVIÇOS e AMBIENTE — é o que fiscaliza a clínica de fisioterapia; epidemiológica olha para DOENÇAS e AGRAVOS na população.","fundamento":"Lei 8.080/1990, art. 6º, §§ 1º e 2º.","macete":"Sanitária = produto/serviço/ambiente. Epidemiológica = doença na população.","erroComum":"Aceitar a definição por ser verdadeira — só que de outro instituto.","comoBancaPensa":"Apresenta uma definição legal correta sob o rótulo errado: troca-conceito pura."}},"SUS-019":{"cognitivo":{"motivo":"Cobrar que a ênfase da descentralização é municipal, não estadual.","palavraCritica":"estados"},"comentario":{"resolucao":"ERRADO. O art. 7º, IX, 'a', diz expressamente: ênfase na descentralização dos serviços para os MUNICÍPIOS. É coerente com o art. 18, que atribui ao município a execução das ações e serviços de saúde no seu território, e com o desenho da atenção primária, que é porta de entrada e portanto municipal. Aos estados cabe sobretudo a coordenação regional e o apoio técnico e financeiro (art. 17). O item trocou o ente.","fundamento":"Lei 8.080/1990, art. 7º, IX, 'a'; arts. 17 e 18.","macete":"Municipalização: a ênfase da descentralização é sempre no município.","erroComum":"Supor que o estado executa a atenção primária por ser ente intermediário.","comoBancaPensa":"Troca o ente federativo num dispositivo cujo restante está correto."}},"SUS-020":{"cognitivo":{"motivo":"Cobrar o inciso XIV, acréscimo recente e diretamente ligado ao campo do cargo.","palavraCritica":"cirurgias plásticas reparadoras"},"comentario":{"resolucao":"CERTO. É o inciso XIV do art. 7º, incluído pela Lei 12.845/2013 no bojo da política de atendimento a vítimas de violência sexual. A menção a cirurgias plásticas reparadoras costuma soar deslocada num rol de princípios e por isso é marcada como ERRADO — mas está na letra da lei. Dispositivo de interesse direto para a especialidade de Fisioterapia em saúde da mulher deste edital, e por isso com chance real de cair.","fundamento":"Lei 8.080/1990, art. 7º, XIV, incluído pela Lei 12.845/2013.","macete":"O art. 7º tem 14 incisos, e o último é o do atendimento à mulher vítima de violência.","erroComum":"Estranhar o detalhamento e negar por parecer específico demais para um rol de princípios.","comoBancaPensa":"Escolhe o inciso menos memorizado do artigo mais cobrado da lei."}},"SUS-021":{"cognitivo":{"motivo":"Fixar as duas instâncias de controle social, base de todo o tópico.","palavraCritica":"Conferência ... Conselho"},"comentario":{"resolucao":"CERTO. É o art. 1º da Lei 8.142. São exatamente DUAS instâncias colegiadas, e a ressalva 'sem prejuízo das funções do Poder Legislativo' deixa claro que o controle social não substitui a fiscalização parlamentar — elas convivem. A banca costuma inventar uma terceira instância (Comissão Intergestores, Ouvidoria, Mesa de Negociação) para ver quem aceita. As Comissões Intergestores existem, mas são instâncias de PACTUAÇÃO entre gestores, criadas pelo Decreto 7.508, não de controle social.","fundamento":"Lei 8.142/1990, art. 1º, I e II.","macete":"Controle social = 2 instâncias: Conferência e Conselho.","erroComum":"Incluir a Comissão Intergestores Tripartite como instância de controle social.","comoBancaPensa":"Acrescenta um órgão real do SUS, mas de outra natureza, ao rol legal."}},"SUS-022":{"cognitivo":{"motivo":"Cobrar o prazo legal da Conferência, alvo preferencial de troca numérica.","palavraCritica":"dois anos"},"comentario":{"resolucao":"ERRADO. O §1º do art. 1º da Lei 8.142 fixa QUATRO anos, não dois. O resto do item é transcrição fiel, o que torna a alteração fácil de passar batido. Guarde os dois números do tópico, que a banca embaralha entre si: a Conferência é quadrienal; o Conselho de Saúde é permanente e, pela Resolução CNS 453/2012, reúne-se ordinariamente a cada mês. Vale lembrar ainda que a Conferência é convocada pelo Executivo ou, extraordinariamente, por ela mesma ou pelo Conselho de Saúde.","fundamento":"Lei 8.142/1990, art. 1º, § 1º.","macete":"Conferência: 4 em 4 anos. Conselho: permanente, reunião mensal.","erroComum":"Confundir com a periodicidade bienal de outros colegiados.","comoBancaPensa":"Transcreve o dispositivo inteiro e altera só o numeral — pseudo-literalidade."}},"SUS-023":{"cognitivo":{"motivo":"Cobrar a natureza deliberativa do Conselho, negada pelo item.","palavraCritica":"consultivo"},"comentario":{"resolucao":"ERRADO. O §2º do art. 1º da Lei 8.142 diz permanente e DELIBERATIVO — e acrescenta que o Conselho atua na formulação de estratégias e no controle da execução da política de saúde, INCLUSIVE NOS ASPECTOS ECONÔMICOS E FINANCEIROS. O item nega as duas coisas. A diferença é prática, não terminológica: órgão consultivo opina e o gestor decide; órgão deliberativo decide, e suas decisões são homologadas pelo chefe do Poder da esfera correspondente. Homologar não é escolher — é dar eficácia formal à decisão já tomada.","fundamento":"Lei 8.142/1990, art. 1º, § 2º.","macete":"Conselho DELIBERA, inclusive sobre dinheiro. O chefe do Executivo apenas homologa.","erroComum":"Tratar o Conselho como órgão de assessoramento do secretário de saúde.","comoBancaPensa":"Rebaixa a natureza do órgão — a troca de conceito mais cobrada do controle social."}},"SUS-024":{"cognitivo":{"motivo":"Fixar a paridade legal, que é de usuários contra TODOS os outros somados.","palavraCritica":"conjunto dos demais segmentos"},"comentario":{"resolucao":"CERTO. É o §4º do art. 1º da Lei 8.142. A expressão decisiva é 'em relação ao CONJUNTO dos demais segmentos': a paridade não é entre os quatro segmentos entre si, e sim entre os usuários de um lado e todos os outros somados do outro. Na prática isso significa 50% de usuários — como detalha a Resolução CNS 453/2012, que reparte os outros 50% em 25% de trabalhadores da saúde e 25% de governo e prestadores de serviço. Quem lê 'paritária' como 'divisão igual em quatro' erra a conta.","fundamento":"Lei 8.142/1990, art. 1º, § 4º; Resolução CNS 453/2012, Quarta Diretriz.","macete":"50% usuários · 25% trabalhadores · 25% governo e prestadores.","erroComum":"Interpretar paridade como 25% para cada um dos quatro segmentos.","comoBancaPensa":"Aposta na leitura intuitiva de 'paritária' como divisão igualitária entre todos."}},"SUS-025":{"cognitivo":{"motivo":"Cobrar os requisitos do art. 4º, que condicionam o repasse à existência de controle social.","palavraCritica":"conselho de saúde"},"comentario":{"resolucao":"CERTO. É o art. 4º da Lei 8.142, que lista cinco requisitos: fundo de saúde; conselho de saúde; plano de saúde; relatórios de gestão; contrapartida de recursos no orçamento; e comissão de elaboração do plano de carreira, cargos e salários. O desenho é deliberado — sem conselho instalado, não entra dinheiro federal —, o que transformou o controle social em condição de financiamento e não em recomendação. O parágrafo único prevê que o descumprimento leva os recursos a serem administrados pelos estados ou pela União.","fundamento":"Lei 8.142/1990, art. 4º e parágrafo único.","macete":"Sem conselho e sem fundo de saúde, não há repasse federal.","erroComum":"Supor que o repasse depende apenas de critérios populacionais e epidemiológicos.","comoBancaPensa":"Cobra a amarração entre controle social e financiamento, que muitos estudam separado."}},"SUS-026":{"cognitivo":{"motivo":"Cobrar que o usuário é o segmento majoritário, não excluído.","palavraCritica":"vedada a participação de usuários"},"comentario":{"resolucao":"ERRADO. O §2º do art. 1º da Lei 8.142 inclui os USUÁRIOS entre os quatro segmentos do Conselho — e o §4º ainda garante a eles representação paritária ao conjunto dos demais, ou seja, 50% das vagas. O item não apenas exclui quem a lei inclui: exclui justamente o segmento majoritário, e o faz invocando um pretexto — a tecnicidade das deliberações — que inverte a razão de ser do controle social. Participação da comunidade é diretriz constitucional (CF, art. 198, III), não concessão administrativa.","fundamento":"Lei 8.142/1990, art. 1º, §§ 2º e 4º; CF/88, art. 198, III.","macete":"Os quatro segmentos: governo, prestadores, trabalhadores e USUÁRIOS.","erroComum":"Aceitar a exclusão por parecer justificada tecnicamente.","comoBancaPensa":"Oferece um motivo plausível para uma restrição que a lei não faz."}},"SUS-027":{"cognitivo":{"motivo":"Fixar a composição dos conselhos de saúde.","palavraCritica":"50% usuários"},"comentario":{"resolucao":"ERRADO. Usuários e trabalhadores estão trocados. Pela Quarta Diretriz da Resolução CNS 453/2012, são 50% de USUÁRIOS, 25% de TRABALHADORES da saúde e 25% de governo e prestadores, juntos. A metade dos usuários é o que dá a paridade prevista no § 4º do art. 1º da Lei 8.142/1990.","fundamento":"Resolução CNS 453/2012, Quarta Diretriz; Lei 8.142/1990, art. 1º, § 4º.","macete":"50 usuários / 25 trabalhadores / 25 governo + prestadores.","erroComum":"Lembrar os percentuais e trocar os segmentos.","comoBancaPensa":"Mantém os números e permuta quem fica com a metade."}},"SUS-028":{"cognitivo":{"motivo":"Cobrar a mudança introduzida em 2012: presidência eletiva, não nata.","palavraCritica":"membro nato"},"comentario":{"resolucao":"ERRADO. A Resolução 453/2012 determina que o Conselho de Saúde ELEJA seu presidente entre os conselheiros, em reunião plenária. A regra existe para dar sentido ao controle social: se o gestor fiscalizado presidisse o órgão que o fiscaliza, o Conselho perderia a independência. É justamente o modelo anterior, ainda presente na memória de muitos municípios, que a resolução veio afastar — e por isso a banca cobra a versão antiga como pegadinha. Nada impede que o secretário seja conselheiro; o que não existe é presidência automática.","fundamento":"Resolução CNS 453/2012, Quinta Diretriz.","macete":"Presidente do Conselho é ELEITO pelos pares, não é o secretário por inércia.","erroComum":"Reproduzir a prática anterior a 2012, ainda comum na realidade de muitos conselhos.","comoBancaPensa":"Oferece a regra revogada, que continua parecendo natural para quem conhece a prática."}},"SUS-029":{"cognitivo":{"motivo":"Fixar a vinculação administrativa dos conselhos de saúde.","palavraCritica":"Ministério da Saúde"},"comentario":{"resolucao":"ERRADO. Pela Primeira Diretriz da Resolução 453/2012, o Conselho de Saúde integra a estrutura organizacional do MINISTÉRIO DA SAÚDE e das secretarias de saúde dos estados, do DF e dos municípios — não a do Conselho Nacional de Saúde, que é ele próprio um desses conselhos, no âmbito federal. O restante (colegiado, deliberativo, permanente, em cada esfera) está correto. Integrar a estrutura do gestor não significa subordinar-se a ele quanto ao mérito das deliberações.","fundamento":"Resolução CNS 453/2012, Primeira e Terceira Diretrizes.","macete":"Conselho fica na estrutura do gestor (Ministério/Secretaria), mas não obedece ao gestor.","erroComum":"Aceitar 'Conselho Nacional' porque soa como a instância superior.","comoBancaPensa":"Reproduz a diretriz e troca o órgão de vinculação."}},"SUS-030":{"cognitivo":{"motivo":"Distinguir homologação de aprovação de mérito.","palavraCritica":"rejeitá-las discricionariamente"},"comentario":{"resolucao":"ERRADO. A Lei 8.142 fala em decisões HOMOLOGADAS pelo chefe do poder legalmente constituído, e homologar é ato de conferência formal — verifica-se legalidade e regularidade, não conveniência. Reconhecer poder de rejeição por discordância de mérito esvaziaria o caráter deliberativo do §2º do art. 1º e reduziria o Conselho a órgão consultivo, que é exatamente o que a lei afastou. A Resolução 453/2012 reforça isso ao prever prazo para homologação e a atuação do Ministério Público diante da omissão do gestor.","fundamento":"Lei 8.142/1990, art. 1º, § 2º; Resolução CNS 453/2012, Quinta Diretriz.","macete":"Homologar é conferir a forma, não escolher se concorda.","erroComum":"Ler homologação como aprovação discricionária do gestor.","comoBancaPensa":"Explora um termo técnico do direito administrativo dentro do tema de controle social."}},"SUS-031":{"cognitivo":{"motivo":"Fixar a definição de Região de Saúde, unidade básica de organização do Decreto 7.508.","palavraCritica":"limítrofes"},"comentario":{"resolucao":"CERTO. É o art. 2º, I, do Decreto 7.508/2011. Duas exigências cumulativas costumam ser suprimidas em item adulterado: a contiguidade geográfica ('espaço contínuo', 'municípios limítrofes') e a identidade socioeconômica e cultural. Não basta juntar municípios por conveniência administrativa. Quem institui as Regiões de Saúde é o ESTADO, em articulação com os municípios e pactuação na CIB — item que atribua essa instituição à União está errado.","fundamento":"Decreto 7.508/2011, art. 2º, I, e art. 4º.","macete":"Região de Saúde: contígua, com identidade comum, instituída pelo Estado.","erroComum":"Admitir região formada por municípios não limítrofes.","comoBancaPensa":"Definição longa: suprime um dos requisitos e conta com a leitura por reconhecimento."}},"SUS-032":{"cognitivo":{"motivo":"Fixar o rol mínimo do art. 5º do Decreto 7.508/2011.","palavraCritica":"atenção psicossocial"},"comentario":{"resolucao":"ERRADO. O rol mínimo do art. 5º do Decreto 7.508/2011 tem cinco itens: atenção primária, urgência e emergência, ATENÇÃO PSICOSSOCIAL, atenção ambulatorial especializada e hospitalar, e vigilância em saúde. A assistência farmacêutica não está no rol; ela entrou no lugar da atenção psicossocial, a mais esquecida da lista.","fundamento":"Decreto 7.508/2011, art. 5º, I a V.","macete":"Cinco mínimos: primária, urgência, psicossocial, especializada/hospitalar, vigilância.","erroComum":"Aceitar serviço plausível no lugar da atenção psicossocial.","comoBancaPensa":"Lista fechada com um item trocado por outro do mesmo campo."}},"SUS-033":{"cognitivo":{"motivo":"Cobrar que a atenção especializada NÃO é porta de entrada — é acesso referenciado.","palavraCritica":"atenção ambulatorial especializada"},"comentario":{"resolucao":"ERRADO. O art. 9º do Decreto 7.508 lista QUATRO portas de entrada: atenção primária, urgência e emergência, atenção psicossocial e serviços especiais de acesso aberto. A atenção ambulatorial especializada e a hospitalar não são porta — o acesso a elas é REFERENCIADO, ou seja, depende de encaminhamento a partir das portas (art. 10). A distinção é o coração do modelo: a atenção primária é ordenadora do cuidado, e permitir entrada direta no especializado desmontaria essa ordenação. Para o fisioterapeuta, é o que explica o fluxo até a reabilitação especializada.","fundamento":"Decreto 7.508/2011, arts. 9º e 10.","macete":"Quatro portas. Especializado e hospital entram por referência, não por porta.","erroComum":"Incluir o ambulatório especializado entre as portas por ser ambulatorial.","comoBancaPensa":"Acrescenta ao rol um serviço real do SUS que ocupa posição diferente no fluxo."}},"SUS-034":{"cognitivo":{"motivo":"Separar duas siglas do mesmo decreto que a banca inverte sistematicamente.","palavraCritica":"medicamentos"},"comentario":{"resolucao":"ERRADO. As definições estão trocadas. RENASES é de AÇÕES E SERVIÇOS (art. 21); RENAME é de MEDICAMENTOS (art. 25). A própria sigla resolve: o 'ASES' de RENASES vem de Ações e Serviços; o 'ME' de RENAME, de Medicamentos Essenciais. Guarde também que a União dispõe sobre a RENASES a cada dois anos e que estados, DF e municípios podem adotar relações complementares, desde que financiadas com recursos próprios — nunca relações mais restritivas que a nacional.","fundamento":"Decreto 7.508/2011, arts. 21 a 26.","macete":"RENASES = Ações e SErviços. RENAME = MEdicamentos.","erroComum":"Trocar as siglas por serem graficamente parecidas.","comoBancaPensa":"Duas siglas quase idênticas do mesmo decreto: inversão de definições clássica."}},"SUS-035":{"cognitivo":{"motivo":"Cobrar os requisitos cumulativos do art. 28, que condicionam a dispensação.","palavraCritica":"no exercício regular de suas funções no SUS"},"comentario":{"resolucao":"CERTO. São incisos do art. 28 do Decreto 7.508, que exige quatro condições cumulativas: estar o usuário assistido por ações e serviços do SUS; prescrição por profissional em exercício regular no SUS; conformidade com a RENAME e os protocolos; e dispensação em unidade indicada pela direção do SUS. O requisito da prescrição feita dentro do SUS é o mais cobrado, porque contraria a intuição de que qualquer receita serviria. Note que 'universal e igualitário' convive com requisitos — eles organizam o acesso, não o restringem por condição pessoal do usuário.","fundamento":"Decreto 7.508/2011, art. 28, I a IV.","macete":"Receita de fora do SUS não gera direito à dispensação pela via administrativa.","erroComum":"Achar que exigir prescrição do SUS violaria a universalidade.","comoBancaPensa":"Testa se o candidato aceita requisitos formais sem confundi-los com restrição de direito."}},"SUS-036":{"cognitivo":{"motivo":"Fixar a estrutura em camadas do modelo mais cobrado de determinantes sociais.","palavraCritica":"camadas"},"comentario":{"resolucao":"CERTO. O modelo organiza os determinantes em cinco camadas concêntricas: no núcleo, os fatores individuais não modificáveis (idade, sexo, herança genética); depois estilos de vida; redes sociais e comunitárias; condições de vida e trabalho (habitação, emprego, educação, saneamento, serviços de saúde); e, na camada externa, as condições socioeconômicas, culturais e ambientais gerais. A lógica é de proximidade: quanto mais externa a camada, mais estrutural o determinante e menos ele depende de escolha individual — que é justamente o argumento contra reduzir promoção da saúde a mudança de comportamento.","fundamento":"Dahlgren e Whitehead (1991); Comissão Nacional sobre Determinantes Sociais da Saúde (CNDSS, 2008).","macete":"Do centro (indivíduo) para fora (estrutura social) — cinco camadas.","erroComum":"Inverter a ordem, colocando o macro no núcleo.","comoBancaPensa":"Modelo gráfico consagrado: cobra a ordem das camadas em vez do conteúdo de cada uma."}},"SUS-037":{"cognitivo":{"motivo":"Separar desigualdade (diferença) de iniquidade (diferença evitável e injusta).","palavraCritica":"quaisquer diferenças"},"comentario":{"resolucao":"ERRADO. O item define DESIGUALDADE, não iniquidade. A distinção é conceitual e tem consequência prática: nem toda diferença é iniquidade — mulheres vivem mais que homens em quase todo o mundo por fatores biológicos, e isso é desigualdade sem injustiça. Iniquidade é o subconjunto das desigualdades que são EVITÁVEIS, DESNECESSÁRIAS e INJUSTAS, porque decorrem da posição social do grupo. É por isso que a política pública mira as iniquidades: são as diferenças sobre as quais a ação social pode e deve incidir.","fundamento":"Whitehead (1992); Relatório Final da CNDSS (2008); CSDH/OMS (2008).","macete":"Desigualdade é qualquer diferença; iniquidade é a diferença injusta e evitável.","erroComum":"Tratar os dois termos como sinônimos.","comoBancaPensa":"Amplia o conceito com 'quaisquer' e 'independentemente' para apagar a nota distintiva."}},"SUS-038":{"cognitivo":{"motivo":"Cobrar a correspondência entre sistema e documento-base.","palavraCritica":"Declaração de Nascido Vivo"},"comentario":{"resolucao":"ERRADO. Os documentos estão invertidos: o SIM se alimenta da Declaração de Óbito (DO) e o SINASC, da Declaração de Nascido Vivo (DN). O próprio nome resolve — Mortalidade combina com óbito; Nascidos Vivos, com nascimento. Juntos, esses dois sistemas sustentam os indicadores mais usados na avaliação de serviços de saúde da mulher e da criança, como a mortalidade materna e a mortalidade infantil, que exigem exatamente o cruzamento entre óbitos e nascidos vivos.","fundamento":"Portaria GM/MS nº 116/2009 (SIM e SINASC); DATASUS.","macete":"SIM ← Declaração de Óbito. SINASC ← Declaração de Nascido Vivo.","erroComum":"Trocar os documentos por decorar as siglas sem associá-las ao evento.","comoBancaPensa":"Inverte dois pares óbvios contando com a memorização mecânica das siglas."}},"SUS-039":{"cognitivo":{"motivo":"Cobrar que a notificação compulsória não se limita a doenças transmissíveis.","palavraCritica":"violência doméstica, sexual"},"comentario":{"resolucao":"CERTO. A violência doméstica, sexual e outras violências integram a Lista Nacional de Notificação Compulsória, e a notificação é UNIVERSAL — obrigatória para todos os serviços de saúde, públicos e privados, independentemente de confirmação e sem depender de autorização da vítima. É um dos pontos em que a banca erra o candidato: notificar não é denunciar à polícia, é alimentar a vigilância epidemiológica, e a obrigação recai sobre o profissional de saúde que atende. Diretamente aplicável ao atendimento em saúde da mulher.","fundamento":"Portaria GM/MS nº 1.271/2014 e atualizações (Lista Nacional de Notificação Compulsória); Lei 10.778/2003.","macete":"SINAN não é só doença: violência também é agravo de notificação compulsória.","erroComum":"Restringir a notificação compulsória a doenças infecciosas.","comoBancaPensa":"Cobra o alcance do conceito de 'agravo', que muitos leem como sinônimo de doença."}},"SUS-040":{"cognitivo":{"motivo":"Separar cadastro de estrutura (CNES) de registro de produção (SIA e SIH).","palavraCritica":"produção"},"comentario":{"resolucao":"ERRADO. O CNES cadastra ESTRUTURA — estabelecimentos, profissionais, equipamentos, leitos e serviços habilitados. Quem registra PRODUÇÃO são outros dois: o SIH/SUS, alimentado pelas Autorizações de Internação Hospitalar (AIH), e o SIA/SUS, pelos boletins de produção ambulatorial. A distinção é a que separa 'o que existe' de 'o que foi feito', e ela tem efeito prático: sem o profissional cadastrado no CNES do estabelecimento, a produção que ele realizar não é faturável no SIA.","fundamento":"Portaria SAS/MS nº 376/2000 e atualizações (CNES); sistemas SIA/SUS e SIH/SUS — DATASUS.","macete":"CNES = o que existe (estrutura). SIA e SIH = o que foi feito (produção).","erroComum":"Tratar o CNES como sistema de faturamento.","comoBancaPensa":"Atribui a um sistema a função de outro dentro da mesma família de sistemas."}},"SUS-041":{"cognitivo":{"motivo":"Fixar o marco inicial da previdência e a lógica das CAPs, base de toda a linha do tempo.","palavraCritica":"organizadas por empresa"},"comentario":{"resolucao":"CERTO. As CAPs eram organizadas por EMPRESA — cada uma tinha a sua —, com custeio tripartite na origem e forte peso de empregados e empregadores. Só depois, nos anos 1930, vieram os IAPs, organizados por CATEGORIA PROFISSIONAL, o que ampliou a cobertura e centralizou a gestão no Estado.","fundamento":"Decreto Legislativo nº 4.682/1923 (Lei Eloy Chaves).","macete":"CAPs = por empresa (Caixa da empresa). IAPs = por categoria (Instituto dos bancários, marítimos...).","erroComum":"Trocar a base de organização das CAPs pela dos IAPs.","comoBancaPensa":"Item correto que serve de âncora para a troca CAP/IAP em outro item da prova."}},"SUS-042":{"cognitivo":{"motivo":"Cobrar a mesma distinção com os critérios permutados.","palavraCritica":"IAPs ... organizados por empresa"},"comentario":{"resolucao":"ERRADO. Está invertido. As CAPs eram por EMPRESA; os IAPs, por CATEGORIA PROFISSIONAL (IAPB dos bancários, IAPM dos marítimos, IAPI dos industriários). A mudança não foi só de forma: ao agrupar por categoria, o Estado assumiu papel central na gestão previdenciária.","fundamento":"Decreto Legislativo nº 4.682/1923 e legislação dos IAPs (décadas de 1930-1940).","macete":"A ordem histórica é CAP → IAP, e a lógica vai de empresa para categoria.","erroComum":"Decorar os dois nomes sem fixar o critério de agrupamento de cada um.","comoBancaPensa":"Permuta dois conceitos vizinhos cuja descrição isolada o candidato reconhece."}},"SUS-043":{"cognitivo":{"motivo":"Cobrar o caráter contributivo e excludente do modelo pré-SUS, que a universalidade viria a romper.","palavraCritica":"excluía do atendimento regular a população sem vínculo formal"},"comentario":{"resolucao":"CERTO. Esse é o ponto central para entender o que o SUS mudou. No modelo previdenciário, saúde era benefício de segurado: quem não contribuía dependia de filantropia, das santas casas ou de ações pontuais do Ministério da Saúde. Em 1977 o INAMPS separou a assistência médica dentro do sistema previdenciário, mas manteve a lógica contributiva. A universalidade só chega com a CF/88.","fundamento":"Decreto-Lei nº 72/1966 (INPS) e Lei nº 6.439/1977 (SINPAS/INAMPS).","macete":"Antes do SUS: saúde para quem tinha carteira assinada. Depois: saúde para todos.","erroComum":"Supor que sempre houve atendimento universal na rede pública.","comoBancaPensa":"Item correto que cobra a compreensão do modelo, não a data."}},"SUS-044":{"cognitivo":{"motivo":"Cobrar as entidades que estruturaram o movimento, citadas com frequência.","palavraCritica":"CEBES ... ABRASCO"},"comentario":{"resolucao":"CERTO. O CEBES, fundado em 1976, e a ABRASCO, em 1979, foram as bases institucionais do movimento — que reunia acadêmicos, profissionais de saúde, sindicatos e movimentos populares em torno da saúde como direito e dever do Estado. A Reforma Sanitária é o antecedente político direto do SUS.","fundamento":"História da saúde pública brasileira — movimento da Reforma Sanitária.","macete":"CEBES (1976) e ABRASCO (1979): a base intelectual do SUS.","erroComum":"Confundir as siglas com órgãos oficiais de governo.","comoBancaPensa":"Item 'limpo' de memória histórica."}},"SUS-045":{"cognitivo":{"motivo":"Contraexemplo: número de conferência e ano corretos, no formato em que a banca costuma trocá-los.","palavraCritica":"8ª ... 1986"},"comentario":{"resolucao":"CERTO. A 8ª CNS (março de 1986) é o marco: aprovou o conceito ampliado de saúde, a saúde como direito de cidadania e dever do Estado, e propôs a criação de um sistema único, separado da previdência. Seu relatório orientou a Subcomissão de Saúde da Constituinte. Números e anos aqui são cobrados com frequência — e estão corretos no item.","fundamento":"Relatório final da 8ª Conferência Nacional de Saúde (1986).","macete":"8ª CNS = 1986 = a Conferência que desenhou o SUS.","erroComum":"Marcar ERRADO por desconfiar de qualquer data em enunciado.","comoBancaPensa":"Cobra o número exato num item verdadeiro, punindo quem chuta contra datas."}},"SUS-046":{"cognitivo":{"motivo":"Cobrar o conteúdo do conceito ampliado, que é o oposto da definição negativa.","palavraCritica":"ausência de doenças"},"comentario":{"resolucao":"ERRADO. O conceito ampliado rompe justamente com a definição de saúde como mera ausência de doença: saúde resulta de condições de alimentação, habitação, educação, renda, meio ambiente, trabalho, transporte, emprego, lazer, liberdade, acesso à terra e aos serviços de saúde. É definição social e positiva, depois vertida no art. 3º da Lei 8.080/1990.","fundamento":"Relatório final da 8ª CNS (1986); Lei nº 8.080/1990, art. 3º.","macete":"Saúde não é 'não estar doente': é resultado de condições de vida.","erroComum":"Reproduzir a definição negativa, de senso comum.","comoBancaPensa":"Oferece a definição intuitiva, que é exatamente a que o conceito ampliado superou."}},"SUS-047":{"cognitivo":{"motivo":"Cobrar o elo entre as AIS/SUDS e o SUS, etapa intermediária pouco estudada.","palavraCritica":"antecedeu o SUS"},"comentario":{"resolucao":"CERTO. A sequência é AIS (Ações Integradas de Saúde, 1984) → SUDS (1987) → SUS (1988/1990). O SUDS estadualizou serviços do INAMPS por meio de convênios, sendo ensaio prático da descentralização que a CF/88 consagraria. O INAMPS só foi extinto em 1993.","fundamento":"Decreto nº 94.657/1987 (SUDS).","macete":"AIS → SUDS → SUS. O SUDS é o ensaio da descentralização.","erroComum":"Ignorar as etapas intermediárias e saltar do INAMPS ao SUS.","comoBancaPensa":"Cobra a etapa que costuma ser pulada no estudo."}},"SUS-048":{"cognitivo":{"motivo":"Cobrar a natureza coletiva e compulsória do modelo campanhista.","palavraCritica":"individual e curativa"},"comentario":{"resolucao":"ERRADO. O modelo campanhista era exatamente o oposto: coletivo, com ações de saneamento, vacinação obrigatória e combate a vetores, executadas com poder de polícia sanitária — daí a Revolta da Vacina (1904). A ênfase na assistência médica individual e curativa é do modelo médico-assistencial privatista, que se firmou depois, com a previdência.","fundamento":"História da saúde pública brasileira — modelos campanhista e médico-assistencial privatista.","macete":"Campanhista = campanha, coletivo, polícia sanitária. Privatista = consultório, individual, curativo.","erroComum":"Trocar as características dos dois modelos.","comoBancaPensa":"Descreve corretamente um modelo e o etiqueta com o nome do outro."}},"SUS-049":{"cognitivo":{"motivo":"Cobrar a literalidade do caput do art. 195, base do financiamento.","palavraCritica":"direta e indireta"},"comentario":{"resolucao":"CERTO. É a redação do art. 195, caput. A expressão 'toda a sociedade' consagra o princípio da solidariedade: financia quem contribui diretamente e também quem contribui de modo indireto, via orçamentos públicos. Note que os quatro entes federativos são citados — não apenas a União.","fundamento":"CF/1988, art. 195, caput.","macete":"Financiamento da seguridade: solidário, direto e indireto, dos quatro entes.","erroComum":"Restringir o financiamento às contribuições sociais.","comoBancaPensa":"Item de literalidade quase transcrita, que a banca cobra sem alteração."}},"SUS-050":{"cognitivo":{"motivo":"Cobrar o caráter não contributivo da saúde, que a separa da previdência.","palavraCritica":"contribuição prévia"},"comentario":{"resolucao":"ERRADO. Saúde é direito de todos e dever do Estado, com acesso UNIVERSAL e IGUALITÁRIO, independentemente de qualquer contribuição — art. 196. Quem exige contribuição prévia é a PREVIDÊNCIA social. Saúde e assistência social são ambas não contributivas; a assistência, porém, é prestada a quem dela necessitar, ao passo que a saúde é universal.","fundamento":"CF/1988, art. 196; art. 201 (previdência, caráter contributivo); art. 203 (assistência).","macete":"Dos três da seguridade, só a previdência exige contribuição.","erroComum":"Estender à saúde a lógica contributiva da previdência.","comoBancaPensa":"Ressuscita o modelo pré-1988, em que saúde dependia de vínculo previdenciário."}},"SUS-051":{"cognitivo":{"motivo":"Cobrar o trio regulamentação/fiscalização/controle e a possibilidade de execução privada.","palavraCritica":"execução por pessoa física ou jurídica de direito privado"},"comentario":{"resolucao":"CERTO. É a redação do art. 197. Duas leituras importam: 'relevância pública' autoriza a intervenção estatal mesmo sobre serviços privados de saúde; e a execução pode ser feita por terceiros — diretamente ou por meio de terceiros, pessoa física ou jurídica de direito privado —, o que não retira do poder público o dever de regulamentar, fiscalizar e controlar.","fundamento":"CF/1988, art. 197.","macete":"Relevância pública: o Estado regula, fiscaliza e controla, mesmo o que é privado.","erroComum":"Concluir que relevância pública impede a execução privada.","comoBancaPensa":"Item de literalidade em que o candidato tende a estranhar a menção ao privado."}},"SUS-052":{"cognitivo":{"motivo":"Cobrar a inversão da prioridade no atendimento integral, recorte clássico do art. 198, II.","palavraCritica":"prioridade para as atividades assistenciais"},"comentario":{"resolucao":"ERRADO. A prioridade está invertida. O art. 198, II, determina atendimento integral com PRIORIDADE PARA AS ATIVIDADES PREVENTIVAS, sem prejuízo dos serviços assistenciais. É uma das trocas mais cobradas da matéria, porque a inversão soa natural — mas o texto constitucional privilegia a prevenção. As demais diretrizes citadas estão corretas.","fundamento":"CF/1988, art. 198, I a III.","macete":"Prevenção primeiro, assistência sem prejuízo. Nunca o contrário.","erroComum":"Ler rápido e não notar a troca entre preventivo e assistencial.","comoBancaPensa":"Mantém corretas duas das três diretrizes e inverte só a ordem interna da segunda."}},"SUS-053":{"cognitivo":{"motivo":"Contraexemplo: um 'exclusivamente' que corresponde ao rol taxativo do art. 198.","palavraCritica":"exclusivamente"},"comentario":{"resolucao":"CERTO. O art. 198 traz três incisos, e apenas três: descentralização com direção única em cada esfera; atendimento integral, com prioridade para as atividades preventivas; e participação da comunidade. O rol é fechado — universalidade, integralidade e equidade são PRINCÍPIOS doutrinários e aparecem detalhados na Lei 8.080, art. 7º, não entre as diretrizes do art. 198.","fundamento":"CF/1988, art. 198, caput e incisos I a III.","macete":"Diretrizes da CF são 3: Descentralização, Atendimento integral, Participação (DAP).","erroComum":"Marcar ERRADO por reflexo diante de 'exclusivamente', ou misturar princípios da Lei 8.080 com diretrizes da CF.","comoBancaPensa":"Usa advérbio de exclusão num rol que é mesmo taxativo."}},"SUS-054":{"cognitivo":{"motivo":"Cobrar a exceção constitucional ao concurso público para esses agentes.","palavraCritica":"processo seletivo público"},"comentario":{"resolucao":"CERTO. É o art. 198, §4º, incluído pela EC 51/2006. A regra geral do art. 37, II, exige concurso público; para agentes comunitários de saúde e de combate às endemias, a Constituição admite PROCESSO SELETIVO PÚBLICO — figura menos formal, mas ainda impessoal e competitiva. Não é livre nomeação.","fundamento":"CF/1988, art. 198, §4º (EC 51/2006); Lei nº 11.350/2006.","macete":"ACS e ACE entram por processo seletivo público — exceção que a própria CF abriu.","erroComum":"Afirmar que a admissão dispensa qualquer seleção, ou que exige concurso comum.","comoBancaPensa":"Cobra uma exceção constitucional expressa, que soa irregular a quem só conhece a regra geral."}},"SUS-055":{"cognitivo":{"motivo":"Fixar o caráter da participação privada no SUS (CF, art. 199, § 1º).","palavraCritica":"complementar"},"comentario":{"resolucao":"ERRADO. A participação privada no SUS é COMPLEMENTAR (CF, art. 199, § 1º): o privado entra quando a capacidade pública é insuficiente, sem substituí-la. Instrumento (contrato de direito público ou convênio) e preferência (filantrópicas e sem fins lucrativos) estão corretos.","fundamento":"CF/1988, art. 199, caput e §1º; Lei nº 8.080/1990, art. 24 e art. 25.","macete":"Privado no SUS é complementar; o filantrópico tem preferência.","erroComum":"Aceitar o item pelo instrumento e pela preferência corretos.","comoBancaPensa":"Troca a palavra que define o regime da participação."}},"SUS-056":{"cognitivo":{"motivo":"Cobrar os dois termos, que a banca inverte com frequência.","palavraCritica":"complementar ... suplementar"},"comentario":{"resolucao":"ERRADO. Está invertido. SAÚDE SUPLEMENTAR é o setor de planos e seguros privados, regulado pela ANS. PARTICIPAÇÃO COMPLEMENTAR é a contratação de serviços privados pelo SUS quando sua capacidade é insuficiente, na forma do art. 199, §1º. O 'C' de complementar é o que Completa o SUS por dentro.","fundamento":"CF/1988, art. 199, §1º; Lei nº 9.656/1998 e Lei nº 9.961/2000 (ANS).","macete":"Complementar = dentro do SUS, contratado por ele. Suplementar = plano de saúde, fora dele.","erroComum":"Usar os dois termos como sinônimos.","comoBancaPensa":"Permuta dois termos quase homógrafos com sentidos institucionais opostos."}},"SUS-057":{"cognitivo":{"motivo":"Cobrar três competências do art. 200 que extrapolam a assistência médica.","palavraCritica":"ordenar a formação de recursos humanos"},"comentario":{"resolucao":"CERTO. São os incisos III, IV e VIII do art. 200. O verbo importa: quanto ao saneamento, o SUS PARTICIPA da formulação e da execução — não é o responsável principal; quanto à formação de recursos humanos, ele ORDENA. E o meio ambiente do trabalho está expressamente incluído, o que fundamenta a atuação em saúde do trabalhador.","fundamento":"CF/1988, art. 200, III, IV e VIII.","macete":"SUS ORDENA formação, PARTICIPA do saneamento, COLABORA com o meio ambiente.","erroComum":"Supor que o SUS executa isoladamente o saneamento básico.","comoBancaPensa":"Item correto que exige atenção aos verbos, e não só aos temas."}},"SUS-058":{"cognitivo":{"motivo":"Cobrar a vedação absoluta à comercialização de órgãos.","palavraCritica":"mediante autorização ... comercialização"},"comentario":{"resolucao":"ERRADO. O art. 199, §4º, veda expressamente TODO tipo de comercialização de órgãos, tecidos e substâncias humanas. A lei dispõe sobre as condições e requisitos para remoção e transplante, mas a vedação à comercialização é absoluta — não há autorização administrativa capaz de afastá-la. O item inventa um procedimento de exceção.","fundamento":"CF/1988, art. 199, §4º; Lei nº 9.434/1997.","macete":"Doação de órgão: sim. Venda: nunca, sob nenhuma condição.","erroComum":"Aceitar a exceção por parecer cercada de formalidades.","comoBancaPensa":"Cria um rito de autorização para tornar plausível o que a Constituição proíbe em termos absolutos."}},"SUS-059":{"cognitivo":{"motivo":"Cobrar a existência de um rol de atribuições COMUNS, anterior à repartição por esfera.","palavraCritica":"em seu âmbito administrativo"},"comentario":{"resolucao":"CERTO. O art. 15 lista atribuições exercidas pelos quatro entes, cada um no seu âmbito — entre elas administração de recursos, planejamento, elaboração de normas técnicas, poder de polícia sanitária e elaboração da proposta orçamentária. Só depois, nos arts. 16 a 18, a lei distribui o que é privativo de cada direção.","fundamento":"Lei nº 8.080/1990, art. 15, caput e incisos.","macete":"Art. 15 = todo mundo faz. Arts. 16, 17 e 18 = cada um faz o seu.","erroComum":"Presumir que toda competência é privativa de uma esfera.","comoBancaPensa":"Item correto que estabelece a estrutura antes das trocas de sujeito."}},"SUS-060":{"cognitivo":{"motivo":"Cobrar o núcleo da competência federal: definir e coordenar sistemas de abrangência nacional.","palavraCritica":"definir e coordenar"},"comentario":{"resolucao":"CERTO. É o art. 16, III. O verbo marca a esfera: à União cabe DEFINIR e COORDENAR sistemas nacionais; aos estados, coordenar e, em caráter complementar, executar; aos municípios, EXECUTAR os serviços. Guardar os verbos resolve a maior parte dos itens de repartição de competências.","fundamento":"Lei nº 8.080/1990, art. 16, III.","macete":"União define e coordena. Estado coordena. Município executa.","erroComum":"Atribuir aos estados a definição dos sistemas nacionais.","comoBancaPensa":"Item correto que fixa os verbos antes das trocas."}},"SUS-061":{"cognitivo":{"motivo":"Cobrar a repartição de competências pela troca das esferas.","palavraCritica":"direção municipal ... em âmbito nacional"},"comentario":{"resolucao":"ERRADO. Duas trocas. Planejar, organizar, controlar, avaliar e EXECUTAR os serviços públicos de saúde é competência da direção MUNICIPAL (art. 18, I). E nenhuma competência de âmbito NACIONAL cabe ao município — a coordenação da rede nacional de laboratórios é da União (art. 16, III). A incoerência entre 'municipal' e 'nacional' entrega o erro.","fundamento":"Lei nº 8.080/1990, arts. 16, III, e 18, I.","macete":"Quem executa serviço é o município. Quem faz algo 'nacional' é a União.","erroComum":"Não notar a incompatibilidade entre a esfera citada e o alcance da atribuição.","comoBancaPensa":"Permuta esferas em enunciado longo, contando com a leitura apressada."}},"SUS-062":{"cognitivo":{"motivo":"Cobrar a posição intermediária do estado: coordena e só executa em caráter complementar.","palavraCritica":"em caráter complementar"},"comentario":{"resolucao":"CERTO. É o art. 17, IV. A expressão 'em caráter complementar' é o que define o papel estadual: a execução ordinária é municipal, e o estado entra quando o município não dá conta ou quando a ação transcende o território municipal. Suprimir essa expressão do enunciado transformaria o item em falso.","fundamento":"Lei nº 8.080/1990, art. 17, IV.","macete":"Estado coordena sempre; executa só complementarmente.","erroComum":"Ler o estado como executor ordinário dos serviços.","comoBancaPensa":"Item correto cuja palavra decisiva é uma locução adverbial fácil de ignorar."}},"SUS-063":{"cognitivo":{"motivo":"Contraexemplo: enunciado curtíssimo e categórico que reproduz o artigo na íntegra.","palavraCritica":"estados e aos municípios"},"comentario":{"resolucao":"CERTO. É a redação integral do art. 19. O DF acumula as duas competências porque não é dividido em municípios (CF, art. 32, §1º). Enunciados muito curtos costumam levantar suspeita, mas aqui o item é a própria lei — e a acumulação é dupla, não apenas estadual.","fundamento":"Lei nº 8.080/1990, art. 19; CF/1988, art. 32, §1º.","macete":"DF é estado e município ao mesmo tempo — na saúde também.","erroComum":"Afirmar que o DF só tem competências estaduais.","comoBancaPensa":"Transcreve o artigo inteiro e conta com a desconfiança do candidato diante da brevidade."}},"SUS-064":{"cognitivo":{"motivo":"Fixar a direção única em cada esfera (Lei 8.080, art. 9º).","palavraCritica":"direção única"},"comentario":{"resolucao":"CERTO. Pelo art. 9º da Lei 8.080, a direção única é exercida na União pelo Ministério da Saúde; nos estados e no DF, pela Secretaria de Saúde ou órgão equivalente; nos municípios, pela Secretaria Municipal de Saúde ou órgão equivalente.","fundamento":"Lei nº 8.080/1990, art. 9º, I a III.","macete":"Uma direção por esfera: Ministério, Secretaria Estadual, Secretaria Municipal.","erroComum":"Achar que direção única significa comando só do Ministério.","comoBancaPensa":"Item correto que a banca costuma inverter."}},"SUS-065":{"cognitivo":{"motivo":"Cobrar a natureza e o método decisório das comissões intergestores.","palavraCritica":"de forma consensual"},"comentario":{"resolucao":"CERTO. É o art. 14-A, incluído pela Lei 12.466/2011. Dois pontos: são foros de GESTORES (não de controle social — este é dos conselhos), e decidem por CONSENSO, não por maioria. A CIT reúne União, estados e municípios; a CIB, estado e municípios; e o Decreto 7.508 acrescentou a CIR, no âmbito regional.","fundamento":"Lei nº 8.080/1990, art. 14-A (Lei nº 12.466/2011).","macete":"Intergestores = gestores, por consenso. Conselho = sociedade, por deliberação.","erroComum":"Confundir comissão intergestores com conselho de saúde.","comoBancaPensa":"Item correto que separa dois colegiados frequentemente embaralhados."}},"SUS-066":{"cognitivo":{"motivo":"Cobrar a composição de cada entidade representativa.","palavraCritica":"CONASS ... municipais"},"comentario":{"resolucao":"ERRADO. Está invertido. O CONASS reúne os secretários ESTADUAIS de saúde; o CONASEMS, os secretários MUNICIPAIS — o próprio nome entrega, pois traz 'Municipais' por extenso. Ambos são entidades de direito privado sem fins lucrativos, reconhecidas como representantes dos gestores pelo art. 14-B.","fundamento":"Lei nº 8.080/1990, art. 14-B (Lei nº 12.466/2011).","macete":"CONASEMS tem 'M' de Municipais. CONASS, por eliminação, é dos estados.","erroComum":"Trocar as duas siglas por semelhança.","comoBancaPensa":"Inverte duas siglas parecidas, apostando na memorização superficial."}},"SUS-067":{"cognitivo":{"motivo":"Contraexemplo: uma fração exata que corresponde ao §1º do art. 35.","palavraCritica":"metade dos recursos"},"comentario":{"resolucao":"CERTO. O art. 35 lista os critérios combinados e o §1º determina que METADE dos recursos destinados a estados e municípios seja distribuída segundo o quantitativo populacional, independentemente de qualquer procedimento prévio. É um piso de equidade populacional: garante que nenhum ente fique sem repasse por mau desempenho relativo.","fundamento":"Lei nº 8.080/1990, art. 35, caput e §1º.","macete":"Metade vai pela população, pura e simplesmente.","erroComum":"Marcar ERRADO por desconfiança de fração exata em enunciado.","comoBancaPensa":"Traz número correto num contexto de muitos critérios, onde o candidato tende a duvidar."}},"SUS-068":{"cognitivo":{"motivo":"Cobrar o pressuposto da contratação privada e o regime jurídico aplicável.","palavraCritica":"forem insuficientes"},"comentario":{"resolucao":"CERTO. É a conjugação dos arts. 24 e 26. O pressuposto é a insuficiência da capacidade pública — não é opção livre do gestor. E o contrato, ainda que celebrado com particular, submete-se às normas de direito público, o que atrai princípios como impessoalidade e publicidade e permite o controle pelos órgãos do SUS.","fundamento":"Lei nº 8.080/1990, arts. 24, caput e parágrafo único, e 26.","macete":"Só contrata privado se o público não der conta — e sob regras públicas.","erroComum":"Tratar a contratação de privados como escolha discricionária.","comoBancaPensa":"Item correto que exige lembrar do pressuposto, e não apenas da possibilidade."}},"SUS-069":{"cognitivo":{"motivo":"Contraexemplo: par de colegiados que a banca troca, aqui descrito corretamente.","palavraCritica":"áreas não compreendidas no âmbito do SUS"},"comentario":{"resolucao":"CERTO. É o art. 14. Dois detalhes que a banca explora: as comissões intersetoriais são subordinadas ao CNS — e não às comissões intergestores —, e sua razão de ser é articular o que está FORA do SUS (saneamento, meio ambiente, educação, alimentação), porque saúde depende de determinantes que o setor sozinho não controla.","fundamento":"Lei nº 8.080/1990, art. 14, caput e parágrafo único.","macete":"Intersetorial = entre setores diferentes, ligada ao Conselho. Intergestores = entre entes, de gestores.","erroComum":"Confundir comissão intersetorial com comissão intergestores.","comoBancaPensa":"Descreve corretamente um colegiado que costuma ser embaralhado com o outro."}},"SUS-070":{"cognitivo":{"motivo":"Cobrar o limite da integração privada ao SUS.","palavraCritica":"todas as instituições privadas"},"comentario":{"resolucao":"ERRADO. A primeira parte reproduz o art. 4º, caput. Mas a iniciativa privada só participa do SUS em CARÁTER COMPLEMENTAR (art. 4º, §2º), mediante contrato ou convênio — não por mera existência. Um hospital particular que atende só planos e pacientes privados não integra o SUS. Além disso, a lei ressalva que os serviços privados contratados passam a seguir as diretrizes do sistema.","fundamento":"Lei nº 8.080/1990, art. 4º, caput e §2º.","macete":"Privado só entra no SUS por contrato ou convênio. Existir não basta.","erroComum":"Ler o SUS como abrangendo todo o setor saúde do país.","comoBancaPensa":"Acopla uma cláusula falsa e generalizante a uma transcrição correta do caput."}},"SUS-071":{"cognitivo":{"motivo":"Cobrar os três objetivos do art. 5º, com destaque para a divulgação dos determinantes.","palavraCritica":"identificação e a divulgação"},"comentario":{"resolucao":"CERTO. São os três incisos do art. 5º. O primeiro é o mais cobrado e o mais esquecido: o SUS não apenas identifica os determinantes — ele tem o dever de DIVULGÁ-LOS. O terceiro objetivo traz a tríade promoção, proteção e recuperação, que estrutura toda a assistência.","fundamento":"Lei nº 8.080/1990, art. 5º, I a III.","macete":"Identificar e divulgar; formular política de redução de riscos; assistir com promoção, proteção e recuperação.","erroComum":"Reduzir os objetivos do SUS à assistência.","comoBancaPensa":"Item de literalidade em que o verbo 'divulgar' é o detalhe cobrado."}},"SUS-072":{"cognitivo":{"motivo":"Cobrar a distinção entre as duas vigilâncias, uma das trocas mais frequentes da disciplina.","palavraCritica":"vigilância epidemiológica"},"comentario":{"resolucao":"ERRADO. A definição apresentada é a de vigilância SANITÁRIA (art. 6º, §1º) — ela cuida de bens, produtos e serviços. A vigilância EPIDEMIOLÓGICA (§2º) é o conjunto de ações que proporciona o conhecimento, a detecção ou prevenção de mudanças nos fatores determinantes e condicionantes da saúde individual ou coletiva, com a finalidade de recomendar e adotar medidas de prevenção e controle de doenças ou agravos.","fundamento":"Lei nº 8.080/1990, art. 6º, §§1º e 2º.","macete":"Sanitária cuida de COISAS (produtos, serviços). Epidemiológica cuida de DOENÇAS (casos, surtos).","erroComum":"Trocar as duas definições, que vêm em parágrafos consecutivos.","comoBancaPensa":"Reproduz fielmente uma definição legal e apenas troca o rótulo."}},"SUS-073":{"cognitivo":{"motivo":"Cobrar o alcance da atuação do SUS em saúde do trabalhador, incluindo o direito à informação.","palavraCritica":"entidade sindical"},"comentario":{"resolucao":"CERTO. O art. 6º, §3º, lista essas atribuições. O dever de informar alcança não só o trabalhador, mas também o sindicato — o que reconhece a dimensão coletiva do risco ocupacional. O SUS também pode requisitar informações às empresas sobre riscos e agravos e avaliar as condições dos ambientes de trabalho.","fundamento":"Lei nº 8.080/1990, art. 6º, §3º, I a VIII.","macete":"Saúde do trabalhador no SUS chega até o ambiente de trabalho e o sindicato.","erroComum":"Supor que a fiscalização do trabalho é exclusiva do Ministério do Trabalho.","comoBancaPensa":"Item correto que amplia o alcance do SUS além da assistência clínica."}},"SUS-074":{"cognitivo":{"motivo":"Cobrar dois princípios do art. 7º cuja redação a banca reproduz quase literalmente.","palavraCritica":"sem preconceitos ou privilégios de qualquer espécie"},"comentario":{"resolucao":"CERTO. São os incisos III e IV do art. 7º. Atenção à formulação legal: a lei fala em IGUALDADE da assistência, sem preconceitos ou privilégios — a EQUIDADE, embora seja princípio doutrinário consagrado, não aparece com essa palavra no rol do art. 7º, e a banca explora essa diferença entre o texto legal e o vocabulário da doutrina.","fundamento":"Lei nº 8.080/1990, art. 7º, III e IV.","macete":"A lei escreve 'igualdade'; a doutrina fala 'equidade'. Saiba os dois.","erroComum":"Procurar a palavra 'equidade' no texto do art. 7º.","comoBancaPensa":"Item de literalidade cuja armadilha correlata é trocar igualdade por equidade."}},"SUS-075":{"cognitivo":{"motivo":"Cobrar a definição legal de integralidade, com seus quatro pares de opostos.","palavraCritica":"em todos os níveis de complexidade"},"comentario":{"resolucao":"CERTO. É o art. 7º, II. A definição legal encadeia oposições que se somam: preventivo E curativo, individual E coletivo, em TODOS os níveis de complexidade. Integralidade não é escolher um dos polos — é articular todos, de forma contínua. Daí a expressão 'conjunto articulado e contínuo'.","fundamento":"Lei nº 8.080/1990, art. 7º, II.","macete":"Integralidade soma: preventivo + curativo, individual + coletivo, todos os níveis.","erroComum":"Reduzir integralidade a 'atender a pessoa por inteiro'.","comoBancaPensa":"Item de literalidade que o candidato tende a estranhar por parecer amplo demais."}},"SUS-076":{"cognitivo":{"motivo":"Cobrar a responsabilidade financeira pelo subsistema indígena.","palavraCritica":"financiado pelos estados e municípios"},"comentario":{"resolucao":"ERRADO. O art. 19-C é expresso: caberá à UNIÃO, com seus recursos próprios, financiar o Subsistema de Atenção à Saúde Indígena. Estados, municípios e outras instituições podem atuar de forma complementar (art. 19-E), mas o custeio é federal — coerente com a competência da União para tratar de terras e populações indígenas.","fundamento":"Lei nº 8.080/1990, arts. 19-C e 19-E.","macete":"Saúde indígena: dinheiro é da União. Os demais entes complementam.","erroComum":"Aplicar a lógica geral de cofinanciamento tripartite ao subsistema indígena.","comoBancaPensa":"Inverte o responsável pelo custeio num subsistema com regra própria."}},"SUS-077":{"cognitivo":{"motivo":"Cobrar o caráter obrigatório da adequação cultural, e não meramente recomendável.","palavraCritica":"obrigatoriamente"},"comentario":{"resolucao":"CERTO. É o art. 19-F. O advérbio 'obrigatoriamente' está no texto legal: a adequação cultural não é sugestão, é dever. O art. 19-G complementa determinando que o subsistema seja descentralizado, hierarquizado e regionalizado, e que as populações indígenas tenham direito a participar dos organismos colegiados de formulação e controle das políticas de saúde.","fundamento":"Lei nº 8.080/1990, arts. 19-F e 19-G.","macete":"Atenção diferenciada aos povos indígenas é obrigação legal expressa.","erroComum":"Ler a adequação cultural como diretriz programática sem força vinculante.","comoBancaPensa":"Item correto em que o advérbio absoluto vem da própria lei."}},"SUS-078":{"cognitivo":{"motivo":"Fixar os requisitos do atendimento domiciliar (art. 19-I).","palavraCritica":"concordância"},"comentario":{"resolucao":"CERTO. É o § 3º do art. 19-I da Lei 8.080: indicação médica E expressa concordância do paciente e de sua família. A internação domiciliar muda a rotina da casa e exige a participação da família no cuidado, daí a concordância.","fundamento":"Lei nº 8.080/1990, art. 19-I, §§1º e 2º.","macete":"Domiciliar: médico indica, paciente e família concordam.","erroComum":"Achar que basta a indicação médica.","comoBancaPensa":"Item correto com os dois requisitos cumulativos."}},"SUS-079":{"cognitivo":{"motivo":"Cobrar o direito ao acompanhante, de aplicação direta na assistência à saúde da mulher.","palavraCritica":"indicado pela própria parturiente"},"comentario":{"resolucao":"CERTO. É o art. 19-J, incluído pela Lei 11.108/2005. Três pontos: o direito alcança a rede própria E a conveniada; cobre os três momentos (trabalho de parto, parto e pós-parto imediato); e a escolha do acompanhante é da PARTURIENTE, não do serviço nem da família. É garantia especialmente cobrada em concursos da área de saúde da mulher.","fundamento":"Lei nº 8.080/1990, art. 19-J (Lei nº 11.108/2005).","macete":"Um acompanhante, escolhido por ela, nos três momentos.","erroComum":"Restringir o direito ao momento do parto propriamente dito.","comoBancaPensa":"Item de literalidade com aplicação prática direta na assistência obstétrica."}},"SUS-080":{"cognitivo":{"motivo":"Fixar quem decide a incorporação de tecnologias no SUS (art. 19-Q).","palavraCritica":"Ministério da Saúde"},"comentario":{"resolucao":"ERRADO. Pelo art. 19-Q da Lei 8.080 (incluído pela Lei 12.401/2011), a decisão é do MINISTÉRIO DA SAÚDE, assessorado pela CONITEC. A Anvisa registra produtos e fiscaliza; o registro é pressuposto da incorporação, mas não a decide.","fundamento":"Lei nº 8.080/1990, arts. 19-Q e 19-R (Lei nº 12.401/2011).","macete":"Anvisa registra; CONITEC recomenda; Ministério decide.","erroComum":"Confundir registro sanitário com incorporação ao SUS.","comoBancaPensa":"Troca o órgão decisório por outro do mesmo setor."}},"SUS-081":{"cognitivo":{"motivo":"Contraexemplo: uma vedação absoluta que a lei formula exatamente assim.","palavraCritica":"em todas as esferas de gestão"},"comentario":{"resolucao":"CERTO. É o art. 19-T, I e II. A vedação alcança as três esferas e é categórica quanto ao que é experimental ou não registrado na ANVISA. É o dispositivo central nas discussões de judicialização da saúde: fundamenta a recusa administrativa ao custeio de tratamentos sem registro sanitário, ainda que haja prescrição médica.","fundamento":"Lei nº 8.080/1990, art. 19-T, I e II (Lei nº 12.401/2011).","macete":"Sem registro na ANVISA, o SUS não paga — em nenhuma esfera.","erroComum":"Marcar ERRADO por reflexo diante de 'todas as esferas'.","comoBancaPensa":"Usa linguagem categórica em vedação que é mesmo absoluta na lei."}},"SUS-082":{"cognitivo":{"motivo":"Cobrar a gratuidade integral, sem brechas de valor simbólico.","palavraCritica":"valor simbólico"},"comentario":{"resolucao":"ERRADO. O art. 43 é taxativo: a gratuidade das ações e serviços de saúde nos serviços públicos contratados fica preservada. Não há autorização para cobrança, ainda que simbólica ou finalisticamente vinculada. A gratuidade decorre do acesso universal e igualitário do art. 196 da CF e do caráter não contributivo da saúde.","fundamento":"Lei nº 8.080/1990, art. 43; CF/1988, art. 196.","macete":"No SUS não se cobra do usuário. Nem pouco, nem para 'ajudar na manutenção'.","erroComum":"Aceitar a exceção por parecer módica e bem-intencionada.","comoBancaPensa":"Cria uma brecha revestida de razoabilidade contra regra que não admite exceção."}},"SUS-083":{"cognitivo":{"motivo":"Suprimir as hipóteses de convocação extraordinária do § 1º, que não são do Executivo.","palavraCritica":"privativa"},"comentario":{"resolucao":"ERRADO. O intervalo de quatro anos está certo, mas a convocação não é privativa do Executivo: o § 1º do art. 1º prevê que a Conferência é convocada pelo Poder Executivo ou, EXTRAORDINARIAMENTE, por ela própria ou pelo Conselho de Saúde. A alternativa importa: sem ela, o controle social dependeria da iniciativa do gestor que ele mesmo fiscaliza.","fundamento":"Lei nº 8.142/1990, art. 1º, § 1º.","macete":"Ordinária: Executivo, a cada 4 anos. Extraordinária: a própria Conferência ou o Conselho.","erroComum":"Aceitar a exclusividade do Executivo por ser quem convoca no caso ordinário.","comoBancaPensa":"Acerta o prazo para dar credibilidade e fecha indevidamente o rol de legitimados."}},"SUS-084":{"cognitivo":{"motivo":"Contraexemplo: as duas instâncias colegiadas contrastadas corretamente, sem inversão.","palavraCritica":"natureza episódica e função propositiva"},"comentario":{"resolucao":"CERTO. O contraste está correto nas duas pontas. O Conselho é permanente e DELIBERATIVO — decide e fiscaliza continuamente. A Conferência é episódica (a cada quatro anos) e PROPOSITIVA — avalia e propõe diretrizes, sem gerir o sistema no dia a dia. Confundir as duas naturezas é o erro mais frequente da matéria, e aqui a atribuição está certa.","fundamento":"Lei nº 8.142/1990, art. 1º, §§1º e 2º.","macete":"Conferência propõe de tempos em tempos; Conselho delibera o tempo todo.","erroComum":"Marcar ERRADO por desconfiar de item que compara as duas instâncias.","comoBancaPensa":"Apresenta corretamente o par que costuma inverter, punindo a resposta por formato."}},"SUS-085":{"cognitivo":{"motivo":"Cobrar a natureza permanente e deliberativa do Conselho.","palavraCritica":"temporário e consultivo"},"comentario":{"resolucao":"ERRADO. O Conselho de Saúde é órgão colegiado de caráter PERMANENTE e DELIBERATIVO (art. 1º, §2º). Atua na formulação de estratégias E no controle da execução da política de saúde, inclusive nos aspectos econômicos e financeiros. Suas decisões são homologadas pelo chefe do poder legalmente constituído em cada esfera — homologação que é ato vinculado quanto à legalidade, não um veto discricionário.","fundamento":"Lei nº 8.142/1990, art. 1º, §2º; Resolução CNS nº 453/2012.","macete":"Conselho: permanente e deliberativo. Conferência: periódica e propositiva.","erroComum":"Tratar o Conselho como órgão meramente opinativo.","comoBancaPensa":"Inverte os dois adjetivos que definem a força jurídica do colegiado."}},"SUS-086":{"cognitivo":{"motivo":"Cobrar o significado exato da paridade, que não é divisão igual entre todos os segmentos.","palavraCritica":"em relação ao conjunto dos demais segmentos"},"comentario":{"resolucao":"CERTO. É o art. 1º, §4º. A paridade é dos usuários contra TODOS OS OUTROS somados — 50% usuários, e os demais 50% repartidos entre trabalhadores da saúde (25%), gestores e prestadores (25%), na forma da Resolução CNS 453/2012. Não é 1/3 para cada um dos três segmentos, que é o erro clássico.","fundamento":"Lei nº 8.142/1990, art. 1º, §4º; Resolução CNS nº 453/2012.","macete":"Usuários 50%. Trabalhadores 25%. Gestores e prestadores 25%.","erroComum":"Dividir em três partes iguais por interpretar 'paritária' como 'igual entre todos'.","comoBancaPensa":"O número é correto, mas exige entender que a paridade se mede contra a soma dos outros."}},"SUS-087":{"cognitivo":{"motivo":"Cobrar o rol completo de condicionantes do repasse, item de alta recorrência.","palavraCritica":"Comissão de elaboração do Plano de Carreira, Cargos e Salários"},"comentario":{"resolucao":"CERTO. São os seis incisos do art. 4º. O mais esquecido é o último — a Comissão de elaboração do PCCS —, e é justamente ele que a banca costuma suprimir ou substituir. Note que a exigência é da COMISSÃO de elaboração, com prazo de dois anos para a conclusão do plano, e não do plano já pronto.","fundamento":"Lei nº 8.142/1990, art. 4º, I a VI.","macete":"Fundo, Conselho, Plano, Relatórios, Contrapartida e Comissão do PCCS. Seis.","erroComum":"Esquecer a Comissão do PCCS ou trocá-la pelo plano concluído.","comoBancaPensa":"Item de literalidade que cobra a integralidade de um rol de seis."}},"SUS-088":{"cognitivo":{"motivo":"Cobrar a modalidade de transferência fundo a fundo.","palavraCritica":"regular e automática"},"comentario":{"resolucao":"CERTO. É a conjugação dos arts. 2º e 3º. A expressão 'regular e automática' define a transferência fundo a fundo: os recursos saem do Fundo Nacional de Saúde direto para os fundos estaduais e municipais, sem necessidade de convênio a cada repasse. É o mecanismo que operacionaliza a descentralização financeira do SUS.","fundamento":"Lei nº 8.142/1990, arts. 2º e 3º, caput.","macete":"Fundo a fundo: regular e automático, sem convênio caso a caso.","erroComum":"Supor que cada repasse depende de instrumento específico.","comoBancaPensa":"Item correto cuja expressão-chave é o par de adjetivos."}},"SUS-089":{"cognitivo":{"motivo":"Cobrar a presença dos gestores estaduais e municipais no CNS.","palavraCritica":"representação assegurada"},"comentario":{"resolucao":"CERTO. É o art. 1º, §3º. CONASS e CONASEMS têm assento garantido no Conselho Nacional de Saúde, integrando o segmento de gestores. Isso não conflita com a paridade dos usuários: eles ocupam parte dos 50% reservados ao conjunto dos demais segmentos.","fundamento":"Lei nº 8.142/1990, art. 1º, §3º.","macete":"CONASS e CONASEMS sentam no CNS, no lado dos gestores.","erroComum":"Supor que o CNS é composto apenas por usuários e trabalhadores.","comoBancaPensa":"Item correto que testa se o candidato conhece a composição, e não só a paridade."}},"SUS-090":{"cognitivo":{"motivo":"Cobrar a competência extraordinária do Conselho para convocar a Conferência.","palavraCritica":"exclusivamente ... nenhuma hipótese"},"comentario":{"resolucao":"ERRADO. O art. 1º, §1º, prevê convocação pelo Poder Executivo OU, extraordinariamente, pelo próprio CONSELHO DE SAÚDE. A previsão é relevante politicamente: impede que um Executivo omisso inviabilize o principal fórum de participação social ao simplesmente não convocá-lo.","fundamento":"Lei nº 8.142/1990, art. 1º, §1º.","macete":"Executivo convoca em regra; o Conselho pode convocar extraordinariamente.","erroComum":"Ler a convocação como monopólio do Executivo.","comoBancaPensa":"Fecha com dois absolutos uma competência que a lei divide."}},"SUS-091":{"cognitivo":{"motivo":"Cobrar a autonomia do Conselho quanto à escolha de seu presidente.","palavraCritica":"necessariamente"},"comentario":{"resolucao":"ERRADO. A Resolução CNS 453/2012 determina que o Conselho de Saúde eleja seu presidente ou mesa diretora entre os conselheiros, em reunião plenária — não há vinculação ao cargo de secretário de saúde. Vincular a presidência ao gestor esvaziaria a função de controle social, já que o controlado presidiria o órgão controlador.","fundamento":"Resolução CNS nº 453/2012, Quarta Diretriz.","macete":"O Conselho elege quem o preside. Não é cargo do secretário por direito.","erroComum":"Presumir que o gestor preside o colegiado por ser autoridade máxima da pasta.","comoBancaPensa":"Cria vinculação hierárquica que contraria a lógica do controle social."}},"SUS-092":{"cognitivo":{"motivo":"Cobrar a consequência do descumprimento dos requisitos do art. 4º.","palavraCritica":"respectivamente"},"comentario":{"resolucao":"CERTO. É o art. 4º, parágrafo único. A consequência não é a perda do recurso — a população não pode ser penalizada pela omissão do gestor —, mas a administração pelo ente imediatamente superior: o estado assume o do município inadimplente, e a União assume o do estado. O advérbio 'respectivamente' organiza essa correspondência.","fundamento":"Lei nº 8.142/1990, art. 4º, parágrafo único.","macete":"Não cumpriu? Não perde o dinheiro: quem administra passa a ser o ente de cima.","erroComum":"Supor que o descumprimento acarreta cancelamento do repasse.","comoBancaPensa":"Item correto cuja leitura exige atenção à ordem estabelecida por 'respectivamente'."}},"SUS-093":{"cognitivo":{"motivo":"Cobrar o percentual estadual e a dedução das transferências, base de cálculo que a banca omite.","palavraCritica":"deduzidas as parcelas transferidas"},"comentario":{"resolucao":"CERTO. É o art. 6º da LC 141/2012. Dois pontos: o percentual estadual é de 12%, e a base de cálculo desconta o que o estado repassa aos municípios — do contrário, o mesmo recurso seria contado duas vezes, no estado e no município que o recebe.","fundamento":"LC nº 141/2012, art. 6º; CF/1988, art. 198, §2º, II.","macete":"Estado 12%, Município 15%. E sempre líquido das transferências.","erroComum":"Trocar os percentuais de estados e municípios entre si.","comoBancaPensa":"Traz o número correto num item que também cobra a base de cálculo."}},"SUS-094":{"cognitivo":{"motivo":"Cobrar o percentual municipal pela troca com o estadual.","palavraCritica":"doze por cento"},"comentario":{"resolucao":"ERRADO. O percentual municipal é de QUINZE por cento (art. 7º da LC 141/2012); 12% é o dos estados. A troca entre os dois números é a pegadinha mais recorrente do tema. O município aplica mais proporcionalmente porque é o principal executor das ações e serviços de saúde.","fundamento":"LC nº 141/2012, arts. 6º e 7º; CF/1988, art. 198, §2º, II e III.","macete":"Quem executa mais, aplica mais: município 15%, estado 12%.","erroComum":"Memorizar os dois números sem fixar de quem é cada um.","comoBancaPensa":"Permuta dois percentuais que o candidato conhece, mas frequentemente não sabe atribuir."}},"SUS-095":{"cognitivo":{"motivo":"Fixar os percentuais mínimos do DF (LC 141/2012).","palavraCritica":"12% estadual; 15% municipal"},"comentario":{"resolucao":"ERRADO. Os percentuais estão invertidos. O DF aplica 12% sobre os impostos de competência ESTADUAL e 15% sobre os de competência MUNICIPAL (LC 141/2012, arts. 6º e 7º), porque acumula as duas competências e segue, em cada base, o mínimo do respectivo ente.","fundamento":"LC nº 141/2012, arts. 6º e 7º, parágrafo único.","macete":"Estado 12%, município 15% — o DF faz os dois, cada um na sua base.","erroComum":"Lembrar os dois números e não a base de cada um.","comoBancaPensa":"Mantém os números e troca as bases."}},"SUS-096":{"cognitivo":{"motivo":"Cobrar as hipóteses em que saneamento conta como ASPS, exceção pouco lembrada.","palavraCritica":"áreas habitadas por população carente"},"comentario":{"resolucao":"CERTO. É o art. 3º, I a XI. O saneamento básico entra como ASPS em hipóteses delimitadas — domicílios ou pequenas comunidades em áreas de população de baixa renda, e ações de saneamento em escolas conveniadas —, justamente porque a regra geral do art. 4º exclui o saneamento de caráter universal. A distinção entre os dois artigos é o núcleo do tema.","fundamento":"LC nº 141/2012, art. 3º, I a XI.","macete":"Saneamento focalizado em área carente: conta. Saneamento para toda a cidade: não conta.","erroComum":"Excluir todo saneamento da conta de ASPS.","comoBancaPensa":"Item correto que cobra justamente a exceção dentro da vedação."}},"SUS-097":{"cognitivo":{"motivo":"Cobrar a vedação do art. 4º, que exclui a assistência não universal.","palavraCritica":"computam-se"},"comentario":{"resolucao":"ERRADO. O art. 4º, III, exclui expressamente a assistência à saúde que não atenda ao princípio da universalidade — hipótese típica dos planos de saúde de servidores. A razão é coerente: o piso constitucional existe para custear o SUS, que é universal, e não benefício restrito a uma categoria. Também não contam pagamento de aposentadorias e pensões, limpeza urbana, merenda escolar e saneamento de caráter universal.","fundamento":"LC nº 141/2012, art. 4º, I a VII.","macete":"Se não é para todos, não conta como ASPS.","erroComum":"Incluir na conta gastos com assistência a servidores.","comoBancaPensa":"Inverte o sentido de uma vedação expressa, usando linguagem técnica correta."}},"SUS-098":{"cognitivo":{"motivo":"Cobrar a exclusão de inativos, mesmo os da própria saúde.","palavraCritica":"inclusive dos servidores da área da saúde"},"comentario":{"resolucao":"CERTO. É o art. 4º, I. A palavra decisiva é 'inclusive': mesmo o aposentado que trabalhou a vida inteira na saúde tem seus proventos fora da conta, porque aposentadoria é despesa previdenciária, não ação de saúde. Contabilizá-la inflaria artificialmente o cumprimento do piso sem qualquer serviço prestado à população.","fundamento":"LC nº 141/2012, art. 4º, I.","macete":"Inativo não presta serviço de saúde: seu provento não conta no piso.","erroComum":"Incluir inativos da saúde por associação com a área.","comoBancaPensa":"Item de literalidade em que o 'inclusive' fecha a brecha que o candidato imagina."}},"SUS-099":{"cognitivo":{"motivo":"Cobrar a periodicidade do relatório de gestão, alterada pela LC 141.","palavraCritica":"trimestre"},"comentario":{"resolucao":"ERRADO. O relatório é QUADRIMESTRAL, não trimestral (art. 36 da LC 141/2012). A periodicidade trimestral constava da redação anterior da Lei 8.689/1993 e foi substituída — por isso o erro é tentador para quem estudou por material desatualizado. O conteúdo mínimo descrito no item, esse sim, está correto.","fundamento":"LC nº 141/2012, art. 36, caput e incisos.","macete":"Relatório de gestão: quadrimestral. Três por ano.","erroComum":"Repetir a periodicidade trimestral da legislação revogada.","comoBancaPensa":"Usa a redação antiga do dispositivo, que ainda circula em materiais de estudo."}},"SUS-100":{"cognitivo":{"motivo":"Fixar os prazos do relatório quadrimestral (LC 141/2012, art. 36, § 5º).","palavraCritica":"fevereiro"},"comentario":{"resolucao":"ERRADO. Os meses são maio, setembro e FEVEREIRO (LC 141/2012, art. 36, § 5º): cada relatório vem no mês seguinte ao fim do quadrimestre, e o de setembro a dezembro só pode ser apresentado em fevereiro do ano seguinte. Em dezembro o quadrimestre ainda não acabou.","fundamento":"LC nº 141/2012, art. 36, §5º.","macete":"Maio, setembro e fevereiro: o mês seguinte ao fim de cada quadrimestre.","erroComum":"Fechar o ano em dezembro por intuição.","comoBancaPensa":"Troca um dos três meses por outro plausível."}},"SUS-101":{"cognitivo":{"motivo":"Contraexemplo: exigência absoluta que corresponde ao art. 2º, parágrafo único.","palavraCritica":"exclusivamente ... até a sua destinação final"},"comentario":{"resolucao":"CERTO. É o art. 2º, parágrafo único, da LC 141/2012. A exclusividade é real e tem função de controle: obrigar a passagem por fundo específico até o pagamento final impede que recursos da saúde se misturem ao caixa único e sejam desviados para outras finalidades. O acompanhamento pelo conselho fecha o desenho.","fundamento":"LC nº 141/2012, art. 2º, parágrafo único.","macete":"Dinheiro da saúde entra e sai pelo fundo de saúde. Sem atalho.","erroComum":"Marcar ERRADO por reflexo diante de 'exclusivamente'.","comoBancaPensa":"Advérbio de exclusão em regra que é mesmo sem exceção."}},"SUS-102":{"cognitivo":{"motivo":"Cobrar o instrumento oficial de comprovação do piso.","palavraCritica":"obrigatória"},"comentario":{"resolucao":"CERTO. É o art. 39 da LC 141/2012. O SIOPS é o sistema no qual todos os entes registram receitas e despesas com saúde, e sua alimentação é obrigatória — o descumprimento pode acarretar suspensão de transferências voluntárias. É a base de dados que permite ao Tribunal de Contas e à sociedade aferir o cumprimento do piso.","fundamento":"LC nº 141/2012, arts. 39 e 40.","macete":"SIOPS: onde se prova que o mínimo foi aplicado.","erroComum":"Tratar o SIOPS como sistema facultativo de gestão.","comoBancaPensa":"Item correto que cobra o instrumento, e não apenas o dever."}},"SUS-103":{"cognitivo":{"motivo":"Cobrar a consequência da aplicação a menor, que não se extingue com o exercício.","palavraCritica":"acrescida ao montante mínimo do exercício subsequente"},"comentario":{"resolucao":"CERTO. É o art. 25 da LC 141/2012. A dívida com a saúde não prescreve com o encerramento do exercício: o que faltou entra como acréscimo ao piso do ano seguinte. Somam-se a isso as sanções da Lei de Responsabilidade Fiscal e a possibilidade de intervenção, prevista na Constituição para o descumprimento do mínimo em saúde.","fundamento":"LC nº 141/2012, art. 25; CF/1988, arts. 34, VII, 'e', e 35, III.","macete":"Deixou de aplicar? A diferença é cobrada no ano seguinte, além das sanções.","erroComum":"Supor que o descumprimento se resolve apenas com sanção ao gestor.","comoBancaPensa":"Item correto que cobra o efeito financeiro, além do punitivo."}},"SUS-104":{"cognitivo":{"motivo":"Cobrar a combinação de critérios no rateio, contra a redução ao populacional.","palavraCritica":"exclusivamente ... vedada"},"comentario":{"resolucao":"ERRADO. O art. 17 da LC 141/2012 determina que o rateio observe as necessidades de saúde da população, considerando as dimensões epidemiológica, demográfica, socioeconômica, espacial e de capacidade de oferta — com o objetivo de reduzir desigualdades regionais. O critério populacional é um entre vários, e nada é vedado nesse sentido. O item confunde essa regra com o art. 35, §1º, da Lei 8.080, que reserva metade dos recursos ao quantitativo populacional.","fundamento":"LC nº 141/2012, art. 17; Lei nº 8.080/1990, art. 35, §1º.","macete":"Rateio combina critérios e mira reduzir desigualdade regional.","erroComum":"Reduzir o rateio ao número de habitantes.","comoBancaPensa":"Fecha com 'exclusivamente' e 'vedada' uma regra que é expressamente multifatorial."}},"SUS-105":{"cognitivo":{"motivo":"Fixar quem institui as Regiões de Saúde (Decreto 7.508/2011).","palavraCritica":"Estado"},"comentario":{"resolucao":"CERTO. Pelo art. 4º do Decreto 7.508/2011, as Regiões de Saúde são instituídas pelo ESTADO, em articulação com os municípios, respeitadas as diretrizes pactuadas na Comissão Intergestores Tripartite.","fundamento":"Decreto nº 7.508/2011, art. 4º e §§.","macete":"Região de Saúde: o Estado institui, com os municípios.","erroComum":"Atribuir à União a criação das regiões.","comoBancaPensa":"Item correto sobre competência."}},"SUS-106":{"cognitivo":{"motivo":"Cobrar a função financeira da Região de Saúde, além da territorial.","palavraCritica":"meramente descritiva ... apenas por critérios populacionais"},"comentario":{"resolucao":"ERRADO. O art. 6º do Decreto 7.508/2011 é expresso: as Regiões de Saúde SERÃO referência para as transferências de recursos entre os entes federativos. A região não é recorte apenas geográfico — é a unidade de planejamento e de financiamento da rede. E o rateio combina critérios epidemiológicos, demográficos, socioeconômicos e de capacidade de oferta, não só população.","fundamento":"Decreto nº 7.508/2011, arts. 5º e 6º; LC nº 141/2012, art. 17.","macete":"A Região de Saúde organiza o serviço e serve de base para o dinheiro.","erroComum":"Reduzir a Região de Saúde a divisão administrativa sem efeito financeiro.","comoBancaPensa":"Esvazia a função de um instituto com duplo fecho: 'meramente' e 'apenas'."}},"SUS-107":{"cognitivo":{"motivo":"Cobrar o quarto item do rol de portas de entrada, que a banca substitui.","palavraCritica":"hospitalares de alta complexidade"},"comentario":{"resolucao":"ERRADO. A quarta porta é a dos SERVIÇOS ESPECIAIS DE ACESSO ABERTO (art. 9º, IV) — e não serviços hospitalares de alta complexidade. A diferença é conceitual: porta de entrada é onde se ingressa no sistema sem encaminhamento prévio; alta complexidade hospitalar é destino de referência, acessado por regulação. Aceitar o item inverteria a lógica de ordenação da rede pela atenção primária.","fundamento":"Decreto nº 7.508/2011, art. 9º, I a IV.","macete":"Portas: primária, urgência, psicossocial e especiais de acesso aberto.","erroComum":"Incluir o hospital de alta complexidade como porta de entrada.","comoBancaPensa":"Substitui o item menos memorizado do rol por outro que soa importante."}},"SUS-108":{"cognitivo":{"motivo":"Cobrar que o Mapa da Saúde inclui a rede privada, e não só a pública.","palavraCritica":"e pela iniciativa privada"},"comentario":{"resolucao":"CERTO. É o art. 2º, III, do Decreto 7.508/2011. O detalhe cobrado é a inclusão da iniciativa privada: planejar exige conhecer toda a capacidade instalada do território, inclusive a que não pertence ao SUS, sob pena de superestimar carências ou duplicar investimentos. O Mapa é insumo do planejamento e da definição das Regiões de Saúde.","fundamento":"Decreto nº 7.508/2011, art. 2º, III.","macete":"O Mapa da Saúde enxerga tudo que existe no território — público e privado.","erroComum":"Restringir o Mapa da Saúde à rede pública.","comoBancaPensa":"Item correto cuja pegadinha correlata é suprimir a menção ao privado."}},"SUS-109":{"cognitivo":{"motivo":"Contraexemplo: RENASES e RENAME, par que a banca troca, aqui descrito corretamente.","palavraCritica":"ações e serviços"},"comentario":{"resolucao":"CERTO. É o art. 21 do Decreto 7.508/2011. A RENASES trata de AÇÕES E SERVIÇOS; a RENAME, de MEDICAMENTOS. Estados, DF e municípios podem adotar relações específicas e complementares, desde que financiadas com recursos próprios. A revisão da RENASES é feita pelo Ministério da Saúde, ouvidos o CNS e a CIT.","fundamento":"Decreto nº 7.508/2011, arts. 21 e 22.","macete":"RENASES = Serviços. RENAME = Medicamentos. A sigla entrega.","erroComum":"Marcar ERRADO por desconfiar de item que descreve corretamente uma das duas relações.","comoBancaPensa":"Apresenta corretamente um dos dois róis que costuma permutar."}},"SUS-110":{"cognitivo":{"motivo":"Contraexemplo: três requisitos cumulativos que parecem restrição indevida e constam do decreto.","palavraCritica":"pressupõe"},"comentario":{"resolucao":"CERTO. É o art. 28 do Decreto 7.508/2011, com os três requisitos cumulativos. Parecem restringir o acesso universal, mas o organizam: garantem que a dispensação siga vínculo assistencial, prescrição qualificada e base técnica. É dispositivo central nas ações judiciais de medicamentos, ao lado do art. 19-T da Lei 8.080.","fundamento":"Decreto nº 7.508/2011, art. 28, I a III.","macete":"Para receber o medicamento: estar no SUS, ter prescrição do SUS e estar na RENAME.","erroComum":"Marcar ERRADO por entender que os requisitos contrariam a universalidade.","comoBancaPensa":"Enumera condições que soam como barreiras, mas estão expressas na norma."}},"SUS-111":{"cognitivo":{"motivo":"Cobrar o conteúdo do COAP, instrumento que formaliza a organização regional.","palavraCritica":"individuais e solidárias"},"comentario":{"resolucao":"CERTO. É o art. 33 do Decreto 7.508/2011. O COAP é o instrumento jurídico que dá concretude à região: transforma pactuação política em obrigação contratual, com metas e indicadores. A expressão 'individuais e solidárias' é o núcleo — cada ente responde pelo seu, e todos respondem pelo conjunto, o que sustenta a responsabilização solidária reconhecida pelo STF em matéria de saúde.","fundamento":"Decreto nº 7.508/2011, arts. 33 a 35.","macete":"COAP: contrato entre entes, com metas, indicadores e responsabilidade solidária.","erroComum":"Tratar o COAP como convênio de repasse financeiro.","comoBancaPensa":"Item de literalidade sobre o instrumento menos estudado do decreto."}},"SUS-112":{"cognitivo":{"motivo":"Cobrar o sentido do planejamento no SUS, que é ascendente.","palavraCritica":"descendente"},"comentario":{"resolucao":"ERRADO. O planejamento da saúde é ASCENDENTE e integrado, do nível LOCAL até o federal (art. 15 do Decreto 7.508/2011, e art. 36 da Lei 8.080). O sentido não é detalhe: parte-se das necessidades identificadas no município, que sobem e se compatibilizam nas instâncias superiores. Inverter a direção contraria a descentralização com direção única e a lógica de aproximação do gestor ao cidadão.","fundamento":"Decreto nº 7.508/2011, art. 15; Lei nº 8.080/1990, art. 36.","macete":"Planejamento sobe: do local para o federal. Ascendente.","erroComum":"Aplicar ao SUS a lógica hierárquica de cima para baixo.","comoBancaPensa":"Inverte uma única palavra que define toda a lógica de planejamento do sistema."}},"SUS-113":{"cognitivo":{"motivo":"Cobrar a CIR, terceira comissão intergestores, criada pelo decreto.","palavraCritica":"vinculada à Secretaria Estadual de Saúde"},"comentario":{"resolucao":"CERTO. É o art. 30, III, e o art. 31 do Decreto 7.508/2011. A CIR completa o desenho: CIT no nacional, CIB no estadual e CIR no regional. A vinculação à Secretaria Estadual é administrativa e operacional — não subordina as decisões, que seguem sendo pactuadas por consenso entre os gestores participantes.","fundamento":"Decreto nº 7.508/2011, arts. 30 e 31.","macete":"CIT nacional, CIB estadual, CIR regional.","erroComum":"Desconhecer a CIR ou confundi-la com a CIB.","comoBancaPensa":"Cobra a comissão mais recente, menos presente nos materiais antigos."}},"SUS-114":{"cognitivo":{"motivo":"Cobrar a definição da quarta porta de entrada.","palavraCritica":"sem necessidade de encaminhamento prévio"},"comentario":{"resolucao":"CERTO. É o art. 2º, VI, do Decreto 7.508/2011. A característica definidora é a dispensa de encaminhamento — o usuário acessa diretamente. Exemplos típicos são os serviços de atenção a pessoas vivendo com HIV/aids e os de tuberculose, em que a barreira do encaminhamento comprometeria o diagnóstico precoce e o controle epidemiológico.","fundamento":"Decreto nº 7.508/2011, art. 2º, VI, e art. 9º, IV.","macete":"Acesso aberto = entra sem encaminhamento.","erroComum":"Confundir com serviços de alta complexidade, que exigem regulação.","comoBancaPensa":"Cobra o conceito que completa o rol de portas de entrada."}},"SUS-115":{"cognitivo":{"motivo":"Cobrar o papel ordenador da atenção primária na rede.","palavraCritica":"ordenar o acesso"},"comentario":{"resolucao":"CERTO. É a conjugação dos arts. 8º e 9º do Decreto 7.508/2011. O adjetivo 'ordenado' foi acrescido ao par 'universal e igualitário' justamente para expressar que há um caminho: entra-se pelas portas e avança-se conforme a complexidade. A atenção primária é a ordenadora da rede e coordenadora do cuidado — não é apenas o nível mais simples.","fundamento":"Decreto nº 7.508/2011, arts. 8º e 9º, parágrafo único.","macete":"Universal, igualitário e ORDENADO. A porta principal é a atenção primária.","erroComum":"Ler universalidade como direito de acessar qualquer serviço diretamente.","comoBancaPensa":"Item correto que concilia universalidade com organização da rede."}},"SUS-116":{"cognitivo":{"motivo":"Cobrar a autonomia do ente no planejamento, coerente com o modelo ascendente.","palavraCritica":"exclusivamente ... vedado"},"comentario":{"resolucao":"ERRADO. O planejamento é ascendente e parte das necessidades locais; o Plano de Saúde é o instrumento em que cada ente expressa suas prioridades, compatibilizando-as — não subordinando-as integralmente — às demais esferas. Vedar objetivos próprios ao município contrariaria a direção única em cada esfera e a própria lógica do art. 15 do decreto.","fundamento":"Decreto nº 7.508/2011, arts. 15 a 19; Lei nº 8.080/1990, art. 36.","macete":"Compatibilizar não é obedecer. Cada ente planeja o seu.","erroComum":"Confundir integração de planos com subordinação hierárquica.","comoBancaPensa":"Transforma compatibilização em submissão, com 'exclusivamente' e 'vedado'."}},"SUS-117":{"cognitivo":{"motivo":"Cobrar o prazo da notificação imediata, número que a banca altera.","palavraCritica":"quarenta e oito horas"},"comentario":{"resolucao":"ERRADO. O prazo da notificação compulsória IMEDIATA é de até 24 HORAS a partir do conhecimento do caso. A notificação semanal é a que se faz em até 7 dias. O prazo de 48 horas não existe nessa classificação — é número inventado, que se aproxima o bastante do correto para parecer plausível.","fundamento":"Portaria de Consolidação nº 4/2017 (MS) — notificação compulsória.","macete":"Imediata = 24 horas. Semanal = 7 dias. Só esses dois prazos.","erroComum":"Aceitar 48 horas por soar razoável para um prazo 'urgente'.","comoBancaPensa":"Insere prazo intermediário entre os dois verdadeiros, dificultando a rejeição imediata."}},"SUS-118":{"cognitivo":{"motivo":"Contraexemplo: prazo numérico exato e verdadeiro, logo após um item cujo número era falso.","palavraCritica":"sete dias"},"comentario":{"resolucao":"CERTO. A notificação semanal é feita em até 7 dias a partir do conhecimento do caso. Reserva-se a doenças e agravos que não exigem resposta imediata de controle — hanseníase e tuberculose, por exemplo. A imediata, de 24 horas, cobre situações com potencial de disseminação rápida ou gravidade elevada.","fundamento":"Portaria de Consolidação nº 4/2017 (MS).","macete":"Semanal é literal: uma semana, 7 dias.","erroComum":"Marcar ERRADO por desconfiança generalizada de prazos.","comoBancaPensa":"Cobra o número correto para separar quem sabe de quem rejeita todo prazo."}},"SUS-119":{"cognitivo":{"motivo":"Cobrar o alcance subjetivo do dever de notificar.","palavraCritica":"apenas para médicos"},"comentario":{"resolucao":"ERRADO. A notificação compulsória é obrigatória para MÉDICOS, OUTROS PROFISSIONAIS DE SAÚDE e responsáveis por organizações e estabelecimentos públicos e privados de saúde e de ensino, na forma da Lei 6.259/1975 e das portarias do Ministério da Saúde. Restringi-la ao médico esvaziaria a vigilância — o fisioterapeuta, o enfermeiro e o gestor do serviço também respondem por esse dever.","fundamento":"Lei nº 6.259/1975, art. 8º; Portaria de Consolidação nº 4/2017 (MS).","macete":"Notificar é dever de todo profissional de saúde, não só do médico.","erroComum":"Atribuir o dever exclusivamente à categoria médica.","comoBancaPensa":"Restringe a um só profissional um dever que a norma distribui amplamente."}},"SUS-120":{"cognitivo":{"motivo":"Fixar o prazo da notificação imediata.","palavraCritica":"vinte e quatro horas"},"comentario":{"resolucao":"ERRADO. Notificação compulsória IMEDIATA é feita em até 24 horas; sete dias é o prazo da notificação SEMANAL. Violência sexual e tentativa de suicídio são de notificação imediata, porque exigem acionamento rápido da rede de proteção e cuidado — o item acerta a classificação e erra o prazo.","fundamento":"Portaria de Consolidação nº 4/2017 (MS); Lei nº 10.778/2003; Lei nº 13.931/2019.","macete":"Imediata = 24 h. Semanal = 7 dias.","erroComum":"Não ligar a palavra 'imediata' ao prazo de 24 horas.","comoBancaPensa":"Classificação certa com prazo de outra categoria."}},"SUS-121":{"cognitivo":{"motivo":"Separar notificação imediata de semanal.","palavraCritica":"semanal"},"comentario":{"resolucao":"CERTO. A hanseníase é de notificação compulsória SEMANAL (até 7 dias). A transmissão é lenta e exige contato prolongado, o que dispensa resposta em 24 horas; o importante é o diagnóstico e o exame dos contatos.","fundamento":"Portaria de Consolidação nº 4/2017 (MS).","macete":"Imediata = 24 h; semanal = 7 dias. Hanseníase: semanal.","erroComum":"Achar que toda doença transmissível é de notificação imediata.","comoBancaPensa":"Item correto que exige saber a categoria."}},"SUS-122":{"cognitivo":{"motivo":"Contraexemplo: a definição correta de vigilância epidemiológica, após o item que a trocou.","palavraCritica":"recomendar e adotar as medidas de prevenção e controle"},"comentario":{"resolucao":"CERTO. É a redação do art. 6º, §2º, da Lei 8.080/1990. A vigilância epidemiológica não apenas observa: ela RECOMENDA E ADOTA medidas. O verbo duplo é o que a distingue de um mero sistema de informação — há poder de intervenção sobre a ocorrência de doenças e agravos.","fundamento":"Lei nº 8.080/1990, art. 6º, §2º.","macete":"Epidemiológica: conhece, detecta, previne — e age.","erroComum":"Trocá-la pela definição de vigilância sanitária.","comoBancaPensa":"Apresenta a definição no rótulo certo, após tê-la deslocado em outro item."}},"SUS-123":{"cognitivo":{"motivo":"Cobrar a função de cada sistema pela inversão.","palavraCritica":"SIM ... notificação compulsória"},"comentario":{"resolucao":"ERRADO. Está invertido. O SINAN registra os agravos de NOTIFICAÇÃO compulsória — o próprio nome traz 'Agravos de Notificação'. O SIM é o Sistema de Informação sobre MORTALIDADE, alimentado pelas declarações de óbito. Completam o conjunto o SINASC (nascidos vivos), o CNES (estabelecimentos) e o SIA/SIH (produção ambulatorial e hospitalar).","fundamento":"Sistemas de informação em saúde do SUS — SINAN, SIM e SINASC.","macete":"SINAN = Agravos de Notificação. SIM = Mortalidade. SINASC = Nascidos vivos.","erroComum":"Trocar as siglas por não desdobrar o que cada letra significa.","comoBancaPensa":"Permuta dois sistemas cujas siglas o candidato reconhece sem saber decompor."}},"SUS-124":{"cognitivo":{"motivo":"Fixar o momento da notificação.","palavraCritica":"suspeita"},"comentario":{"resolucao":"CERTO. Notifica-se a SUSPEITA, justamente para permitir resposta rápida da vigilância. Esperar o exame atrasaria o bloqueio da transmissão e a investigação.","fundamento":"Lei nº 6.259/1975; Portaria de Consolidação nº 4/2017 (MS).","macete":"Suspeitou, notificou.","erroComum":"Achar que só se notifica caso confirmado.","comoBancaPensa":"Item correto e de alto valor prático."}},"SUS-125":{"cognitivo":{"motivo":"Cobrar as hipóteses em que o evento — e não a doença — determina a notificação imediata.","palavraCritica":"ainda que a doença envolvida não conste isoladamente da lista"},"comentario":{"resolucao":"CERTO. A lógica é do EVENTO, não apenas da doença. Agravo inusitado, reaparecimento de doença erradicada, surtos e epidemias exigem notificação imediata pelo que representam epidemiologicamente — mudança de padrão —, ainda que a doença isolada seja de notificação semanal. É o que permite detectar precocemente o inesperado.","fundamento":"Portaria de Consolidação nº 4/2017 (MS) — eventos de saúde pública.","macete":"Mudou o padrão — surto, agravo inusitado, doença que voltou? Notificação imediata.","erroComum":"Consultar apenas a lista de doenças e ignorar a categoria de eventos.","comoBancaPensa":"Item correto que exige distinguir notificação por doença de notificação por evento."}},"SUS-126":{"cognitivo":{"motivo":"Treinar zoonoses de notificação imediata — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"febre amarela e leptospirose"},"comentario":{"resolucao":"C. Na lista nacional, febre amarela e leptospirose aparecem entre as zoonoses de notificação imediata nos casos humanos indicados (o material adotou essa combinação). Esquistossomose e leishmanioses são de notificação semanal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-127":{"cognitivo":{"motivo":"Treinar violência contra a pessoa idosa — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"notificação compulsória à autoridade sanitária"},"comentario":{"resolucao":"D. Pelo Estatuto da Pessoa Idosa, a suspeita ou confirmação de violência contra idoso é de notificação compulsória pelos serviços de saúde à autoridade sanitária, além da comunicação a órgãos como Ministério Público, delegacia e conselhos do idoso. Não se aguarda confirmação nem se 'intima' a família.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Suspeitou de violência contra idoso, criança ou mulher: notifica.","erroComum":"Esperar confirmar para notificar.","comoBancaPensa":"Dever legal do profissional."}},"SUS-128":{"cognitivo":{"motivo":"Treinar violência contra a pessoa idosa — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"suspeita ou confirmação"},"comentario":{"resolucao":"CERTO. O Estatuto (art. 19) impõe a notificação compulsória da suspeita ou confirmação; a notificação é instrumento de vigilância e proteção, não de investigação policial, e não depende de prova.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Suspeitou de violência contra idoso, criança ou mulher: notifica.","erroComum":"Esperar confirmar para notificar.","comoBancaPensa":"Dever legal do profissional."}},"SUS-129":{"cognitivo":{"motivo":"Treinar agravo não notificável — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"pneumonia nosocomial"},"comentario":{"resolucao":"C. Infecção pelo HTLV, dengue, sífilis e hepatites virais estão na lista nacional de notificação compulsória; a pneumonia nosocomial, isoladamente, não.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-130":{"cognitivo":{"motivo":"Treinar acidente de trabalho com material biológico — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"semanal — 7 dias"},"comentario":{"resolucao":"C. O acidente de trabalho com exposição a material biológico é de notificação compulsória SEMANAL: até 7 dias a partir do conhecimento.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-131":{"cognitivo":{"motivo":"Treinar acidente de trabalho com material biológico — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"imediata"},"comentario":{"resolucao":"ERRADO. É de notificação SEMANAL (até 7 dias). A imediata (24 h) vale, por exemplo, para acidente de trabalho grave, fatal e em crianças e adolescentes — distinção cobrada com frequência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-132":{"cognitivo":{"motivo":"Treinar notificação compulsória e atenção primária — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"qualquer cidadão pode comunicar"},"comentario":{"resolucao":"C (pelo texto da norma; a tabela e o comentário divergem). Só a II está correta: a notificação compulsória é a comunicação obrigatória da ocorrência de doença, agravo ou evento à autoridade sanitária, feita por profissional de saúde ou por qualquer cidadão. I erra (cada ACS acompanha no máximo 750 pessoas); III erra (a USF integra a atenção primária).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Profissional é obrigado; cidadão pode.","erroComum":"Aceitar o número de 22 mil pessoas por ACS.","comoBancaPensa":"Conceito da Portaria."}},"SUS-133":{"cognitivo":{"motivo":"Treinar quem pode notificar — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"qualquer cidadão"},"comentario":{"resolucao":"C. A comunicação de doença, agravo ou evento de notificação compulsória pode ser feita por qualquer cidadão que deles tenha conhecimento; para médicos, profissionais de saúde e responsáveis por estabelecimentos ela é obrigatória. AVC não é notificável; a imediata é em até 24 h; nem toda doença transmissível é notificável.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-134":{"cognitivo":{"motivo":"Treinar quem pode notificar — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"exclusiva de médicos e enfermeiros"},"comentario":{"resolucao":"ERRADO. A obrigação alcança médicos, outros profissionais de saúde e responsáveis pelos estabelecimentos públicos e privados (e de ensino); qualquer cidadão PODE comunicar. O fisioterapeuta também é obrigado a notificar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-135":{"cognitivo":{"motivo":"Treinar lista nacional — incorreta — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"Alzheimer não é notificável"},"comentario":{"resolucao":"B (pelo comentário; a tabela traz D). Tuberculose, hanseníase e toxoplasmose gestacional constam da lista nacional; a doença de Alzheimer não é de notificação compulsória.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-136":{"cognitivo":{"motivo":"Treinar agravos de notificação imediata — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"botulismo, violência sexual, tentativa de suicídio"},"comentario":{"resolucao":"D (I, III e IV). Botulismo, violência sexual e tentativa de suicídio são de notificação imediata (as duas últimas à autoridade municipal); a hanseníase é de notificação semanal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-137":{"cognitivo":{"motivo":"Treinar agravos de notificação imediata — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"imediata à autoridade municipal"},"comentario":{"resolucao":"CERTO. A imediaticidade permite a profilaxia (IST, HIV, contracepção de emergência) e a proteção do paciente; outras violências interpessoais são notificadas semanalmente.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-138":{"cognitivo":{"motivo":"Treinar o que notificar em até 24 h — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"sarampo suspeito e tentativa de suicídio"},"comentario":{"resolucao":"A. Devem ser notificados em até 24 h o caso SUSPEITO de sarampo (não se espera confirmação) e a tentativa de suicídio. Tuberculose, hepatite viral e violência doméstica são de notificação semanal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-139":{"cognitivo":{"motivo":"Treinar meningite bacteriana — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"SMS e SES em até 24 h"},"comentario":{"resolucao":"D. A meningite é de notificação imediata (24 h) às Secretarias Municipal e Estadual de Saúde, para investigação de contatos e quimioprofilaxia.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-140":{"cognitivo":{"motivo":"Treinar violência doméstica — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"semanal — 7 dias"},"comentario":{"resolucao":"A. A violência doméstica/interpessoal (sem violência sexual) é de notificação semanal: em até 7 dias a partir do conhecimento.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-141":{"cognitivo":{"motivo":"Treinar botulismo — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"imediata"},"comentario":{"resolucao":"B. O botulismo é de notificação imediata; esquistossomose, hepatites virais e hanseníase são semanais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-142":{"cognitivo":{"motivo":"Treinar conceitos da Portaria de Consolidação nº 4/2017 — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"epizootia, agravo, evento, doença"},"comentario":{"resolucao":"D (3 - 1 - 4 - 2). A pista de cada lacuna: falou em animal, é epizootia; falou em dano por acidente, intoxicação ou violência, é agravo; falou em ameaça coletiva (surto, causa desconhecida), é evento de saúde pública; sobrou a definição de enfermidade, que é doença.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Agravo = dano (acidente, violência); doença = enfermidade.","erroComum":"Trocar agravo e evento.","comoBancaPensa":"Definições normativas."}},"SUS-143":{"cognitivo":{"motivo":"Treinar tipos de notificação — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"imediata, semanal e negativa"},"comentario":{"resolucao":"A (2 - 1 - 3). O prazo de sete dias identifica a semanal; o de 24 horas, a imediata; e a comunicação de que 'nada houve' na semana epidemiológica é a negativa, que prova que a vigilância está funcionando.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-144":{"cognitivo":{"motivo":"Treinar tipos de notificação — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"negativa"},"comentario":{"resolucao":"CERTO. Ela demonstra que a vigilância está ativa ('silêncio epidemiológico' não é ausência de notificação); é exigida das unidades sentinelas e notificantes.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-145":{"cognitivo":{"motivo":"Treinar doença de Chagas crônica — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"Portaria nº 264/2020"},"comentario":{"resolucao":"A. A Portaria GM/MS nº 264/2020 incluiu a doença de Chagas crônica na lista nacional de notificação compulsória (de notificação semanal).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-146":{"cognitivo":{"motivo":"Treinar sINAN — finalidade — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"SINAN registra agravos de notificação"},"comentario":{"resolucao":"ERRADO. O SINAN armazena e processa as notificações e investigações de doenças e agravos da lista de notificação compulsória. Condições de moradia, saneamento, situação de saúde e produção das equipes eram registradas no SIAB (hoje e-SUS APS/SISAB).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"SINAN = agravos notificáveis; SIM = óbitos; SINASC = nascidos vivos; SIAB/SISAB = atenção básica.","erroComum":"Trocar SINAN por SIAB.","comoBancaPensa":"Sistemas de informação."}},"SUS-147":{"cognitivo":{"motivo":"Treinar sINAN — finalidade — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"Declaração de Óbito"},"comentario":{"resolucao":"CERTO. A DO alimenta o SIM; a DNV, o SINASC; a ficha de notificação/investigação, o SINAN; a AIH, o SIH; e o BPA/APAC, o SIA — documentos-base clássicos em prova.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"SINAN = agravos notificáveis; SIM = óbitos; SINASC = nascidos vivos; SIAB/SISAB = atenção básica.","erroComum":"Trocar SINAN por SIAB.","comoBancaPensa":"Sistemas de informação."}},"SUS-148":{"cognitivo":{"motivo":"Treinar sRAG por coronavírus — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"imediata (24 h)"},"comentario":{"resolucao":"ERRADO. A síndrome respiratória aguda grave associada a coronavírus é de notificação IMEDIATA (até 24 h), às três esferas conforme a lista; não é 48 h nem apenas ao município.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Usar 48 h.","comoBancaPensa":"Prazo e destinatário."}},"SUS-149":{"cognitivo":{"motivo":"Treinar sífilis — tratamento após um teste reagente — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"vítimas de violência sexual"},"comentario":{"resolucao":"B. O Ministério da Saúde recomenda iniciar o tratamento após um único teste reagente em grupos como gestantes, vítimas de violência sexual, pessoas com risco de perda de seguimento e com sinais de sífilis primária ou secundária.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Um teste reagente basta em gestante e violência sexual.","erroComum":"Escolher sífilis latente.","comoBancaPensa":"Conduta do MS."}},"SUS-150":{"cognitivo":{"motivo":"Treinar óbito por dengue — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"imediata — 24 h"},"comentario":{"resolucao":"A. Óbito por dengue (ou caso grave/com sinais de alarme) é de notificação imediata, em até 24 horas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-151":{"cognitivo":{"motivo":"Treinar sNVE — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"Lei 6.259/1975"},"comentario":{"resolucao":"B. A Lei nº 6.259/1975 e o Decreto nº 78.231/1976 organizaram o Sistema Nacional de Vigilância Epidemiológica (SNVE) e tornaram obrigatória a notificação de doenças.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Lei 6.259/75 = vigilância e notificação.","erroComum":"Escolher o RSI.","comoBancaPensa":"Marco legal."}},"SUS-152":{"cognitivo":{"motivo":"Treinar óbito materno — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"durante a gestação ou até 42 dias"},"comentario":{"resolucao":"D. Óbito materno é a morte de mulher durante a gestação ou até 42 dias após o término dela, por qualquer causa relacionada ou agravada pela gravidez ou por medidas a ela relacionadas, excluídas as causas acidentais ou incidentais. Inclui transtornos mentais do puerpério.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Materno: gestação + 42 dias, causa ligada à gravidez.","erroComum":"Incluir causas acidentais.","comoBancaPensa":"Conceito de indicador."}},"SUS-153":{"cognitivo":{"motivo":"Treinar óbito materno — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"42 dias"},"comentario":{"resolucao":"CERTO. É a definição da CID-10 usada no cálculo da razão de mortalidade materna (por 100 mil nascidos vivos); mortes entre 43 dias e 1 ano são 'tardias'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Materno: gestação + 42 dias, causa ligada à gravidez.","erroComum":"Incluir causas acidentais.","comoBancaPensa":"Conceito de indicador."}},"SUS-154":{"cognitivo":{"motivo":"Treinar zika em gestante — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"imediata"},"comentario":{"resolucao":"C (pelo texto da norma; o comentário traz E). Doença aguda pelo vírus Zika em gestante é de notificação compulsória IMEDIATA; casos suspeitos devem ser notificados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-155":{"cognitivo":{"motivo":"Treinar sRAG — 24 h — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"SRAG associada a coronavírus"},"comentario":{"resolucao":"E. A SRAG associada a coronavírus é de notificação em até 24 h a partir da suspeita; HIV, Chagas crônica, esquistossomose e hanseníase são semanais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-156":{"cognitivo":{"motivo":"Treinar sarampo — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"viral, aerossóis, pródromo"},"comentario":{"resolucao":"CERTO. O sarampo é doença viral (gênero Morbillivirus, família Paramyxoviridae), aguda, potencialmente grave, transmitida por aerossóis e extremamente contagiosa; o pródromo traz febre, tosse, coriza, conjuntivite e fotofobia. É de notificação imediata.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Sarampo suspeito: notifica em 24 h.","erroComum":"Esperar o exantema para notificar.","comoBancaPensa":"Item conceitual."}},"SUS-157":{"cognitivo":{"motivo":"Treinar doença notificável — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"hepatites virais"},"comentario":{"resolucao":"A. As hepatites virais são de notificação compulsória; mononucleose, herpes zóster, herpes simples e sialoadenite infecciosa não.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Confundir notificação imediata e semanal.","comoBancaPensa":"Prazo e destinatário da notificação."}},"SUS-158":{"cognitivo":{"motivo":"Treinar motivação da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"romper com o modelo excludente"},"comentario":{"resolucao":"A. A Reforma Sanitária buscava romper com o modelo excludente e previdenciário (só o trabalhador formal tinha assistência pelo INAMPS), propondo um sistema público e universal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-159":{"cognitivo":{"motivo":"Treinar 8ª Conferência Nacional de Saúde — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"marco dos princípios do SUS"},"comentario":{"resolucao":"D. A VIII Conferência Nacional de Saúde (1986), primeira aberta à sociedade civil, delineou os princípios que orientariam o SUS; seu relatório embasou o capítulo da saúde na Constituição de 1988.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-160":{"cognitivo":{"motivo":"Treinar 8ª Conferência Nacional de Saúde — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"1986"},"comentario":{"resolucao":"CERTO. Com o lema 'Democracia é Saúde', reuniu cerca de 4 mil participantes; firmou a saúde como direito de todos e dever do Estado, o conceito ampliado de saúde e a proposta do sistema único.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-161":{"cognitivo":{"motivo":"Treinar modelos de atenção — campanhista — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"campanhas verticais contra epidemias"},"comentario":{"resolucao":"C (F, F, F, V). O modelo campanhista (início do séc. XX, Oswaldo Cruz) era de intervenções verticais, centralizadas e às vezes autoritárias contra epidemias e endemias, não assistência individual hospitalocêntrica; o SUS não adota o modelo privatista; o perfil crônico atual pede modelos integrais, não campanhistas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-162":{"cognitivo":{"motivo":"Treinar modelos de atenção — campanhista — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"assistência médica individual"},"comentario":{"resolucao":"ERRADO. O campanhista era coletivo, vertical e centralizado (campanhas contra febre amarela, peste, varíola, com polícia sanitária). O modelo médico-assistencial privatista, individual e hospitalocêntrico, é que se consolidou com INPS e INAMPS no regime militar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-163":{"cognitivo":{"motivo":"Treinar alma-Ata (1978) — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"atenção primária"},"comentario":{"resolucao":"A (I e II verdadeiras, II justifica I). A Conferência de Alma-Ata (1978) é marco da atenção primária à saúde ('Saúde para todos no ano 2000') e trouxe a discussão da reestruturação dos sistemas de saúde, influenciando a APS brasileira.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-164":{"cognitivo":{"motivo":"Treinar conquista da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"criação do SUS"},"comentario":{"resolucao":"B. A grande conquista da Reforma Sanitária foi a criação do SUS (CF/88 e Leis Orgânicas). As Conferências já existiam desde 1941; CAPs e INAMPS pertencem ao modelo previdenciário anterior.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-165":{"cognitivo":{"motivo":"Treinar papel da 8ª CNS — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"princípios do SUS"},"comentario":{"resolucao":"B. A 8ª CNS propôs universalidade, equidade, integralidade e participação social, base conceitual do SUS. Não criou formalmente o SUS (CF/88 e Lei 8.080/90), nem a ESF (1994), nem os percentuais mínimos (EC 29/2000 e LC 141/2012), nem gestão centralizada.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-166":{"cognitivo":{"motivo":"Treinar papel da 8ª CNS — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"criou formalmente o SUS"},"comentario":{"resolucao":"ERRADO. O SUS foi criado pela Constituição de 1988 e regulamentado pelas Leis 8.080 e 8.142 de 1990; os mínimos de aplicação vieram com a EC 29/2000 e a LC 141/2012. A 8ª CNS formulou propostas e princípios.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-167":{"cognitivo":{"motivo":"Treinar características da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"artífices em posições acadêmicas e de gestão"},"comentario":{"resolucao":"E. Vários artífices da Reforma Sanitária ocuparam posições centrais na saúde coletiva acadêmica e em cargos-chave das políticas de saúde (Arouca, Hésio Cordeiro). A RSB ocorreu em período de crise das políticas sociais no mundo (neoliberalismo); a 8ª CNS foi convocada pelo Executivo (Ministério da Saúde); o projeto não é considerado implantado em plenitude; o movimento foi plural, não predominantemente sindical.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-168":{"cognitivo":{"motivo":"Treinar momento culminante da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"8ª Conferência"},"comentario":{"resolucao":"E. Na formulação da banca, a 8ª CNS foi o momento culminante do movimento, ampliando a participação social e consolidando a Reforma Sanitária como projeto da sociedade; a CF/88 institucionalizou suas propostas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-169":{"cognitivo":{"motivo":"Treinar fatos da história da saúde — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"IAPs na Era Vargas"},"comentario":{"resolucao":"D. Os IAPs foram criados na Era Vargas (a partir de 1933). As Santas Casas surgiram no período colonial (1543, Santos); a Revolta da Vacina (1904) foi contra a vacinação obrigatória contra a VARÍOLA; o Ministério da Educação e Saúde é de 1930 (Vargas).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-170":{"cognitivo":{"motivo":"Treinar fatos da história da saúde — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"varíola"},"comentario":{"resolucao":"CERTO. A lei da vacinação obrigatória (1904), somada às reformas urbanas e à truculência das brigadas sanitárias, provocou a revolta; o governo decretou estado de sítio e revogou a obrigatoriedade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-171":{"cognitivo":{"motivo":"Treinar construção histórica do SUS — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"CF/88 universaliza"},"comentario":{"resolucao":"A (F – V – F). O SUS não foi criado na Era Vargas (que expandiu a previdência por categorias); a CF/88 introduziu a universalização e a rede regionalizada e hierarquizada; o SUDS (1987) PRECEDEU o SUS como estratégia de transição, não é seu destino 'em aberto'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-172":{"cognitivo":{"motivo":"Treinar principal proposta da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"universalização e direitos sociais"},"comentario":{"resolucao":"E. Segundo o CFESS (2011), a principal proposta da Reforma Sanitária é a defesa da universalização das políticas sociais e a garantia dos direitos sociais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-173":{"cognitivo":{"motivo":"Treinar princípios da construção do SUS — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"integralidade, descentralização, universalização"},"comentario":{"resolucao":"D. A organização do SUS apoia-se em integralidade, descentralização e universalização. Centralização, focalização e desfinanciamento são opostos ao projeto.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-174":{"cognitivo":{"motivo":"Treinar cebes, Abrasco, 8ª CNS e Arouca — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"conceito ampliado de saúde"},"comentario":{"resolucao":"C (I e III, pelo gabarito). Cebes (1976) e Abrasco (1979) foram centrais para a saúde coletiva; Sérgio Arouca foi o principal articulador do movimento sanitário. II erra: a 8ª CNS não tratou 'prioritariamente' de campanhas contra hanseníase e tuberculose, mas da saúde como direito, da reformulação do sistema e do financiamento.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-175":{"cognitivo":{"motivo":"Treinar iNPS (1966) — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"unificação dos IAPs"},"comentario":{"resolucao":"D. Em 1966 os IAPs foram unificados no Instituto Nacional de Previdência Social (INPS). As CAPs são de 1923, os IAPs de 1933, o INAMPS de 1977 e o SUDS de 1987.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-176":{"cognitivo":{"motivo":"Treinar iNPS (1966) — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"1977"},"comentario":{"resolucao":"CERTO. O INAMPS (Lei 6.439/1977, SINPAS) separou a assistência médica do INPS; atendia apenas contribuintes e comprava serviços privados — modelo médico-assistencial privatista.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-177":{"cognitivo":{"motivo":"Treinar regulação dos serviços privados — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"relevância pública — regulamentação, fiscalização e controle"},"comentario":{"resolucao":"ERRADO. A CF (art. 197) diz que as ações e serviços de saúde são de relevância pública, cabendo ao Poder Público dispor sobre sua regulamentação, fiscalização e controle — inclusive dos serviços privados, que não são 'autorregulamentados'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Saúde é de relevância pública, também no setor privado.","erroComum":"Aceitar a autorregulação do privado.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-178":{"cognitivo":{"motivo":"Treinar competências do SUS — meio ambiente — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"colaborar na proteção do meio ambiente"},"comentario":{"resolucao":"CERTO. Entre as competências do SUS no art. 200 da CF está colaborar na proteção do meio ambiente, nele compreendido o do trabalho (inciso VIII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Art. 200, VIII: meio ambiente, incluído o do trabalho.","erroComum":"Achar que meio ambiente não é tema do SUS.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-179":{"cognitivo":{"motivo":"Treinar diretrizes do SUS — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"descentralização, não centralização"},"comentario":{"resolucao":"ERRADO. As diretrizes constitucionais do SUS (art. 198) são descentralização com direção única em cada esfera, atendimento integral e participação da comunidade; 'centralização das ações' contraria a diretriz.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Diretriz é DEScentralizar.","erroComum":"Ler 'municipalização' e aceitar.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-180":{"cognitivo":{"motivo":"Treinar seguridade social — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"saúde, previdência e assistência"},"comentario":{"resolucao":"ERRADO. A seguridade social (CF, art. 194) compreende ações destinadas a assegurar os direitos relativos à SAÚDE, à PREVIDÊNCIA e à ASSISTÊNCIA SOCIAL — não ao 'trabalho'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Seguridade = saúde + previdência + assistência.","erroComum":"Trocar previdência por trabalho.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-181":{"cognitivo":{"motivo":"Treinar sUDS — exceto — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"participação social não era objetivo do SUDS"},"comentario":{"resolucao":"A (exceto). Entre os objetivos do SUDS (1987) estavam a descentralização, a integralidade, a implementação de distritos sanitários e a universalização com equidade; a 'promoção da participação social' não figurava entre eles na formulação da banca.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-182":{"cognitivo":{"motivo":"Treinar condução da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"sociedade civil"},"comentario":{"resolucao":"B. A Reforma Sanitária foi conduzida pela sociedade civil (movimento sanitário: intelectuais, profissionais, movimentos populares), e não monopolizada por partidos políticos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-183":{"cognitivo":{"motivo":"Treinar lei Eloy Chaves — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"CAP dos ferroviários (1923)"},"comentario":{"resolucao":"C. A Lei Eloy Chaves (Decreto nº 4.682/1923) criou a Caixa de Aposentadoria e Pensão dos ferroviários e é o marco inicial da Previdência Social no Brasil.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-184":{"cognitivo":{"motivo":"Treinar lei Eloy Chaves — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"por empresa"},"comentario":{"resolucao":"CERTO. CAPs: por empresa, bipartite; IAPs (1933 em diante): por categoria (marítimos, comerciários, bancários…), tripartite; INPS (1966) unificou os IAPs.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-185":{"cognitivo":{"motivo":"Treinar 8ª CNS e SUDS — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"8ª Conferência (1986)"},"comentario":{"resolucao":"E. A 8ª Conferência Nacional de Saúde (1986) teve como desdobramentos o SUDS e as bases do capítulo da saúde na Constituição, propagando a Reforma Sanitária.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-186":{"cognitivo":{"motivo":"Treinar iNAMPS sucede o INPS — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"INAMPS | INPS"},"comentario":{"resolucao":"B. Em 1977 foi criado o INAMPS, que assumiu a assistência médica antes vinculada ao INPS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-187":{"cognitivo":{"motivo":"Treinar hésio Cordeiro — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"presidente do INAMPS e sanitarista"},"comentario":{"resolucao":"B. Hésio de Albuquerque Cordeiro, sanitarista e presidente do INAMPS (1985–1988), levou o órgão a incorporar os princípios do movimento sanitário e ajudou a formular a proposta do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-188":{"cognitivo":{"motivo":"Treinar movimento que buscou equilibrar desigualdades — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"Reforma Sanitária"},"comentario":{"resolucao":"E. O movimento que se opôs ao modelo em que a assistência dependia do vínculo previdenciário foi a Reforma Sanitária.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-189":{"cognitivo":{"motivo":"Treinar marcos históricos — Revolta da Vacina e Lei Eloy Chaves — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"afirmativas 1 e 2"},"comentario":{"resolucao":"B (1 e 2, pelo gabarito). A Revolta da Vacina (1904) foi primeira grande interferência popular nas questões sanitárias; a Lei Eloy Chaves (1923) vinculou a assistência às CAPs. A 3 erra ao dizer que as Santas Casas eram a 'única' opção para os não contribuintes (havia serviços públicos de saúde pública e filantropia diversa).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-190":{"cognitivo":{"motivo":"Treinar origem da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"Reforma Sanitária precede as AIS"},"comentario":{"resolucao":"ERRADO. O movimento da Reforma Sanitária nasceu nos anos 1970 (Cebes, Abrasco, departamentos de medicina preventiva), antes das Ações Integradas de Saúde (AIS, 1983), que vigoraram até o SUDS (1987) — não foram encerradas 'no ano seguinte'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"RSB (anos 70) → AIS (1983) → SUDS (1987).","erroComum":"Inverter a cronologia.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-191":{"cognitivo":{"motivo":"Treinar reforma Sanitária × modelo biomédico — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"superar o modelo biomédico"},"comentario":{"resolucao":"ERRADO. Os expoentes da Reforma Sanitária CRITICAVAM o modelo biomédico hegemônico e defenderam o conceito ampliado de saúde, com determinantes sociais; o SUS incorporou esse paradigma, não o biomédico.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"RSB = contra o modelo biomédico.","erroComum":"Aceitar por citar a criação do SUS.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-192":{"cognitivo":{"motivo":"Treinar iAPs nos anos 1930 — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"riscos de categorias estratégicas"},"comentario":{"resolucao":"A. Os IAPs cobriam riscos ligados à perda da capacidade de trabalho de categorias estratégicas (marítimos, comerciários, bancários, industriários). Eram tripartites; eram estatais (não clandestinos); a seguridade social (tripé) só surge na CF/88.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-193":{"cognitivo":{"motivo":"Treinar conceito de saúde na Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"todas corretas"},"comentario":{"resolucao":"E (todas). O conceito ampliado de saúde da 8ª CNS reúne exatamente esses quatro elementos, ou seja, nenhum item destoa do ideário do movimento sanitário — que se opunha ao modelo biomédico e individual.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-194":{"cognitivo":{"motivo":"Treinar projeto da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"concepção de saúde e serviço público universal"},"comentario":{"resolucao":"D. O projeto da Reforma Sanitária tem duas características centrais: uma inovadora concepção de saúde e a constituição de um serviço público e estatal com acesso universal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-195":{"cognitivo":{"motivo":"Treinar 8ª CNS — saúde como direito — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"direito de cidadania e dever do Estado"},"comentario":{"resolucao":"A. A 8ª CNS consolidou a saúde como direito de cidadania e dever do Estado.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-196":{"cognitivo":{"motivo":"Treinar reforma Sanitária — incorreta — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"valor individual e privatista"},"comentario":{"resolucao":"D (incorreta). O referencial ético da Reforma Sanitária era a saúde como direito social e valor coletivo, não individual e privatista. As demais estão corretas (transição democrática, intelectuais e profissionais, determinação social, departamentos de medicina preventiva).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-197":{"cognitivo":{"motivo":"Treinar reforma sanitária e antimanicomial — datação — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"anos 1970, não fim dos 60"},"comentario":{"resolucao":"ERRADO (gabarito oficial). Os movimentos da reforma sanitária e da reforma psiquiátrica/antimanicomial emergiram na segunda metade da década de 1970 (o Movimento dos Trabalhadores em Saúde Mental é de 1978), e não no final da década de 1960.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Anos 70: Cebes, Abrasco, MTSM.","erroComum":"Aceitar 'fim dos anos 60'.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-198":{"cognitivo":{"motivo":"Treinar reforma sanitária × psiquiátrica — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"a sanitária legitimou a psiquiátrica"},"comentario":{"resolucao":"ERRADO (gabarito oficial). Os processos são contemporâneos, mas foi a reforma SANITÁRIA que deu base e legitimidade à reforma psiquiátrica (dentro do projeto do SUS), e não o contrário, como sugere o item.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Sanitária abre caminho; psiquiátrica segue.","erroComum":"Inverter a relação de influência.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-199":{"cognitivo":{"motivo":"Treinar reforma Sanitária — conceito — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"ampla articulação de atores sociais"},"comentario":{"resolucao":"E. A Reforma Sanitária foi movimento de ampla articulação de atores sociais que pautou nova organização do sistema de saúde. Não era plataforma de governo, não defendia especialização individual nem 'sistema complementar', e não descreve a criação do INAMPS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-200":{"cognitivo":{"motivo":"Treinar propostas da Reforma Sanitária (CFESS) — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"universalização e direitos sociais"},"comentario":{"resolucao":"D. Segundo o CFESS (2010), as principais propostas da Reforma Sanitária são a defesa da universalização das políticas sociais e a garantia dos direitos sociais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-201":{"cognitivo":{"motivo":"Treinar revolta da Vacina — reação do governo — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"estado de sítio e revogação"},"comentario":{"resolucao":"B. Diante da revolta, Rodrigues Alves decretou estado de sítio e revogou a obrigatoriedade da vacinação contra a varíola.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-202":{"cognitivo":{"motivo":"Treinar revolta da Vacina — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"antivaríola, Rio de Janeiro, 1904"},"comentario":{"resolucao":"C. A Revolta da Vacina foi contra a vacina antivariólica, no Rio de Janeiro, em novembro de 1904.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-203":{"cognitivo":{"motivo":"Treinar política de saúde de 1930 a meados de 1960 — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"sanitarismo mínimo + medicina previdenciária"},"comentario":{"resolucao":"C. Entre os anos 1930 e meados de 1960, a política de saúde combinou condições sanitárias mínimas (saúde pública) com a medicina previdenciária dos IAPs. O modelo médico-assistencial privatista consolida-se após 1966; o SUDS é de 1987.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-204":{"cognitivo":{"motivo":"Treinar participação em saúde (Machado, 1986) — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"intervenções das forças sociais"},"comentario":{"resolucao":"A. Para Machado (1986), participação em saúde é o conjunto de intervenções das forças sociais para influenciar a formulação, a execução e a avaliação das políticas públicas de saúde. C e D definem conselho de saúde; B define ações de saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-205":{"cognitivo":{"motivo":"Treinar reforma Sanitária — itens — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"todos verdadeiros"},"comentario":{"resolucao":"E (todos). Nasceu na luta contra a ditadura (anos 1970); Sérgio Arouca destacou-se; suas propostas resultaram na universalidade do direito à saúde (CF/88) e no SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-206":{"cognitivo":{"motivo":"Treinar sUS — afirmativa correta — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"igualdade da assistência"},"comentario":{"resolucao":"C. A igualdade da assistência à saúde, sem preconceitos ou privilégios, é princípio do SUS (Lei 8.080, art. 7º, IV). O SUS foi criado pela CF de 1988 e regulamentado em 1990; o INAMPS não era universal; integralidade é princípio.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-207":{"cognitivo":{"motivo":"Treinar sUS — afirmativa correta — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"1987 ... 1989"},"comentario":{"resolucao":"ERRADO. O SUS foi instituído pela Constituição de 1988 e regulamentado pela Lei 8.080 de 19 de setembro de 1990 (complementada pela Lei 8.142 de 28 de dezembro de 1990).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-208":{"cognitivo":{"motivo":"Treinar desafios para resgatar a Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"regionalização solidária e equidade"},"comentario":{"resolucao":"B. Entre os desafios estão fortalecer a regionalização cooperativa e solidária, ampliar o acesso com equidade e considerar a diversidade cultural e as desigualdades. As demais misturam propostas com elementos contrários (capital estrangeiro, centralidade médica, co-gestão com o setor privado, fortalecimento só do gestor federal).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-209":{"cognitivo":{"motivo":"Treinar cebes e Abrasco — incorreta — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"não defendiam a divisão saúde pública/previdenciária"},"comentario":{"resolucao":"C (incorreta). Abrasco e Cebes defendiam a UNIFICAÇÃO do sistema, superando a divisão entre saúde pública e assistência previdenciária. As demais afirmativas estão corretas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-210":{"cognitivo":{"motivo":"Treinar marcos da Reforma Sanitária — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"8ª CNS / CF 1988"},"comentario":{"resolucao":"C. Marco institucional: 8ª Conferência Nacional de Saúde (1986); oficialização da universalidade: Constituição de 1988 com a criação do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-211":{"cognitivo":{"motivo":"Treinar fundamentos da reforma — exceto — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"SUAS não é fundamento da reforma sanitária"},"comentario":{"resolucao":"C (exceto). Normatizar e regular a prestação de serviços de assistência social não é fundamento do projeto de reforma sanitária; são fundamentos a melhoria da qualidade com modelo integral e equitativo, a democratização das ações e do acesso e a transparência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-212":{"cognitivo":{"motivo":"Treinar cebes e modelo médico-centrado — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"Cebes criticava o modelo privado"},"comentario":{"resolucao":"ERRADO. O Cebes (1976) produziu estudos críticos ao modelo médico-assistencial privatista e defendeu a democratização da saúde e o sistema público; não estimulou modelo centrado no médico nem a saúde privada.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Cebes = crítica e saúde coletiva.","erroComum":"Aceitar por reconhecer o Cebes.","comoBancaPensa":"Item real IADES."}},"SUS-213":{"cognitivo":{"motivo":"Treinar sUS — afirmativa correta — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"saúde direito de todos e dever do Estado"},"comentario":{"resolucao":"B. A CF/88 garantiu a saúde como direito de todos e dever do Estado, mediante políticas sociais e econômicas (art. 196). Antes de 1988 o sistema previdenciário atendia CONTRIBUINTES; o SUS nasceu descentralizado e participativo; a 8ª CNS foi em 1986; o Ministério da Saúde foi criado em 1953.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-214":{"cognitivo":{"motivo":"Treinar sUS — afirmativa correta — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"1953"},"comentario":{"resolucao":"CERTO. 1930: Ministério dos Negócios da Educação e Saúde Pública (Vargas); 1953: criação do Ministério da Saúde. 1808 é o ano da chegada da corte e das primeiras escolas médicas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Linha do tempo: CAPs 1923 → IAPs 1933 → INPS 1966 → INAMPS 1977 → AIS 1983 → 8ª CNS 1986 → SUDS 1987 → CF 1988.","erroComum":"Trocar datas e órgãos da linha do tempo.","comoBancaPensa":"Marco histórico."}},"SUS-215":{"cognitivo":{"motivo":"Treinar ações Integradas de Saúde — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"AIS (1983) → SUDS (1987)"},"comentario":{"resolucao":"CERTO. AIS (1983, no contexto do CONASP) e SUDS (1987, convênios do INAMPS com os estados) foram estratégias de transição, de integração e descentralização, que antecederam a criação do SUS em 1988.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"AIS 83 → SUDS 87 → SUS 88.","erroComum":"Colocar o SUDS depois do SUS.","comoBancaPensa":"Cronologia."}},"SUS-216":{"cognitivo":{"motivo":"Treinar modelo médico-assistencial privatista — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"compra de serviços privados"},"comentario":{"resolucao":"CERTO. É a síntese clássica (Mendes): Estado como financiador via previdência, setor privado nacional como prestador e setor internacional como produtor de insumos; modelo hospitalocêntrico que gerou crise financeira no fim dos anos 1970.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Estado paga, privado presta, hospital no centro.","erroComum":"Atribuir esse modelo ao SUS.","comoBancaPensa":"Caracterização de modelo."}},"SUS-217":{"cognitivo":{"motivo":"Treinar lei Eloy Chaves e acesso à saúde — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"CAPs só para trabalhadores das empresas"},"comentario":{"resolucao":"ERRADO. As CAPs atendiam apenas os empregados das empresas que as instituíam (inicialmente ferroviários), com contribuição de empregados e empresas; o acesso continuou vinculado ao trabalho formal até a universalização pela CF/88.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"CAP = benefício do empregado, não do cidadão.","erroComum":"Antecipar a universalidade para 1923.","comoBancaPensa":"Cidadania regulada."}},"SUS-218":{"cognitivo":{"motivo":"Treinar sUDS — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"descentralização para estados"},"comentario":{"resolucao":"ERRADO. O SUDS DEScentralizou: por convênios, transferiu aos estados (e, por meio deles, aos municípios) a gestão de serviços e recursos do INAMPS, em direção à unificação e à descentralização que o SUS consolidou.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"SUDS = descentralizado (está no nome).","erroComum":"Achar que o SUDS centralizou.","comoBancaPensa":"Termo do próprio nome."}},"SUS-219":{"cognitivo":{"motivo":"Treinar portaria de Consolidação nº 4/2017 — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"imediata pelo meio mais rápido"},"comentario":{"resolucao":"CERTO. São as definições da norma; quando a imediata não puder ser feita pelo meio rápido, o registro posterior no SINAN deve ocorrer dentro dos prazos do fluxo de cada agravo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Imediata = até 24 h; semanal = até 7 dias.","erroComum":"Trocar os prazos.","comoBancaPensa":"Definições normativas."}},"SUS-220":{"cognitivo":{"motivo":"Treinar notificação e sigilo — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"dever de notificar prevalece"},"comentario":{"resolucao":"ERRADO. A notificação compulsória é dever legal (Lei 6.259/1975 e Portaria de Consolidação nº 4/2017) e constitui justa causa para a comunicação à autoridade sanitária, que mantém o sigilo das informações; não depende de autorização do paciente.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Notificar é dever legal, não quebra indevida de sigilo.","erroComum":"Exigir consentimento.","comoBancaPensa":"Conflito aparente entre sigilo e dever."}},"SUS-221":{"cognitivo":{"motivo":"Treinar conceito ampliado de saúde — ponto de reforma Sanitária e construção do SUS que a banca transforma em item.","palavraCritica":"determinantes sociais"},"comentario":{"resolucao":"CERTO. É o conceito ampliado de saúde, que a Lei 8.080 incorporou nos determinantes e condicionantes do art. 3º; a saúde passa a expressar a organização social e econômica do país.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Saúde = resultado das condições de vida.","erroComum":"Reduzir saúde à ausência de doença.","comoBancaPensa":"Conceito-base do SUS."}},"SUS-222":{"cognitivo":{"motivo":"Treinar cidadania regulada — ponto de evolução histórica do sistema de saúde que a banca transforma em item.","palavraCritica":"direitos vinculados à ocupação"},"comentario":{"resolucao":"CERTO. O conceito (Wanderley Guilherme dos Santos) explica por que os IAPs cobriam só categorias com carteira e profissões reconhecidas; quem estava fora do mercado formal dependia da filantropia e da saúde pública.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 1 — evolução histórica da organização do sistema de saúde no Brasil e construção do SUS. Base: Estratégia, Legislação SUS, Aula 01.","macete":"Direito pela carteira de trabalho.","erroComum":"Confundir com cidadania universal.","comoBancaPensa":"Conceito histórico."}},"SUS-223":{"cognitivo":{"motivo":"Treinar notificação de suspeitos — ponto de notificação compulsória e vigilância que a banca transforma em item.","palavraCritica":"notifica-se a suspeita"},"comentario":{"resolucao":"CERTO. A vigilância trabalha com casos suspeitos (sarampo, meningite, dengue grave); aguardar o laboratório atrasaria bloqueio vacinal, quimioprofilaxia e investigação de contatos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 7 — sistemas de informação em saúde (vigilância e notificação compulsória; Portaria de Consolidação GM/MS nº 4/2017, Anexo V). Base: Estratégia, Legislação SUS, Aula 00.","macete":"Na dúvida, notifica.","erroComum":"Esperar o exame.","comoBancaPensa":"Princípio operacional da vigilância."}},"SUS-224":{"cognitivo":{"motivo":"Treinar participação complementar da iniciativa privada — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"contrato de direito público ou convênio"},"comentario":{"resolucao":"E. As instituições privadas participam de forma complementar do SUS, segundo as diretrizes deste, mediante contrato de direito público ou convênio, com preferência para as filantrópicas e sem fins lucrativos (art. 199, § 1º). É vedado destinar recursos públicos a auxílios ou subvenções a instituições com fins lucrativos (§ 2º) e comercializar sangue e órgãos (§ 4º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-225":{"cognitivo":{"motivo":"Treinar participação complementar da iniciativa privada — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"auxílios ou subvenções"},"comentario":{"resolucao":"CERTO. São coisas distintas: subvenção (repasse sem contraprestação) é vedada às lucrativas (art. 199, § 2º); a contratação de serviços para complementar a rede é permitida a qualquer instituição privada, com preferência às filantrópicas e sem fins lucrativos (§ 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-226":{"cognitivo":{"motivo":"Treinar diretrizes do art. 198 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"atendimento integral com prioridade preventiva"},"comentario":{"resolucao":"D. As diretrizes do art. 198 são: descentralização, com direção única em cada esfera de governo; atendimento integral, com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais; e participação da comunidade. A descentralização não é 'gestão única municipal'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-227":{"cognitivo":{"motivo":"Treinar diretrizes do art. 198 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"prioridade para as atividades assistenciais"},"comentario":{"resolucao":"ERRADO. Inverteu a prioridade: o art. 198, II, fala em atendimento integral, com prioridade para as atividades PREVENTIVAS, sem prejuízo dos serviços ASSISTENCIAIS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-228":{"cognitivo":{"motivo":"Treinar art. 197 — relevância pública — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"pessoa física ou jurídica de direito privado"},"comentario":{"resolucao":"A. Art. 197: são de relevância pública as ações e serviços de saúde, cabendo ao Poder Público dispor sobre sua regulamentação, fiscalização e controle, devendo sua execução ser feita diretamente ou através de terceiros e, também, por pessoa física ou jurídica de direito PRIVADO. Os distratores trocam 'privado' por 'público', 'Poder Público' por 'Poder Privado' e 'relevância pública' por 'privada'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-229":{"cognitivo":{"motivo":"Treinar arts. 196-200 — incorreta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"assistência é livre à iniciativa privada"},"comentario":{"resolucao":"D (incorreta). A assistência à saúde É livre à iniciativa privada (art. 199, caput), sem depender de lei complementar. As demais reproduzem a Constituição (art. 196; art. 198, § 1º; art. 198, § 10 — aposentadoria especial e adicional de insalubridade de ACS e ACE, EC 120/2022; art. 200, II).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-230":{"cognitivo":{"motivo":"Treinar arts. 196-200 — incorreta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"aposentadoria especial"},"comentario":{"resolucao":"CERTO. É o § 10 do art. 198, incluído pela EC 120/2022, que também fixou piso salarial não inferior a dois salários mínimos para essas categorias (§ 9º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-231":{"cognitivo":{"motivo":"Treinar art. 196 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"políticas sociais e econômicas"},"comentario":{"resolucao":"B. A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas (art. 196).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-232":{"cognitivo":{"motivo":"Treinar art. 196 — políticas — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"sociais e econômicas"},"comentario":{"resolucao":"A. Políticas sociais e econômicas que visem à redução do risco de doença e ao acesso universal e igualitário.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-233":{"cognitivo":{"motivo":"Treinar saúde na CF — correta — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"rede regionalizada e hierarquizada"},"comentario":{"resolucao":"E. Art. 198: as ações e serviços públicos de saúde integram uma rede regionalizada e hierarquizada e constituem um sistema único, com atendimento integral e prioridade preventiva. A aplicação mínima cabe a União, estados, DF e municípios (A erra); a execução por pessoa jurídica de direito privado é permitida (B erra); o SUS é financiado pelo orçamento da seguridade (C erra); auxílios a lucrativas são vedados (D erra).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-234":{"cognitivo":{"motivo":"Treinar seguridade social — V/F — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"saúde direito de todos"},"comentario":{"resolucao":"B (F, V, F). A saúde é direito de todos e dever do Estado. A primeira erra (proteção social e vigilância socioassistencial são diretrizes da assistência social na LOAS, não princípios da seguridade); a terceira erra (a assistência social segue DEScentralização político-administrativa e participação da população na formulação E no controle).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-235":{"cognitivo":{"motivo":"Treinar execução das ações de saúde — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"diretamente, por terceiros, por privado"},"comentario":{"resolucao":"A (I, II e III). Pelo art. 197, a execução pode ser feita diretamente, através de terceiros e por pessoa física ou jurídica de direito privado.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-236":{"cognitivo":{"motivo":"Treinar art. 200 — exceto — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"participa do saneamento básico"},"comentario":{"resolucao":"B (exceto). Compete ao SUS PARTICIPAR da formulação da política e da execução das ações de saneamento básico (art. 200, IV); 'não participar' contraria o texto.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-237":{"cognitivo":{"motivo":"Treinar objetivos da seguridade — seletividade — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"seletividade e distributividade"},"comentario":{"resolucao":"CERTO. A seletividade e a distributividade na prestação dos benefícios e serviços constam do art. 194, parágrafo único, III, entre os objetivos da seguridade social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Objetivos do art. 194: UNI-UNI-SELE-IRRE-EQUI-DIVER-DEMO.","erroComum":"Achar que seletividade contraria a universalidade.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-238":{"cognitivo":{"motivo":"Treinar objetivos da seguridade — seletividade — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"uniformidade e equivalência"},"comentario":{"resolucao":"CERTO. O parágrafo único do art. 194 lista: universalidade da cobertura e do atendimento; uniformidade e equivalência urbano-rural; seletividade e distributividade; irredutibilidade; equidade no custeio; diversidade da base de financiamento; caráter democrático e descentralizado da administração (gestão quadripartite).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Objetivos do art. 194: UNI-UNI-SELE-IRRE-EQUI-DIVER-DEMO.","erroComum":"Achar que seletividade contraria a universalidade.","comoBancaPensa":"Item real CEBRASPE."}},"SUS-239":{"cognitivo":{"motivo":"Treinar art. 200 — exceto (meio ambiente) — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"colaborar, não coordenar"},"comentario":{"resolucao":"B (exceto). Ao SUS compete COLABORAR na proteção do meio ambiente, nele compreendido o do trabalho (art. 200, VIII) — não 'coordenar' essas ações.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-240":{"cognitivo":{"motivo":"Treinar art. 200 — exceto (meio ambiente) — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"coordenar"},"comentario":{"resolucao":"ERRADO. Os verbos estão trocados: ao SUS compete COLABORAR na proteção do meio ambiente (art. 200, VIII) e PARTICIPAR da formulação da política e da execução das ações de saneamento básico (inciso IV).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-241":{"cognitivo":{"motivo":"Treinar diretrizes do SUS — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"descentralização, atendimento integral, participação"},"comentario":{"resolucao":"B. Descentralização, atendimento integral e participação da comunidade (art. 198, I a III).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-242":{"cognitivo":{"motivo":"Treinar art. 200 — afirmativas — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"todas corretas"},"comentario":{"resolucao":"D (todas). Controlar e fiscalizar procedimentos e produtos e participar da produção de insumos; executar vigilância sanitária, epidemiológica e saúde do trabalhador; ordenar a formação de recursos humanos; incrementar o desenvolvimento científico, tecnológico e a inovação (art. 200, I, II, III e V).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-243":{"cognitivo":{"motivo":"Treinar objetivos da seguridade — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"universalidade, equidade, irredutibilidade"},"comentario":{"resolucao":"D. Universalidade da cobertura, equidade na forma de participação no custeio e irredutibilidade do valor dos benefícios são objetivos do art. 194. 'Confiscatoriedade', 'retroatividade', 'redutibilidade' e 'anterioridade' não são.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-244":{"cognitivo":{"motivo":"Treinar art. 200 — afirmativas — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"todas corretas"},"comentario":{"resolucao":"D (todas). Os incisos II, I, VI e VII do art. 200 foram reproduzidos corretamente.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-245":{"cognitivo":{"motivo":"Treinar princípios/objetivos da seguridade — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"irredutibilidade e equidade no custeio"},"comentario":{"resolucao":"D. Irredutibilidade do valor dos benefícios e equidade na forma de participação no custeio constam do art. 194. A gestão é 'quadripartite' (não regional); 'receitas das contribuições' e 'participação da iniciativa privada' não são objetivos; a participação na formulação e controle 'em todos os níveis' é diretriz da assistência social (art. 204).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-246":{"cognitivo":{"motivo":"Treinar conceito de seguridade social — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"art. 194"},"comentario":{"resolucao":"B. A seguridade social compreende um conjunto integrado de ações de iniciativa dos Poderes Públicos e da sociedade, destinado a assegurar os direitos à saúde, à previdência e à assistência social (art. 194).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-247":{"cognitivo":{"motivo":"Treinar seletividade e distributividade — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"prioridade aos mais necessitados"},"comentario":{"resolucao":"E. A seletividade e distributividade permite à lei escolher as contingências cobertas e distribuir benefícios priorizando os mais necessitados. Universalidade é a abrangência ampla; irredutibilidade protege o valor; equidade refere-se ao custeio.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-248":{"cognitivo":{"motivo":"Treinar seguridade — correta — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"gestão democrática e descentralizada"},"comentario":{"resolucao":"D. A administração da seguridade tem caráter democrático e descentralizado, com gestão quadripartite (trabalhadores, empregadores, aposentados e Governo). O valor dos benefícios é irredutível; o financiamento é por toda a sociedade (não por doações); a cobertura é universal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-249":{"cognitivo":{"motivo":"Treinar seguridade — correta — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"quadripartite"},"comentario":{"resolucao":"CERTO. É o art. 194, parágrafo único, VII. A prova costuma trocar 'aposentados' por 'usuários' ou 'conselhos', ou transformar a gestão em 'tripartite'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-250":{"cognitivo":{"motivo":"Treinar seguridade — conceito — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"integrado, poderes públicos e sociedade"},"comentario":{"resolucao":"C. Conjunto INTEGRADO de ações de iniciativa dos Poderes Públicos E da sociedade, para saúde, previdência e assistência social. Os distratores trocam 'integrado' por 'independentes', incluem educação ou cultura e falam em iniciativa 'privativa' dos poderes públicos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-251":{"cognitivo":{"motivo":"Treinar objetivos — exceto — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"descentralizado, não centralizado"},"comentario":{"resolucao":"E (exceto). O caráter da gestão é democrático e DEScentralizado, com participação de trabalhadores, empregadores, aposentados e Governo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-252":{"cognitivo":{"motivo":"Treinar conteúdo do art. 196 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"direito à saúde, acesso universal"},"comentario":{"resolucao":"C. O art. 196 assegura a saúde como direito de todos e dever do Estado, com acesso universal e igualitário.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-253":{"cognitivo":{"motivo":"Treinar iniciativa privada — correta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"livre à iniciativa privada"},"comentario":{"resolucao":"D. A assistência à saúde é livre à iniciativa privada (art. 199). A participação complementar é aberta a privadas em geral, com PREFERÊNCIA (não exclusividade) para filantrópicas; auxílios a lucrativas são vedados; o capital estrangeiro é vedado salvo nos casos previstos em lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-254":{"cognitivo":{"motivo":"Treinar iniciativa privada — correta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"salvo nos casos previstos em lei"},"comentario":{"resolucao":"CERTO. É o art. 199, § 3º; a Lei 13.097/2015 alterou a Lei 8.080 e ampliou as hipóteses permitidas (por exemplo, hospitais e clínicas), mas a regra constitucional segue sendo a vedação com exceções legais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-255":{"cognitivo":{"motivo":"Treinar iniciativa privada — correta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"restrita"},"comentario":{"resolucao":"ERRADO. As filantrópicas e sem fins lucrativos têm PREFERÊNCIA (art. 199, § 1º), não exclusividade; empresas lucrativas podem ser contratadas para complementar a rede. O que lhes é vedado é receber auxílios ou subvenções (§ 2º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-256":{"cognitivo":{"motivo":"Treinar áreas da seguridade — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"previdência, saúde e assistência"},"comentario":{"resolucao":"D. Previdência social, saúde e assistência social (art. 194).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-257":{"cognitivo":{"motivo":"Treinar seguridade — conceito e objetivo — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"irredutibilidade"},"comentario":{"resolucao":"C. Conjunto integrado de ações dos Poderes Públicos e da sociedade, com objetivo, entre outros, de irredutibilidade do valor dos benefícios. As demais falam em iniciativa 'exclusiva' dos Poderes Públicos ou em equivalência 'exclusivamente urbana'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-258":{"cognitivo":{"motivo":"Treinar art. 194 — lacunas — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"poderes públicos e sociedade; saúde, previdência, assistência"},"comentario":{"resolucao":"A. Dos Poderes Públicos e da sociedade; saúde, previdência e assistência social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-259":{"cognitivo":{"motivo":"Treinar art. 194 — direitos — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"saúde, previdência e assistência"},"comentario":{"resolucao":"B. Saúde, previdência e assistência social — o 'trabalho' não integra a seguridade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-260":{"cognitivo":{"motivo":"Treinar rede regionalizada e hierarquizada — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"níveis de complexidade"},"comentario":{"resolucao":"B. A hierarquização organiza o SUS por níveis de complexidade da atenção (primária, secundária e terciária). O SUS não é contributivo nem ligado a institutos previdenciários; a regionalização não se articula só pelas secretarias estaduais; 'hierarquia e disciplina' é regime militar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-261":{"cognitivo":{"motivo":"Treinar diretrizes do art. 198 — exceto — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"descentralização"},"comentario":{"resolucao":"E (exceto). A diretriz é DEScentralização, com direção única em cada esfera de governo. As outras alternativas reproduzem o art. 198 (participação da comunidade, atendimento integral) e seus parágrafos (financiamento; aposentadoria especial dos ACS e ACE).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-262":{"cognitivo":{"motivo":"Treinar descentralização com direção única — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"direção única em cada esfera"},"comentario":{"resolucao":"CERTO. Art. 198, I: descentralização, com direção única em cada esfera de governo; as ações e serviços públicos de saúde integram rede regionalizada e hierarquizada e constituem sistema único.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Direção única POR esfera (não única nacional).","erroComum":"Confundir direção única com centralização.","comoBancaPensa":"Item real Quadrix."}},"SUS-263":{"cognitivo":{"motivo":"Treinar fontes de financiamento — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"seguridade, União, estados, DF e municípios"},"comentario":{"resolucao":"D (I, II e III). O SUS é financiado com recursos do orçamento da seguridade social, da União, dos estados, do DF e dos municípios, além de outras fontes (art. 198, § 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-264":{"cognitivo":{"motivo":"Treinar mínimo da União — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"15% da receita corrente líquida"},"comentario":{"resolucao":"C. A União aplica anualmente, em ações e serviços públicos de saúde, no mínimo 15% da receita corrente líquida do respectivo exercício (art. 198, § 2º, I, redação da EC 86/2015).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-265":{"cognitivo":{"motivo":"Treinar mínimo da União — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"12% ... 15%"},"comentario":{"resolucao":"CERTO. Estados: 12% (deduzidas as transferências aos municípios); municípios: 15%; DF: 12% ou 15% conforme a natureza da receita; União: 15% da receita corrente líquida (art. 198, § 2º, I, da CF).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-266":{"cognitivo":{"motivo":"Treinar mínimo da União — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"12% da sua receita corrente líquida"},"comentario":{"resolucao":"ERRADO. Para a União o piso é de 15% da receita corrente líquida (EC 86/2015); 12% é o mínimo dos ESTADOS sobre impostos e transferências (LC 141/2012). Os 15% dos municípios estão corretos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-267":{"cognitivo":{"motivo":"Treinar art. 200 — correta — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"participar da produção de insumos"},"comentario":{"resolucao":"D. Participar da produção de medicamentos, equipamentos, imunobiológicos, hemoderivados e outros insumos (art. 200, I). As demais distorcem: saúde do trabalhador está incluída; o meio ambiente compreende o do trabalho; substâncias 'de interesse para a saúde'; águas para consumo HUMANO.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-268":{"cognitivo":{"motivo":"Treinar organização das ações do SUS — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"regionalizada e hierarquizada em complexidade crescente"},"comentario":{"resolucao":"B. As ações e serviços do SUS, diretamente ou mediante participação complementar privada, organizam-se de forma regionalizada e hierarquizada em níveis de complexidade crescente (Lei 8.080, art. 8º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-269":{"cognitivo":{"motivo":"Treinar iniciativa privada — V/F — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"fomentar subvenções às lucrativas é falso"},"comentario":{"resolucao":"D (V - V - F). A assistência é livre à iniciativa privada; as privadas participam complementarmente por contrato ou convênio, com preferência às filantrópicas e sem fins lucrativos; é VEDADA a destinação de recursos públicos para auxílios ou subvenções às lucrativas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-270":{"cognitivo":{"motivo":"Treinar participação complementar — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"contrato de direito público ou convênio"},"comentario":{"resolucao":"CERTO. É a literalidade do art. 199, § 1º: participação complementar, segundo diretrizes do SUS, mediante contrato de direito público ou convênio, com preferência às filantrópicas e às sem fins lucrativos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Complementar, não suplementar.","erroComum":"Trocar 'complementar' por 'suplementar'.","comoBancaPensa":"Item real Quadrix."}},"SUS-271":{"cognitivo":{"motivo":"Treinar art. 199 — correta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"remoção de órgãos e sangue"},"comentario":{"resolucao":"B. A lei disporá sobre as condições e os requisitos que facilitem a remoção de órgãos, tecidos e substâncias humanas para transplante, pesquisa e tratamento, bem como coleta, processamento e transfusão de sangue e derivados, vedado todo tipo de comercialização (art. 199, § 4º). Há preferência às filantrópicas (A erra); o capital estrangeiro é vedado salvo exceções (C erra); a vedação de subvenções é só às lucrativas (D erra).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-272":{"cognitivo":{"motivo":"Treinar art. 199 — correta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"admite a comercialização"},"comentario":{"resolucao":"ERRADO. O art. 199, § 4º, veda TODO tipo de comercialização de órgãos, tecidos, substâncias humanas, sangue e derivados; a lei regula coleta, processamento e transfusão.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-273":{"cognitivo":{"motivo":"Treinar saúde na CF — afirmativas — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"direção única, não compartilhada"},"comentario":{"resolucao":"B (I, III e IV). II erra: a descentralização é com direção ÚNICA em cada esfera de governo, não 'compartilhada entre executivo e conselho'; a diretriz é atendimento integral (não 'atenção integral' com direção compartilhada).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-274":{"cognitivo":{"motivo":"Treinar atribuição do SUS — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"participar da produção de insumos"},"comentario":{"resolucao":"C. Participar da produção de medicamentos, equipamentos, imunobiológicos, hemoderivados e outros insumos é atribuição do art. 200, I. Proteção à família e à maternidade é objetivo da assistência social; desenvolvimento urbano e abastecimento não são atribuições do SUS na CF.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-275":{"cognitivo":{"motivo":"Treinar financiamento e ACS/ACE — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"I e II corretos"},"comentario":{"resolucao":"D (I e II). O SUS é financiado com recursos da seguridade e dos entes (art. 198, § 1º); os gestores locais podem admitir ACS e ACE por processo seletivo público (§ 4º, EC 51/2006). III erra: saúde é dever do ESTADO, com acesso UNIVERSAL, para promoção, proteção e RECUPERAÇÃO.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-276":{"cognitivo":{"motivo":"Treinar financiamento e ACS/ACE — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"processo seletivo público"},"comentario":{"resolucao":"CERTO. É o § 4º do art. 198 (EC 51/2006); o § 5º remete à lei federal o regime jurídico e o piso salarial, e o § 6º permite a perda do cargo por descumprimento dos requisitos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-277":{"cognitivo":{"motivo":"Treinar financiamento da seguridade — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"orçamentos próprios dos entes"},"comentario":{"resolucao":"A (I, II e III). A seguridade é financiada por toda a sociedade, direta e indiretamente, por recursos dos orçamentos dos entes e por contribuições sociais (art. 195); as receitas de estados, DF e municípios destinadas à seguridade constam dos respectivos orçamentos, não integrando o da União (§ 1º); universalidade é objetivo (art. 194).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-278":{"cognitivo":{"motivo":"Treinar contribuições sociais — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"concursos de prognósticos"},"comentario":{"resolucao":"A. Entre as contribuições do art. 195 está a incidente sobre a receita de concursos de prognósticos (loterias, inciso III).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-279":{"cognitivo":{"motivo":"Treinar contribuições sociais — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"concursos de prognósticos"},"comentario":{"resolucao":"CERTO. São os incisos I a IV do art. 195; a EC 132/2023 acrescentou o inciso V (contribuição sobre bens e serviços, nos termos de lei complementar).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-280":{"cognitivo":{"motivo":"Treinar arts. 196-199 — incorreta — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"centralização e atendimento parcial"},"comentario":{"resolucao":"E (incorreta). O art. 198 fala em DEScentralização e em atendimento INTEGRAL, não em centralização e atendimento 'parcial'. As demais estão corretas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-281":{"cognitivo":{"motivo":"Treinar financiamento do SUS — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"seguridade + entes + outras fontes"},"comentario":{"resolucao":"B. Orçamento da seguridade social, da União, dos estados, do DF e dos municípios, além de outras fontes (art. 198, § 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-282":{"cognitivo":{"motivo":"Treinar art. 200 — correta — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"psicoativos, tóxicos e radioativos"},"comentario":{"resolucao":"D. Compete ao SUS participar do controle e fiscalização da produção, transporte, guarda e utilização de substâncias psicoativas, tóxicas e radioativas (art. 200, VII). Colaborar com o meio ambiente é atribuição, não 'extracurricular'; ACE são de 'endemias' (não 'epidemias'); a participação privada é 'complementar', não 'essencial'; participação da comunidade é diretriz.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-283":{"cognitivo":{"motivo":"Treinar art. 196 — redação — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"direito de todos"},"comentario":{"resolucao":"D. Saúde é direito de TODOS e dever do Estado, com acesso universal e igualitário — não só de quem contribui ou não tem plano.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-284":{"cognitivo":{"motivo":"Treinar mínimo da União — CEBRASPE — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"15% da receita corrente líquida"},"comentario":{"resolucao":"B. A União aplica no mínimo 15% de sua receita corrente líquida em ações e serviços públicos de saúde (art. 198, § 2º, I).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Leia o artigo: a prova troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade constitucional."}},"SUS-285":{"cognitivo":{"motivo":"Treinar regra da contrapartida — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"fonte de custeio total"},"comentario":{"resolucao":"CERTO. É o art. 195, § 5º (regra da contrapartida ou da precedência do custeio), que protege o equilíbrio financeiro da seguridade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Benefício novo exige fonte de custeio.","erroComum":"Achar que a regra vale só para a previdência.","comoBancaPensa":"Princípio do financiamento."}},"SUS-286":{"cognitivo":{"motivo":"Treinar anterioridade das contribuições sociais — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"90 dias"},"comentario":{"resolucao":"CERTO. É a anterioridade nonagesimal do art. 195, § 6º; essas contribuições não se submetem à regra do 'exercício seguinte' (art. 150, III, b).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Contribuição social: 90 dias.","erroComum":"Aplicar a anterioridade anual.","comoBancaPensa":"Regra tributária da seguridade."}},"SUS-287":{"cognitivo":{"motivo":"Treinar participação da comunidade — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"diretriz, não opção"},"comentario":{"resolucao":"ERRADO. A participação da comunidade é diretriz constitucional (art. 198, III) regulamentada pela Lei 8.142/1990, que instituiu em cada esfera a Conferência e o Conselho de Saúde como instâncias colegiadas — inclusive como condição para receber recursos do Fundo Nacional de Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Conselho e conferência são obrigatórios.","erroComum":"Achar que a participação é opcional.","comoBancaPensa":"Diretriz × faculdade."}},"SUS-288":{"cognitivo":{"motivo":"Treinar piso salarial dos ACS e ACE — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"dois salários mínimos"},"comentario":{"resolucao":"CERTO. É o § 9º do art. 198 (EC 120/2022), que também previu a responsabilidade da União pela assistência financeira complementar e incluiu, no § 10, aposentadoria especial e adicional de insalubridade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"ACS/ACE: piso de 2 salários mínimos.","erroComum":"Confundir com o piso da enfermagem.","comoBancaPensa":"Alteração constitucional recente."}},"SUS-289":{"cognitivo":{"motivo":"Treinar direção única — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"direção única em cada esfera"},"comentario":{"resolucao":"ERRADO. A direção é única EM CADA ESFERA de governo (Ministério da Saúde na União, secretarias nos estados e municípios), sem subordinação hierárquica entre os entes, que são autônomos; a articulação se dá por pactuação nas comissões intergestores.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Uma direção por esfera, sem hierarquia entre entes.","erroComum":"Ler 'direção única' como centralização nacional.","comoBancaPensa":"Pegadinha clássica do art. 198."}},"SUS-290":{"cognitivo":{"motivo":"Treinar complementar × suplementar — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"complementar ao SUS"},"comentario":{"resolucao":"ERRADO. A participação é COMPLEMENTAR, segundo as diretrizes DO SUS (art. 199, § 1º); pela Lei 8.080 (art. 24), o recurso ao setor privado ocorre quando as disponibilidades do SUS forem insuficientes para garantir a cobertura assistencial. 'Saúde suplementar' é o setor de planos privados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Complementar = completa o SUS quando falta; suplementar = planos de saúde.","erroComum":"Trocar os termos.","comoBancaPensa":"Troca clássica de palavra."}},"SUS-291":{"cognitivo":{"motivo":"Treinar saúde × previdência × assistência — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"saúde não é contributiva"},"comentario":{"resolucao":"ERRADO. Só a PREVIDÊNCIA é contributiva; a SAÚDE é universal e independe de contribuição (art. 196), e a ASSISTÊNCIA SOCIAL é prestada a quem dela necessitar, independentemente de contribuição (art. 203).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Saúde: todos; previdência: quem contribui; assistência: quem precisa.","erroComum":"Estender a contributividade à saúde.","comoBancaPensa":"Comparação das três áreas."}},"SUS-292":{"cognitivo":{"motivo":"Treinar acesso universal e igualitário — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"universal e igualitário"},"comentario":{"resolucao":"ERRADO. O art. 196 assegura acesso UNIVERSAL e IGUALITÁRIO às ações e serviços para promoção, proteção e recuperação da saúde, sem restringir a universalidade às urgências; a seletividade é objetivo da seguridade aplicado aos benefícios.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Art. 196: universal e igualitário.","erroComum":"Trazer a seletividade para o acesso à saúde.","comoBancaPensa":"Troca de adjetivos do artigo."}},"SUS-293":{"cognitivo":{"motivo":"Treinar financiamento tripartite — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"não só União"},"comentario":{"resolucao":"ERRADO. O financiamento envolve o orçamento da seguridade social e recursos da União, dos estados, do DF e dos municípios, além de outras fontes (art. 198, § 1º), e todos os entes têm percentuais mínimos de aplicação (§ 2º e LC 141/2012).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"SUS = tripartite (União, estados e municípios).","erroComum":"Pôr o financiamento só na União.","comoBancaPensa":"Responsabilidade dos entes."}},"SUS-294":{"cognitivo":{"motivo":"Treinar formação de recursos humanos — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"SUS ordena a formação de RH"},"comentario":{"resolucao":"ERRADO. Ordenar a formação de recursos humanos na área de saúde é atribuição expressa do SUS (art. 200, III), base de políticas como a Educação Permanente em Saúde e as residências em saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Art. 200, III: o SUS ordena a formação de RH.","erroComum":"Atribuir só ao MEC.","comoBancaPensa":"Atribuição constitucional."}},"SUS-295":{"cognitivo":{"motivo":"Treinar fiscalização de alimentos e águas — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"consumo humano"},"comentario":{"resolucao":"ERRADO. O inciso VI do art. 200 fala em bebidas e águas para consumo HUMANO; a extensão ao consumo 'animal' é acréscimo da banca (a fiscalização de produtos de uso veterinário cabe à agricultura).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Art. 200, VI: consumo humano.","erroComum":"Aceitar o acréscimo 'e animal'.","comoBancaPensa":"Acréscimo indevido."}},"SUS-296":{"cognitivo":{"motivo":"Treinar irredutibilidade dos benefícios — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"não admite redução"},"comentario":{"resolucao":"ERRADO. A irredutibilidade (art. 194, parágrafo único, IV) impede a redução do valor dos benefícios; não há exceção por crise fiscal na Constituição, e a jurisprudência a entende como vedação à redução nominal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Irredutível é irredutível.","erroComum":"Criar exceção que a CF não prevê.","comoBancaPensa":"Exceção inventada."}},"SUS-297":{"cognitivo":{"motivo":"Treinar equidade na participação no custeio — ponto de seguridade social (CF, arts. 194-195) que a banca transforma em item.","palavraCritica":"capacidade contributiva"},"comentario":{"resolucao":"ERRADO. Equidade não é igualdade de alíquotas: quem tem maior capacidade contributiva (ou atividade de maior risco) contribui mais; a Constituição admite alíquotas diferenciadas e progressivas (art. 195, § 9º, e inciso II).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 4 — Constituição Federal, arts. 194 a 200 e suas alterações. Base: Estratégia, Legislação SUS, Aula 02.","macete":"Equidade = cada um conforme sua capacidade.","erroComum":"Confundir equidade com alíquota única.","comoBancaPensa":"Conceito de equidade."}},"SUS-298":{"cognitivo":{"motivo":"Treinar subsistema de Atenção à Saúde Indígena — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"organismos colegiados"},"comentario":{"resolucao":"E. As populações indígenas têm direito a participar dos organismos colegiados de formulação, acompanhamento e avaliação das políticas de saúde, como o CNS e os conselhos estaduais e municipais (art. 19-H). Erros: quem financia o subsistema é a UNIÃO, com recursos próprios (art. 19-C), e estados e municípios atuam complementarmente (art. 19-E); o registro da raça/cor é OBRIGATÓRIO (art. 19-G, § 1º-A); o acesso compreende a atenção primária, secundária e terciária (§ 2º); a abordagem deve ser DIFERENCIADA e global, não padronizada (art. 19-F).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-299":{"cognitivo":{"motivo":"Treinar subsistema de Atenção à Saúde Indígena — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"União, com recursos próprios"},"comentario":{"resolucao":"CERTO. O financiamento principal é federal (art. 19-C); a atuação de estados, municípios e entidades, governamentais ou não, é complementar, no custeio e na execução (art. 19-E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-300":{"cognitivo":{"motivo":"Treinar subsistema de Atenção à Saúde Indígena — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"obrigatoriamente"},"comentario":{"resolucao":"ERRADO. O § 1º-A do art. 19-G determina que a rede do SUS deverá OBRIGATORIAMENTE fazer o registro e a notificação da declaração de raça ou cor, garantindo a identificação de todos os indígenas atendidos nos sistemas públicos de saúde — o dado serve para orientar a política, não depende de pedido do usuário.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-301":{"cognitivo":{"motivo":"Treinar subsistema de Atenção à Saúde Indígena — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"primária, secundária e terciária"},"comentario":{"resolucao":"CERTO. É a redação do § 2º do art. 19-G: o subsistema não se limita à atenção básica — a garantia alcança os três níveis de atenção, inclusive os centros especializados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-302":{"cognitivo":{"motivo":"Treinar comissões intersetoriais — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"subordinadas ao Conselho Nacional de Saúde"},"comentario":{"resolucao":"D. Art. 12: serão criadas comissões INTERSETORIAIS de âmbito nacional, subordinadas ao CONSELHO NACIONAL DE SAÚDE, integradas pelos ministérios e órgãos competentes e por entidades representativas da sociedade civil. Elas articulam políticas cuja execução envolve áreas não compreendidas no SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-303":{"cognitivo":{"motivo":"Treinar comissões intersetoriais — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"subordinadas ao CNS"},"comentario":{"resolucao":"ERRADO. Elas são subordinadas ao CONSELHO NACIONAL DE SAÚDE e integradas pelos ministérios e órgãos competentes e por entidades representativas da SOCIEDADE CIVIL (art. 12). Comissão só de gestores é a intergestores (CIT/CIB), que é outra coisa.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-304":{"cognitivo":{"motivo":"Treinar universalidade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"acesso irrestrito como direito"},"comentario":{"resolucao":"A. A universalidade garante acesso de todos os cidadãos às ações e serviços de saúde, em todos os níveis de assistência, como direito de cidadania (art. 7º, I).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-305":{"cognitivo":{"motivo":"Treinar pilares da Lei 8.080 — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"universalização, integralidade, participação"},"comentario":{"resolucao":"B. Universalidade, integralidade e participação da comunidade estão no art. 7º. O acesso não depende de vínculo empregatício (modelo do antigo INAMPS), não é dirigido a grupos de alta renda e a vigilância epidemiológica está no campo de atuação do SUS (art. 6º, I, b).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-306":{"cognitivo":{"motivo":"Treinar atendimento e internação domiciliar — V/F — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"indicação médica e concordância"},"comentario":{"resolucao":"A (V, V, V). As três afirmativas reproduzem o art. 19-I: §1º (procedimentos médicos, de enfermagem, fisioterapêuticos, psicológicos e de assistência social), §2º (equipes multidisciplinares nos níveis preventivo, terapêutico e reabilitador) e §3º (só por indicação médica, com expressa concordância do paciente e de sua família).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-307":{"cognitivo":{"motivo":"Treinar atendimento e internação domiciliar — V/F — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"só por indicação médica"},"comentario":{"resolucao":"CERTO. Trata-se do § 3º do art. 19-I. A palavra 'só' aqui é do próprio texto legal — não é termo absoluto inventado pela banca.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-308":{"cognitivo":{"motivo":"Treinar atendimento e internação domiciliar — V/F — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"preventiva, terapêutica e reabilitadora"},"comentario":{"resolucao":"ERRADO. O § 2º do art. 19-I diz que as equipes multidisciplinares atuarão nos níveis da medicina PREVENTIVA, terapêutica e reabilitadora; a lei não retira a prevenção do cuidado prestado no domicílio.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-309":{"cognitivo":{"motivo":"Treinar lacunas — organização, regido, integralidade, descentralizada — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"integralidade; descentralizada"},"comentario":{"resolucao":"B. A Lei 8.080 estabelece as bases para a ORGANIZAÇÃO e o funcionamento do SUS, que é REGIDO pelos princípios da universalidade, equidade e INTEGRALIDADE, com gestão DESCENTRALIZADA (direção única em cada esfera, ênfase nos municípios — art. 7º, IX).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-310":{"cognitivo":{"motivo":"Treinar conta especial dos recursos do SUS — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"fiscalização dos Conselhos de Saúde"},"comentario":{"resolucao":"C. Art. 33: os recursos financeiros do SUS serão depositados em conta especial, em cada esfera de sua atuação, e movimentados sob fiscalização dos respectivos CONSELHOS DE SAÚDE. (O material marca B, mas transcreve o artigo com 'Conselhos', que é a C na ordem das alternativas.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-311":{"cognitivo":{"motivo":"Treinar conta especial dos recursos do SUS — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"Fundo Nacional de Saúde"},"comentario":{"resolucao":"CERTO. É o § 1º do art. 33. A banca costuma trocar o administrador (Ministério da Economia/Fazenda) ou o instrumento (orçamento geral da União) — o correto é Ministério da Saúde, via Fundo Nacional de Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-312":{"cognitivo":{"motivo":"Treinar conta especial dos recursos do SUS — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"Conselhos de Saúde"},"comentario":{"resolucao":"ERRADO. A fiscalização da movimentação dos recursos cabe aos CONSELHOS DE SAÚDE de cada esfera (art. 33). CIB e CIT são foros de pactuação entre gestores (art. 14-A), não órgãos de controle social dos fundos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-313":{"cognitivo":{"motivo":"Treinar assistência terapêutica e incorporação de tecnologia — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"tabelas do gestor federal"},"comentario":{"resolucao":"E. Art. 19-M, II: a assistência terapêutica integral inclui a oferta de procedimentos terapêuticos, em regime domiciliar, ambulatorial e hospitalar, constantes de tabelas elaboradas pelo gestor federal do SUS, realizados no território nacional por serviço próprio, conveniado ou contratado. Erros: a incorporação é atribuição do MINISTÉRIO DA SAÚDE, assessorado pela Conitec (A e B); a Conitec considera a avaliação econômica comparativa de benefícios e custos (C); terapias experimentais não são pagas pelo SUS (D; art. 19-T).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-314":{"cognitivo":{"motivo":"Treinar assistência terapêutica e incorporação de tecnologia — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"Ministério da Saúde, assessorado pela Conitec"},"comentario":{"resolucao":"CERTO. É o caput do art. 19-Q: a decisão é do Ministério da Saúde; a Comissão Nacional de Incorporação de Tecnologias no SUS assessora, emitindo relatório.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-315":{"cognitivo":{"motivo":"Treinar assistência terapêutica e incorporação de tecnologia — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"avaliação econômica comparativa"},"comentario":{"resolucao":"ERRADO. O § 2º do art. 19-Q exige, além das evidências científicas, a AVALIAÇÃO ECONÔMICA COMPARATIVA dos benefícios e dos custos em relação às tecnologias já incorporadas, inclusive no que se refere aos atendimentos domiciliar, ambulatorial ou hospitalar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-316":{"cognitivo":{"motivo":"Treinar assistência terapêutica e incorporação de tecnologia — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"experimental"},"comentario":{"resolucao":"CERTO. É a regra do art. 19-T, I. A Lei 14.313/2022 abriu exceção apenas para o uso off-label recomendado pela Conitec e com protocolo do Ministério da Saúde — o que não muda a vedação geral ao experimental.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-317":{"cognitivo":{"motivo":"Treinar vigilância sanitária — controle de serviços — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"direta ou indiretamente"},"comentario":{"resolucao":"ERRADO. Pelo art. 6º, § 1º, II, a vigilância sanitária abrange o controle da prestação de serviços que se relacionam DIRETA OU INDIRETAMENTE com a saúde. O 'apenas diretamente' restringe o que a lei não restringe. (O material marca 'Certa', mas o artigo que o próprio comentário transcreve contradiz essa marcação.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Vigilância sanitária: bens de consumo + serviços, direta OU indiretamente ligados à saúde.","erroComum":"Achar que a vigilância só alcança serviços de saúde em sentido estrito.","comoBancaPensa":"Restrição indevida com 'apenas'."}},"SUS-318":{"cognitivo":{"motivo":"Treinar vigilância sanitária — controle de serviços — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"eliminar, diminuir ou prevenir riscos"},"comentario":{"resolucao":"CERTO. É a definição do § 1º do art. 6º. Guarde as palavras-chave: 'eliminar, diminuir ou prevenir riscos' e 'intervir nos problemas sanitários' — a vigilância epidemiológica, por sua vez, é 'conhecimento, detecção ou prevenção de mudanças nos fatores determinantes'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Vigilância sanitária: bens de consumo + serviços, direta OU indiretamente ligados à saúde.","erroComum":"Achar que a vigilância só alcança serviços de saúde em sentido estrito.","comoBancaPensa":"Restrição indevida com 'apenas'."}},"SUS-319":{"cognitivo":{"motivo":"Treinar vigilância epidemiológica — definição — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"conhecimento, detecção ou prevenção"},"comentario":{"resolucao":"E. Art. 6º, § 2º: vigilância epidemiológica é o conjunto de ações que proporcionam o conhecimento, a detecção ou a prevenção de qualquer mudança nos fatores determinantes e condicionantes de saúde individual ou coletiva, para recomendar e adotar medidas de prevenção e controle de doenças ou agravos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-320":{"cognitivo":{"motivo":"Treinar vigilância epidemiológica — definição — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"definição da vigilância sanitária"},"comentario":{"resolucao":"ERRADO. A definição transcrita é a da VIGILÂNCIA SANITÁRIA (art. 6º, § 1º). A epidemiológica (§ 2º) é o conjunto de ações que proporcionam o conhecimento, a detecção ou a prevenção de mudanças nos fatores determinantes e condicionantes da saúde, para recomendar medidas de controle.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-321":{"cognitivo":{"motivo":"Treinar universalidade × igualdade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"todos têm acesso"},"comentario":{"resolucao":"D. Garantir que TODOS tenham acesso às ações e serviços, independentemente de raça, sexo ou classe social, é a universalidade. A igualdade (art. 7º, IV) proíbe preconceitos e privilégios na assistência; a equidade trata desigualmente os desiguais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-322":{"cognitivo":{"motivo":"Treinar princípios doutrinários — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"universalidade, integralidade e equidade"},"comentario":{"resolucao":"A. Os princípios doutrinários do SUS são universalidade, integralidade e equidade. Descentralização, regionalização, hierarquização e participação da comunidade são diretrizes organizativas; a participação da comunidade é marca do SUS, não algo excluído.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-323":{"cognitivo":{"motivo":"Treinar hierarquização — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"níveis crescentes de complexidade"},"comentario":{"resolucao":"E. Organizar os serviços em atenção primária, secundária e terciária, em níveis de complexidade crescente, é a HIERARQUIZAÇÃO (art. 8º). A regionalização trata da distribuição territorial; a descentralização, da redistribuição de poder entre as esferas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-324":{"cognitivo":{"motivo":"Treinar hierarquização — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"hierarquização"},"comentario":{"resolucao":"ERRADO. O conceito descrito é o de HIERARQUIZAÇÃO. A regionalização organiza a rede num território delimitado (região de saúde), com população definida; as duas aparecem juntas no art. 7º, IX, b, e no art. 8º, mas não se confundem.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-325":{"cognitivo":{"motivo":"Treinar telessaúde — V/F — ponto de telessaúde (Lei 8.080, arts. 26-A a 26-H) que a banca transforma em item.","palavraCritica":"atendimento presencial garantido"},"comentario":{"resolucao":"E (V, F, V). Assistência segura e com qualidade e confidencialidade dos dados são princípios da telessaúde (art. 26-A). Quem recusa a telessaúde NÃO perde o atendimento presencial: é garantido sempre que solicitado. A normatização ética cabe aos conselhos federais de fiscalização profissional (art. 26-D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-326":{"cognitivo":{"motivo":"Treinar telessaúde — V/F — ponto de telessaúde (Lei 8.080, arts. 26-A a 26-H) que a banca transforma em item.","palavraCritica":"sempre que solicitado"},"comentario":{"resolucao":"CERTO. O art. 26-A, III, assegura o direito de recusa com garantia de atendimento presencial 'sempre que solicitado' — aqui o 'sempre' é do texto legal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-327":{"cognitivo":{"motivo":"Treinar telessaúde — V/F — ponto de telessaúde (Lei 8.080, arts. 26-A a 26-H) que a banca transforma em item.","palavraCritica":"conselhos federais"},"comentario":{"resolucao":"ERRADO. O art. 26-D atribui aos CONSELHOS FEDERAIS de fiscalização do exercício profissional a normatização ética da telessaúde, aplicando-se os padrões das modalidades presenciais no que não colidirem com a lei. Ao órgão de direção do SUS cabem normas sobre condições de funcionamento (art. 26-E), não sobre ética profissional.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-328":{"cognitivo":{"motivo":"Treinar equidade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"igualdade e justiça social"},"comentario":{"resolucao":"A. Respeito às necessidades, diversidades e especificidades de cada cidadão ou grupo, com relação direta com igualdade e justiça social: é a EQUIDADE — tratar desigualmente os desiguais, investindo mais onde a carência é maior.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-329":{"cognitivo":{"motivo":"Treinar princípios do art. 7º — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"direito à informação, igualdade, participação"},"comentario":{"resolucao":"B. Direito à informação (V), igualdade da assistência (IV) e participação da comunidade (VIII) estão no rol do art. 7º. As demais misturam atribuições (art. 15/16), objetivos e termos estranhos à lei; 'centralização' contraria a descentralização (IX).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-330":{"cognitivo":{"motivo":"Treinar princípios do art. 7º — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"direito à informação"},"comentario":{"resolucao":"CERTO. São os incisos V e VI do art. 7º. Note que o sigilo não é princípio: a lei manda DIVULGAR o potencial dos serviços.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-331":{"cognitivo":{"motivo":"Treinar subsistemas da Lei 8.080 — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"indígena, domiciliar, parto"},"comentario":{"resolucao":"E. A Lei 8.080 prevê, em capítulos próprios, o Subsistema de Atenção à Saúde Indígena (arts. 19-A a 19-H), o Subsistema de Atendimento e Internação Domiciliar (art. 19-I) e o Subsistema de Acompanhamento durante o Trabalho de Parto, Parto e Pós-Parto Imediato (art. 19-J). Saúde prisional, da mulher, do homem, da criança e do idoso são políticas, não subsistemas da lei. (O material não traz o gabarito; a resposta sai do texto legal.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-332":{"cognitivo":{"motivo":"Treinar subsistemas da Lei 8.080 — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"indicado pela parturiente"},"comentario":{"resolucao":"CERTO. É o art. 19-J (Lei 11.108/2005). O acompanhante é UM e é indicado pela PARTURIENTE — não pela equipe nem pela família.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-333":{"cognitivo":{"motivo":"Treinar subsistemas da Lei 8.080 — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"subsistemas da lei"},"comentario":{"resolucao":"ERRADO. Os subsistemas da lei são o de atenção à saúde indígena, o de atendimento e internação domiciliar e o de acompanhamento do parto. Saúde prisional e saúde do idoso são objeto de políticas próprias (PNAISP, Estatuto da Pessoa Idosa), não de subsistemas da Lei 8.080.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-334":{"cognitivo":{"motivo":"Treinar internação domiciliar — incorreta — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"internação domiciliar é preconizada"},"comentario":{"resolucao":"D (incorreta). O SUS preconiza tanto o atendimento quanto a INTERNAÇÃO domiciliar (art. 19-I, caput). As demais reproduzem os §§ 1º a 3º do mesmo artigo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-335":{"cognitivo":{"motivo":"Treinar lei 8.080 — incorreta — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"quem regulamenta é o Decreto 7.508"},"comentario":{"resolucao":"C (incorreta). 'Regulamenta a Lei 8.080/1990, para dispor sobre a organização do SUS, o planejamento da saúde, a assistência à saúde e a articulação interfederativa' é a ementa do DECRETO 7.508/2011 — e ele regulamenta a 8.080, não a 8.142. As demais são da própria Lei 8.080 (ementa, art. 1º, art. 4º, art. 2º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-336":{"cognitivo":{"motivo":"Treinar lei 8.080 — incorreta — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"regulamenta a Lei 8.080"},"comentario":{"resolucao":"ERRADO. O Decreto 7.508/2011 regulamenta a Lei 8.080/1990. Conferências e conselhos de saúde já estão na própria Lei 8.142/1990, que trata da participação da comunidade e das transferências intergovernamentais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-337":{"cognitivo":{"motivo":"Treinar objetivos do SUS (art. 5º) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"epidemiologia é princípio"},"comentario":{"resolucao":"B (I e II). São objetivos do SUS (art. 5º): identificar e divulgar fatores condicionantes e determinantes; formular política de saúde nos campos econômico e social; e prestar assistência por ações de promoção, proteção e recuperação. A utilização da epidemiologia para estabelecer prioridades (III) é PRINCÍPIO (art. 7º, VII), não objetivo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-338":{"cognitivo":{"motivo":"Treinar objetivos do SUS (art. 5º) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"princípio, não objetivo"},"comentario":{"resolucao":"ERRADO. Está no art. 7º, VII, entre os PRINCÍPIOS e diretrizes. Os objetivos do art. 5º são três: identificar e divulgar determinantes, formular política de saúde e prestar assistência integrada.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-339":{"cognitivo":{"motivo":"Treinar princípios — exceto — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"centralidade não é princípio"},"comentario":{"resolucao":"B. 'Centralidade' não existe entre os princípios: a lei adota a DEScentralização político-administrativa (art. 7º, IX). Igualdade, integralidade e universalidade estão no art. 7º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-340":{"cognitivo":{"motivo":"Treinar art. 2º — dever do Estado — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"não exclui pessoas, família, empresas"},"comentario":{"resolucao":"B. Art. 2º, § 2º: o dever do Estado não exclui o das pessoas, da família, das empresas e da sociedade. Erros: condições INDISPENSÁVEIS (A); política de sangue está no campo do SUS (C; art. 6º, XI); a definição em D é de vigilância SANITÁRIA; os determinantes são exemplificativos ('entre outros'), não exclusivos (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-341":{"cognitivo":{"motivo":"Treinar art. 2º — dever do Estado — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"política de sangue"},"comentario":{"resolucao":"CERTO. Estão no art. 6º, incisos XI e IV, respectivamente. Ambas são pegadinhas recorrentes do tipo 'não está incluída'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-342":{"cognitivo":{"motivo":"Treinar atribuições comuns (art. 15) — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"formação e desenvolvimento de RH"},"comentario":{"resolucao":"A. Participar da formulação e da execução da política de formação e desenvolvimento de recursos humanos para a saúde é atribuição COMUM às três esferas (art. 15, IX). As demais são competências da direção NACIONAL (art. 16): articulação com órgãos educacionais, política de insumos e equipamentos, identificação de serviços de referência nacional, controle de procedimentos e substâncias.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-343":{"cognitivo":{"motivo":"Treinar direção municipal — exceto — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"alimentação e nutrição é federal"},"comentario":{"resolucao":"A (exceto). Formular, avaliar e apoiar políticas de alimentação e nutrição é competência da direção NACIONAL (art. 16, I). Ao município cabe executar a política de insumos (art. 18, V), gerir laboratórios públicos e hemocentros (VIII) e formar consórcios intermunicipais (VII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-344":{"cognitivo":{"motivo":"Treinar direção municipal — exceto — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"gerir laboratórios e hemocentros"},"comentario":{"resolucao":"CERTO. Art. 18, VIII e VII. Compare: ao estado cabe COORDENAR a rede estadual de laboratórios e hemocentros (art. 17); ao município, GERIR os seus.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-345":{"cognitivo":{"motivo":"Treinar direção municipal — exceto — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"direção nacional formula"},"comentario":{"resolucao":"ERRADO. Inverteu os papéis: formular, avaliar e apoiar políticas de alimentação e nutrição é da direção NACIONAL (art. 16, I); ao município cabe EXECUTAR os serviços de alimentação e nutrição (art. 18, IV, c).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-346":{"cognitivo":{"motivo":"Treinar arts. 2º e 3º — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"todas corretas"},"comentario":{"resolucao":"A (I, II, III e IV). Todas reproduzem a lei: art. 2º, caput e §§ 1º e 2º, e art. 3º, caput (determinantes e condicionantes, rol exemplificativo, e os níveis de saúde expressando a organização social e econômica do País).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-347":{"cognitivo":{"motivo":"Treinar arts. 2º e 3º — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"atividade física"},"comentario":{"resolucao":"CERTO. A atividade física foi incluída no art. 3º pela Lei 12.864/2013. O rol é exemplificativo ('entre outros').","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-348":{"cognitivo":{"motivo":"Treinar arts. 2º e 3º — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"entre outros"},"comentario":{"resolucao":"ERRADO. O art. 3º usa 'entre outros': o rol é EXEMPLIFICATIVO. O parágrafo único ainda inclui as ações destinadas a garantir condições de bem-estar físico, mental e social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-349":{"cognitivo":{"motivo":"Treinar cinco princípios — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"universalidade a participação popular"},"comentario":{"resolucao":"A. Universalidade, equidade e integralidade (doutrinários) e descentralização e participação popular (organizativos). Centralização, 'não participação' e organismos internacionais (ONU/OTAN) não têm relação com o SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-350":{"cognitivo":{"motivo":"Treinar competências do município — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"planejar, organizar, controlar, avaliar e gerir"},"comentario":{"resolucao":"B. Art. 18, I: compete à direção municipal planejar, organizar, controlar e avaliar as ações e os serviços de saúde e gerir e executar os serviços públicos de saúde. A coordenação da rede de laboratórios e hemocentros (A) e das regionais (C) é do estado; 'participar da execução... nas unidades estaduais' (D) mistura as esferas; não há '75% do orçamento' na lei (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-351":{"cognitivo":{"motivo":"Treinar princípios — conceitos — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"equidade reconhece diferenças"},"comentario":{"resolucao":"B. Equidade: ofertar o cuidado reconhecendo as diferenças nas condições de vida e saúde, conforme as necessidades. Erros: universalidade não prioriza cadastrados (A); integralidade inclui casos agudos e todos os níveis (C); 'gratuidade' e 'coordenação do cuidado' não são princípios do art. 7º nos termos propostos (D, E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-352":{"cognitivo":{"motivo":"Treinar acesso de todos — universalidade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"universalidade, não integralidade"},"comentario":{"resolucao":"ERRADO. Garantir que TODA pessoa tenha acesso à saúde é a UNIVERSALIDADE. A integralidade é o conjunto articulado e contínuo de ações preventivas e curativas, individuais e coletivas, em todos os níveis de complexidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Todos = universalidade; tudo = integralidade; cada um conforme a necessidade = equidade.","erroComum":"Confundir universalidade com integralidade.","comoBancaPensa":"Troca de princípio sobre o mesmo fragmento."}},"SUS-353":{"cognitivo":{"motivo":"Treinar acesso ao tratamento — universalidade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"princípio da justiça não existe"},"comentario":{"resolucao":"ERRADO. Não existe 'princípio da justiça' no rol do SUS. Assegurar que toda pessoa tenha acesso ao tratamento de qualquer doença decorre da UNIVERSALIDADE; a ideia de justiça social está ligada à equidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Todos = universalidade; tudo = integralidade; cada um conforme a necessidade = equidade.","erroComum":"Aceitar princípio inexistente.","comoBancaPensa":"Princípio inventado."}},"SUS-354":{"cognitivo":{"motivo":"Treinar equidade — atender conforme a necessidade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"de modos diferentes"},"comentario":{"resolucao":"CERTO. Atender cada indivíduo, de modos diferentes, conforme sua necessidade é exatamente a EQUIDADE: tratar desigualmente os desiguais, reconhecendo as diferentes condições de vida.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Todos = universalidade; tudo = integralidade; cada um conforme a necessidade = equidade.","erroComum":"Confundir equidade com igualdade.","comoBancaPensa":"Item conceitual direto."}},"SUS-355":{"cognitivo":{"motivo":"Treinar resolubilidade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"resolver até o nível da competência"},"comentario":{"resolucao":"B. Resolubilidade (capacidade de resolução dos serviços em todos os níveis de assistência — art. 7º, XII): o serviço deve estar capacitado para enfrentar e resolver o problema até o nível de sua competência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-356":{"cognitivo":{"motivo":"Treinar resolubilidade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"evitar duplicidade"},"comentario":{"resolucao":"CERTO. Art. 7º, XII e XIII. 'Garantir a duplicidade' é a pegadinha clássica; o texto é EVITAR duplicidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-357":{"cognitivo":{"motivo":"Treinar objetivos do SUS — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"identificação e divulgação dos determinantes"},"comentario":{"resolucao":"A. Art. 5º, I: identificar e divulgar os fatores condicionantes e determinantes da saúde. Erros: a assistência (não 'informação') se dá por ações de promoção, proteção e recuperação (B); o SUS PARTICIPA da política de saneamento (C); o trabalhador vítima de acidente de trabalho está incluído (D; art. 6º, § 3º, I); fiscalização de alimentos e bebidas está no campo do SUS (E; art. 6º, VIII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-358":{"cognitivo":{"motivo":"Treinar objetivos do SUS — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"acidente de trabalho"},"comentario":{"resolucao":"CERTO. É o § 3º do art. 6º, inciso I e seguintes: a assistência inclui tanto a vítima de acidente de trabalho quanto o portador de doença profissional e do trabalho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-359":{"cognitivo":{"motivo":"Treinar objetivos do SUS — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"campo de atuação do SUS"},"comentario":{"resolucao":"ERRADO. O art. 6º, VIII, inclui no campo do SUS a fiscalização e a inspeção de alimentos, água e bebidas para consumo humano. A Anvisa é vinculada ao MINISTÉRIO DA SAÚDE e integra o Sistema Nacional de Vigilância Sanitária.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-360":{"cognitivo":{"motivo":"Treinar princípios — incorreta (equidade) — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"equidade não desconsidera desigualdades"},"comentario":{"resolucao":"C (incorreta). A equidade faz o oposto: CONSIDERA as desigualdades sociais e econômicas e prioriza quem tem mais necessidade. Distribuir igualmente recursos entre regiões com necessidades diferentes contraria a equidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-361":{"cognitivo":{"motivo":"Treinar iniciativa privada — complementar — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"caráter complementar, não integral"},"comentario":{"resolucao":"C (incorreta). A iniciativa privada pode participar do SUS em caráter COMPLEMENTAR (art. 4º, § 2º), não integral. As demais são o art. 2º, o art. 1º e o art. 4º, § 1º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-362":{"cognitivo":{"motivo":"Treinar iniciativa privada — complementar — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"incluídas no SUS"},"comentario":{"resolucao":"CERTO. É o § 1º do art. 4º. A pegadinha é dizer que essas instituições estão 'excluídas' do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-363":{"cognitivo":{"motivo":"Treinar direção única na União — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"Ministério da Saúde"},"comentario":{"resolucao":"B. Art. 9º: a direção do SUS é única, exercida no âmbito da União pelo MINISTÉRIO DA SAÚDE; nos estados e DF, pela secretaria de saúde ou órgão equivalente; nos municípios, pela secretaria de saúde ou órgão equivalente.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-364":{"cognitivo":{"motivo":"Treinar direção única na União — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"secretaria de saúde ou órgão equivalente"},"comentario":{"resolucao":"CERTO. É o art. 9º, II e III. Conselho de saúde não dirige o SUS: delibera e controla (Lei 8.142).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-365":{"cognitivo":{"motivo":"Treinar direção única na União — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"secretaria municipal"},"comentario":{"resolucao":"ERRADO. A direção municipal é da SECRETARIA MUNICIPAL DE SAÚDE ou órgão equivalente (art. 9º, III). O conselho é instância colegiada deliberativa de controle social (Lei 8.142), não gestor nem executor dos serviços.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-366":{"cognitivo":{"motivo":"Treinar dever do Estado (art. 2º, § 1º) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"políticas econômicas e sociais"},"comentario":{"resolucao":"A. O dever do Estado consiste na formulação e execução de políticas econômicas e sociais que visem à redução de riscos de doenças e de outros agravos e no estabelecimento de condições que assegurem acesso UNIVERSAL e IGUALITÁRIO (art. 2º, § 1º). Não é 'taxativamente a cura', nem restrito, nem exclui pessoas, família e empresas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-367":{"cognitivo":{"motivo":"Treinar lei 8.080 — correta — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"indicação médica"},"comentario":{"resolucao":"D. Art. 19-I, § 3º. Erros: o dever do Estado NÃO exclui o das pessoas (A); controle da prestação de serviços é vigilância SANITÁRIA (B); estados e municípios PODEM atuar complementarmente no subsistema indígena (C; art. 19-E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-368":{"cognitivo":{"motivo":"Treinar direção municipal — correta — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"condições e ambientes de trabalho"},"comentario":{"resolucao":"B. Art. 18, III: participar da execução, controle e avaliação das ações referentes às condições e aos ambientes de trabalho. A (alimentação e nutrição) e C (critérios de qualidade sanitária) são da direção nacional; D (coordenar a vigilância epidemiológica) é da estadual — o município EXECUTA.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-369":{"cognitivo":{"motivo":"Treinar direção municipal — correta — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"coordenar e, complementarmente, executar"},"comentario":{"resolucao":"CERTO. É o art. 17, IV. A gradação é: União DEFINE e coordena os sistemas nacionais; estado COORDENA e executa complementarmente; município EXECUTA.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-370":{"cognitivo":{"motivo":"Treinar capital estrangeiro — incorreta — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"permitido nos casos da lei"},"comentario":{"resolucao":"C (incorreta). Desde a Lei 13.097/2015, o art. 23 PERMITE a participação direta ou indireta, inclusive controle, de empresas ou capital estrangeiro na assistência à saúde em casos como doações de organismos internacionais, hospitais gerais e especializados, policlínicas e clínicas, e serviços mantidos por empresas para seus empregados. Não há vedação absoluta.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-371":{"cognitivo":{"motivo":"Treinar capital estrangeiro — incorreta — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"capital estrangeiro permitido"},"comentario":{"resolucao":"CERTO. Art. 23, II, a, na redação da Lei 13.097/2015. Antes a regra era a vedação, com exceções; hoje a lei lista os casos permitidos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-372":{"cognitivo":{"motivo":"Treinar lei 8.080 — de acordo (hemocentros) — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"município gere hemocentros"},"comentario":{"resolucao":"C. Art. 18, VIII. Erros: o subsistema indígena é financiado pela UNIÃO (A); a internação domiciliar é prevista (B; art. 19-I); vigilância nutricional está no campo do SUS (D; art. 6º, IV); em emergência em saúde pública pode ser adotado procedimento SIMPLIFICADO para remessa de patrimônio genético ao exterior (E; art. 16, § 2º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-373":{"cognitivo":{"motivo":"Treinar lei 8.080 — de acordo (hemocentros) — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"procedimento simplificado"},"comentario":{"resolucao":"CERTO. É o § 2º do art. 16 — regra pensada para acelerar a pesquisa em epidemias. A banca troca 'simplificado' por 'padrão' e acrescenta sanção inexistente.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-374":{"cognitivo":{"motivo":"Treinar telessaúde — abrangência — ponto de telessaúde (Lei 8.080, arts. 26-A a 26-H) que a banca transforma em item.","palavraCritica":"todas as profissões da saúde"},"comentario":{"resolucao":"B. Art. 26-A: a telessaúde abrange a prestação remota de serviços relacionados a TODAS as profissões da área da saúde regulamentadas pelos órgãos competentes do Poder Executivo federal. Erros: é aplicável ao SUS (A); a dispensa de inscrição secundária vale para quem atua EXCLUSIVAMENTE por telessaúde, sem limite de atendimentos (C; art. 26-H); não é só medicina (D); admite textos, sons e imagens (E; art. 26-B).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-375":{"cognitivo":{"motivo":"Treinar telessaúde — abrangência — ponto de telessaúde (Lei 8.080, arts. 26-A a 26-H) que a banca transforma em item.","palavraCritica":"exclusivamente por telessaúde"},"comentario":{"resolucao":"CERTO. É o art. 26-H. O 'exclusivamente' é do texto legal; o que a banca inventa é um limite numérico de atendimentos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-376":{"cognitivo":{"motivo":"Treinar telessaúde — abrangência — ponto de telessaúde (Lei 8.080, arts. 26-A a 26-H) que a banca transforma em item.","palavraCritica":"textos, sons, imagens"},"comentario":{"resolucao":"ERRADO. O art. 26-B admite a transmissão por meio de textos, de sons, de imagens ou outras formas adequadas, e seu parágrafo único dá aos atos praticados em telessaúde validade em TODO o território nacional.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-377":{"cognitivo":{"motivo":"Treinar universalidade — sem distinção — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"igualdade de acesso sem discriminação"},"comentario":{"resolucao":"C. Direito à vida e igualdade de ACESSO sem distinção de raça, sexo, religião ou qualquer discriminação remete à universalidade. Integralidade é o conjunto de ações; equidade, a priorização dos mais necessitados; transversalidade e gratuidade não são os princípios descritos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-378":{"cognitivo":{"motivo":"Treinar comissão Intergestores Bipartite — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"municipais e estaduais"},"comentario":{"resolucao":"B. A CIB reúne gestores ESTADUAIS e MUNICIPAIS (vinculada à secretaria estadual); a CIT reúne gestores federal, estaduais e municipais (vinculada ao Ministério da Saúde). São foros de negociação e pactuação reconhecidos pelo art. 14-A.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-379":{"cognitivo":{"motivo":"Treinar comissão Intergestores Bipartite — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"negociação e pactuação"},"comentario":{"resolucao":"CERTO. É o art. 14-A, incluído pela Lei 12.466/2011, que também reconheceu o CONASS e o CONASEMS como entidades representativas dos gestores (art. 14-B).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-380":{"cognitivo":{"motivo":"Treinar comissão Intergestores Bipartite — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"estaduais e municipais"},"comentario":{"resolucao":"ERRADO. A CIB é formada por gestores ESTADUAIS e MUNICIPAIS — a secretaria estadual é justamente uma das partes. Gestor federal entra na CIT (tripartite), junto com estados e municípios.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-381":{"cognitivo":{"motivo":"Treinar caso — estrangeiro com dor precordial — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"universalidade e equidade"},"comentario":{"resolucao":"E. Atender o estrangeiro, mesmo em situação migratória irregular, é universalidade; atendê-lo antes dos agendados, pela gravidade (dor precordial intensa), é equidade — dar mais a quem mais precisa. Integralidade não é o que justifica a ordem do atendimento.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-382":{"cognitivo":{"motivo":"Treinar caso — estrangeiro com dor precordial — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"equidade na priorização"},"comentario":{"resolucao":"CERTO. Universalidade garante o acesso independentemente de nacionalidade ou situação documental; a priorização conforme a gravidade (classificação de risco) é a equidade em ação.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-383":{"cognitivo":{"motivo":"Treinar planejamento ascendente — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"do local ao federal"},"comentario":{"resolucao":"D. Art. 36: o planejamento e o orçamento do SUS são ASCENDENTES, do nível local até o federal, ouvidos os órgãos deliberativos. Erros: conta ESPECIAL movimentada sob FISCALIZAÇÃO dos conselhos (A); recursos federais administrados pelo Ministério da SAÚDE, via Fundo Nacional (B); receitas próprias vão para contas especiais da direção do SUS, não para o caixa único (E; art. 32, § 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-384":{"cognitivo":{"motivo":"Treinar planejamento ascendente — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"ascendente"},"comentario":{"resolucao":"CERTO. É o caput do art. 36 — ascendente, do local ao federal, ouvidos os conselhos. Esse artigo é dos mais cobrados da lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-385":{"cognitivo":{"motivo":"Treinar planejamento ascendente — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"exceto emergência ou calamidade"},"comentario":{"resolucao":"ERRADO. O § 2º do art. 36 veda essa transferência, EXCETO em situações emergenciais ou de calamidade pública na área de saúde — justamente as hipóteses que a banca diz não excepcionadas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-386":{"cognitivo":{"motivo":"Treinar planejamento ascendente — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"contas especiais"},"comentario":{"resolucao":"ERRADO. O § 1º do art. 32 manda creditá-las diretamente em CONTAS ESPECIAIS, movimentadas pela direção do SUS na esfera onde forem arrecadadas — o dinheiro fica vinculado à saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-387":{"cognitivo":{"motivo":"Treinar princípios do art. 7º — correta — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"epidemiologia para prioridades"},"comentario":{"resolucao":"E. Art. 7º, VII. Erros: universalidade, não 'seletividade' (A); DEScentralização (B); DIVULGAÇÃO, não sigilo, do potencial dos serviços (C); EVITAR duplicidade (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-388":{"cognitivo":{"motivo":"Treinar participação complementar — instrumento — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"contrato ou convênio"},"comentario":{"resolucao":"A. Art. 24, parágrafo único: a participação complementar dos serviços privados será formalizada mediante CONTRATO ou CONVÊNIO, observadas as normas de direito público. As filantrópicas e as sem fins lucrativos têm preferência (art. 25).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-389":{"cognitivo":{"motivo":"Treinar participação complementar — instrumento — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"aprovados no CNS"},"comentario":{"resolucao":"CERTO. Arts. 25 e 26 da Lei 8.080. A tabela de remuneração é da direção nacional, com aprovação do CNS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-390":{"cognitivo":{"motivo":"Treinar participação complementar — instrumento — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"preferência às filantrópicas"},"comentario":{"resolucao":"ERRADO. O art. 25 dá preferência às entidades FILANTRÓPICAS e às SEM FINS LUCRATIVOS. A capacidade instalada não altera essa ordem legal de preferência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-391":{"cognitivo":{"motivo":"Treinar composição do SUS (art. 4º) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"fundações mantidas pelo Poder Público"},"comentario":{"resolucao":"B. Art. 4º: o SUS é o conjunto de ações e serviços prestados por órgãos e instituições públicas federais, estaduais e municipais, da administração direta e indireta e das FUNDAÇÕES mantidas pelo Poder Público; a iniciativa privada participa em caráter COMPLEMENTAR (§ 2º) e as instituições de controle de qualidade, pesquisa e produção estão INCLUÍDAS (§ 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-392":{"cognitivo":{"motivo":"Treinar composição do SUS (art. 4º) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"instituições públicas"},"comentario":{"resolucao":"ERRADO. Pelo art. 4º, o SUS é formado por órgãos e instituições PÚBLICAS (incluídas as fundações mantidas pelo Poder Público). A iniciativa privada pode participar, mas em caráter COMPLEMENTAR (§ 2º), não em igualdade com a rede pública.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-393":{"cognitivo":{"motivo":"Treinar controle de bens de consumo — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"vigilância sanitária"},"comentario":{"resolucao":"E. O controle de bens de consumo que se relacionam com a saúde, em todas as etapas, da produção ao consumo, é ação de vigilância SANITÁRIA (art. 6º, § 1º, I).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-394":{"cognitivo":{"motivo":"Treinar princípios — redação do art. 7º — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"descentralização com regionalização"},"comentario":{"resolucao":"C (apenas III). A descentralização político-administrativa envolve a regionalização e a hierarquização da rede (art. 7º, IX, b). I erra: o acesso em todos os níveis é a UNIVERSALIDADE (I), e a igualdade é 'sem preconceitos ou privilégios' (IV). II erra: a preservação da autonomia é princípio autônomo (III), e a integralidade é o conjunto articulado de ações preventivas e curativas (II).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-395":{"cognitivo":{"motivo":"Treinar princípios — redação do art. 7º — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"conjunto articulado e contínuo"},"comentario":{"resolucao":"CERTO. É o inciso II do art. 7º, palavra por palavra. A banca troca a definição pela de outro inciso (autonomia, igualdade).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-396":{"cognitivo":{"motivo":"Treinar princípios — redação do art. 7º — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"sem preconceitos ou privilégios"},"comentario":{"resolucao":"ERRADO. A igualdade é a assistência 'sem preconceitos ou privilégios de qualquer espécie' (art. 7º, IV). O acesso em todos os níveis é a definição da UNIVERSALIDADE (inciso I), e a contribuição não dá prioridade a ninguém no SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Literalidade da Lei 8.080."}},"SUS-397":{"cognitivo":{"motivo":"Treinar consórcios e distritos — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"consórcios intermunicipais"},"comentario":{"resolucao":"CERTO. O art. 10 autoriza os consórcios e o § 1º determina que a eles se aplique a direção única, com os respectivos atos constitutivos dispondo sobre sua observância. O § 2º permite ainda organizar o município em distritos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Consórcio: municípios juntos, direção única preservada.","erroComum":"Achar que o consórcio cria uma quarta esfera de gestão.","comoBancaPensa":"Artigo de organização pouco lembrado."}},"SUS-398":{"cognitivo":{"motivo":"Treinar comissões de integração ensino-serviço — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"integração entre serviços e instituições de ensino"},"comentario":{"resolucao":"CERTO. É o art. 14 e seu parágrafo único — base legal da articulação ensino-serviço, que se soma à atribuição de ordenar a formação de recursos humanos (art. 6º, III, e art. 200, III, da CF).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"SUS ordena a formação e integra serviço e escola.","erroComum":"Achar que a formação de RH é só do MEC.","comoBancaPensa":"Dispositivo de RH."}},"SUS-399":{"cognitivo":{"motivo":"Treinar união — vigilância em circunstâncias especiais — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"agravos inusitados"},"comentario":{"resolucao":"CERTO. É a regra do art. 16, § 1º (antigo parágrafo único): a regra é a execução municipal, com coordenação estadual, mas a União pode executar diretamente nessas circunstâncias.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Regra: município executa. Exceção: União em agravo inusitado ou risco nacional.","erroComum":"Achar que a União nunca executa ações de vigilância.","comoBancaPensa":"Exceção à repartição de competências."}},"SUS-400":{"cognitivo":{"motivo":"Treinar vigilância de portos, aeroportos e fronteiras — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"executar a vigilância sanitária de portos"},"comentario":{"resolucao":"ERRADO. A vigilância sanitária de portos, aeroportos e fronteiras é executada pela União (direção nacional, via Anvisa — art. 16, VII), podendo a execução ser complementada pelos estados, DF e municípios. Ao município cabe COLABORAR com a União e os estados nessa execução (art. 18, IX).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Portos, aeroportos e fronteiras: União executa; município colabora.","erroComum":"Atribuir a execução ao município.","comoBancaPensa":"Troca de sujeito na competência."}},"SUS-401":{"cognitivo":{"motivo":"Treinar sistema Nacional de Auditoria — ponto de competências das três esferas (Lei 8.080, arts. 15 a 18) que a banca transforma em item.","palavraCritica":"União estabelece o SNA"},"comentario":{"resolucao":"ERRADO. Estabelecer o Sistema Nacional de Auditoria e coordenar a avaliação técnica e financeira do SUS em todo o território nacional é competência da direção NACIONAL (art. 16, XIX), em cooperação técnica com estados, municípios e DF.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Nacional = União. O que é 'em todo o território' é da direção nacional.","erroComum":"Atribuir ao município uma competência nacional.","comoBancaPensa":"Troca de esfera."}},"SUS-402":{"cognitivo":{"motivo":"Treinar campo de atuação — saúde bucal — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"saúde bucal incluída"},"comentario":{"resolucao":"CERTO. São as alíneas do art. 6º, I; a saúde bucal (alínea e) foi incluída pela Lei 14.572/2023, que instituiu a Política Nacional de Saúde Bucal no SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Art. 6º, I: VS, VE, ST, assistência terapêutica e saúde bucal.","erroComum":"Achar que saúde bucal é só política infralegal.","comoBancaPensa":"Atualização legislativa recente."}},"SUS-403":{"cognitivo":{"motivo":"Treinar substâncias psicoativas, tóxicas e radioativas — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"participação no controle"},"comentario":{"resolucao":"CERTO. Art. 6º, IX e X. O verbo é PARTICIPAR do controle — o SUS não é o único responsável, mas integra a fiscalização.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Campo do SUS é amplo: de alimentos a radioativos.","erroComum":"Restringir o SUS à assistência.","comoBancaPensa":"Amplitude do art. 6º."}},"SUS-404":{"cognitivo":{"motivo":"Treinar meio ambiente do trabalho — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"colaborar na proteção"},"comentario":{"resolucao":"ERRADO. Ao SUS cabe COLABORAR na proteção do meio ambiente, NELE COMPREENDIDO O DO TRABALHO (art. 6º, V). A saúde do trabalhador inclui, aliás, a fiscalização das condições de produção e dos ambientes de trabalho (§ 3º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Meio ambiente: o SUS colabora, e o trabalho está dentro.","erroComum":"Excluir o ambiente de trabalho.","comoBancaPensa":"Dupla troca: verbo e alcance."}},"SUS-405":{"cognitivo":{"motivo":"Treinar preservação da autonomia — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"integridade física e moral"},"comentario":{"resolucao":"ERRADO. O art. 7º, III, protege justamente a AUTONOMIA do paciente: decisões sobre seu corpo e sua integridade passam pelo consentimento. A conclusão do item inverte o sentido do princípio.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Autonomia = o paciente decide.","erroComum":"Inverter a finalidade do princípio.","comoBancaPensa":"Conclusão que contradiz a premissa."}},"SUS-406":{"cognitivo":{"motivo":"Treinar atendimento à mulher vítima de violência — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"atendimento específico e especializado"},"comentario":{"resolucao":"CERTO. Incisos XIV (Lei 13.427/2017) e XVI (Lei 14.679/2023) do art. 7º; o inciso XV trata da proteção integral dos direitos humanos dos usuários e da identificação de maus-tratos, negligência e violência sexual contra crianças e adolescentes.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Art. 7º cresceu: XIV mulher vítima de violência, XV crianças, XVI humanização.","erroComum":"Achar que o rol parou no inciso XIII.","comoBancaPensa":"Incisos incluídos recentemente."}},"SUS-407":{"cognitivo":{"motivo":"Treinar descentralização com ênfase nos municípios — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"ênfase nos municípios"},"comentario":{"resolucao":"ERRADO. O art. 7º, IX, a, dá ênfase à descentralização dos serviços para os MUNICÍPIOS; aos estados cabe sobretudo coordenar e apoiar, e executar em caráter complementar (art. 17).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Descentralizar = municipalizar.","erroComum":"Trocar o município pelo estado.","comoBancaPensa":"Troca de esfera."}},"SUS-408":{"cognitivo":{"motivo":"Treinar prazo para incorporação de tecnologia — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"180 dias, prorrogáveis por 90"},"comentario":{"resolucao":"CERTO. É o art. 19-R. O processo também exige consulta pública e, a critério do órgão, audiência pública (§ 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Conitec: 180 + 90 dias.","erroComum":"Trocar os números.","comoBancaPensa":"Troca numérica clássica."}},"SUS-409":{"cognitivo":{"motivo":"Treinar medicamento sem registro na Anvisa — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"sem registro na Anvisa"},"comentario":{"resolucao":"ERRADO. O art. 19-T, II, veda a dispensação, o pagamento, o ressarcimento ou o reembolso de medicamento e produto, nacional ou importado, sem registro na Anvisa. As exceções do parágrafo único são estreitas (uso off-label recomendado pela Conitec; produto recomendado pela Conitec e adquirido por organismo multilateral internacional para programa de saúde pública do Ministério) e não dependem da vontade do prescritor.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Sem registro = vedado (salvo hipóteses legais estritas).","erroComum":"Achar que a prescrição basta.","comoBancaPensa":"Exceção ampliada pela banca."}},"SUS-410":{"cognitivo":{"motivo":"Treinar validade nacional dos atos de telessaúde — ponto de telessaúde (Lei 8.080, arts. 26-A a 26-H) que a banca transforma em item.","palavraCritica":"todo o território nacional"},"comentario":{"resolucao":"CERTO. Art. 26-B, parágrafo único, e art. 26-C: o profissional pode, inclusive, indicar o atendimento presencial sempre que entender necessário.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Telessaúde: vale em todo o país; o profissional decide.","erroComum":"Restringir a validade ao estado.","comoBancaPensa":"Literalidade da Lei 14.510/2022."}},"SUS-411":{"cognitivo":{"motivo":"Treinar restrição à telessaúde — ponto de telessaúde (Lei 8.080, arts. 26-A a 26-H) que a banca transforma em item.","palavraCritica":"imprescindibilidade da medida"},"comentario":{"resolucao":"ERRADO. O art. 26-F exige que o ato normativo que pretenda restringir a telessaúde demonstre a IMPRESCINDIBILIDADE da medida para evitar danos à saúde dos pacientes — a restrição tem ônus de justificação.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Restringir telessaúde exige demonstrar imprescindibilidade.","erroComum":"Achar que a restrição é livre.","comoBancaPensa":"Exigência suprimida."}},"SUS-412":{"cognitivo":{"motivo":"Treinar fontes de financiamento — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"outras fontes"},"comentario":{"resolucao":"CERTO. O art. 32 lista como 'outras fontes': serviços prestados sem prejuízo da assistência, ajudas, contribuições, doações e donativos, alienações patrimoniais e rendimentos de capital, taxas, multas, emolumentos e preços públicos, e rendas eventuais, inclusive comerciais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"SUS = seguridade + outras fontes do art. 32.","erroComum":"Achar que só há recursos orçamentários.","comoBancaPensa":"Rol de fontes."}},"SUS-413":{"cognitivo":{"motivo":"Treinar critérios de repasse — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"perfil demográfico e epidemiológico"},"comentario":{"resolucao":"ERRADO. O art. 35 combina vários critérios: perfil demográfico e epidemiológico da região, características quantitativas e qualitativas da rede, desempenho técnico, econômico e financeiro no período anterior, participação do setor saúde nos orçamentos, plano de investimentos e ressarcimento de serviços prestados a outras esferas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Repasse: vários critérios, não só população.","erroComum":"Reduzir a um critério.","comoBancaPensa":"Rol reduzido a um item."}},"SUS-414":{"cognitivo":{"motivo":"Treinar subvenções a entidades lucrativas — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"finalidade lucrativa"},"comentario":{"resolucao":"ERRADO. O art. 38 não permite a destinação de subvenções e auxílios a instituições prestadoras de serviços de saúde com finalidade lucrativa — regra que repete a vedação do art. 199, § 2º, da Constituição. Contratar serviços (pagando a produção) é diferente de subvencionar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Contratar pode; subvencionar lucrativa, não.","erroComum":"Confundir contrato com subvenção.","comoBancaPensa":"Vedação repetida da CF."}},"SUS-415":{"cognitivo":{"motivo":"Treinar diretrizes dos planos de saúde — ponto de financiamento, planejamento e orçamento (Lei 8.080, arts. 31 a 38) que a banca transforma em item.","palavraCritica":"Conselho Nacional de Saúde"},"comentario":{"resolucao":"CERTO. É o art. 37. A banca costuma trocar o CNS por outro órgão (Ministério, CIT, CONASS).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Diretrizes dos planos: CNS.","erroComum":"Trocar o órgão.","comoBancaPensa":"Troca de sujeito."}},"SUS-416":{"cognitivo":{"motivo":"Treinar cONASS e CONASEMS — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"recursos do orçamento geral da União"},"comentario":{"resolucao":"ERRADO. O art. 14-B, § 1º, prevê que CONASS e CONASEMS receberão recursos do orçamento geral da União, por meio do Fundo Nacional de Saúde, para auxiliar no custeio de suas despesas institucionais, podendo ainda celebrar convênios com a União.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"CONASS/CONASEMS: representam gestores e recebem recursos via FNS.","erroComum":"Inventar vedação de financiamento.","comoBancaPensa":"Vedação inexistente."}},"SUS-417":{"cognitivo":{"motivo":"Treinar interdição do ambiente de trabalho — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"sindicato dos trabalhadores"},"comentario":{"resolucao":"ERRADO. O art. 6º, § 3º, VIII, garante ao SINDICATO DOS TRABALHADORES requerer ao órgão competente a interdição de máquina, setor de serviço ou de todo o ambiente de trabalho diante de risco iminente. A mesma seção prevê a revisão periódica da lista de doenças do trabalho, com colaboração das entidades sindicais (VII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Interdição por risco iminente: quem pede é o sindicato.","erroComum":"Trocar o sujeito da prerrogativa.","comoBancaPensa":"Troca de sujeito."}},"SUS-418":{"cognitivo":{"motivo":"Treinar responsabilidade financeira por medicamentos — ponto de subsistemas e assistência terapêutica (Lei 8.080, arts. 19-A a 19-U) que a banca transforma em item.","palavraCritica":"pactuada na CIT"},"comentario":{"resolucao":"ERRADO. O art. 19-U determina que essa responsabilidade financeira seja PACTUADA na Comissão Intergestores Tripartite — a divisão do custeio de medicamentos entre União, estados e municípios é negociada, não imposta.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 03.","macete":"Quem paga o quê na assistência farmacêutica: pactuação na CIT.","erroComum":"Achar que o Ministério decide sozinho.","comoBancaPensa":"Pactuação suprimida."}},"SUS-419":{"cognitivo":{"motivo":"Treinar organização dos conselhos (terceira diretriz) — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"plenária no município"},"comentario":{"resolucao":"E (I, II e III). As três afirmativas reproduzem a terceira diretriz da Resolução 453: composição pelos quatro segmentos com presidente eleito em plenária; eleição em plenária no MUNICÍPIO, promovida pelo Conselho Municipal, onde faltarem entidades organizadas; e critério de representatividade, abrangência e complementaridade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-420":{"cognitivo":{"motivo":"Treinar organização dos conselhos (terceira diretriz) — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"plenária no município"},"comentario":{"resolucao":"CERTO. A solução prevista é local: plenária no próprio município, convocada pelo Conselho Municipal. A pegadinha frequente desloca a plenária para o estado ou a entrega ao Conselho Estadual.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-421":{"cognitivo":{"motivo":"Treinar organização dos conselhos (terceira diretriz) — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"presidente eleito em plenária"},"comentario":{"resolucao":"ERRADO. A Resolução manda que o presidente seja ELEITO entre os membros do conselho, em reunião plenária. Não há presidência nata do secretário de saúde ou do ministro; qualquer conselheiro pode ser eleito.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-422":{"cognitivo":{"motivo":"Treinar composição da CIT — ponto de participação da comunidade e gestão do SUS que a banca transforma em item.","palavraCritica":"CONASEMS"},"comentario":{"resolucao":"E. A Comissão Intergestores Tripartite reúne representantes do Ministério da Saúde, do CONASS (secretários estaduais) e do CONASEMS (secretários municipais). Secretaria estadual isolada, o COSEMS (conselho ESTADUAL de secretários municipais) e secretários de municípios específicos não compõem a CIT — o COSEMS integra a CIB.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-423":{"cognitivo":{"motivo":"Treinar composição da CIT — ponto de participação da comunidade e gestão do SUS que a banca transforma em item.","palavraCritica":"MS, CONASS e CONASEMS"},"comentario":{"resolucao":"CERTO. Tripartite = três partes: União (MS), estados (CONASS) e municípios (CONASEMS). Na CIB, os municípios são representados pelo COSEMS do respectivo estado, ao lado da secretaria estadual.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-424":{"cognitivo":{"motivo":"Treinar distribuição das vagas no conselho — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"25% de trabalhadores"},"comentario":{"resolucao":"E. Pela Resolução 453 (quarta diretriz): 50% de entidades e movimentos representativos de usuários; 25% de entidades representativas dos trabalhadores da área de saúde; e 25% de representação de governo e prestadores de serviços privados conveniados ou sem fins lucrativos. (A tabela do material marca D, mas o comentário e a Resolução dão E: o governo não tem 50%.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-425":{"cognitivo":{"motivo":"Treinar distribuição das vagas no conselho — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"governo + prestadores = 25%"},"comentario":{"resolucao":"CERTO. Governo e prestadores dividem um único bloco de 25%; os outros 25% são dos trabalhadores e os 50% restantes, dos usuários.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-426":{"cognitivo":{"motivo":"Treinar distribuição das vagas no conselho — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"trabalhadores têm 25% sozinhos"},"comentario":{"resolucao":"ERRADO. A paridade é mantida, mas os blocos de 25% estão trocados: um quarto é dos TRABALHADORES da saúde, sozinhos; o outro quarto é do GOVERNO junto com os PRESTADORES conveniados ou sem fins lucrativos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-427":{"cognitivo":{"motivo":"Treinar conferências e conselhos — correta — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"etapas municipais e estaduais"},"comentario":{"resolucao":"D. As conferências municipais e estaduais são etapas preparatórias da Conferência Nacional, aprovando propostas que sobem para o debate nacional. Erros: os conselhos são descentralizados e autônomos, não subordinados (A, E); a conferência nacional ocorre a cada QUATRO anos (B); o conselho delibera e controla, mas não executa os serviços (C).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-428":{"cognitivo":{"motivo":"Treinar conferências e conselhos — correta — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"autonomia do conselho"},"comentario":{"resolucao":"CERTO. A Resolução 453 (quinta diretriz) assegura autonomia ao conselho e impõe ao governo prover dotação orçamentária, estrutura administrativa e secretaria executiva. Integrar a estrutura não significa subordinação.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-429":{"cognitivo":{"motivo":"Treinar participação popular — incorreta — ponto de participação da comunidade e gestão do SUS que a banca transforma em item.","palavraCritica":"participação social não é partidária"},"comentario":{"resolucao":"B (incorreta). Participação social não é 'participação partidária': é a participação da comunidade, por meio de conselhos e conferências, independentemente de partidos. As demais estão corretas: é diretriz/princípio organizativo, ajuda a formular políticas e fiscaliza o Estado.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-430":{"cognitivo":{"motivo":"Treinar instâncias colegiadas — ponto de participação da comunidade e gestão do SUS que a banca transforma em item.","palavraCritica":"conselhos e conferências"},"comentario":{"resolucao":"B. Art. 1º da Lei 8.142: o SUS contará, em cada esfera de governo, sem prejuízo das funções do Poder Legislativo, com duas instâncias colegiadas — a Conferência de Saúde e o Conselho de Saúde. CIB e CIT são foros de pactuação entre gestores, não de participação da comunidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-431":{"cognitivo":{"motivo":"Treinar instâncias colegiadas — ponto de participação da comunidade e gestão do SUS que a banca transforma em item.","palavraCritica":"sem prejuízo do Legislativo"},"comentario":{"resolucao":"CERTO. O controle social não substitui o controle parlamentar: a Lei 8.142 ressalva expressamente as funções do Legislativo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-432":{"cognitivo":{"motivo":"Treinar lei 8.142 — contraria — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"quatro anos, não três"},"comentario":{"resolucao":"A (contraria). A conferência reúne-se a cada QUATRO anos (art. 1º, § 1º). B, C e D reproduzem o § 2º, o § 5º e o art. 2º, I.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-433":{"cognitivo":{"motivo":"Treinar requisitos do art. 4º — exceto — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"planos funerários não existem"},"comentario":{"resolucao":"D (exceto). Os requisitos do art. 4º são: fundo de saúde; conselho de saúde paritário; plano de saúde; relatórios de gestão; contrapartida de recursos no orçamento; e comissão de elaboração do PCCS. 'Plano de gestão e planos funerários' não constam.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-434":{"cognitivo":{"motivo":"Treinar requisitos do art. 4º — exceto — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"relatórios de gestão"},"comentario":{"resolucao":"CERTO. Relatório de gestão é o quarto requisito do art. 4º. Os seis: fundo, conselho, plano, relatório, contrapartida e comissão do PCCS (mnemônico: 'FUCOPLAREC + PCCS').","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-435":{"cognitivo":{"motivo":"Treinar requisitos do art. 4º — exceto — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"administrados pelo estado ou pela União"},"comentario":{"resolucao":"ERRADO. O parágrafo único do art. 4º prevê outra consequência: os recursos passam a ser administrados, respectivamente, pelos ESTADOS (no caso de municípios) ou pela UNIÃO (no caso de estados). Não há perda definitiva nem redistribuição regional.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-436":{"cognitivo":{"motivo":"Treinar característica do conselho — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"composição paritária"},"comentario":{"resolucao":"C. A representação dos usuários é paritária em relação ao conjunto dos demais segmentos (art. 1º, § 4º). O conselho é PERMANENTE e DELIBERATIVO (não provisório nem consultivo); sua organização é definida em regimento próprio aprovado pelo próprio conselho; e paridade não é divisão igual entre os quatro segmentos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-437":{"cognitivo":{"motivo":"Treinar característica do conselho — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"usuários × conjunto dos demais"},"comentario":{"resolucao":"ERRADO. Paridade é entre USUÁRIOS e o CONJUNTO dos demais segmentos: metade das vagas para usuários e metade para governo, prestadores e trabalhadores juntos. Divisão em quartos iguais não é o que a lei prevê.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-438":{"cognitivo":{"motivo":"Treinar periodicidade e convocação — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"quatro; Conselho de Saúde"},"comentario":{"resolucao":"C. A conferência reúne-se a cada QUATRO anos, convocada pelo Poder Executivo ou, extraordinariamente, por ela própria ou pelo CONSELHO DE SAÚDE (art. 1º, § 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-439":{"cognitivo":{"motivo":"Treinar objetivo da Lei 8.142 — ponto de participação da comunidade e gestão do SUS que a banca transforma em item.","palavraCritica":"participação da comunidade"},"comentario":{"resolucao":"C. A Lei 8.142 dispõe sobre a participação da comunidade na gestão do SUS (conselhos e conferências) e sobre as transferências intergovernamentais de recursos financeiros na saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-440":{"cognitivo":{"motivo":"Treinar lei 8.142 — incorreta — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"quatro anos, não sete"},"comentario":{"resolucao":"D (incorreta). A conferência reúne-se a cada QUATRO anos. As demais reproduzem a lei: conselho (§ 2º), CONASS e CONASEMS no CNS (§ 3º), paridade (§ 4º) e regimento próprio (§ 5º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-441":{"cognitivo":{"motivo":"Treinar lei 8.142 — incorreta — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"CONASS e CONASEMS no CNS"},"comentario":{"resolucao":"CERTO. É o § 3º do art. 1º. A pegadinha usual nega essa representação ('não terão representação').","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-442":{"cognitivo":{"motivo":"Treinar convocação da conferência — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"Executivo ou, extraordinariamente, ela própria ou o conselho"},"comentario":{"resolucao":"A. Convocação ordinária pelo Poder EXECUTIVO; extraordinária pela própria conferência ou pelo Conselho de Saúde. Periodicidade de quatro anos (B erra); não é o Legislativo que convoca (C); homologação pelo chefe do poder é das decisões do CONSELHO (D); permanente e deliberativo é o conselho (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-443":{"cognitivo":{"motivo":"Treinar convocação da conferência — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"homologação é do conselho"},"comentario":{"resolucao":"ERRADO. Trocou as instâncias: a Lei 8.142 manda homologar as decisões do CONSELHO (art. 1º, § 2º). A conferência avalia a situação de saúde e propõe diretrizes, sem previsão legal de homologação.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-444":{"cognitivo":{"motivo":"Treinar conselho — permanente e paritário — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"atuação permanente"},"comentario":{"resolucao":"D. Atuação permanente, caráter deliberativo e fiscalizatório, 50% de usuários e 50% dos demais segmentos: é o CONSELHO de Saúde. A conferência também é instância de participação, mas é periódica (a cada quatro anos).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-445":{"cognitivo":{"motivo":"Treinar definição legal do conselho — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"permanente e deliberativo, quatro segmentos"},"comentario":{"resolucao":"C. Art. 1º, § 2º: órgão colegiado composto por representantes do governo, prestadores de serviço, profissionais de saúde e usuários, em caráter permanente e DELIBERATIVO. Não é executivo e não pode excluir os usuários.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-446":{"cognitivo":{"motivo":"Treinar segmentos do conselho — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"governo, prestadores, profissionais, usuários"},"comentario":{"resolucao":"A. Os quatro segmentos são: governo, prestadores de serviço, profissionais (trabalhadores) de saúde e usuários. Conselhos profissionais (COREN, CRM), sindicatos e movimentos podem integrar algum segmento por indicação, mas não são segmentos em si.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-447":{"cognitivo":{"motivo":"Treinar controle social — correta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paridade dos usuários"},"comentario":{"resolucao":"C. Art. 1º, § 4º. Erros: os recursos do FNS também cobrem despesas de capital, investimentos e repasses (A); o conselho atua na formulação e no controle (B); é PERMANENTE (D); a conferência ocorre a cada QUATRO anos (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-448":{"cognitivo":{"motivo":"Treinar conselho Municipal — V/F — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"só a segunda é verdadeira"},"comentario":{"resolucao":"A (F, V, F, F, F). Só a segunda é verdadeira (art. 1º, § 2º). Todos os conselheiros votam, não só os usuários; o conselho é deliberativo e fiscaliza todas as contas da saúde; não pode ser extinto pelo gestor (é previsto em lei); e a paridade é 50% usuários, 25% trabalhadores e 25% governo + prestadores.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-449":{"cognitivo":{"motivo":"Treinar conselho Municipal — V/F — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"não pode ser extinto"},"comentario":{"resolucao":"CERTO. O conselho é instância exigida pela Lei 8.142 e instituída por lei do ente (Resolução 453, primeira diretriz); sua existência é até requisito para receber recursos do FNS (art. 4º, II). O gestor não tem poder para revogá-lo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-450":{"cognitivo":{"motivo":"Treinar fNS — custeio e capital — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"despesas de custeio e de capital"},"comentario":{"resolucao":"B. Art. 2º, I: os recursos do FNS são alocados como despesas de custeio e de capital do Ministério da Saúde, seus órgãos e entidades, da administração direta e indireta. Erros: regimento aprovado pelo próprio conselho (A); conferência a cada quatro anos (C); CONASS e CONASEMS TÊM representação no CNS (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-451":{"cognitivo":{"motivo":"Treinar alocação do FNS — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"cobertura das ações dos entes"},"comentario":{"resolucao":"D. Art. 2º, IV: cobertura das ações e serviços de saúde a serem implementados pelos municípios, estados e DF. As demais deformam os incisos II (investimentos em lei orçamentária, de iniciativa do LEGISLATIVO) e III (Plano QUINQUENAL do Ministério, sem 'órgãos e entidades').","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-452":{"cognitivo":{"motivo":"Treinar alocação do FNS — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"Plano Quinquenal"},"comentario":{"resolucao":"CERTO. São os incisos II e III do art. 2º. A banca costuma trocar 'quinquenal' por 'quadrienal' ou 'plurianual'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-453":{"cognitivo":{"motivo":"Treinar repasse aos municípios — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"pelo menos setenta por cento"},"comentario":{"resolucao":"D. Art. 3º, § 2º: os recursos do inciso IV do art. 2º serão destinados, pelo menos 70% (setenta por cento), aos municípios, afetando-se o restante aos estados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-454":{"cognitivo":{"motivo":"Treinar repasse aos municípios — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"no mínimo 70%"},"comentario":{"resolucao":"CERTO. É o § 2º do art. 3º. O percentual é um PISO para os municípios ('pelo menos'), coerente com a ênfase da descentralização na municipalização.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-455":{"cognitivo":{"motivo":"Treinar repasse aos municípios — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"remanejar entre si"},"comentario":{"resolucao":"ERRADO. O § 3º do art. 3º autoriza os municípios a estabelecerem consórcio e, nele, a remanejar entre si parcelas dos recursos do inciso IV do art. 2º. A proibição foi inventada pela banca.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-456":{"cognitivo":{"motivo":"Treinar lei 8.142 — incorreta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"conselho é permanente"},"comentario":{"resolucao":"C (incorreta). O conselho é PERMANENTE, não temporário, e a periodicidade mensal de reuniões vem da Resolução 453 (mínimo uma vez por mês), não da lei. As demais estão corretas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-457":{"cognitivo":{"motivo":"Treinar lei 8.142 — incorreta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"no mínimo mensal"},"comentario":{"resolucao":"CERTO. A Resolução prevê reunião ordinária no mínimo mensal, extraordinária quando necessário (por convocação do presidente ou da maioria dos membros) e reuniões abertas ao público, em espaços e horários que permitam a participação da sociedade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-458":{"cognitivo":{"motivo":"Treinar gestores nas conferências — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"governo participa"},"comentario":{"resolucao":"ERRADO. As conferências reúnem a representação dos vários segmentos sociais — usuários, trabalhadores, prestadores e governo. Gestores e representantes governamentais participam das conferências; a CIB e a CIT são espaços adicionais de pactuação entre gestores, não excludentes.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: todos os segmentos, inclusive governo.","erroComum":"Achar que gestor só atua nas comissões intergestores.","comoBancaPensa":"Exclusão inventada com 'exclusivamente'."}},"SUS-459":{"cognitivo":{"motivo":"Treinar indígenas no CNS — ponto de participação da comunidade e gestão do SUS que a banca transforma em item.","palavraCritica":"participação indígena"},"comentario":{"resolucao":"CERTO. A Lei 8.080 (art. 19-H) assegura às populações indígenas participação nos organismos colegiados de formulação, acompanhamento e avaliação das políticas de saúde, como o Conselho Nacional de Saúde e os conselhos estaduais e municipais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Indígenas: participam dos conselhos (art. 19-H da 8.080).","erroComum":"Achar que só usuários urbanos organizados têm assento.","comoBancaPensa":"Integração entre 8.080 e 8.142."}},"SUS-460":{"cognitivo":{"motivo":"Treinar resolução 453 — incorreta — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"plenária no município"},"comentario":{"resolucao":"B (incorreta). Onde faltarem entidades organizadas, a eleição é realizada em plenária NO MUNICÍPIO, promovida pelo CONSELHO MUNICIPAL — não no estado nem pelo Conselho Estadual. As demais reproduzem a Resolução (democracia e conferências; conselhos regionais, locais, distritais e dos DSEI; instância privilegiada; segmentos distintos e autônomos).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-461":{"cognitivo":{"motivo":"Treinar resolução 453 — incorreta — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"segmentos distintos e autônomos"},"comentario":{"resolucao":"ERRADO. A Resolução exige que a representação de cada segmento seja distinta e autônoma: quem ocupa cargo de direção ou de confiança na gestão do SUS, ou atua como prestador, NÃO pode representar usuários nem trabalhadores, ainda que indicado por entidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-462":{"cognitivo":{"motivo":"Treinar resolução 453 — incorreta (aspectos econômicos) — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"inclusive aspectos econômicos e financeiros"},"comentario":{"resolucao":"D (incorreta). O conselho atua na formulação e proposição de estratégias e no controle da execução das políticas de saúde, INCLUSIVE nos aspectos econômicos e financeiros. As demais reproduzem a Resolução 453.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-463":{"cognitivo":{"motivo":"Treinar resolução 453 — incorreta (aspectos econômicos) — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"inclusive aspectos econômicos e financeiros"},"comentario":{"resolucao":"ERRADO. A Lei 8.142 (art. 1º, § 2º) diz 'inclusive nos aspectos econômicos e financeiros'. Tribunal de contas e Legislativo também controlam, mas isso não retira a competência do conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-464":{"cognitivo":{"motivo":"Treinar paridade — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paritária"},"comentario":{"resolucao":"E. Art. 1º, § 4º: a representação dos usuários nos conselhos e conferências será PARITÁRIA em relação ao conjunto dos demais segmentos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-465":{"cognitivo":{"motivo":"Treinar regimento próprio — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"aprovadas pelo respectivo conselho"},"comentario":{"resolucao":"C. Art. 1º, § 5º: conferências e conselhos terão sua organização e normas de funcionamento definidas em regimento próprio, aprovadas pelo respectivo conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-466":{"cognitivo":{"motivo":"Treinar regimento próprio — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"aprovado pelo respectivo conselho"},"comentario":{"resolucao":"ERRADO. Quem aprova o regimento é o próprio CONSELHO respectivo (art. 1º, § 5º). Pôr o gestor para aprovar as regras do órgão que o fiscaliza comprometeria a autonomia do controle social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-467":{"cognitivo":{"motivo":"Treinar contrapartida como requisito — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"contrapartida no orçamento"},"comentario":{"resolucao":"CERTO. O art. 4º da Lei 8.142 lista seis requisitos, e a contrapartida de recursos para a saúde no respectivo orçamento é o quinto (inciso V).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Seis requisitos: fundo, conselho, plano, relatório, contrapartida, PCCS.","erroComum":"Esquecer a contrapartida ou o PCCS.","comoBancaPensa":"Item literal do Quadrix."}},"SUS-468":{"cognitivo":{"motivo":"Treinar resolução 453 — I e IV — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"decide sobre seu orçamento"},"comentario":{"resolucao":"A (I e IV). O conselho é instância colegiada, deliberativa e permanente (primeira diretriz) e decide sobre seu próprio orçamento (quinta diretriz). O SUS é universal, não voltado à rede privada (II); as plenárias são abertas ao público (III).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-469":{"cognitivo":{"motivo":"Treinar resolução 453 — I e IV — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"decide sobre o seu orçamento"},"comentario":{"resolucao":"CERTO. É a quinta diretriz da Resolução 453, que trata da estrutura e do funcionamento. O orçamento do conselho é decidido por ele, não pelo gestor.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-470":{"cognitivo":{"motivo":"Treinar usuários — 50% — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"50%"},"comentario":{"resolucao":"D. Pela Resolução 453 (quarta diretriz), 50% das vagas são de entidades e movimentos representativos de usuários.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-471":{"cognitivo":{"motivo":"Treinar base legal do SUS — ponto de participação da comunidade e gestão do SUS que a banca transforma em item.","palavraCritica":"CF, Lei 8.080 e Lei 8.142"},"comentario":{"resolucao":"A. A base legal do SUS é formada pela Constituição de 1988 (arts. 196 a 200), pela Lei 8.080/1990 (organização e funcionamento) e pela Lei 8.142/1990 (participação da comunidade e transferências). O Decreto 7.508/2011 e as NOB vieram depois, regulamentando e operacionalizando.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-472":{"cognitivo":{"motivo":"Treinar conselho — I e II — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"proporção, não número de membros"},"comentario":{"resolucao":"A (I e II). I e II estão corretas. III erra: a Resolução 453 não fixa o NÚMERO de conselheiros (10 a 20), e sim a PROPORÇÃO — e os 25% finais são de governo e prestadores, não só de prestadores. O número é definido pela lei e pelo regimento de cada conselho, aprovados em plenário.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-473":{"cognitivo":{"motivo":"Treinar conselho — I e II — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"número definido pelo conselho"},"comentario":{"resolucao":"CERTO. A quarta diretriz da Resolução 453 diz que o número de conselheiros será definido pelos conselhos de saúde e constituído em lei; a Resolução só fixa os percentuais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-474":{"cognitivo":{"motivo":"Treinar lacuna — o Conselho de Saúde — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"homologação pelo chefe do poder"},"comentario":{"resolucao":"C. O dispositivo transcrito é o § 2º do art. 1º, que define o CONSELHO de Saúde (permanente, deliberativo, quatro segmentos, decisões homologadas pelo chefe do poder).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-475":{"cognitivo":{"motivo":"Treinar requisitos — fundo, plano, contrapartida — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"todos verdadeiros"},"comentario":{"resolucao":"E. Fundo de saúde (I), plano de saúde (III) e contrapartida no orçamento (V) estão todos no art. 4º, ao lado do conselho paritário, dos relatórios de gestão e da comissão do PCCS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-476":{"cognitivo":{"motivo":"Treinar princípio na instituição dos conselhos — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"democracia"},"comentario":{"resolucao":"D. É a DEMOCRACIA: a primeira diretriz da Resolução 453 obriga o Executivo, ao criar ou reformular um conselho, a incorporar o que a população aprovou nas conferências — o desenho do controle social nasce da participação, e não de escolha unilateral do gestor.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-477":{"cognitivo":{"motivo":"Treinar princípio na instituição dos conselhos — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"instituído por lei"},"comentario":{"resolucao":"ERRADO. A primeira diretriz da Resolução 453 diz que a instituição dos conselhos é estabelecida por LEI federal, estadual, do DF e municipal, obedecida a Lei 8.142. Integrar a estrutura administrativa não dispensa a lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-478":{"cognitivo":{"motivo":"Treinar periodicidade da conferência — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"a cada quatro anos"},"comentario":{"resolucao":"E. A conferência de saúde reúne-se a cada QUATRO anos (art. 1º, § 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-479":{"cognitivo":{"motivo":"Treinar conferência — correta — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"quatro anos, propor diretrizes"},"comentario":{"resolucao":"A. Reúne-se a cada quatro anos, com representação dos vários segmentos, para avaliar a situação de saúde e propor diretrizes. D e E descrevem o CONSELHO; B e C erram a periodicidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-480":{"cognitivo":{"motivo":"Treinar conferência — correta (avaliar e propor) — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"avaliar e propor diretrizes"},"comentario":{"resolucao":"D. A conferência, com representação dos vários segmentos, avalia a situação de saúde e propõe diretrizes a cada quatro anos. B e C misturam características do conselho (permanente, deliberativo, controle da execução); A e E são invenções.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-481":{"cognitivo":{"motivo":"Treinar quem convoca a conferência — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"Executivo; extraordinariamente, ela ou o conselho"},"comentario":{"resolucao":"D. Poder Executivo, ou, extraordinariamente, a própria conferência ou o Conselho de Saúde. Legislativo, ministros e conselhos de secretários não convocam.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-482":{"cognitivo":{"motivo":"Treinar finalidade das conferências — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"participação e controle"},"comentario":{"resolucao":"CERTO. As conferências são espaços de participação da comunidade: avaliam a situação de saúde e propõem diretrizes, estimulando a participação, o controle e a avaliação dos serviços pelos cidadãos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência = participação + avaliação + proposta de diretrizes.","erroComum":"Achar que só o conselho exerce controle social.","comoBancaPensa":"Item conceitual."}},"SUS-483":{"cognitivo":{"motivo":"Treinar conferências — III e IV — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"três esferas, espaço de debate"},"comentario":{"resolucao":"A (III e IV). A conferência ocorre nas três esferas e é espaço de debate, formulação e avaliação das políticas. I erra: a convocação extraordinária pelo conselho não exige '50% mais 1' na lei; II erra: a periodicidade é de quatro anos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-484":{"cognitivo":{"motivo":"Treinar paridade (art. 1º, § 4º) — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paritária"},"comentario":{"resolucao":"E. Paritária: metade das vagas é dos usuários e a outra metade se divide entre governo, prestadores e trabalhadores (§ 4º do art. 1º). Controlada, específica, espontânea e qualificada não são termos da lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-485":{"cognitivo":{"motivo":"Treinar conselhos — fortalecimento do controle social — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"participação da sociedade organizada"},"comentario":{"resolucao":"B. Os conselhos fortalecem o controle social pela participação da sociedade organizada. Erros: não há sindicatos patronais obrigatórios nem mediador designado (A); o conselho tem autonomia e não se subordina à conferência (C); atua inclusive nos aspectos econômicos e financeiros (D); fiscaliza também os serviços privados que integram o SUS (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-486":{"cognitivo":{"motivo":"Treinar conselhos — fortalecimento do controle social — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"não há subordinação"},"comentario":{"resolucao":"ERRADO. Não há hierarquia entre as duas instâncias: a conferência propõe diretrizes a cada quatro anos, e o conselho, permanente, delibera e controla a execução da política. As decisões do conselho vão à homologação do chefe do poder, sem passar pela conferência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-487":{"cognitivo":{"motivo":"Treinar comissão do PCCS — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"condição para receber recursos do FNS"},"comentario":{"resolucao":"B. Contar com comissão de elaboração do PCCS, com prazo de dois anos para implantação, é um dos requisitos do art. 4º para que municípios, estados e DF recebam os recursos do art. 3º (cobertura das ações e serviços que implementam).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-488":{"cognitivo":{"motivo":"Treinar comissão do PCCS — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"dois anos"},"comentario":{"resolucao":"CERTO. Inciso VI do art. 4º. A banca troca o prazo (cinco anos, um ano) ou diz que o PCCS deve estar implantado, quando a lei exige a comissão com prazo para implantar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-489":{"cognitivo":{"motivo":"Treinar gestão participativa — correta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"quatro segmentos"},"comentario":{"resolucao":"E. Art. 1º, § 2º. Erros: inclusive aspectos econômicos e financeiros (A); a representação É paritária (B); conferência a cada quatro anos (C); CONASS e CONASEMS TÊM representação no CNS (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-490":{"cognitivo":{"motivo":"Treinar função do conselho — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"inclusive aspectos econômicos e financeiros"},"comentario":{"resolucao":"E. O conselho formula estratégias e controla e fiscaliza a execução da política de saúde, inclusive nos aspectos econômicos e financeiros. Reunir-se a cada período fixo é da conferência (B, D); o conselho não restringe atendimentos nem indica compras (A, C).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-491":{"cognitivo":{"motivo":"Treinar homologação das resoluções — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"prazo de 30 dias"},"comentario":{"resolucao":"CERTO. É a quinta diretriz. Se o gestor não homologar nem enviar justificativa com proposta de alteração ou rejeição a ser apreciada na reunião seguinte, as entidades do conselho podem buscar a validação das resoluções na Justiça e no Ministério Público.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Homologação: 30 dias; silêncio do gestor → Justiça/MP.","erroComum":"Trocar o prazo ou achar que o gestor pode ignorar a resolução.","comoBancaPensa":"Prazo da Resolução 453."}},"SUS-492":{"cognitivo":{"motivo":"Treinar silêncio do gestor — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"Justiça e Ministério Público"},"comentario":{"resolucao":"ERRADO. A Resolução 453 prevê o contrário da rejeição tácita: sem homologação nem justificativa no prazo, as entidades que integram o conselho podem buscar a validação das resoluções recorrendo à Justiça e ao Ministério Público, quando necessário.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Silêncio do gestor não derruba a resolução.","erroComum":"Inventar rejeição tácita.","comoBancaPensa":"Consequência invertida."}},"SUS-493":{"cognitivo":{"motivo":"Treinar renovação das entidades — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"no mínimo 30%"},"comentario":{"resolucao":"CERTO. A regra de renovação mínima de 30% das entidades evita a perpetuação das mesmas organizações. O mandato dos conselheiros é definido no regimento interno, sem coincidir com o mandato do governo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Renovação: mínimo 30% das entidades a cada eleição.","erroComum":"Trocar o percentual.","comoBancaPensa":"Número da Resolução 453."}},"SUS-494":{"cognitivo":{"motivo":"Treinar parlamentares e Judiciário no conselho — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"não é permitida"},"comentario":{"resolucao":"ERRADO. A Resolução veda a participação, como conselheiros, de membros eleitos do Poder Legislativo, de representação do Poder Judiciário e do Ministério Público. Esses órgãos exercem controle por outras vias, e sua presença comprometeria a autonomia do conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Legislativo, Judiciário e MP não são conselheiros.","erroComum":"Achar que a indicação por entidade resolve.","comoBancaPensa":"Vedação da Resolução 453."}},"SUS-495":{"cognitivo":{"motivo":"Treinar função de conselheiro — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"relevância pública, não remunerada"},"comentario":{"resolucao":"CERTO. A terceira diretriz da Resolução 453 define a função como não remunerada e de relevância pública, assegurando a liberação do trabalho para as atividades do conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conselheiro: não remunerado, relevância pública, dispensado do trabalho.","erroComum":"Achar que há jeton ou que a falta ao trabalho é descontada.","comoBancaPensa":"Garantia da Resolução 453."}},"SUS-496":{"cognitivo":{"motivo":"Treinar auditoria externa — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"auditorias externas e independentes"},"comentario":{"resolucao":"ERRADO. A Resolução 453 (quinta diretriz) prevê que os conselhos, com a devida justificativa, busquem auditorias externas e independentes sobre as contas e atividades do gestor do SUS. O SNA e os tribunais de contas atuam em paralelo, sem exclusividade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conselho pode pedir auditoria externa, com justificativa.","erroComum":"Achar que a fiscalização contábil é exclusiva do SNA.","comoBancaPensa":"Competência suprimida."}},"SUS-497":{"cognitivo":{"motivo":"Treinar conselhos locais e distritais — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"coordenação do conselho da esfera"},"comentario":{"resolucao":"CERTO. A Resolução 453 registra esse desdobramento do controle social e mantém a coordenação no conselho da esfera correspondente (municipal, estadual ou nacional).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conselhos locais: coordenados pelo conselho da esfera.","erroComum":"Achar que são independentes ou ligados ao CNS.","comoBancaPensa":"Dispositivo pouco lembrado."}},"SUS-498":{"cognitivo":{"motivo":"Treinar mesa diretora e comissões — ponto de diretrizes dos conselhos (Resolução CNS 453/2012) que a banca transforma em item.","palavraCritica":"eleita em plenário"},"comentario":{"resolucao":"ERRADO. A mesa diretora é ELEITA em plenário, respeitada a paridade, e as comissões permanentes e intersetoriais podem reunir conselheiros e outros integrantes, sem restrição ao segmento governo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Mesa diretora: eleita em plenário.","erroComum":"Pôr a direção nas mãos do gestor.","comoBancaPensa":"Dupla troca."}},"SUS-499":{"cognitivo":{"motivo":"Treinar repasse regular e automático — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"regular e automática"},"comentario":{"resolucao":"CERTO. É o caput do art. 3º da Lei 8.142: transferência fundo a fundo, regular e automática, segundo os critérios do art. 35 da Lei 8.080.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Fundo a fundo: regular e automático.","erroComum":"Achar que depende de convênio caso a caso.","comoBancaPensa":"Literalidade do art. 3º."}},"SUS-500":{"cognitivo":{"motivo":"Treinar destino dos recursos do inciso IV — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"investimentos, ambulatorial e hospitalar"},"comentario":{"resolucao":"ERRADO. O parágrafo único do art. 2º diz que esses recursos destinam-se a investimentos na rede de serviços, à cobertura assistencial ambulatorial e hospitalar e às demais ações de saúde. A lei não os restringe à folha nem veda investimentos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Inciso IV: investimentos + cobertura ambulatorial/hospitalar + demais ações.","erroComum":"Inventar vedação a investimentos.","comoBancaPensa":"Restrição indevida."}},"SUS-501":{"cognitivo":{"motivo":"Treinar conselho com composição paritária como requisito — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"conselho paritário"},"comentario":{"resolucao":"ERRADO. O requisito do inciso II é a existência de CONSELHO de saúde com composição paritária. A conferência ocorre a cada quatro anos e não figura entre os requisitos para os repasses.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Requisito: conselho paritário, não conferência anual.","erroComum":"Trocar conselho por conferência.","comoBancaPensa":"Troca de instância."}},"SUS-502":{"cognitivo":{"motivo":"Treinar conferência nacional e etapas — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"etapas preparatórias"},"comentario":{"resolucao":"ERRADO. As conferências municipais e estaduais funcionam como etapas preparatórias da nacional: elegem delegados e aprovam propostas que sobem para a Conferência Nacional, que avalia a situação de saúde e propõe diretrizes para a política nos níveis correspondentes.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conferência: município → estado → nação.","erroComum":"Achar que as etapas são independentes.","comoBancaPensa":"Desconexão inventada."}},"SUS-503":{"cognitivo":{"motivo":"Treinar homologação × deliberação — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"conselho delibera"},"comentario":{"resolucao":"ERRADO. Deliberativo é o oposto de consultivo: o conselho decide, e suas resoluções seguem para homologação do chefe do poder. Pela Resolução 453, o gestor que não homologar deve justificar e propor alteração ou rejeição, sob pena de as entidades recorrerem à Justiça e ao Ministério Público.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Deliberativo ≠ consultivo.","erroComum":"Confundir deliberativo com opinativo.","comoBancaPensa":"Conceito invertido."}},"SUS-504":{"cognitivo":{"motivo":"Treinar critério provisório de repasse — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"critério do § 1º do art. 35"},"comentario":{"resolucao":"ERRADO. O § 1º do art. 3º da Lei 8.142 determina o uso, nesse período, do critério do § 1º do art. 35 da Lei 8.080 — metade dos recursos distribuída segundo o quociente da divisão pelo número de habitantes, independentemente de qualquer procedimento prévio. Pagamento por produção é a lógica que a lei quis superar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Transição: critério populacional do § 1º do art. 35.","erroComum":"Trocar por remuneração por produção.","comoBancaPensa":"Critério trocado."}},"SUS-505":{"cognitivo":{"motivo":"Treinar conselho e serviços privados — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"fiscaliza o SUS como um todo"},"comentario":{"resolucao":"ERRADO. O conselho controla a execução da política de saúde na instância correspondente, o que abrange os serviços privados contratados ou conveniados, que integram o SUS e seguem suas diretrizes. O contrato com o gestor não afasta o controle social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2, 3 e 5 — controle social, Resolução CNS nº 453/2012 e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 04.","macete":"Conselho fiscaliza o SUS inteiro, inclusive a rede complementar.","erroComum":"Achar que o privado conveniado escapa do controle social.","comoBancaPensa":"Restrição indevida."}},"SUS-506":{"cognitivo":{"motivo":"Treinar revolta da Vacina (1904) — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"varíola"},"comentario":{"resolucao":"D. A Revolta da Vacina (Rio de Janeiro, novembro de 1904) reagiu à lei que tornou obrigatória a vacinação contra a VARÍOLA, conduzida por Oswaldo Cruz no modelo do sanitarismo campanhista.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-507":{"cognitivo":{"motivo":"Treinar revolta da Vacina (1904) — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"varíola"},"comentario":{"resolucao":"ERRADO. A vacina obrigatória era contra a VARÍOLA. A febre amarela, transmitida por mosquito, foi combatida por Oswaldo Cruz com brigadas mata-mosquitos e isolamento, não com vacinação em massa.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-508":{"cognitivo":{"motivo":"Treinar revolta da Vacina (1904) — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"sanitarismo campanhista"},"comentario":{"resolucao":"CERTO. O modelo campanhista (Oswaldo Cruz) era autoritário e centralizado, voltado a proteger a economia agroexportadora (saneamento de portos e cidades); a imposição da vacina antivariólica explodiu na revolta de 1904.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-509":{"cognitivo":{"motivo":"Treinar lei Eloy Chaves (1923) — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"Caixas de Aposentadoria e Pensão"},"comentario":{"resolucao":"E. A Lei Eloy Chaves (1923) determinou a criação das CAIXAS de Aposentadoria e Pensão (CAPs), por empresa — começando pelos ferroviários —, marco inicial da previdência social no Brasil. Os IAPs vieram na década de 1930; o SUS, em 1988.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-510":{"cognitivo":{"motivo":"Treinar lei Eloy Chaves (1923) — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"CAPs por empresa"},"comentario":{"resolucao":"ERRADO. A Lei Eloy Chaves criou as CAIXAS (CAPs), organizadas por EMPRESA e geridas por empregadores e empregados. Os Institutos (IAPs), por CATEGORIA profissional e com participação do Estado, surgiram a partir de 1933, no governo Vargas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-511":{"cognitivo":{"motivo":"Treinar evolução histórica — correta — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"assistência condicionada à previdência"},"comentario":{"resolucao":"B. A assistência médica no Brasil cresceu atrelada ao sistema previdenciário: começou com as CAPs e seguiu com os IAPs, o INPS e o INAMPS, atendendo só quem contribuía. Erros: a economia era agroexportadora, não industrial (A); quem centralizou foi a criação do INPS em 1966, não a Lei Eloy Chaves (C); o INPS era estatal (D); IAPs são previdência, e o auge campanhista é anterior (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-512":{"cognitivo":{"motivo":"Treinar evolução histórica — correta — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"vinculada à previdência"},"comentario":{"resolucao":"CERTO. O modelo previdenciário era contributivo; os demais dependiam da filantropia (Santas Casas) e dos serviços de saúde pública. A universalidade do SUS rompeu com essa lógica.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-513":{"cognitivo":{"motivo":"Treinar evolução histórica — correta — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"gestão estatal"},"comentario":{"resolucao":"ERRADO. O INPS unificou os IAPs sob gestão ESTATAL e centralizada, afastando os trabalhadores da administração. Gestão por empregados e empregadores era característica das antigas CAPs.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-514":{"cognitivo":{"motivo":"Treinar diretrizes — art. 198 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"artigo 198"},"comentario":{"resolucao":"B. O art. 198 da Constituição organiza as ações e serviços públicos de saúde numa rede regionalizada e hierarquizada, com as diretrizes de descentralização, atendimento integral e participação da comunidade; a Lei 8.080 (art. 7º) remete a ele.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-515":{"cognitivo":{"motivo":"Treinar princípios — exceto — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"centralização"},"comentario":{"resolucao":"B (exceto). A Lei 8.080 adota a DEScentralização político-administrativa, com direção única em cada esfera. Universalidade, participação da comunidade e igualdade sem preconceitos ou privilégios estão no art. 7º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-516":{"cognitivo":{"motivo":"Treinar art. 200 — incorreta — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"executar vigilância sanitária, epidemiológica e do trabalhador"},"comentario":{"resolucao":"B (incorreta). Executar as ações de vigilância sanitária e epidemiológica e as de saúde do trabalhador É atribuição do SUS (art. 200, II). As demais reproduzem os incisos I, III e VI.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-517":{"cognitivo":{"motivo":"Treinar organização constitucional do SUS — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"ações e serviços PÚBLICOS"},"comentario":{"resolucao":"B. São as ações e serviços PÚBLICOS de saúde que integram a rede regionalizada e hierarquizada (art. 198), com descentralização, atendimento integral e participação da comunidade. A troca por 'privados', 'centralização' ou 'mix público-privado' é o erro.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-518":{"cognitivo":{"motivo":"Treinar cF — compete ao SUS — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"ordenar a formação de recursos humanos"},"comentario":{"resolucao":"E. Art. 200, III. Erros: é VEDADA a subvenção a lucrativas (A); a assistência é LIVRE à iniciativa privada, que participa do SUS de forma COMPLEMENTAR (B); a participação de capital estrangeiro é vedada SALVO nos casos previstos em lei (C); a fiscalização é de bebidas e águas para consumo HUMANO (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-519":{"cognitivo":{"motivo":"Treinar cF — compete ao SUS — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"salvo nos casos previstos em lei"},"comentario":{"resolucao":"CERTO. É o § 3º do art. 199. A lei (Lei 8.080, art. 23, com a redação da Lei 13.097/2015) hoje lista vários casos permitidos — mas a regra constitucional continua sendo vedação com exceções legais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-520":{"cognitivo":{"motivo":"Treinar iniciativa privada — I, II e V — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"comercialização vedada"},"comentario":{"resolucao":"A (I, II e V). Participação complementar (I), mediante contrato de direito público ou convênio (II), e vedação de todo tipo de comercialização de órgãos, tecidos e substâncias humanas (V; art. 199, § 4º). III inverte a preferência (filantrópicas e sem fins lucrativos); IV contraria o § 3º, que veda o capital estrangeiro salvo nos casos da lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-521":{"cognitivo":{"motivo":"Treinar iniciativa privada — I, II e V — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"vedado todo tipo de comercialização"},"comentario":{"resolucao":"ERRADO. O § 4º do art. 199 veda TODO tipo de comercialização, abrangendo órgãos, tecidos e substâncias humanas para transplante, pesquisa e tratamento, além da coleta, do processamento e da transfusão de sangue e seus derivados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-522":{"cognitivo":{"motivo":"Treinar participação privada — complementar — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"complementar"},"comentario":{"resolucao":"C. As instituições privadas participam do SUS de forma COMPLEMENTAR (art. 199, § 1º), quando a rede pública é insuficiente.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-523":{"cognitivo":{"motivo":"Treinar diretrizes — II e III — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"descentralização, não centralização"},"comentario":{"resolucao":"C (II e III). A diretriz é DEScentralização, com direção única em cada esfera de governo; atendimento integral com prioridade preventiva e participação da comunidade completam o art. 198.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-524":{"cognitivo":{"motivo":"Treinar art. 200 — correta — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"saneamento e desenvolvimento científico"},"comentario":{"resolucao":"C. Art. 200, IV e V. Erros: o SUS também PARTICIPA da produção de medicamentos e insumos (A); executa as ações de saúde do trabalhador (B); o controle do teor nutricional está incluído (D); a proteção do meio ambiente abrange o do trabalho (E erra na segunda parte, art. 200, VIII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-525":{"cognitivo":{"motivo":"Treinar diretrizes do art. 198 — I a III — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"três diretrizes"},"comentario":{"resolucao":"A (I, II e III). As diretrizes do caput do art. 198 são três: descentralização com direção única, atendimento integral com prioridade preventiva e participação da comunidade. Normas de fiscalização de despesas (§ 3º, III) e admissão de ACS e ACE por processo seletivo (§ 4º) são parágrafos do artigo, não diretrizes.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-526":{"cognitivo":{"motivo":"Treinar diretrizes do art. 198 — I a III — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"processo seletivo público"},"comentario":{"resolucao":"CERTO. É o § 4º do art. 198 (EC 51/2006). A lei federal (Lei 11.350/2006) disciplina o regime jurídico dessas categorias.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-527":{"cognitivo":{"motivo":"Treinar diretriz — participação da comunidade — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"participação da comunidade"},"comentario":{"resolucao":"D. Participação da comunidade é diretriz do art. 198, III. A direção é única em CADA esfera (não só a federal); a rede é hierarquizada; e a prioridade do atendimento integral é PREVENTIVA.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-528":{"cognitivo":{"motivo":"Treinar art. 196 — acesso universal e igualitário — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"universal e igualitário"},"comentario":{"resolucao":"A. O art. 196 garante acesso universal e igualitário às ações e serviços de promoção, proteção e recuperação. Regime geral, contributivo e de filiação obrigatória é a PREVIDÊNCIA (art. 201); a assistência é livre à iniciativa privada; e não há exigência de carteira assinada.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-529":{"cognitivo":{"motivo":"Treinar art. 196 — acesso universal e igualitário — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"previdência é contributiva"},"comentario":{"resolucao":"ERRADO. Regime geral contributivo e de filiação obrigatória é a PREVIDÊNCIA SOCIAL (art. 201). A saúde é direito de todos, com acesso universal e igualitário que independe de contribuição (art. 196).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-530":{"cognitivo":{"motivo":"Treinar cF e Lei 8.080 — V/F — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"saneamento é atribuição do SUS"},"comentario":{"resolucao":"D (V, V, V, F). As três primeiras estão corretas: vedação de subvenção a lucrativas (art. 199, § 2º), identificação dos determinantes como objetivo do SUS (Lei 8.080, art. 5º, I) e participação complementar com preferência às filantrópicas (art. 199, § 1º). A quarta erra: participar da política e da execução das ações de saneamento básico É atribuição do SUS (art. 200, IV).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-531":{"cognitivo":{"motivo":"Treinar art. 200 — todos verdadeiros — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"oito incisos"},"comentario":{"resolucao":"E. Os oito incisos transcritos correspondem ao art. 200: controle de procedimentos e produção de medicamentos (I), vigilâncias e saúde do trabalhador (II), formação de RH (III), saneamento (IV), ciência e tecnologia (V), alimentos e águas (VI), substâncias psicoativas, tóxicas e radioativas (VII) e meio ambiente, incluído o do trabalho (VIII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-532":{"cognitivo":{"motivo":"Treinar art. 200 — todos verdadeiros — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"e a inovação"},"comentario":{"resolucao":"CERTO. Art. 200, V, com a redação da EC 85/2015, que acrescentou 'e a inovação'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-533":{"cognitivo":{"motivo":"Treinar cF — não está correta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"assistência é livre à iniciativa privada"},"comentario":{"resolucao":"D (incorreta). O art. 199 diz o contrário: a assistência à saúde É livre à iniciativa privada. As demais reproduzem os arts. 197, 198 (caput e § 4º) e 199, § 2º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-534":{"cognitivo":{"motivo":"Treinar seção da saúde — correta — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"art. 196"},"comentario":{"resolucao":"B. Reproduz o art. 196. As demais misturam trechos verdadeiros com acréscimos falsos — como a alternativa D, que diz não ser vedada a subvenção às lucrativas (art. 199, § 2º, veda).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-535":{"cognitivo":{"motivo":"Treinar art. 197 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"relevância pública"},"comentario":{"resolucao":"B. O art. 197 declara de relevância pública as ações e serviços de saúde, cabendo ao Poder Público dispor sobre sua regulamentação, fiscalização e controle, com execução direta, por terceiros ou por pessoa física ou jurídica de direito privado. A é o art. 196; C, o 198; D, o 199; E, o 200.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-536":{"cognitivo":{"motivo":"Treinar art. 197 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"execução por direito privado"},"comentario":{"resolucao":"ERRADO. O art. 197 admite expressamente a execução diretamente ou por terceiros e, também, por pessoa física ou jurídica de DIREITO PRIVADO. Relevância pública significa regulação e controle pelo Poder Público, não monopólio de execução.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-537":{"cognitivo":{"motivo":"Treinar mínimo da União — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"15% da receita corrente líquida"},"comentario":{"resolucao":"A. Pelo art. 198, § 2º, I (EC 86/2015), a União aplica em ações e serviços públicos de saúde, no mínimo, 15% da receita corrente líquida do exercício. Estados aplicam 12% e municípios 15% de suas receitas de impostos e transferências (LC 141/2012).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-538":{"cognitivo":{"motivo":"Treinar mínimo da União — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"12% estados, 15% municípios"},"comentario":{"resolucao":"CERTO. Estados e DF: 12%; municípios e DF (na parcela municipal): 15%. A União segue regra própria, sobre a receita corrente líquida.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-539":{"cognitivo":{"motivo":"Treinar mínimo da União — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"percentuais e bases diferentes"},"comentario":{"resolucao":"ERRADO. Não há percentual único nem base única: a União aplica 15% da receita corrente líquida (art. 198, § 2º, I), e estados (12%) e municípios (15%) calculam sobre impostos e transferências (§ 2º, II e III; LC 141/2012).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-540":{"cognitivo":{"motivo":"Treinar completar o art. 196 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"políticas sociais e econômicas"},"comentario":{"resolucao":"C. 'A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e igualitário às ações e serviços para sua promoção, proteção e recuperação.' A é o art. 197; B, o 198.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-541":{"cognitivo":{"motivo":"Treinar convênio e participação complementar — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"integra de forma complementar"},"comentario":{"resolucao":"CERTO. A instituição privada que firma contrato ou convênio com o SUS passa a integrá-lo de forma complementar, submetida às suas diretrizes (CF, art. 199, § 1º; Lei 8.080, arts. 4º, § 2º, e 24).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Contrato/convênio = privado dentro do SUS, de forma complementar.","erroComum":"Achar que o conveniado continua fora do SUS.","comoBancaPensa":"Item conceitual do CEBRASPE."}},"SUS-542":{"cognitivo":{"motivo":"Treinar conceito constitucional de saúde — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"direito de todos e dever do Estado"},"comentario":{"resolucao":"E. O art. 196 diz: a saúde é direito de TODOS e dever do Estado, garantido mediante políticas sociais e econômicas. As demais suprimem o dever do Estado, restringem o direito aos brasileiros ou cortam partes do texto.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-543":{"cognitivo":{"motivo":"Treinar 8ª Conferência Nacional de Saúde — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"VIII Conferência"},"comentario":{"resolucao":"C. A 8ª Conferência Nacional de Saúde (1986), presidida por Sérgio Arouca, consolidou as propostas da Reforma Sanitária — saúde como direito de todos e dever do Estado, sistema único, descentralização e participação — que inspiraram a Constituinte e o SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-544":{"cognitivo":{"motivo":"Treinar 8ª Conferência Nacional de Saúde — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"1986, base da Constituinte"},"comentario":{"resolucao":"CERTO. As conferências anteriores eram restritas a técnicos e gestores; a 8ª reuniu milhares de participantes, inclusive usuários, e seu relatório orientou a Constituinte.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-545":{"cognitivo":{"motivo":"Treinar 8ª Conferência Nacional de Saúde — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"8ª Conferência"},"comentario":{"resolucao":"ERRADO. A conferência que inspirou o SUS foi a 8ª (1986), ANTERIOR à Constituição. A 10ª ocorreu em 1996, já com o SUS em implantação, e tratou sobretudo da NOB-SUS 01/96 e da gestão.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-546":{"cognitivo":{"motivo":"Treinar diretrizes — exceto — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"prioridade preventiva"},"comentario":{"resolucao":"C (exceto). O art. 198, II, fala em prioridade para as atividades PREVENTIVAS, sem prejuízo dos serviços assistenciais — e prevenção não é atribuição do Ministério da Educação.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-547":{"cognitivo":{"motivo":"Treinar art. 199 — incorreta — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"capital estrangeiro vedado salvo lei"},"comentario":{"resolucao":"C (incorreta). O capital estrangeiro não participa 'diretamente e sem limitações': a regra constitucional é a VEDAÇÃO, salvo nos casos previstos em lei (art. 199, § 3º). As demais reproduzem os §§ 1º, 2º e 4º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-548":{"cognitivo":{"motivo":"Treinar atribuições — V/F — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"colaborar na proteção do meio ambiente"},"comentario":{"resolucao":"C (V, F, V). Ordenar a formação de RH (art. 200, III) e fiscalizar alimentos, com controle do teor nutricional, bebidas e águas para consumo humano (VI) são atribuições do SUS. A segunda é falsa: o SUS deve COLABORAR na proteção do meio ambiente, nele compreendido o do trabalho (VIII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-549":{"cognitivo":{"motivo":"Treinar compete ao SUS — correta — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"psicoativos, tóxicos e radioativos"},"comentario":{"resolucao":"A. Art. 200, VII. Erros: as águas e bebidas são para consumo HUMANO (B); a saúde do trabalhador está incluída (C).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-550":{"cognitivo":{"motivo":"Treinar instrumentos da participação privada — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"contrato de direito público ou convênio"},"comentario":{"resolucao":"B. Art. 199, § 1º: contrato de direito público ou convênio, com preferência para as entidades filantrópicas e as sem fins lucrativos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-551":{"cognitivo":{"motivo":"Treinar natureza das políticas — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"sociais e econômicas"},"comentario":{"resolucao":"B. As políticas que garantem o direito à saúde são SOCIAIS e ECONÔMICAS (art. 196) — saúde depende de renda, moradia, saneamento, trabalho, e não só de serviços assistenciais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-552":{"cognitivo":{"motivo":"Treinar diretriz do art. 198 — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"prioridade preventiva"},"comentario":{"resolucao":"A. Atendimento integral, com prioridade para as atividades preventivas, sem prejuízo dos serviços assistenciais (art. 198, II). Centralização, ausência de participação e direção privada contrariam o artigo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-553":{"cognitivo":{"motivo":"Treinar afirmativas sobre o SUS — só I — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"contrato de direito público"},"comentario":{"resolucao":"A (I). II erra: o contrato é de direito PÚBLICO (ou convênio), não 'privado'. III erra: a vedação de subvenção às lucrativas não tem exceção legal no texto constitucional.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-554":{"cognitivo":{"motivo":"Treinar fases históricas — Reforma Barros Barreto — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"Reforma Barros Barreto (1941)"},"comentario":{"resolucao":"B. A Reforma Barros Barreto (1941) instituiu órgãos normativos e supletivos para a assistência sanitária e hospitalar e criou serviços nacionais de combate a endemias (malária, febre amarela, peste). Erros: o Ministério da Educação e Saúde Pública é de 1930, antes do Estado Novo (A); o Serviço de Malária do Nordeste (1939) antecede o Ministério da Saúde, criado em 1953 (C); o INAMPS é de 1977 e não era universal (D); a Lei 8.080 não dá ao SUS recursos 'do Inamps' (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-555":{"cognitivo":{"motivo":"Treinar fases históricas — Reforma Barros Barreto — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"INAMPS 1977, contributivo"},"comentario":{"resolucao":"CERTO. O INAMPS (1977, SINPAS) manteve a lógica contributiva; só com o SUDS (1987) e o SUS (1988) a assistência se universalizou, e o INAMPS foi extinto em 1993.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-556":{"cognitivo":{"motivo":"Treinar fases históricas — Reforma Barros Barreto — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"Ministério da Saúde em 1953"},"comentario":{"resolucao":"ERRADO. Em 1930 foi criado o Ministério da EDUCAÇÃO E SAÚDE Pública; o Ministério da Saúde autônomo só surgiu em 1953. E a assistência médica previdenciária ficava com os IAPs, ligados ao Ministério do Trabalho, não com a pasta da saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-557":{"cognitivo":{"motivo":"Treinar sistema segmentado — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"planos privados paralelos"},"comentario":{"resolucao":"E. O texto descreve um sistema SEGMENTADO: os planos privados operam em paralelo ao SUS, com regulação (ANS) e lógica próprias. Isso não é complementaridade (que é a participação privada DENTRO do SUS, por contrato ou convênio), nem descaracteriza formalmente a universalidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-558":{"cognitivo":{"motivo":"Treinar sistema segmentado — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"complementar × suplementar"},"comentario":{"resolucao":"ERRADO. Complementar é o privado que atua DENTRO do SUS, por contrato ou convênio, para suprir a insuficiência da rede pública. Suplementar é o mercado de planos, que funciona em paralelo e não integra o SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-559":{"cognitivo":{"motivo":"Treinar ideais da Reforma Sanitária — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"democratização, universalidade, descentralização"},"comentario":{"resolucao":"A. A Reforma Sanitária defendia a democratização do acesso, a universalidade das ações e a descentralização com controle social — ideias que a 8ª Conferência levou à Constituição.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-560":{"cognitivo":{"motivo":"Treinar ideais da Reforma Sanitária — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"direito de cidadania"},"comentario":{"resolucao":"CERTO. A Reforma Sanitária nasceu na resistência à ditadura (CEBES, ABRASCO, movimentos populares) e propunha um sistema único, público e universal, com controle social — base do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-561":{"cognitivo":{"motivo":"Treinar enfrentamentos da Reforma Sanitária — I e II — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"segmentação e participação"},"comentario":{"resolucao":"A (I e II). A segmentação e o avanço privado dificultam a universalização (I), e a participação social democratizou a saúde (II). III, IV e V trazem afirmações absolutas e falsas: a descentralização não eliminou as desigualdades; o financiamento do SUS é historicamente instável; a política de saúde segue em disputa.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-562":{"cognitivo":{"motivo":"Treinar proposta da Reforma Sanitária (CFESS) — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"universalização das políticas sociais"},"comentario":{"resolucao":"E. A principal proposta era a universalização das políticas sociais e a garantia dos direitos sociais. Atenção 'quaternária', centralização e enxugamento do Estado são o oposto do projeto.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-563":{"cognitivo":{"motivo":"Treinar determinação social da saúde — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"saúde como efeito do engajamento humano"},"comentario":{"resolucao":"E. O trecho entende a saúde como resultado das transformações históricas da vida social produzidas pela ação humana. As demais reduzem a saúde à fisiologia, à psicologia ou à ciência médica, ou invertem a relação (o organismo moldando a sociedade).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-564":{"cognitivo":{"motivo":"Treinar determinação social × determinantes sociais — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"rompe com o paradigma do risco"},"comentario":{"resolucao":"D. A determinação social do processo saúde-doença rompe com o paradigma do risco e com a causalidade do modelo biomédico, entendendo a saúde como produzida pela organização social. Ela não se confunde com os 'determinantes sociais' focados em estilos de vida (C) nem isola fatores do contexto (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-565":{"cognitivo":{"motivo":"Treinar determinação social × determinantes sociais — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"não é paradigma do risco"},"comentario":{"resolucao":"ERRADO. A determinação social critica justamente essa abordagem: em vez de somar fatores de risco e culpar estilos de vida, explica a saúde pela forma como a sociedade organiza a produção e a reprodução da vida (classe, trabalho, território).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-566":{"cognitivo":{"motivo":"Treinar racionalidade hegemônica no SUS (Moraes) — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"saúde e desenvolvimento"},"comentario":{"resolucao":"B. Segundo Moraes (2019), a racionalidade hegemônica convive com elementos da Reforma Sanitária por três eixos: saúde e desenvolvimento, redefinição do público estatal e novos modelos e instrumentos de gestão. As demais trazem princípios do SUS ou elementos da agenda gerencial isolados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-567":{"cognitivo":{"motivo":"Treinar três projetos em disputa — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"Reforma Sanitária flexibilizada"},"comentario":{"resolucao":"A. Na leitura de Bravo, disputam a saúde pública brasileira o projeto da Reforma Sanitária, o da Reforma Sanitária flexibilizada e o projeto privatista, submetido ao mercado.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-568":{"cognitivo":{"motivo":"Treinar três projetos em disputa — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"focalização × universalidade"},"comentario":{"resolucao":"CERTO. O projeto privatista (alinhado às recomendações do Banco Mundial) propõe um SUS focalizado e o mercado para os demais; a Reforma Sanitária defende o sistema público, universal e estatal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-569":{"cognitivo":{"motivo":"Treinar características do projeto da Reforma Sanitária — ponto de reforma Sanitária e determinação social que a banca transforma em item.","palavraCritica":"serviço público e estatal universal"},"comentario":{"resolucao":"D. A Reforma Sanitária propunha uma nova concepção de saúde (determinação social, direito de cidadania) e um serviço público e estatal de acesso universal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Leia a ordem dos fatos e o texto constitucional.","erroComum":"Trocar datas, órgãos ou palavras do artigo.","comoBancaPensa":"Questão de revisão multibancas."}},"SUS-570":{"cognitivo":{"motivo":"Treinar sUDS e transição — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"SUDS de 1987"},"comentario":{"resolucao":"CERTO. Depois das Ações Integradas de Saúde (AIS, 1983), o SUDS (1987) estadualizou parte da rede do INAMPS. A Constituição de 1988 criou o SUS, e o INAMPS foi extinto em 1993 (Lei 8.689).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"AIS (1983) → SUDS (1987) → SUS (1988) → fim do INAMPS (1993).","erroComum":"Inverter a ordem cronológica.","comoBancaPensa":"Linha do tempo."}},"SUS-571":{"cognitivo":{"motivo":"Treinar extinção do INAMPS — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"1993"},"comentario":{"resolucao":"ERRADO. O INAMPS só foi extinto em 1993 (Lei 8.689), e a transferência da rede ocorreu de forma gradual, conduzida pelas Normas Operacionais Básicas — não imediatamente nem integralmente aos municípios.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"INAMPS: 1977 a 1993.","erroComum":"Achar que a CF extinguiu o INAMPS.","comoBancaPensa":"Data trocada."}},"SUS-572":{"cognitivo":{"motivo":"Treinar iAPs — por categoria — ponto de evolução histórica (1904-1988) que a banca transforma em item.","palavraCritica":"por categoria profissional"},"comentario":{"resolucao":"ERRADO. Os IAPs eram organizados por CATEGORIA profissional (marítimos, comerciários, bancários, industriários), com participação do Estado. Organização por empresa, com gestão de empregados e empregadores, era o modelo das CAPs da Lei Eloy Chaves.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"CAP = empresa; IAP = categoria.","erroComum":"Trocar CAPs por IAPs.","comoBancaPensa":"Troca clássica."}},"SUS-573":{"cognitivo":{"motivo":"Treinar universalidade e estrangeiros — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"direito de todos"},"comentario":{"resolucao":"CERTO. O texto fala em direito de TODOS; o STF e a Lei de Migração (Lei 13.445/2017) reconhecem o acesso de estrangeiros, inclusive em situação migratória irregular, às ações e serviços do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Todos = todos.","erroComum":"Restringir a brasileiros.","comoBancaPensa":"Alcance do art. 196."}},"SUS-574":{"cognitivo":{"motivo":"Treinar orçamento da seguridade social — ponto de financiamento do SUS (CF, art. 198) que a banca transforma em item.","palavraCritica":"seguridade social"},"comentario":{"resolucao":"CERTO. É o § 1º do art. 198, que remete ao art. 195. Por isso a saúde não se confunde com o orçamento fiscal comum: integra a seguridade, com previdência e assistência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Saúde = seguridade social.","erroComum":"Trocar por orçamento fiscal.","comoBancaPensa":"Literalidade do § 1º."}},"SUS-575":{"cognitivo":{"motivo":"Treinar remoção de órgãos e tecidos — ponto de iniciativa privada na saúde (CF, art. 199) que a banca transforma em item.","palavraCritica":"lei disporá"},"comentario":{"resolucao":"ERRADO. O § 4º do art. 199 manda a lei facilitar a remoção, mas veda TODO tipo de comercialização; a doação é gratuita (Lei 9.434/1997), e nenhuma comissão hospitalar pode autorizar remuneração.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Facilitar a doação, nunca vender.","erroComum":"Achar que há exceção para doador vivo.","comoBancaPensa":"Exceção inventada."}},"SUS-576":{"cognitivo":{"motivo":"Treinar produção de medicamentos — ponto de atribuições do SUS (CF, art. 200) que a banca transforma em item.","palavraCritica":"participar da produção"},"comentario":{"resolucao":"ERRADO. O art. 200, I, atribui ao SUS também PARTICIPAR da produção de medicamentos, equipamentos, imunobiológicos, hemoderivados e outros insumos — base dos laboratórios oficiais (Fiocruz/Bio-Manguinhos, Butantan).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"O SUS controla E participa da produção.","erroComum":"Cortar a segunda metade do inciso I.","comoBancaPensa":"Restrição indevida."}},"SUS-577":{"cognitivo":{"motivo":"Treinar direção única em cada esfera — ponto de direito à saúde e diretrizes do SUS (CF, arts. 196-198) que a banca transforma em item.","palavraCritica":"cada esfera de governo"},"comentario":{"resolucao":"CERTO. É o art. 198, I. Na Lei 8.080 (art. 9º), a direção é exercida pelo Ministério da Saúde e pelas secretarias estaduais e municipais de saúde ou órgãos equivalentes.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 1 e 4 — evolução histórica da organização do sistema de saúde e Constituição Federal, arts. 194 a 200. Base: Estratégia, Legislação SUS, Aula 05.","macete":"Um gestor por esfera.","erroComum":"Achar que a direção única é só federal.","comoBancaPensa":"Leitura da diretriz."}},"SUS-578":{"cognitivo":{"motivo":"Treinar associação de princípios — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"A-1, B-3, C-4, D-2, E-5"},"comentario":{"resolucao":"B. A chave é A-1, B-3, C-4, D-2, E-5: quem garante acesso a todos é a universalidade; quem prioriza conforme a necessidade é a equidade; a integralidade cobre todos os níveis; a regionalização organiza o território; e o controle social se faz em conselhos e conferências.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-579":{"cognitivo":{"motivo":"Treinar integralidade na prática — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"da prevenção à recuperação"},"comentario":{"resolucao":"C. Integralidade é atender às necessidades da pessoa em todas as etapas, da prevenção à recuperação, de forma contínua e articulada. Atender alguém sem exigir documentos é universalidade (D); priorizar áreas de risco por critério epidemiológico é equidade/epidemiologia (B).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-580":{"cognitivo":{"motivo":"Treinar integralidade na prática — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"universalidade, não integralidade"},"comentario":{"resolucao":"ERRADO. Garantir o ACESSO sem barreiras de documentação é aplicação da UNIVERSALIDADE (e da equidade, ao reconhecer a vulnerabilidade). Integralidade diz respeito ao conjunto articulado de ações, da prevenção à reabilitação, exigido por cada caso.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-581":{"cognitivo":{"motivo":"Treinar princípios — V/F (técnicos) — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"F, V, F, V"},"comentario":{"resolucao":"C (F, V, F, V). Descentralização redistribui o poder, com ênfase nos municípios — não concentra na União (1ª F). Integralidade vai da prevenção à reabilitação (2ª V). Hierarquização organiza níveis com referência e regulação, não acesso direto a tudo (3ª F). Conselhos e conferências influem nas decisões (4ª V).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-582":{"cognitivo":{"motivo":"Treinar princípios — V/F (técnicos) — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"referência e contrarreferência"},"comentario":{"resolucao":"CERTO. Hierarquizar é organizar níveis de complexidade crescente (art. 8º) com fluxos de encaminhamento; a atenção primária é a ordenadora do cuidado, e a regulação organiza o acesso aos níveis especializados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-583":{"cognitivo":{"motivo":"Treinar princípios e diretrizes — correta — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"integralidade em todos os níveis"},"comentario":{"resolucao":"C. A integralidade abrange promoção, prevenção, diagnóstico, tratamento e reabilitação em todos os níveis de complexidade. Erros: descentralizar não é concentrar nas capitais (A); conselhos têm poder deliberativo (B); hierarquizar não é acesso direto à alta complexidade (D); universalidade não é focalização nos pobres (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-584":{"cognitivo":{"motivo":"Treinar lei 8.080 — I e III — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"universalidade não é para grupos"},"comentario":{"resolucao":"C (I e III). A saúde é direito fundamental, cabendo ao Estado prover as condições indispensáveis (art. 2º), e o SUS atua na promoção, proteção e recuperação em todos os níveis. II erra: a universalidade alcança TODOS, não grupos específicos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-585":{"cognitivo":{"motivo":"Treinar arts. 2º e 4º — V/F — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"V, V, V"},"comentario":{"resolucao":"E (V, V, V). As três reproduzem a lei: composição do SUS (art. 4º), saúde como direito fundamental (art. 2º) e participação complementar da iniciativa privada (art. 4º, § 2º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-586":{"cognitivo":{"motivo":"Treinar determinantes — lacuna — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"meio ambiente"},"comentario":{"resolucao":"A. O art. 3º lista, entre os determinantes e condicionantes, a alimentação, a moradia, o saneamento básico, o MEIO AMBIENTE, o trabalho, a renda, a educação, a atividade física, o transporte, o lazer e o acesso aos bens e serviços essenciais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-587":{"cognitivo":{"motivo":"Treinar lei 8.080 — base jurídica — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"base jurídica com CF e Lei 8.142"},"comentario":{"resolucao":"D. A Lei 8.080 é uma das bases jurídicas do SUS, ao lado da seção da saúde na Constituição e da Lei 8.142. Percentuais mínimos são da LC 141/2012 (E); a PNAB é portaria (B); a política da Covid-19 e a responsabilidade pelos planos vêm de outras normas (A, C).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-588":{"cognitivo":{"motivo":"Treinar financiamento do subsistema indígena — ponto de subsistemas e acompanhante (Lei 8.080, arts. 19-A a 19-J) que a banca transforma em item.","palavraCritica":"União"},"comentario":{"resolucao":"C. Cabe à UNIÃO, com seus recursos próprios, financiar o Subsistema de Atenção à Saúde Indígena (art. 19-C); estados, municípios e organizações atuam de forma complementar (art. 19-E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-589":{"cognitivo":{"motivo":"Treinar objetivo — assistência integrada — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"assistenciais e preventivas"},"comentario":{"resolucao":"A. Art. 5º, III: assistência às pessoas por ações de promoção, proteção e recuperação da saúde, com a realização integrada das ações assistenciais e das atividades preventivas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-590":{"cognitivo":{"motivo":"Treinar participação indígena nos colegiados — ponto de subsistemas e acompanhante (Lei 8.080, arts. 19-A a 19-J) que a banca transforma em item.","palavraCritica":"organismos colegiados"},"comentario":{"resolucao":"CERTO. A participação da comunidade é princípio do SUS (art. 7º, VIII), e o art. 19-H assegura às populações indígenas participar dos organismos colegiados de formulação, acompanhamento e avaliação das políticas de saúde (CNS, conselhos estaduais e municipais).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia a lei, não a intuição.","erroComum":"Confundir princípio legal com norma infralegal.","comoBancaPensa":"Item real CEBRASPE (PC-DF 2025)."}},"SUS-591":{"cognitivo":{"motivo":"Treinar proteção integral e maus-tratos — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"princípio legal (art. 7º, XV)"},"comentario":{"resolucao":"ERRADO. As duas partes estão no MESMO inciso legal: o art. 7º, XV (Lei 13.427/2017), prevê a proteção integral dos direitos humanos de todos os usuários E a especial atenção à identificação de maus-tratos, negligência e violência sexual contra crianças e adolescentes. Nada ali é recomendação infralegal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia a lei, não a intuição.","erroComum":"Confundir princípio legal com norma infralegal.","comoBancaPensa":"Item real CEBRASPE (PC-DF 2025)."}},"SUS-592":{"cognitivo":{"motivo":"Treinar dever do Estado — políticas econômicas e sociais — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"políticas econômicas e sociais"},"comentario":{"resolucao":"CERTO. O art. 2º, § 1º, define o dever do Estado como a formulação e execução de políticas econômicas e sociais que visem à redução de riscos de doenças e agravos e ao acesso universal e igualitário — a saúde depende de mais do que políticas setoriais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia a lei, não a intuição.","erroComum":"Confundir princípio legal com norma infralegal.","comoBancaPensa":"Item real CEBRASPE (PC-DF 2025)."}},"SUS-593":{"cognitivo":{"motivo":"Treinar distrito Federal — atribuições — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"estados e municípios"},"comentario":{"resolucao":"ERRADO. O art. 19 da Lei 8.080 atribui ao Distrito Federal as competências reservadas aos ESTADOS e aos MUNICÍPIOS. As atribuições da direção nacional (União) não são acumuladas pelo DF.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia a lei, não a intuição.","erroComum":"Acrescentar a União às atribuições do DF.","comoBancaPensa":"Item real CEBRASPE (PC-DF 2025)."}},"SUS-594":{"cognitivo":{"motivo":"Treinar atendimento às mulheres vítimas de violência — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"cirurgias plásticas reparadoras"},"comentario":{"resolucao":"CERTO. É o art. 7º, XIV (Lei 13.427/2017): organização de atendimento público específico e especializado para mulheres e vítimas de violência doméstica em geral, que garanta atendimento, acompanhamento psicológico e cirurgias plásticas reparadoras.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia a lei, não a intuição.","erroComum":"Confundir princípio legal com norma infralegal.","comoBancaPensa":"Item real CEBRASPE (PC-DF 2025)."}},"SUS-595":{"cognitivo":{"motivo":"Treinar distritos e consórcios — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"distritos no nível municipal"},"comentario":{"resolucao":"D. Art. 10, § 2º: no nível municipal, o SUS poderá organizar-se em distritos para integrar e articular recursos, técnicas e práticas voltadas para a cobertura total das ações de saúde. Erros: os municípios PODEM formar consórcios (A); as comissões de integração ensino-serviço são PERMANENTES (B); as comissões intersetoriais são NACIONAIS e subordinadas ao CNS (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-596":{"cognitivo":{"motivo":"Treinar distritos e consórcios — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"comissões permanentes"},"comentario":{"resolucao":"CERTO. É o art. 14 e seu parágrafo único. A banca troca 'permanentes' por 'transitórias' — erro da alternativa B.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-597":{"cognitivo":{"motivo":"Treinar competências — autonomia municipal — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"municípios executam com autonomia"},"comentario":{"resolucao":"E. Os municípios têm autonomia para organizar e executar os serviços de saúde, respeitadas as diretrizes gerais do SUS (art. 18, I). Erros: a União não executa tudo (A); o financiamento é tripartite (C); fiscalização e controle não são exclusivos dos conselhos (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-598":{"cognitivo":{"motivo":"Treinar lei Orgânica da Saúde — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"8.080, de 19/9/1990"},"comentario":{"resolucao":"A. A Lei Orgânica da Saúde é a Lei 8.080, de 19 de setembro de 1990, que dispõe sobre as condições para promoção, proteção e recuperação da saúde e a organização e o funcionamento dos serviços. A 8.142 é de 28 de dezembro de 1990 e trata da participação da comunidade e das transferências.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-599":{"cognitivo":{"motivo":"Treinar sistemas da direção nacional — exceto — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"meio ambiente é participação"},"comentario":{"resolucao":"C (exceto). À direção nacional cabe DEFINIR E COORDENAR os sistemas de redes de alta complexidade, laboratórios de saúde pública, vigilância epidemiológica e vigilância sanitária (art. 16, III). Quanto ao controle das agressões ao meio ambiente, ela PARTICIPA da formulação e implementação da política (art. 16, II, a).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-600":{"cognitivo":{"motivo":"Treinar determinantes — I a IV — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"alimentação, trabalho, lazer, saneamento"},"comentario":{"resolucao":"A. Alimentação, trabalho, lazer e saneamento básico estão entre os determinantes e condicionantes do art. 3º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-601":{"cognitivo":{"motivo":"Treinar comissões intersetoriais — atividades — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"V, V, V"},"comentario":{"resolucao":"B (V, V, V). O art. 13 lista as atividades articuladas pelas comissões intersetoriais: alimentação e nutrição; saneamento e meio ambiente; vigilância sanitária e farmacoepidemiologia; recursos humanos; ciência e tecnologia; e saúde do trabalhador.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-602":{"cognitivo":{"motivo":"Treinar comissões intersetoriais — atividades — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"seis atividades do art. 13"},"comentario":{"resolucao":"CERTO. São as seis atividades do art. 13. Comissões intersetoriais tratam justamente de políticas que dependem de áreas fora do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-603":{"cognitivo":{"motivo":"Treinar objetivos — não corresponde — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"tratamentos particulares"},"comentario":{"resolucao":"E. 'Promover tratamentos exclusivos e particulares para favorecer instituições privadas' não é objetivo do SUS. Identificar e divulgar os determinantes (A, B), formular política nos campos econômico e social (C) e prestar assistência integrada (D) são os objetivos do art. 5º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-604":{"cognitivo":{"motivo":"Treinar estoques de medicamentos na internet — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"obrigadas, quinzenal, cidadão comum"},"comentario":{"resolucao":"C. As instâncias gestoras do SUS ficam OBRIGADAS a disponibilizar na internet os estoques de medicamentos das farmácias públicas sob sua gestão, com atualização QUINZENAL, de forma acessível ao CIDADÃO COMUM (art. 6º, § 4º, incluído em 2023).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-605":{"cognitivo":{"motivo":"Treinar estoques de medicamentos na internet — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"atualização quinzenal"},"comentario":{"resolucao":"ERRADO. A atualização é QUINZENAL e a lei não cria exceção por porte do município: todas as instâncias gestoras ficam obrigadas, com informação acessível ao cidadão comum.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-606":{"cognitivo":{"motivo":"Treinar autonomia — integridade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"física e moral"},"comentario":{"resolucao":"B. Art. 7º, III: preservação da autonomia das pessoas na defesa de sua integridade FÍSICA e MORAL.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-607":{"cognitivo":{"motivo":"Treinar organização da rede (art. 8º) — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"complexidade crescente"},"comentario":{"resolucao":"A. Art. 8º: as ações e serviços de saúde, diretamente ou com participação complementar da iniciativa privada, serão organizados de forma regionalizada e hierarquizada em níveis de complexidade CRESCENTE.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-608":{"cognitivo":{"motivo":"Treinar consórcios e distritos — I e III — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"direção única nos consórcios"},"comentario":{"resolucao":"C (I e III). Os municípios podem formar consórcios (art. 10) e organizar-se em distritos (§ 2º). II erra: aos consórcios aplica-se o princípio da direção ÚNICA (§ 1º), não 'compartilhada'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-609":{"cognitivo":{"motivo":"Treinar consórcios e distritos — I e III — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"direção única"},"comentario":{"resolucao":"ERRADO. O § 1º do art. 10 manda aplicar aos consórcios o princípio da DIREÇÃO ÚNICA, e os atos constitutivos devem dispor sobre sua observância. Direção compartilhada contraria o art. 7º, IX.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-610":{"cognitivo":{"motivo":"Treinar objetivos e atribuições — II, III e IV — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"fiscalização de alimentos é do SUS"},"comentario":{"resolucao":"C (II, III e IV). Assistência integrada (art. 5º, III), campo de atuação com as vigilâncias, saúde do trabalhador, assistência terapêutica e saúde bucal (art. 6º, I) e política de medicamentos e insumos com participação na produção (art. 6º, VI). I erra: a fiscalização de alimentos, água e bebidas É do SUS (art. 6º, VIII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-611":{"cognitivo":{"motivo":"Treinar diretrizes e competências — correta — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"condições e ambientes de trabalho"},"comentario":{"resolucao":"C. Participar da execução, controle e avaliação das ações referentes às condições e aos ambientes de trabalho é competência municipal (art. 18, III). Erros: o capital estrangeiro é permitido nos casos da lei (A); a participação da comunidade é princípio, não faculdade (B); evitar duplicidade é princípio autônomo (D); identificar determinantes é OBJETIVO (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-612":{"cognitivo":{"motivo":"Treinar saúde do trabalhador (art. 6º, § 3º) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"vigilância e assistência"},"comentario":{"resolucao":"B. Saúde do trabalhador é o conjunto de atividades que, por meio das vigilâncias epidemiológica e sanitária, se destina à promoção e proteção da saúde dos trabalhadores e à recuperação e reabilitação dos submetidos aos riscos e agravos das condições de trabalho. Inspeção do trabalho e NRs são do Ministério do Trabalho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-613":{"cognitivo":{"motivo":"Treinar saúde do trabalhador (art. 6º, § 3º) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"impacto das tecnologias"},"comentario":{"resolucao":"CERTO. São os incisos IV e V do § 3º do art. 6º, ao lado da assistência, da participação em pesquisas, da normatização, da revisão da lista de doenças do trabalho e do direito de o sindicato pedir interdição.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-614":{"cognitivo":{"motivo":"Treinar níveis de proteção — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"políticas intersetoriais"},"comentario":{"resolucao":"A. A promoção da saúde exige políticas intersetoriais sobre os determinantes sociais. As demais trazem restrições falsas: prevenção não se resume a exames e vacinas; recuperação não é 'secundária'; reabilitação não é só para deficiência física; a responsabilidade do SUS não é só curativa.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-615":{"cognitivo":{"motivo":"Treinar lei 8.080 — incorreta (tempo integral) — ponto de financiamento, recursos humanos e disposições finais (Lei 8.080, arts. 27 a 55) que a banca transforma em item.","palavraCritica":"tempo integral"},"comentario":{"resolucao":"A (incorreta). Os cargos e funções de chefia, direção e assessoramento no SUS só podem ser exercidos em regime de TEMPO INTEGRAL (art. 28). As demais estão corretas: desvio de recursos do SUS configura crime de emprego irregular de verbas públicas (art. 52), o SNA é da direção nacional (art. 16, XIX) e os princípios do art. 7º valem para os serviços contratados e conveniados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-616":{"cognitivo":{"motivo":"Treinar lei 8.080 — incorreta (tempo integral) — ponto de financiamento, recursos humanos e disposições finais (Lei 8.080, arts. 27 a 55) que a banca transforma em item.","palavraCritica":"tempo integral"},"comentario":{"resolucao":"CERTO. É o art. 28, caput. O § 1º admite que os servidores que legalmente acumulam dois cargos ou empregos exerçam suas atividades em mais de um estabelecimento do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-617":{"cognitivo":{"motivo":"Treinar lei 8.080 — incorreta (tempo integral) — ponto de financiamento, recursos humanos e disposições finais (Lei 8.080, arts. 27 a 55) que a banca transforma em item.","palavraCritica":"crime de emprego irregular de verbas"},"comentario":{"resolucao":"ERRADO. O art. 52 tipifica a conduta: sem prejuízo de outras sanções cabíveis, constitui crime de emprego irregular de verbas ou rendas públicas (Código Penal, art. 315) usar recursos do SUS em finalidades diversas das previstas na lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-618":{"cognitivo":{"motivo":"Treinar lei 8.080 — incorreta (COSEMS) — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"vinculados ao CONASEMS"},"comentario":{"resolucao":"C (incorreta). Pelo art. 14-B, § 2º, os COSEMS são reconhecidos como entidades que representam os entes municipais no âmbito estadual, para tratar de matérias de saúde, DESDE QUE vinculados institucionalmente ao CONASEMS, na forma de seus estatutos. As demais reproduzem a lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-619":{"cognitivo":{"motivo":"Treinar lei 8.080 — incorreta (COSEMS) — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"vinculados ao CONASEMS"},"comentario":{"resolucao":"CERTO. É o § 2º do art. 14-B. CONASS e CONASEMS representam estados e municípios em âmbito nacional; os COSEMS, os municípios no âmbito de cada estado (e compõem a CIB).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-620":{"cognitivo":{"motivo":"Treinar responsabilidades comuns — I e III — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"planejar e vigilância"},"comentario":{"resolucao":"A (I e III). Planejar, organizar, regular e avaliar ações e desenvolver vigilância e controle de endemias são responsabilidades comuns das três esferas. Definir normas nacionais (II) e coordenar a formação de RH em âmbito nacional (IV) cabem à direção nacional; as esferas apenas PARTICIPAM da política de RH (art. 15, IX).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-621":{"cognitivo":{"motivo":"Treinar lei 8.080 — correta (tecnologias) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"impacto das tecnologias"},"comentario":{"resolucao":"A. A avaliação do impacto que as tecnologias provocam à saúde integra a saúde do trabalhador (art. 6º, § 3º, IV). Erros: atendimento e internação domiciliares fazem parte do SUS (B; art. 19-I); a garantia ao recusar a telessaúde é de atendimento PRESENCIAL (D; art. 26-A).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-622":{"cognitivo":{"motivo":"Treinar lei 8.080 — correta (dever compartilhado) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"não exclui pessoas e família"},"comentario":{"resolucao":"A. Art. 2º, § 2º. Erros: a definição em B é da vigilância SANITÁRIA; os consórcios são de MUNICÍPIOS (D; art. 10); o registro obrigatório é da declaração de RAÇA OU COR (E; art. 19-G, § 1º-A).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-623":{"cognitivo":{"motivo":"Treinar direção municipal — saúde bucal — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"executar saúde bucal e alimentação"},"comentario":{"resolucao":"C. Compete à direção municipal executar serviços de vigilância epidemiológica e sanitária, de alimentação e nutrição, de saneamento básico, de saúde do trabalhador e de SAÚDE BUCAL (art. 18, IV, incluída pela Lei 14.572/2023). Definir e coordenar a rede de laboratórios é da direção nacional (B).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-624":{"cognitivo":{"motivo":"Treinar direção municipal — saúde bucal — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"município executa saúde bucal"},"comentario":{"resolucao":"CERTO. Art. 18, IV (município executa) e art. 16, III, a (União define e coordena). Saúde bucal entrou no art. 18 com a Lei 14.572/2023.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-625":{"cognitivo":{"motivo":"Treinar não é princípio do art. 7º — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"objetivo da CIB e da CIT"},"comentario":{"resolucao":"A. 'Decidir sobre os aspectos operacionais, financeiros e administrativos da gestão compartilhada do SUS' é OBJETIVO da atuação das comissões intergestores (art. 14-A, parágrafo único, I), não princípio. Divulgação do potencial dos serviços, proteção integral dos direitos humanos e participação da comunidade estão no art. 7º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-626":{"cognitivo":{"motivo":"Treinar vigilância epidemiológica na prática — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"surtos e agravos de notificação"},"comentario":{"resolucao":"D. A vigilância epidemiológica monitora o impacto das ações preventivas, investiga surtos e epidemias e controla os agravos de notificação compulsória (art. 6º, § 2º). Fiscalizar serviços privados (A) é vigilância sanitária/controle; auditoria (B) é do SNA.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-627":{"cognitivo":{"motivo":"Treinar controle dos serviços privados — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"direção municipal"},"comentario":{"resolucao":"B. Art. 18, XI: compete à direção MUNICIPAL controlar e fiscalizar os procedimentos dos serviços privados de saúde. O município também celebra contratos e convênios com prestadores privados e avalia sua execução (art. 18, X).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-628":{"cognitivo":{"motivo":"Treinar controle dos serviços privados — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"direção municipal"},"comentario":{"resolucao":"ERRADO. Essas competências estão no art. 18 (X e XI), entre as da direção MUNICIPAL, que contrata, controla e avalia os prestadores privados de sua rede.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-629":{"cognitivo":{"motivo":"Treinar princípios do SUS — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"integralidade, descentralização, participação"},"comentario":{"resolucao":"B. Integralidade da assistência, descentralização político-administrativa e participação da comunidade estão no art. 7º (II, IX e VIII). 'Igualdade na organização dos serviços', 'integralidade do financiamento', 'centralização' e 'exclusividade pública' não.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-630":{"cognitivo":{"motivo":"Treinar definição — vigilância epidemiológica — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"epidemiológica"},"comentario":{"resolucao":"B. Conhecer, detectar e prevenir mudanças nos fatores determinantes, para recomendar medidas de controle, é tarefa da vigilância EPIDEMIOLÓGICA (art. 6º, § 2º); a sanitária elimina, diminui ou previne riscos de bens e serviços.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-631":{"cognitivo":{"motivo":"Treinar campo de atuação — não prevista — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"prioridade a segurados do INSS"},"comentario":{"resolucao":"C. Atendimento prioritário a segurados do INSS contraria a universalidade e não está na lei — era a lógica do antigo INAMPS. Saúde do trabalhador, vigilância epidemiológica e assistência terapêutica integral estão no art. 6º, I.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-632":{"cognitivo":{"motivo":"Treinar periodicidade — estoques — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"quinzenal"},"comentario":{"resolucao":"C. A divulgação dos estoques de medicamentos das farmácias públicas na internet deve ser atualizada QUINZENALMENTE (art. 6º, § 4º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-633":{"cognitivo":{"motivo":"Treinar direção na União — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"Ministério da Saúde"},"comentario":{"resolucao":"A. Art. 9º, I: no âmbito da União, a direção do SUS é exercida pelo Ministério da Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-634":{"cognitivo":{"motivo":"Treinar pesquisa — cofinanciamento — ponto de financiamento, recursos humanos e disposições finais (Lei 8.080, arts. 27 a 55) que a banca transforma em item.","palavraCritica":"SUS, universidades e orçamento fiscal"},"comentario":{"resolucao":"B (I, II e III). Art. 32, § 5º: as atividades de pesquisa e desenvolvimento científico e tecnológico em saúde serão cofinanciadas pelo SUS, pelas universidades e pelo orçamento fiscal, além de recursos de fomento, de origem externa e receita própria das instituições executoras.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-635":{"cognitivo":{"motivo":"Treinar pesquisa — cofinanciamento — ponto de financiamento, recursos humanos e disposições finais (Lei 8.080, arts. 27 a 55) que a banca transforma em item.","palavraCritica":"cofinanciadas pelo SUS"},"comentario":{"resolucao":"ERRADO. O art. 32, § 5º, prevê o COfinanciamento pelo SUS, pelas universidades e pelo orçamento fiscal, além dos recursos de fomento. A pesquisa também está no campo de atuação do SUS (art. 6º, X).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-636":{"cognitivo":{"motivo":"Treinar município executa — I, II e III — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"inclusive saúde bucal"},"comentario":{"resolucao":"A. O município executa serviços de vigilância sanitária, de saúde do trabalhador e de saúde bucal, além da vigilância epidemiológica, alimentação e nutrição e saneamento (art. 18, IV).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-637":{"cognitivo":{"motivo":"Treinar acesso independente de condição — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"universalidade"},"comentario":{"resolucao":"B. Acesso de todos, independentemente da localização ou condição socioeconômica, é a UNIVERSALIDADE. Setorização não é princípio; hierarquização e regionalização tratam da organização da rede.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-638":{"cognitivo":{"motivo":"Treinar dever do Estado — I, II e III — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"todas corretas"},"comentario":{"resolucao":"D (I, II e III). As três afirmativas reproduzem o art. 2º, caput e § 1º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-639":{"cognitivo":{"motivo":"Treinar acompanhante da mulher — ponto de subsistemas e acompanhante (Lei 8.080, arts. 19-A a 19-J) que a banca transforma em item.","palavraCritica":"maior de idade, independentemente"},"comentario":{"resolucao":"C. A Lei 14.737/2023 incluiu na Lei 8.080 o direito de toda mulher, em consultas, exames e procedimentos em unidades públicas ou privadas, fazer-se acompanhar por pessoa MAIOR DE IDADE, durante todo o atendimento, INDEPENDENTEMENTE de notificação prévia.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-640":{"cognitivo":{"motivo":"Treinar acompanhante da mulher — ponto de subsistemas e acompanhante (Lei 8.080, arts. 19-A a 19-J) que a banca transforma em item.","palavraCritica":"independentemente de notificação"},"comentario":{"resolucao":"ERRADO. O direito existe INDEPENDENTEMENTE de notificação prévia. As 24 horas aparecem em outra regra: nos atendimentos com sedação, a eventual RENÚNCIA ao acompanhante deve ser feita por escrito com no mínimo 24 horas de antecedência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-641":{"cognitivo":{"motivo":"Treinar princípios — I, II e IV — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"descentralização com direção única"},"comentario":{"resolucao":"D (I, II e IV). Os princípios listados em I, II e IV constam do art. 7º; a afirmativa III deforma a descentralização (que é com direção única EM CADA esfera de governo).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-642":{"cognitivo":{"motivo":"Treinar campo de atuação — exceto — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"ordenação, não coordenação"},"comentario":{"resolucao":"D (exceto). O campo do SUS inclui a ORDENAÇÃO da formação de recursos humanos na área de saúde (art. 6º, III), não a 'coordenação da formação na área de assistência'. Meio ambiente, alimentos e sangue estão nos incisos V, VIII e XI.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-643":{"cognitivo":{"motivo":"Treinar saúde do trabalhador — I, II e III — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"todas corretas"},"comentario":{"resolucao":"A (I, II e III). As três afirmativas reproduzem incisos do art. 6º, § 3º, inclusive a revisão periódica da listagem oficial de doenças originadas no processo de trabalho, com colaboração das entidades sindicais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-644":{"cognitivo":{"motivo":"Treinar serviços privados — V/F — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"V, F, F, F"},"comentario":{"resolucao":"B (V, F, F, F). A assistência é livre à iniciativa privada (art. 21). As normas a observar são as do órgão de direção do SUS, não de 'órgão privado' (art. 22); diante da insuficiência, o SUS PODERÁ (não 'deverá') recorrer ao privado (art. 24); e aos dirigentes de entidades contratadas é VEDADO exercer cargo de chefia ou função de confiança no SUS (art. 26, § 4º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-645":{"cognitivo":{"motivo":"Treinar serviços privados — V/F — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"vedado cargo de chefia"},"comentario":{"resolucao":"CERTO. É o § 4º do art. 26: a regra evita o conflito de interesses de quem contrata e fiscaliza o próprio serviço.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-646":{"cognitivo":{"motivo":"Treinar serviços privados — V/F — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"mantido o equilíbrio econômico-financeiro"},"comentario":{"resolucao":"ERRADO. O § 2º do art. 26 submete os contratados às normas e princípios do SUS, MANTIDO o equilíbrio econômico e financeiro do contrato.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-647":{"cognitivo":{"motivo":"Treinar cIB e CIT — V, V, V — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"objetivos das comissões intergestores"},"comentario":{"resolucao":"A (V, V, V). O parágrafo único do art. 14-A atribui às comissões intergestores decidir sobre aspectos operacionais, financeiros e administrativos da gestão compartilhada, conforme os planos aprovados pelos conselhos, e definir diretrizes nacionais, regionais e intermunicipais sobre a organização das redes, sobretudo governança e integração entre os entes.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-648":{"cognitivo":{"motivo":"Treinar cIB e CIT — V, V, V — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"em conformidade com os planos"},"comentario":{"resolucao":"ERRADO. As decisões das comissões devem estar em conformidade com a política consubstanciada em planos de saúde APROVADOS PELOS CONSELHOS (art. 14-A, parágrafo único, I): a pactuação entre gestores não se sobrepõe ao controle social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-649":{"cognitivo":{"motivo":"Treinar regionalização — correta — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"redes hierarquizadas"},"comentario":{"resolucao":"E. A regionalização organiza os serviços em redes hierarquizadas, integrando os níveis de atenção. Erros: integralidade não se limita à atenção básica (A); a participação social é deliberativa, não só consultiva (B); universalidade não prioriza trabalhadores formais (C); equidade não é uniformidade (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-650":{"cognitivo":{"motivo":"Treinar atribuições comuns — exceto — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"participação no controle ambiental é nacional"},"comentario":{"resolucao":"D (exceto). Participar da definição de normas e mecanismos de controle de agravos sobre o meio ambiente, com órgãos afins, é competência da direção NACIONAL (art. 16, II). Sistema de informação, acompanhamento do nível de saúde e normas técnicas de padrões de qualidade são atribuições comuns (art. 15).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-651":{"cognitivo":{"motivo":"Treinar financiamento — incorreta — ponto de financiamento, recursos humanos e disposições finais (Lei 8.080, arts. 27 a 55) que a banca transforma em item.","palavraCritica":"não é só dos municípios"},"comentario":{"resolucao":"C (incorreta). O financiamento do SUS é tripartite (União, estados, DF e municípios) e não exclusivo dos municípios.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-652":{"cognitivo":{"motivo":"Treinar bem-estar físico, mental e social — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"todos os itens"},"comentario":{"resolucao":"D. O parágrafo único do art. 3º diz que dizem respeito à saúde as ações destinadas a garantir às pessoas e à coletividade condições de bem-estar FÍSICO, MENTAL e SOCIAL.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-653":{"cognitivo":{"motivo":"Treinar serviços contratados — 1ª parte — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"vedado aos dirigentes"},"comentario":{"resolucao":"B. A 1ª parte reproduz o art. 26, § 2º (submissão às normas do SUS, mantido o equilíbrio econômico-financeiro). A 2ª parte erra: aos dirigentes de entidades contratadas é VEDADO exercer cargo de chefia ou função de confiança no SUS (§ 4º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-654":{"cognitivo":{"motivo":"Treinar equidade — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"tratar desiguais de maneira desigual"},"comentario":{"resolucao":"A. Equidade é tratar desigualmente os desiguais, atendendo às necessidades conforme as diferenças. Atendimento indistinto é igualdade; níveis crescentes é hierarquização.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-655":{"cognitivo":{"motivo":"Treinar definições — todas incorretas — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"todas incorretas"},"comentario":{"resolucao":"C. As quatro afirmativas deformam a lei: a saúde do trabalhador trata dos riscos das condições de TRABALHO, não de 'qualquer atividade do cotidiano'; e a saúde bucal abrange TODOS os níveis de atenção, não só a atenção básica (art. 6º, § 5º, Lei 14.572/2023), entre outros erros.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-656":{"cognitivo":{"motivo":"Treinar definições — todas incorretas — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"todos os níveis de atenção"},"comentario":{"resolucao":"CERTO. É a definição do § 5º do art. 6º (Lei 14.572/2023). O erro da banca costuma ser restringi-la à atenção básica.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-657":{"cognitivo":{"motivo":"Treinar lei 8.080 — incorreta (saneamento) — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"saneamento está incluído"},"comentario":{"resolucao":"E (incorreta). A participação na formulação da política e na execução de ações de saneamento básico ESTÁ incluída no campo de atuação do SUS (art. 6º, II).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-658":{"cognitivo":{"motivo":"Treinar objetivos — I, II e III — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"todos corretos"},"comentario":{"resolucao":"E. Os três itens são os objetivos do art. 5º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-659":{"cognitivo":{"motivo":"Treinar princípios — exceto (sigilo) — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"divulgação, não sigilo"},"comentario":{"resolucao":"D (exceto). A lei manda DIVULGAR informações quanto ao potencial dos serviços de saúde e sua utilização pelo usuário (art. 7º, VI); 'resguardado o sigilo' inverte o princípio.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-660":{"cognitivo":{"motivo":"Treinar definições do art. 6º — todas corretas — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"todas corretas"},"comentario":{"resolucao":"E. As três afirmativas reproduzem os §§ 1º (vigilância sanitária), 2º (vigilância epidemiológica) e 3º (saúde do trabalhador) do art. 6º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-661":{"cognitivo":{"motivo":"Treinar campo de atuação — execução — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"vigilância epidemiológica"},"comentario":{"resolucao":"C. O campo de atuação inclui a execução de ações de vigilância epidemiológica (art. 6º, I, b). 'Saúde sanitária', 'vigilância do trabalhador' e assistência terapêutica 'parcial' não são termos da lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-662":{"cognitivo":{"motivo":"Treinar rede de laboratórios — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"direção nacional"},"comentario":{"resolucao":"A. Definir e coordenar os sistemas de rede de laboratórios de saúde pública é da direção NACIONAL (art. 16, III, b). O estado coordena a rede estadual de laboratórios e hemocentros; o município gere os seus.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-663":{"cognitivo":{"motivo":"Treinar proteção integral dos direitos humanos — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"princípios"},"comentario":{"resolucao":"B. A proteção integral dos direitos humanos de todos os usuários, com atenção à identificação de maus-tratos, negligência e violência sexual contra crianças e adolescentes, foi incluída entre os PRINCÍPIOS do SUS (art. 7º, XV).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-664":{"cognitivo":{"motivo":"Treinar participação da iniciativa privada — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"complementar"},"comentario":{"resolucao":"A. A iniciativa privada poderá participar do SUS em caráter COMPLEMENTAR (art. 4º, § 2º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-665":{"cognitivo":{"motivo":"Treinar lei Orgânica — complementar — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"caráter complementar"},"comentario":{"resolucao":"D. Entre as alternativas, a que corresponde à Lei 8.080 nos termos propostos é a participação da iniciativa privada em caráter complementar (art. 4º, § 2º). A alternativa C transcreve a Lei 8.142 (conferências e conselhos).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-666":{"cognitivo":{"motivo":"Treinar acompanhante da mulher — II e III — ponto de subsistemas e acompanhante (Lei 8.080, arts. 19-A a 19-J) que a banca transforma em item.","palavraCritica":"renúncia por escrito com 24 horas"},"comentario":{"resolucao":"E (II e III). I erra: o direito ao acompanhante maior de idade vale INDEPENDENTEMENTE de notificação prévia. II e III estão corretas: com sedação, a renúncia deve ser por escrito, após esclarecimento, com no mínimo 24 horas de antecedência; em centro cirúrgico ou UTI com restrições justificadas, só se admite acompanhante profissional de saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-667":{"cognitivo":{"motivo":"Treinar acompanhante da mulher — II e III — ponto de subsistemas e acompanhante (Lei 8.080, arts. 19-A a 19-J) que a banca transforma em item.","palavraCritica":"por escrito, 24 horas antes"},"comentario":{"resolucao":"CERTO. A regra protege a paciente sedada, que não poderia manifestar recusa no momento; sem renúncia formal, a unidade deve garantir o acompanhante.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-668":{"cognitivo":{"motivo":"Treinar v/F — toxicologia, vigilância e direção — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"V, F, F"},"comentario":{"resolucao":"E (V, F, F). A assistência toxicológica abrange a prevenção, o diagnóstico e o tratamento das intoxicações agudas por substâncias químicas, animais peçonhentos e plantas tóxicas (V). A definição da 2ª afirmativa é da vigilância EPIDEMIOLÓGICA. Acompanhar, controlar e avaliar as REDES HIERARQUIZADAS é competência da direção ESTADUAL (art. 17, II).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-669":{"cognitivo":{"motivo":"Treinar v/F — toxicologia, vigilância e direção — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"estado avalia as redes hierarquizadas"},"comentario":{"resolucao":"ERRADO. Inverteu as esferas: acompanhar, controlar e avaliar as redes hierarquizadas é da direção ESTADUAL (art. 17, II); acompanhar, controlar e avaliar as ações e serviços, respeitadas as competências estaduais e municipais, é da direção NACIONAL (art. 16, XVII).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-670":{"cognitivo":{"motivo":"Treinar alteração de 2024 — ponto de princípios e diretrizes do SUS (Lei 8.080, arts. 7º e 8º) que a banca transforma em item.","palavraCritica":"mulheres vítimas de violência"},"comentario":{"resolucao":"E. Em 2024 a Lei 8.080 recebeu disposições sobre o acolhimento e o atendimento a mulheres vítimas de qualquer tipo de violência, ampliando o princípio do atendimento específico e especializado (art. 7º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Leia o artigo: a banca troca uma palavra.","erroComum":"Aceitar a palavra trocada.","comoBancaPensa":"Revisão multibancas da Lei 8.080."}},"SUS-671":{"cognitivo":{"motivo":"Treinar acúmulo legal de cargos — ponto de financiamento, recursos humanos e disposições finais (Lei 8.080, arts. 27 a 55) que a banca transforma em item.","palavraCritica":"mais de um estabelecimento"},"comentario":{"resolucao":"CERTO. É a combinação do caput e do § 1º do art. 28: a regra geral permite o exercício em mais de um estabelecimento a quem acumula legalmente; chefia, direção e assessoramento exigem tempo integral.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Chefia = tempo integral; acumulação legal = mais de um estabelecimento.","erroComum":"Estender a permissão à chefia.","comoBancaPensa":"Combinação de dispositivos."}},"SUS-672":{"cognitivo":{"motivo":"Treinar acompanhante em centro cirúrgico e UTI — ponto de subsistemas e acompanhante (Lei 8.080, arts. 19-A a 19-J) que a banca transforma em item.","palavraCritica":"profissional de saúde"},"comentario":{"resolucao":"ERRADO. Nessas situações a lei não suprime o direito: limita-o, admitindo apenas acompanhante que seja PROFISSIONAL DE SAÚDE. A mulher continua acompanhada durante o procedimento.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Centro cirúrgico/UTI: acompanhante profissional de saúde.","erroComum":"Achar que o direito some.","comoBancaPensa":"Supressão inventada."}},"SUS-673":{"cognitivo":{"motivo":"Treinar atribuições comuns — sistema de informação — ponto de competências das três esferas (Lei 8.080, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"atribuição comum"},"comentario":{"resolucao":"CERTO. Estão no art. 15 (incisos IV e VI), que lista as atribuições comuns. O que vem 'em todo o território nacional' costuma ser da direção nacional (art. 16).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Art. 15 = comum; art. 16 = nacional; art. 17 = estadual; art. 18 = municipal.","erroComum":"Atribuir só à União.","comoBancaPensa":"Leitura do art. 15."}},"SUS-674":{"cognitivo":{"motivo":"Treinar assistência toxicológica — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"intoxicações agudas"},"comentario":{"resolucao":"ERRADO. A assistência toxicológica abrange as ações e serviços de PREVENÇÃO, DIAGNÓSTICO e TRATAMENTO das intoxicações agudas decorrentes da exposição a substâncias químicas, toxinas de animais peçonhentos e plantas tóxicas — não só o tratamento hospitalar de intoxicações medicamentosas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Toxicologia: prevenção + diagnóstico + tratamento; químicos, peçonhentos e plantas.","erroComum":"Restringir o alcance.","comoBancaPensa":"Restrição indevida."}},"SUS-675":{"cognitivo":{"motivo":"Treinar divulgação dos estoques — alcance — ponto de disposições gerais, objetivos e campo de atuação (Lei 8.080, arts. 2º a 6º) que a banca transforma em item.","palavraCritica":"farmácias públicas sob sua gestão"},"comentario":{"resolucao":"CERTO. É o § 4º do art. 6º. A regra busca transparência: o usuário consulta onde há o medicamento antes de se deslocar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Estoques: internet, quinzenal, cidadão comum.","erroComum":"Trocar a periodicidade.","comoBancaPensa":"Lei recente, cobrada em 2025."}},"SUS-676":{"cognitivo":{"motivo":"Treinar cONASS e CONASEMS — natureza — ponto de organização, direção e gestão (Lei 8.080, arts. 9º a 14-B) que a banca transforma em item.","palavraCritica":"entidades representativas"},"comentario":{"resolucao":"ERRADO. São entidades representativas dos entes estaduais e municipais, reconhecidas pela lei (art. 14-B) como de utilidade pública e relevante função social, que tratam de matérias de saúde e recebem recursos do FNS. Não são órgãos do Ministério nem executam políticas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"CONASS/CONASEMS representam gestores; não são órgãos do MS.","erroComum":"Confundir representação com estrutura administrativa.","comoBancaPensa":"Natureza jurídica trocada."}},"SUS-677":{"cognitivo":{"motivo":"Treinar capital estrangeiro — serviços de empresas — ponto de serviços privados e participação complementar (Lei 8.080, arts. 20 a 26) que a banca transforma em item.","palavraCritica":"sem ônus para a seguridade"},"comentario":{"resolucao":"ERRADO. O art. 23, III, permite expressamente a participação direta ou indireta, inclusive controle, de capital estrangeiro nesses serviços mantidos por empresas, sem finalidade lucrativa, para seus empregados e dependentes, sem qualquer ônus para a seguridade social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Lei nº 8.080/1990 (Lei Orgânica da Saúde). Base: Estratégia, Legislação SUS, Aula 06.","macete":"Art. 23: doações internacionais, hospitais e clínicas, serviços de empresas para empregados, demais casos da lei.","erroComum":"Achar que a vedação do capital estrangeiro é geral.","comoBancaPensa":"Hipótese permitida tratada como vedada."}},"SUS-678":{"cognitivo":{"motivo":"Treinar lei da participação da comunidade — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"Lei 8.142/1990"},"comentario":{"resolucao":"C. A participação da comunidade na gestão do SUS está na Lei 8.142, de 28 de dezembro de 1990. A Lei 9.656/1998 trata dos planos de saúde; a 9.961/2000 cria a ANS; a 9.782/1999 cria a Anvisa; a 10.205/2001 regula sangue e hemoderivados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-679":{"cognitivo":{"motivo":"Treinar lei da participação da comunidade — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"Lei 8.142 e Resolução 453"},"comentario":{"resolucao":"ERRADO. ANS (Lei 9.961/2000) e Anvisa (Lei 9.782/1999) são agências reguladoras; nada dispõem sobre conselhos de saúde. A composição dos conselhos vem da Lei 8.142 (paridade) e da Resolução CNS 453/2012.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-680":{"cognitivo":{"motivo":"Treinar lei 8.142 — II e III — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"plano de saúde e consórcio"},"comentario":{"resolucao":"B (II e III). O plano de saúde é requisito para os repasses (art. 4º, III) e os municípios podem formar consórcio (art. 3º, § 3º). I descreve a CONFERÊNCIA (avaliar a situação de saúde e propor diretrizes), não o conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-681":{"cognitivo":{"motivo":"Treinar cONASEMS — representação — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"Conselho Nacional de Saúde"},"comentario":{"resolucao":"D. CONASS e CONASEMS têm representação no Conselho Nacional de Saúde (art. 1º, § 3º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-682":{"cognitivo":{"motivo":"Treinar alocação dos recursos do FNS — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"custeio, capital, investimentos, cobertura"},"comentario":{"resolucao":"A. O art. 2º aloca os recursos do FNS como: despesas de custeio e de capital do Ministério da Saúde, seus órgãos e entidades, da administração direta e indireta; investimentos previstos em lei orçamentária, de iniciativa do Poder Legislativo e aprovados pelo Congresso; investimentos do Plano Quinquenal do Ministério; e cobertura das ações e serviços dos municípios, estados e DF. As demais trocam o poder (Judiciário), suprimem a administração indireta ou mudam a esfera.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-683":{"cognitivo":{"motivo":"Treinar lei 8.142 — III e IV — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"seis anos e transitório são erros"},"comentario":{"resolucao":"D (III e IV). I erra a periodicidade (quatro anos, não seis) e o convocante (Poder Executivo, não Legislativo). II erra a natureza do conselho: é PERMANENTE, não transitório.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-684":{"cognitivo":{"motivo":"Treinar percentual aos municípios — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"no mínimo 70%"},"comentario":{"resolucao":"D. Pelo art. 3º, § 2º, no mínimo 70% dos recursos destinados à cobertura das ações e serviços dos entes vão aos municípios; o restante, aos estados.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-685":{"cognitivo":{"motivo":"Treinar conferências — correta — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"avaliar e propor diretrizes"},"comentario":{"resolucao":"C. A conferência avalia a situação de saúde e propõe diretrizes para a política nos níveis correspondentes. Ela ocorre a cada QUATRO anos (A erra), é convocada pelo Poder Executivo de cada esfera ou, extraordinariamente, por ela ou pelo conselho (B erra), e reúne os vários segmentos sociais (D erra).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-686":{"cognitivo":{"motivo":"Treinar conselhos e controle social — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"controle social"},"comentario":{"resolucao":"D. Os conselhos de saúde concretizam o controle social (participação da comunidade), diretriz do art. 198, III, da Constituição.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-687":{"cognitivo":{"motivo":"Treinar composição do conselho — exceto — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"representantes do povo"},"comentario":{"resolucao":"D (exceto). Os quatro segmentos são governo, prestadores de serviço, profissionais de saúde e usuários; 'representantes do povo' não é segmento da lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-688":{"cognitivo":{"motivo":"Treinar instâncias colegiadas — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"conselho e conferência"},"comentario":{"resolucao":"A. Em cada esfera de governo, o SUS conta com duas instâncias colegiadas: a Conferência de Saúde e o Conselho de Saúde (art. 1º). Não se restringem a uma esfera.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-689":{"cognitivo":{"motivo":"Treinar conferência — como se reúne — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"a cada 4 anos"},"comentario":{"resolucao":"E. A conferência reúne-se a cada QUATRO anos, com a representação dos vários segmentos, para avaliar a situação de saúde e propor diretrizes. C e D descrevem o conselho; A e B erram a periodicidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-690":{"cognitivo":{"motivo":"Treinar conselho — como funciona — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"permanente e deliberativo"},"comentario":{"resolucao":"D. O conselho funciona em caráter permanente e deliberativo, como órgão colegiado dos quatro segmentos (art. 1º, § 2º). A periodicidade quadrienal (A) é da conferência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-691":{"cognitivo":{"motivo":"Treinar cONASS e CONASEMS no CNS — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"assento e voto"},"comentario":{"resolucao":"A. CONASS e CONASEMS têm representação no Conselho Nacional de Saúde, com assento e voto, integrando os gestores estaduais e municipais às deliberações nacionais. A lei não limita sua participação a funções consultivas ou temas administrativos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-692":{"cognitivo":{"motivo":"Treinar cONASS e CONASEMS no CNS — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"representação no CNS"},"comentario":{"resolucao":"CERTO. O § 3º do art. 1º trata da representação no CONSELHO Nacional de Saúde. As conferências reúnem a representação dos vários segmentos sociais, sem regra legal específica para essas entidades.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-693":{"cognitivo":{"motivo":"Treinar frequência da conferência — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"4 anos"},"comentario":{"resolucao":"D. A cada quatro anos (art. 1º, § 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-694":{"cognitivo":{"motivo":"Treinar lei da participação — número — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"8.142/90"},"comentario":{"resolucao":"D. Lei 8.142/1990. A 8.080/90 é a Lei Orgânica da Saúde; a 8.069/90, o ECA; a 8.689/93 extinguiu o INAMPS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-695":{"cognitivo":{"motivo":"Treinar instrumento legal da participação — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"8.142/90"},"comentario":{"resolucao":"B. Lei 8.142/1990. Resoluções do CNS (como a 333/2003, substituída pela 453/2012) detalham os conselhos, mas não são o instrumento legal que dispõe sobre a participação.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-696":{"cognitivo":{"motivo":"Treinar conferência — 4 anos, propor diretrizes — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"propor diretrizes"},"comentario":{"resolucao":"C. A conferência se reúne a cada quatro anos para avaliar a situação de saúde e propor diretrizes. Controlar a execução da política é função do conselho; a representação dos usuários é PARITÁRIA (não proporcional). (O enunciado traz '8124' por erro de digitação: trata-se da Lei 8.142.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-697":{"cognitivo":{"motivo":"Treinar lei 8.142 — correta — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"duas instâncias colegiadas"},"comentario":{"resolucao":"D. Art. 1º: duas instâncias colegiadas em cada esfera, sem prejuízo das funções do Legislativo. As demais erram a periodicidade (3 e 10 anos), negam a representação de CONASS/CONASEMS ou deformam a definição do conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-698":{"cognitivo":{"motivo":"Treinar conferência — objetivo — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"avaliar e propor diretrizes"},"comentario":{"resolucao":"E. A conferência avalia a situação de saúde e propõe diretrizes. A e B descrevem o conselho; ela não se reúne a cada cinco anos (C) nem é convocada pelo Judiciário (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-699":{"cognitivo":{"motivo":"Treinar conselho — correta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"formulação de estratégias e controle"},"comentario":{"resolucao":"C. O conselho atua na formulação de estratégias e no controle da execução da política de saúde, inclusive nos aspectos econômicos e financeiros. A e B trocam conselho e conferência; a paridade é dos USUÁRIOS, não dos prestadores (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-700":{"cognitivo":{"motivo":"Treinar lei 8.142 — investimentos do Plano Quinquenal — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"Plano Quinquenal"},"comentario":{"resolucao":"E. Art. 2º, III: os recursos do FNS são alocados também como investimentos previstos no Plano Quinquenal do Ministério da Saúde. As demais inventam exclusões e exigências, e a conferência é quadrienal (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-701":{"cognitivo":{"motivo":"Treinar lei 8.142 — investimentos do Plano Quinquenal — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"Plano Quinquenal"},"comentario":{"resolucao":"CERTO. É o inciso III do art. 2º — quinquenal, não plurianual ou quadrienal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-702":{"cognitivo":{"motivo":"Treinar disposição fundamental da Lei 8.142 — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"conselhos e conferências"},"comentario":{"resolucao":"A. A Lei 8.142 institui conselhos e conferências como mecanismos de participação da comunidade e regula as transferências intergovernamentais. Ela não trata da indústria farmacêutica, da direção do SUS (Lei 8.080, art. 9º) nem de inscrição profissional.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-703":{"cognitivo":{"motivo":"Treinar alocação do FNS — I a IV — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"educação não é do FNS"},"comentario":{"resolucao":"D (I, II, III e IV). Os quatro primeiros itens reproduzem os incisos do art. 2º. O V é invenção: custeio de ações do Ministério da EDUCAÇÃO não é forma de alocação do FNS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-704":{"cognitivo":{"motivo":"Treinar conselho — permanente — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"permanente, não temporário"},"comentario":{"resolucao":"ERRADO. O conselho de saúde é órgão colegiado de caráter PERMANENTE e deliberativo (art. 1º, § 2º). E a paridade é entre usuários e o conjunto dos demais segmentos, não entre os quatro segmentos igualmente.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conselho: permanente, deliberativo, controle social (não executa nem se subordina).","erroComum":"Atribuir ao conselho gestão, execução ou subordinação.","comoBancaPensa":"Item real CEBRASPE (PO-AL 2023)."}},"SUS-705":{"cognitivo":{"motivo":"Treinar conselho — não executa — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"formulação e controle"},"comentario":{"resolucao":"ERRADO. Ao conselho cabe atuar na FORMULAÇÃO de estratégias e no CONTROLE da execução da política de saúde (art. 1º, § 2º). A execução das ações e serviços e a gestão financeira são do gestor; o conselho fiscaliza, inclusive os aspectos econômicos e financeiros.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conselho: permanente, deliberativo, controle social (não executa nem se subordina).","erroComum":"Atribuir ao conselho gestão, execução ou subordinação.","comoBancaPensa":"Item real CEBRASPE (PO-AL 2023)."}},"SUS-706":{"cognitivo":{"motivo":"Treinar conselho — autonomia — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"não há subordinação"},"comentario":{"resolucao":"ERRADO. O conselho integra a estrutura do Ministério e das secretarias, mas tem AUTONOMIA — não é subordinado direto do gestor. Subordinação, aliás, contradiz a própria ideia de 'garantir autonomia' que o item invoca.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conselho: permanente, deliberativo, controle social (não executa nem se subordina).","erroComum":"Atribuir ao conselho gestão, execução ou subordinação.","comoBancaPensa":"Item real CEBRASPE (PO-AL 2023)."}},"SUS-707":{"cognitivo":{"motivo":"Treinar conferência — convocação e finalidade — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"convocada pelo Executivo; avaliar e propor"},"comentario":{"resolucao":"ERRADO. A conferência é convocada pelo Poder Executivo de cada esfera (não só pelo Ministério) ou, extraordinariamente, por ela ou pelo conselho; e sua finalidade é avaliar a situação de saúde e propor diretrizes — não analisar a gestão financeira, que é controle exercido pelo conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conselho: permanente, deliberativo, controle social (não executa nem se subordina).","erroComum":"Atribuir ao conselho gestão, execução ou subordinação.","comoBancaPensa":"Item real CEBRASPE (PO-AL 2023)."}},"SUS-708":{"cognitivo":{"motivo":"Treinar lei 8.142 — exceção (peso superior) — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paridade, não peso superior"},"comentario":{"resolucao":"B (exceção). A representação dos usuários é PARITÁRIA em relação ao conjunto dos demais segmentos — não tem 'peso superior'. As demais reproduzem a lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-709":{"cognitivo":{"motivo":"Treinar lei 8.142 — paridade (correta) — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paritária"},"comentario":{"resolucao":"A. Art. 1º, § 4º. Erros: a conferência reúne os vários segmentos, não só gestores (B); os requisitos de repasse estão no art. 4º e o plano não é 'elaborado pelos usuários' (C); o conselho inclui os USUÁRIOS (D); o regimento é aprovado pelo conselho, não só pelos usuários (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-710":{"cognitivo":{"motivo":"Treinar legislação das conferências — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"Lei 8.142 — participação da comunidade"},"comentario":{"resolucao":"D. A Lei 8.142, de 28/12/1990, dispõe sobre a participação da comunidade na gestão do SUS. A e B trocam as ementas das Leis 8.080 e 8.142; a 8.213/1991 trata dos benefícios da previdência; o Decreto 3.048/1999 é o Regulamento da Previdência Social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-711":{"cognitivo":{"motivo":"Treinar controle social — correta — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"transparência e enfrentamento de iniquidades"},"comentario":{"resolucao":"E. A participação popular confere à gestão transparência, compromisso com as demandas sociais e ampliação das ações para enfrentar iniquidades. Erros: o controle social se relaciona à DEScentralização (A); a gestão participativa é da sociedade, não dos três poderes (B); as instâncias colegiadas da lei são conselhos e conferências (C); emenda parlamentar não é condição legal de repasse (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-712":{"cognitivo":{"motivo":"Treinar regra de composição — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paritária"},"comentario":{"resolucao":"E. A Lei 8.142 exige representação PARITÁRIA dos usuários em relação ao conjunto dos demais segmentos. Percentuais diferentes, exclusão do governo ou 100% de usuários contrariam a lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-713":{"cognitivo":{"motivo":"Treinar recursos aos entes — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"pelo menos 70% aos municípios"},"comentario":{"resolucao":"E. Art. 3º, § 2º. Erros: o consórcio não impede o uso dos recursos — permite remanejá-los (A, D); sem fundo, conselho ou relatório, os recursos são administrados pelo ESTADO (no caso de município) ou pela União (no caso de estado), conforme o parágrafo único do art. 4º (B, C).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-714":{"cognitivo":{"motivo":"Treinar recursos aos entes — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"administrados pelo estado"},"comentario":{"resolucao":"CERTO. É o parágrafo único do art. 4º: o não atendimento implica que os recursos sejam administrados, respectivamente, pelos estados (para os municípios) ou pela União (para os estados).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-715":{"cognitivo":{"motivo":"Treinar instância que controla a execução — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"Conselho de Saúde"},"comentario":{"resolucao":"C. É o Conselho de Saúde que, em caráter permanente e deliberativo, atua na formulação de estratégias e no controle da execução da política, inclusive nos aspectos econômicos e financeiros. O Conselho NACIONAL é um dos conselhos (o da esfera federal), não a instância genérica descrita.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-716":{"cognitivo":{"motivo":"Treinar instâncias deliberativas — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"conferência e conselho"},"comentario":{"resolucao":"A. Conferência de Saúde e Conselho de Saúde. CIB e CIT são foros de pactuação entre gestores; comissões intersetoriais são da Lei 8.080; o Legislativo atua sem prejuízo das instâncias.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-717":{"cognitivo":{"motivo":"Treinar conselho — alternativa do gabarito — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"composição do conselho"},"comentario":{"resolucao":"B. O conselho é órgão colegiado dos quatro segmentos: governo, prestadores de serviço, profissionais de saúde e usuários (art. 1º, § 2º). A descreve a CONFERÊNCIA; a lei não prevê eleições quadrienais (C); e a convocação pelo Executivo ou pelo conselho é regra da conferência, não das reuniões do conselho (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-718":{"cognitivo":{"motivo":"Treinar v/F — paridade, consórcio, Fiocruz — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"F, V, F"},"comentario":{"resolucao":"C (F, V, F). A paridade dos usuários É prevista (1ª F); o consórcio com remanejamento de recursos está no art. 3º, § 3º (2ª V); CONASS e CONASEMS têm representação no Conselho Nacional de Saúde, não na Fiocruz (3ª F).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-719":{"cognitivo":{"motivo":"Treinar v/F — paridade, consórcio, Fiocruz — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"remanejando entre si"},"comentario":{"resolucao":"CERTO. É o § 3º do art. 3º. O remanejamento entre consorciados é expressamente autorizado.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-720":{"cognitivo":{"motivo":"Treinar administração dos recursos federais — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"FNS"},"comentario":{"resolucao":"B. Na esfera federal, os recursos são administrados pelo Ministério da Saúde por meio do Fundo Nacional de Saúde (FNS). FES e FMS são os fundos estadual e municipal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-721":{"cognitivo":{"motivo":"Treinar instância — controle da execução — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"Conselho de Saúde"},"comentario":{"resolucao":"A. O dispositivo descreve o Conselho de Saúde (art. 1º, § 2º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-722":{"cognitivo":{"motivo":"Treinar cONASS e CONASEMS — correta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"representação no CNS"},"comentario":{"resolucao":"A. CONASS e CONASEMS têm representação no Conselho Nacional de Saúde. Erros: a representação é PARITÁRIA (B); a conferência é quadrienal (C); o FNS PODE alocar investimentos previstos em lei orçamentária e no Plano Quinquenal (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-723":{"cognitivo":{"motivo":"Treinar plano Quinquenal — correta — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"investimentos"},"comentario":{"resolucao":"C. Os recursos do FNS podem ser alocados como investimentos do Plano Quinquenal. Erros: conferência a cada quatro anos (A); conselho com os quatro segmentos (B); o regimento é aprovado pelo respectivo conselho (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-724":{"cognitivo":{"motivo":"Treinar lei 8.142 — regimento próprio — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"aprovadas pelo conselho"},"comentario":{"resolucao":"B. Art. 1º, § 5º. Erros: a iniciativa dos investimentos em lei orçamentária é do LEGISLATIVO (A); o prazo do PCCS é de DOIS anos (C); as instâncias colegiadas são conselho e CONFERÊNCIA, e o FNS é fundo, não instância (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-725":{"cognitivo":{"motivo":"Treinar lei 8.142 — regimento próprio — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"dois anos"},"comentario":{"resolucao":"ERRADO. O inciso VI do art. 4º prevê prazo de DOIS anos para a implantação do PCCS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-726":{"cognitivo":{"motivo":"Treinar paridade — correta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paritária"},"comentario":{"resolucao":"B. Paridade dos usuários (art. 1º, § 4º). As demais deformam o regimento, os investimentos ou proíbem o consórcio, que é permitido.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-727":{"cognitivo":{"motivo":"Treinar paridade — correta (2) — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paritária"},"comentario":{"resolucao":"A. Paridade dos usuários. Erros: conferência quadrienal (B); o FNS pode alocar investimentos (C); os municípios podem formar consórcio (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-728":{"cognitivo":{"motivo":"Treinar conselhos permanentes × conferências periódicas — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"conselhos são permanentes"},"comentario":{"resolucao":"B. Os conselhos são instâncias permanentes, em atividade contínua. As demais trocam as instâncias: conselho não é evento periódico (D), e conferência não é órgão permanente que fiscaliza a aplicação de recursos (A, C).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-729":{"cognitivo":{"motivo":"Treinar lei 8.142 — incorreta — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"conferências não são instituições permanentes"},"comentario":{"resolucao":"C (incorreta). A lei não trata as conferências como instituições deliberativas permanentes: elas são instâncias periódicas que avaliam a situação de saúde e PROPÕEM diretrizes; o caráter deliberativo e permanente é do conselho. As demais descrevem corretamente o objeto e a finalidade da lei.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-730":{"cognitivo":{"motivo":"Treinar convocação extraordinária — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"Conselho de Saúde"},"comentario":{"resolucao":"C. A conferência é convocada pelo Poder Executivo ou, extraordinariamente, por ela própria ou pelo Conselho de Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-731":{"cognitivo":{"motivo":"Treinar sigla CONASS — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"Conselho Nacional de Secretários de Saúde"},"comentario":{"resolucao":"B. CONASS = Conselho Nacional de Secretários de Saúde (estaduais); CONASEMS = Conselho Nacional de Secretarias Municipais de Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-732":{"cognitivo":{"motivo":"Treinar lei 8.142 — III falso — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"provisório e sem usuários"},"comentario":{"resolucao":"C. Só o item III é falso: o conselho é PERMANENTE (não provisório) e inclui os USUÁRIOS. I e II reproduzem a ementa e o art. 1º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-733":{"cognitivo":{"motivo":"Treinar lei 8.142 — I e III — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"conselho não é temporário"},"comentario":{"resolucao":"D (I e III). II erra duas vezes: omite os usuários e diz que o conselho é temporário (ele é permanente).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-734":{"cognitivo":{"motivo":"Treinar instâncias colegiadas — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"conferência e conselho"},"comentario":{"resolucao":"B. Conferência e Conselho de Saúde (art. 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-735":{"cognitivo":{"motivo":"Treinar periodicidade — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"4 anos"},"comentario":{"resolucao":"B. A cada quatro anos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-736":{"cognitivo":{"motivo":"Treinar reunião quadrienal dos segmentos — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"Conferência de Saúde"},"comentario":{"resolucao":"D. A reunião periódica dos vários segmentos para avaliar a situação de saúde e propor diretrizes nos níveis municipal, estadual e federal é a Conferência de Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-737":{"cognitivo":{"motivo":"Treinar como se dá a participação popular — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"conferências e conselhos"},"comentario":{"resolucao":"C. Pelas Conferências e pelos Conselhos de Saúde. Comissões intergestores reúnem gestores, não a população.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-738":{"cognitivo":{"motivo":"Treinar ementa da Lei 8.142 — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"transferências intergovernamentais"},"comentario":{"resolucao":"B. A Lei 8.142 dispõe sobre a participação da comunidade na gestão do SUS e sobre as transferências INTERGOVERNAMENTAIS de recursos financeiros na área da saúde. As demais trocam o segundo objeto (transferências 'estaduais', condutas éticas, medicamentos).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-739":{"cognitivo":{"motivo":"Treinar objeto da Lei 8.142 — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"gestão e transferências"},"comentario":{"resolucao":"E. Participação da comunidade na GESTÃO do SUS e transferências intergovernamentais. A troca 'gestão' por 'execução' (A) é o erro; B é a ementa da 8.080; D é a Lei 10.216/2001 (saúde mental).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-740":{"cognitivo":{"motivo":"Treinar requisitos — todos — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"fundo, plano, contrapartida, PCCS"},"comentario":{"resolucao":"E. Os quatro itens são requisitos do art. 4º (fundo, plano, contrapartida e comissão do PCCS com prazo de dois anos), ao lado do conselho paritário e dos relatórios de gestão.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-741":{"cognitivo":{"motivo":"Treinar instâncias colegiadas — I e II — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"CONASS e CONASEMS não são instâncias"},"comentario":{"resolucao":"A (I e II). As instâncias colegiadas são a Conferência e o Conselho de Saúde. CONASS e CONASEMS são entidades representativas dos gestores, com assento no CNS, não instâncias colegiadas do art. 1º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-742":{"cognitivo":{"motivo":"Treinar qual é a lei — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"Lei 8.142"},"comentario":{"resolucao":"E. É a Lei 8.142. Atenção: a data correta é 28 de dezembro de 1990 — a alternativa traz '19 de setembro', data da Lei 8.080; mesmo assim, é a única que indica a lei certa. As demais são o mandado de segurança (12.016/2009), a Lei Maria da Penha (11.340/2006), uma lei inexistente e a Lei 12.401/2011 (assistência terapêutica e incorporação de tecnologias).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-743":{"cognitivo":{"motivo":"Treinar alocação — I, II e IV — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"quinquenal, não plurianual"},"comentario":{"resolucao":"C (I, II e IV). III erra: os investimentos são os previstos no Plano QUINQUENAL do Ministério, não no Plano Plurianual.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-744":{"cognitivo":{"motivo":"Treinar alocação — I, II e IV — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"Plano Quinquenal do MS"},"comentario":{"resolucao":"ERRADO. O inciso III do art. 2º fala em investimentos previstos no Plano QUINQUENAL do Ministério da Saúde. O que é aprovado pelo Congresso são os investimentos em lei orçamentária, de iniciativa do Legislativo (inciso II).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-745":{"cognitivo":{"motivo":"Treinar composição do conselho — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"quatro segmentos"},"comentario":{"resolucao":"C. Governo, prestadores de serviço, profissionais de saúde e usuários (art. 1º, § 2º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-746":{"cognitivo":{"motivo":"Treinar objeto da lei — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"participação e transferências"},"comentario":{"resolucao":"C. Participação da comunidade na gestão do SUS e transferências intergovernamentais. A é a 8.080; B, a Lei 11.350/2006; D, os arts. 19-A a 19-H da 8.080; E, portaria da PNAB.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-747":{"cognitivo":{"motivo":"Treinar regimento próprio — correta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"aprovadas pelo respectivo conselho"},"comentario":{"resolucao":"B. Art. 1º, § 5º. Erros: a convocação extraordinária é pela própria conferência ou pelo CONSELHO, não pelo Legislativo (A); os MUNICÍPIOS formam consórcio (C); órgão colegiado dos quatro segmentos é o conselho, não a conferência (D); CONASS e CONASEMS têm representação no Conselho NACIONAL DE SAÚDE (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-748":{"cognitivo":{"motivo":"Treinar segundo objeto da lei — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"transferências intergovernamentais"},"comentario":{"resolucao":"E. Além da participação da comunidade, a Lei 8.142 dispõe sobre as transferências intergovernamentais de recursos financeiros na área da saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-749":{"cognitivo":{"motivo":"Treinar lei 8.142 — incorreta — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"composição do conselho"},"comentario":{"resolucao":"B (incorreta). Ao descrever o conselho, a alternativa omite os USUÁRIOS, segmento que detém metade das vagas (art. 1º, §§ 2º e 4º). As demais (conferência quadrienal, requisitos do art. 4º, regimento próprio) estão corretas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-750":{"cognitivo":{"motivo":"Treinar instância permanente e deliberativa — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"Conselhos de Saúde"},"comentario":{"resolucao":"C. Os Conselhos de Saúde são a instância colegiada permanente e deliberativa da sociedade organizada na administração do SUS. A CIB é foro de gestores.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-751":{"cognitivo":{"motivo":"Treinar paridade — correta (3) — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"paritária"},"comentario":{"resolucao":"A. Paridade dos usuários. Erros: o regimento próprio é das conferências e conselhos, não de 'auditorias' (B); a periodicidade quadrienal é da conferência (C); o controle da execução é do conselho (D).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-752":{"cognitivo":{"motivo":"Treinar requisito — contrapartida — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"contrapartida no orçamento"},"comentario":{"resolucao":"C. A contrapartida de recursos para a saúde no respectivo orçamento é requisito do art. 4º, V. A lei exige CONSELHO (não conferência) paritário, plano de saúde (sem 'assistência social') e comissão de ELABORAÇÃO do PCCS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-753":{"cognitivo":{"motivo":"Treinar alocação do FNS — I, III e IV — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"iniciativa do Legislativo"},"comentario":{"resolucao":"B (I, III e IV). II erra: os investimentos são os previstos em lei orçamentária, de iniciativa do Poder LEGISLATIVO e aprovados pelo Congresso — não de iniciativa do Executivo aprovados pelo conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-754":{"cognitivo":{"motivo":"Treinar função do conselho — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"controlar a execução"},"comentario":{"resolucao":"C. Controlar a execução das políticas de saúde. Avaliar a situação de saúde e propor diretrizes (A, E) é da conferência.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-755":{"cognitivo":{"motivo":"Treinar alocação do FNS — todos — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"quatro incisos"},"comentario":{"resolucao":"E. Os quatro itens reproduzem os incisos I a IV do art. 2º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-756":{"cognitivo":{"motivo":"Treinar lei 8.142 — I e II — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"conferência reúne vários segmentos"},"comentario":{"resolucao":"D (I e II). III erra: a conferência reúne a representação dos VÁRIOS segmentos sociais, não 'somente dos profissionais de saúde'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-757":{"cognitivo":{"motivo":"Treinar providências da Lei 8.142 — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"permanente e deliberativo"},"comentario":{"resolucao":"A. Os conselhos têm caráter permanente e deliberativo. A representação majoritária é dos USUÁRIOS (paridade), não dos trabalhadores (B); a conferência é quadrienal (C); o regimento é próprio, aprovado pelo conselho (D); CONASS/CONASEMS não têm 'prioridade' sobre os usuários (E). (Gabarito conferido pela lei: a tabela do material não o traz.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-758":{"cognitivo":{"motivo":"Treinar significado da paridade — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"igual à soma dos demais"},"comentario":{"resolucao":"D. Paridade significa que a soma dos representantes dos usuários é IGUAL à soma dos representantes dos demais segmentos — 50% do total.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-759":{"cognitivo":{"motivo":"Treinar significado da paridade — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"metade das vagas"},"comentario":{"resolucao":"CERTO. Usuários = 50%; os outros 50% somam governo, prestadores e trabalhadores (na Resolução 453: 25% trabalhadores e 25% governo + prestadores).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-760":{"cognitivo":{"motivo":"Treinar critério para receber recursos — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"Plano de Saúde"},"comentario":{"resolucao":"A. O plano de saúde é requisito do art. 4º, III. Relatório de auditoria, indicadores, programação anual e PDR não figuram no artigo (a lei exige relatórios de GESTÃO).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-761":{"cognitivo":{"motivo":"Treinar critério para receber recursos — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"relatórios de gestão"},"comentario":{"resolucao":"ERRADO. O art. 4º exige fundo, conselho paritário, plano de saúde, RELATÓRIOS DE GESTÃO, contrapartida e comissão do PCCS. Auditoria externa e PDR não estão entre os requisitos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-762":{"cognitivo":{"motivo":"Treinar alocação do FNS — todos (2) — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"quatro incisos"},"comentario":{"resolucao":"E. Os quatro itens são os incisos do art. 2º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-763":{"cognitivo":{"motivo":"Treinar controle social na Lei 8.142 — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"duas instâncias formais"},"comentario":{"resolucao":"A. A Lei 8.142 detalha pela primeira vez o exercício do controle social, por meio de duas instâncias formais, que também são espaços de luta: o conselho e a conferência de saúde. Erros: o conselho é permanente (B); a composição é 50% usuários (C); a função não se resume a fiscalizar (D); a participação não se dá em detrimento de gestores e trabalhadores (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-764":{"cognitivo":{"motivo":"Treinar conselho × conferência — I — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"II e III trocam as instâncias"},"comentario":{"resolucao":"A (I, apenas). I está correta. II descreve a CONFERÊNCIA (avaliar e propor diretrizes) e III descreve o CONSELHO (formulação de estratégias e controle da execução) — os itens trocaram as instâncias. (Gabarito conferido pela lei: a tabela do material não o traz.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-765":{"cognitivo":{"motivo":"Treinar conselhos e conferências — em cada esfera — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"em cada esfera de governo"},"comentario":{"resolucao":"D. Conselhos e conferências devem existir em CADA esfera de governo (art. 1º). Não são temporários nem facultativos; os conselhos são deliberativos em todas as esferas, e a conferência é quadrienal. (A tabela do material indica B, mas 'facultativos' contraria a lei e o próprio comentário.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-766":{"cognitivo":{"motivo":"Treinar conselhos e conferências — em cada esfera — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"em cada esfera"},"comentario":{"resolucao":"CERTO. O art. 1º prevê as duas instâncias 'em cada esfera de governo', e o § 2º define o conselho como permanente e deliberativo sem distinguir esferas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência: 4 em 4 anos, propõe. Conselho: permanente, deliberativo, paritário, controla.","erroComum":"Trocar as características da conferência e do conselho.","comoBancaPensa":"Literalidade da Lei 8.142."}},"SUS-767":{"cognitivo":{"motivo":"Treinar origem da Lei 8.142 — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"vetos da Lei 8.080"},"comentario":{"resolucao":"CERTO. Os vetos presidenciais à Lei 8.080 atingiram justamente a participação da comunidade e os repasses; a mobilização do movimento sanitário levou à Lei 8.142, em dezembro de 1990.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"8.080 (setembro) com vetos → 8.142 (dezembro) recompõe.","erroComum":"Achar que as leis são independentes.","comoBancaPensa":"Contexto histórico."}},"SUS-768":{"cognitivo":{"motivo":"Treinar conselho paritário — Decreto 99.438 — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"Decreto 99.438/1990"},"comentario":{"resolucao":"CERTO. O inciso II do art. 4º remete ao Decreto 99.438/1990, que reorganizou o Conselho Nacional de Saúde; hoje a composição é detalhada pela Resolução CNS 453/2012.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Requisito II: conselho paritário (Decreto 99.438).","erroComum":"Esquecer a paridade do requisito.","comoBancaPensa":"Remissão normativa."}},"SUS-769":{"cognitivo":{"motivo":"Treinar ministério da Saúde e condições de aplicação — ponto de lei 8.142 — objeto e participação da comunidade que a banca transforma em item.","palavraCritica":"Ministério da Saúde"},"comentario":{"resolucao":"CERTO. É o art. 5º: o Ministério da Saúde está autorizado a estabelecer condições para a aplicação da lei, mediante portaria — base das Normas Operacionais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Art. 5º: MS regulamenta por portaria.","erroComum":"Atribuir ao CNS ou ao Congresso.","comoBancaPensa":"Dispositivo final."}},"SUS-770":{"cognitivo":{"motivo":"Treinar repasses — convênio × automático — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"regular e automático"},"comentario":{"resolucao":"ERRADO. O art. 3º determina o repasse de forma REGULAR e AUTOMÁTICA, fundo a fundo, segundo os critérios do art. 35 da Lei 8.080. O convênio é instrumento de outras transferências, não da cobertura assistencial.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Cobertura: fundo a fundo, regular e automático.","erroComum":"Exigir convênio caso a caso.","comoBancaPensa":"Mecanismo trocado."}},"SUS-771":{"cognitivo":{"motivo":"Treinar conselho × Legislativo — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"sem prejuízo das funções do Legislativo"},"comentario":{"resolucao":"ERRADO. As instâncias colegiadas funcionam 'sem prejuízo das funções do Poder Legislativo' (art. 1º). Controle social e controle externo convivem: o conselho fiscaliza, inclusive aspectos financeiros, e o Legislativo, com o tribunal de contas, também.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Controle social soma, não substitui.","erroComum":"Achar que o conselho substitui o Legislativo.","comoBancaPensa":"Ressalva suprimida."}},"SUS-772":{"cognitivo":{"motivo":"Treinar convocação ordinária em cada esfera — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"Poder Executivo de cada esfera"},"comentario":{"resolucao":"ERRADO. A conferência é convocada pelo Poder Executivo de cada esfera (art. 1º, § 1º): a municipal, pelo prefeito/secretaria; a estadual, pelo governo do estado; a nacional, pelo Ministério. Extraordinariamente, por ela própria ou pelo conselho.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Cada esfera convoca a sua conferência.","erroComum":"Centralizar no Ministério.","comoBancaPensa":"Troca de sujeito."}},"SUS-773":{"cognitivo":{"motivo":"Treinar seis requisitos do art. 4º — ponto de fundo Nacional de Saúde e repasses (Lei 8.142, arts. 2º a 4º) que a banca transforma em item.","palavraCritica":"todos os seis"},"comentario":{"resolucao":"CERTO. São os seis incisos do art. 4º, cumulativos. Faltando algum, os recursos passam a ser administrados pelo estado (no caso dos municípios) ou pela União (no caso dos estados).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Fundo, conselho, plano, relatório, contrapartida, PCCS — todos.","erroComum":"Achar que basta um ou dois.","comoBancaPensa":"Requisitos cumulativos."}},"SUS-774":{"cognitivo":{"motivo":"Treinar homologação das decisões do conselho — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"chefe do poder legalmente constituído"},"comentario":{"resolucao":"CERTO. É a parte final do § 2º do art. 1º. A Resolução CNS 453/2012 fixa prazo de 30 dias para a homologação e, em caso de silêncio do gestor, admite recurso à Justiça e ao Ministério Público.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conselho decide; chefe do Executivo homologa.","erroComum":"Achar que o conselho dispensa homologação.","comoBancaPensa":"Literalidade do § 2º."}},"SUS-775":{"cognitivo":{"motivo":"Treinar conferência nas três esferas — ponto de conferência de Saúde (Lei 8.142, art. 1º, § 1º) que a banca transforma em item.","palavraCritica":"nos níveis correspondentes"},"comentario":{"resolucao":"CERTO. O art. 1º prevê as instâncias colegiadas em cada esfera de governo, e o § 1º fala em diretrizes 'nos níveis correspondentes' — municipal, estadual e nacional.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Conferência municipal, estadual e nacional.","erroComum":"Achar que só existe a nacional.","comoBancaPensa":"Alcance das três esferas."}},"SUS-776":{"cognitivo":{"motivo":"Treinar conselho — quem preside — ponto de conselho de Saúde (Lei 8.142, art. 1º, §§ 2º a 5º) que a banca transforma em item.","palavraCritica":"eleito entre os membros"},"comentario":{"resolucao":"ERRADO. A Lei 8.142 não define a presidência; a Resolução CNS 453/2012 determina que o presidente seja ELEITO entre os membros do conselho, em reunião plenária. Não há presidência nata do gestor.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, itens 2 e 5 — controle social e Lei nº 8.142/1990. Base: Estratégia, Legislação SUS, Aula 07.","macete":"Presidente eleito em plenária (Res. 453).","erroComum":"Inventar presidência nata.","comoBancaPensa":"Exigência inexistente."}},"SUS-777":{"cognitivo":{"motivo":"Treinar decreto 7.508 — todos os itens — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"todos corretos"},"comentario":{"resolucao":"D. Os três itens reproduzem o decreto, inclusive a garantia de acesso e as regras aplicáveis também às unidades privadas que participam do SUS de forma complementar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-778":{"cognitivo":{"motivo":"Treinar região de Saúde — conteúdo mínimo — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"cinco grupos de ações"},"comentario":{"resolucao":"D (I a V). Para ser instituída, a Região de Saúde deve conter, no mínimo, ações e serviços de atenção primária, urgência e emergência, atenção psicossocial, atenção ambulatorial especializada e hospitalar e vigilância em saúde (art. 5º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-779":{"cognitivo":{"motivo":"Treinar região de Saúde — conteúdo mínimo — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"cinco requisitos"},"comentario":{"resolucao":"CERTO. São os cinco requisitos do art. 5º. Atenção odontológica, assistência farmacêutica e serviços especiais de acesso aberto não estão nessa lista mínima.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-780":{"cognitivo":{"motivo":"Treinar região de Saúde — conteúdo mínimo — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"psicossocial e vigilância obrigatórias"},"comentario":{"resolucao":"ERRADO. Atenção psicossocial e vigilância em saúde são obrigatórias (art. 5º), ao lado da atenção primária, da urgência e emergência e da atenção ambulatorial especializada e hospitalar. A assistência farmacêutica não está entre os cinco requisitos, e o decreto não condiciona nada ao porte.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-781":{"cognitivo":{"motivo":"Treinar regiões em áreas de fronteira — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"relações internacionais"},"comentario":{"resolucao":"A. A instituição de Regiões de Saúde em áreas de fronteira com outros países deve respeitar as normas que regem as RELAÇÕES INTERNACIONAIS (art. 4º, § 2º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-782":{"cognitivo":{"motivo":"Treinar definição do SUS no decreto (art. 3º) — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"regionalizada e hierarquizada"},"comentario":{"resolucao":"B. Art. 3º: o SUS é constituído pela conjugação das ações e serviços de promoção, proteção e recuperação da saúde executados pelos entes federativos, de forma direta ou indireta, mediante a participação complementar da iniciativa PRIVADA, sendo organizado de forma REGIONALIZADA e HIERARQUIZADA. (O material marca C — 'de forma geral e hierarquizada' —, o que contraria o texto do artigo.)","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-783":{"cognitivo":{"motivo":"Treinar definição do SUS no decreto (art. 3º) — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"regionalizada e hierarquizada"},"comentario":{"resolucao":"CERTO. É o art. 3º, que repete a lógica do art. 198 da Constituição e do art. 8º da Lei 8.080 — rede regionalizada e hierarquizada, com o privado em caráter complementar.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-784":{"cognitivo":{"motivo":"Treinar decreto 7.508 — correta — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"agrupamento de municípios"},"comentario":{"resolucao":"B. É a única coerente com o decreto, que define a Região de Saúde como espaço geográfico contínuo constituído por agrupamentos de municípios limítrofes, delimitado a partir de identidades culturais, econômicas e sociais e de redes de comunicação e infraestrutura de transportes compartilhados. Erros: o COAP é firmado entre os ENTES federativos, não pela União com prestadores (A); a assistência farmacêutica não se restringe à alta complexidade (C); o planejamento é obrigatório para os entes públicos (D); o acesso se ordena nas redes (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-785":{"cognitivo":{"motivo":"Treinar decreto 7.508 — correta — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"municípios limítrofes"},"comentario":{"resolucao":"CERTO. É a definição do art. 2º, I. A finalidade é integrar a organização, o planejamento e a execução de ações e serviços de saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-786":{"cognitivo":{"motivo":"Treinar rENAME — correta — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"medicamentos do SUS"},"comentario":{"resolucao":"C. A RENAME compreende a seleção e a padronização dos medicamentos indicados para o atendimento de doenças ou agravos no âmbito do SUS. Erros: há regiões interestaduais (A); o COAP não se limita à alta complexidade (B); o planejamento é integrado (D); a RAS inclui a atenção primária (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-787":{"cognitivo":{"motivo":"Treinar região de Saúde — lista mínima — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"inclui psicossocial e vigilância"},"comentario":{"resolucao":"B. A lista completa: atenção primária; urgência e emergência; atenção psicossocial; atenção ambulatorial especializada e hospitalar; e vigilância em saúde. As demais omitem um item ou cortam 'e hospitalar'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-788":{"cognitivo":{"motivo":"Treinar regiões de Saúde — I e II — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"uma ou várias regiões"},"comentario":{"resolucao":"B (I e II). As afirmativas III e IV deformam o decreto — a última, ao dizer que as Redes de Atenção estariam numa só Região 'jamais em várias delas', quando o art. 7º admite uma Região ou várias.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-789":{"cognitivo":{"motivo":"Treinar base da regionalização — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"articulação para o cuidado integral"},"comentario":{"resolucao":"C. A regionalização se funda na articulação entre serviços para assegurar o cuidado integral em um território, considerando necessidades e recursos. Proximidade geográfica isolada, limites político-administrativos rígidos, critério só populacional ou prioridades políticas não são a base.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-790":{"cognitivo":{"motivo":"Treinar requisitos — I, II e III — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"todos fazem parte"},"comentario":{"resolucao":"E. Atenção psicossocial, atenção ambulatorial especializada e hospitalar e urgência e emergência estão entre os requisitos mínimos do art. 5º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-791":{"cognitivo":{"motivo":"Treinar planejamento ascendente e integrado — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"do local ao federal"},"comentario":{"resolucao":"C. O planejamento é ascendente e integrado, do nível local até o federal, ouvidos os Conselhos de Saúde, compatibilizando-se as necessidades das políticas de saúde com a disponibilidade de recursos financeiros (art. 15).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-792":{"cognitivo":{"motivo":"Treinar planejamento ascendente e integrado — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"obrigatório para os entes públicos"},"comentario":{"resolucao":"CERTO. É o § 1º do art. 15. A banca inverte: 'obrigatório para os entes privados' (erro da Q13, C).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-793":{"cognitivo":{"motivo":"Treinar cOAP — disposições essenciais (exceto) — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"monitoramento permanente"},"comentario":{"resolucao":"E (não completa). O art. 36 fala em critérios de avaliação dos resultados e forma de monitoramento PERMANENTE, não 'pontual'. As responsabilidades assumidas no processo de regionalização são, sim, estabelecidas de forma individualizada (C).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-794":{"cognitivo":{"motivo":"Treinar cOAP — disposições essenciais (exceto) — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"monitoramento permanente"},"comentario":{"resolucao":"CERTO. Constam do art. 36, que lista ainda: necessidades de saúde locais e regionais, oferta de ações em âmbito regional e inter-regional, responsabilidades individualizadas, indicadores e metas, estratégias de melhoria e recursos financeiros de cada partícipe.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-795":{"cognitivo":{"motivo":"Treinar planejamento — correta — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"ascendente, ouvidos os conselhos"},"comentario":{"resolucao":"D. Art. 15. Erros: o Mapa da Saúde orienta o planejamento integrado dos ENTES federativos, não só dos municípios (B); o planejamento é obrigatório para os entes PÚBLICOS e indutor para a iniciativa privada (C); quem pactua as etapas e prazos do planejamento municipal é a COMISSÃO INTERGESTORES BIPARTITE, não a Tripartite (E; art. 19).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-796":{"cognitivo":{"motivo":"Treinar planejamento — correta — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"CIB, não CIT"},"comentario":{"resolucao":"ERRADO. O art. 19 atribui essa pactuação à Comissão Intergestores BIPARTITE (CIB), que reúne estado e municípios — o planejamento municipal se articula primeiro no âmbito estadual.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-797":{"cognitivo":{"motivo":"Treinar integralidade na RAS — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"regional e interestadual"},"comentario":{"resolucao":"B. Art. 20: a integralidade da assistência à saúde se inicia e se completa na Rede de Atenção à Saúde, mediante referenciamento do usuário na rede REGIONAL e INTERESTADUAL, conforme pactuado nas Comissões Intergestores.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-798":{"cognitivo":{"motivo":"Treinar portas de Entrada — I, II e III — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"acesso aberto, não restrito"},"comentario":{"resolucao":"B (I, II e III). São Portas de Entrada os serviços de atenção primária, de urgência e emergência, de atenção psicossocial e os especiais de acesso ABERTO (art. 9º). 'Acesso restrito' é a troca da banca.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-799":{"cognitivo":{"motivo":"Treinar portas de Entrada — I, II e III — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"quatro portas de entrada"},"comentario":{"resolucao":"CERTO. São as quatro portas do art. 9º. Compare com os cinco requisitos mínimos da Região (art. 5º), que incluem atenção ambulatorial especializada/hospitalar e vigilância, mas não os serviços especiais de acesso aberto.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-800":{"cognitivo":{"motivo":"Treinar portas de Entrada — I, II e III — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"referenciados pelas portas"},"comentario":{"resolucao":"ERRADO. Os serviços hospitalares e ambulatoriais especializados, entre outros de maior complexidade e densidade tecnológica, são REFERENCIADOS pelas Portas de Entrada (art. 10) — não são porta de entrada.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-801":{"cognitivo":{"motivo":"Treinar rENASES — incorreta — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"a cada dois anos"},"comentario":{"resolucao":"C (incorreta). O Ministério da Saúde consolida e publica as atualizações da RENASES a cada DOIS anos, não três. As demais reproduzem os arts. 21 a 24.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-802":{"cognitivo":{"motivo":"Treinar rENASES — incorreta — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"a cada dois anos"},"comentario":{"resolucao":"CERTO. Arts. 21 e 22 do decreto. RENASES e RENAME seguem a mesma periodicidade bienal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-803":{"cognitivo":{"motivo":"Treinar art. 5º — lista completa — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"lista completa"},"comentario":{"resolucao":"D. Só a D traz os cinco requisitos completos do art. 5º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-804":{"cognitivo":{"motivo":"Treinar relação de medicamentos — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"RENAME"},"comentario":{"resolucao":"E. O acesso à assistência farmacêutica pressupõe prescrição em conformidade com a RENAME e os protocolos clínicos e diretrizes terapêuticas, ou com a relação específica complementar estadual, distrital ou municipal de medicamentos (art. 28).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-805":{"cognitivo":{"motivo":"Treinar leis do SUS e Decreto 7.508 — V/F — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"V, F, V, V"},"comentario":{"resolucao":"B (V, F, V, V). Apenas a segunda afirmativa está errada; as demais descrevem corretamente as Leis 8.080 e 8.142 e o papel do Decreto 7.508 na regulação e articulação das redes regionais.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-806":{"cognitivo":{"motivo":"Treinar ordenação do acesso — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"atenção primária"},"comentario":{"resolucao":"B. O acesso universal e igualitário às ações e serviços de saúde é ordenado pela atenção PRIMÁRIA (art. 11).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-807":{"cognitivo":{"motivo":"Treinar lei 8.142 e Decreto 7.508 — correta — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"Mapa da Saúde e Região de Saúde"},"comentario":{"resolucao":"A. O decreto introduziu conceitos como Mapa da Saúde e Região de Saúde. Erros: conselhos são deliberativos e paritários (B); as RAS são pactuadas, não facultativas (C); a Lei 8.142 não distribui recursos 'entre União, estados e municípios' nesses termos (D); não há centralização (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-808":{"cognitivo":{"motivo":"Treinar acesso — C, E, C, C — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"gravidade do risco e critério cronológico"},"comentario":{"resolucao":"B (C, E, C, C). O acesso é fundado na avaliação da gravidade do risco individual e coletivo e no critério cronológico, observadas as especificidades das pessoas com proteção especial — e é ordenado pela atenção PRIMÁRIA, não pela psicossocial (art. 11).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-809":{"cognitivo":{"motivo":"Treinar acesso — C, E, C, C — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"risco e critério cronológico"},"comentario":{"resolucao":"CERTO. É o art. 11. Risco e ordem de chegada se combinam — gravidade primeiro, cronologia entre casos de mesmo risco.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-810":{"cognitivo":{"motivo":"Treinar acesso — C, E, C, C — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"gravidade do risco"},"comentario":{"resolucao":"ERRADO. O art. 11 combina a avaliação da GRAVIDADE DO RISCO individual e coletivo com o critério cronológico. Priorizar casos graves concretiza a equidade e não fere a igualdade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-811":{"cognitivo":{"motivo":"Treinar mapa da Saúde — lacunas — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"humanos; indicadores de saúde"},"comentario":{"resolucao":"E. Mapa da Saúde é a descrição geográfica da distribuição de recursos HUMANOS e de ações e serviços de saúde ofertados pelo SUS e pela iniciativa privada, considerando a capacidade instalada, os investimentos e o desempenho aferido a partir dos INDICADORES DE SAÚDE do sistema (art. 2º, V).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-812":{"cognitivo":{"motivo":"Treinar mapa da Saúde — lacunas — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"SUS e iniciativa privada"},"comentario":{"resolucao":"ERRADO. O Mapa inclui as ações e serviços ofertados pelo SUS E pela INICIATIVA PRIVADA (art. 2º, V), e o art. 16 manda considerar no planejamento os serviços privados, complementares ou não ao SUS, que deverão compor os Mapas regional, estadual e nacional.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-813":{"cognitivo":{"motivo":"Treinar quem dispõe sobre a RENASES — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"Ministério da Saúde"},"comentario":{"resolucao":"B. O Ministério da Saúde disporá sobre a RENASES em âmbito nacional, observadas as diretrizes pactuadas pela CIT (art. 23).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-814":{"cognitivo":{"motivo":"Treinar porta de Entrada — psicossocial — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"atenção psicossocial"},"comentario":{"resolucao":"A. Os serviços de atenção psicossocial são Portas de Entrada (art. 9º, III). Farmácias, comissões, conselhos e 'enfermagem psiquiátrica' não são.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-815":{"cognitivo":{"motivo":"Treinar portas de Entrada — I, II e III — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"todas"},"comentario":{"resolucao":"A (I, II e III). Atenção psicossocial, urgência e emergência e serviços especiais de acesso aberto são Portas de Entrada, ao lado da atenção primária (art. 9º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-816":{"cognitivo":{"motivo":"Treinar decreto 7.508 — Regiões de Saúde — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"espaços geográficos"},"comentario":{"resolucao":"D. O decreto define as Regiões de Saúde como espaços geográficos para a organização das ações e serviços. Ele não dá à União a gestão de fundos estaduais, não revoga planos de saúde e não admite atuação privada sem contrato.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-817":{"cognitivo":{"motivo":"Treinar art. 3º — lacunas — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"ações; recuperação; direta ou indireta"},"comentario":{"resolucao":"B. 'O SUS é constituído pela conjugação das AÇÕES e serviços de promoção, proteção e RECUPERAÇÃO da saúde executados pelos entes federativos, de forma DIRETA OU INDIRETA, mediante a participação complementar da iniciativa privada.'","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-818":{"cognitivo":{"motivo":"Treinar periodicidade da RENASES — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"a cada dois anos"},"comentario":{"resolucao":"A. A cada dois anos (art. 22).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-819":{"cognitivo":{"motivo":"Treinar definições — só II — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"Rede de Atenção à Saúde"},"comentario":{"resolucao":"B (só II). A definição correta é a da Rede de Atenção à Saúde: conjunto de ações e serviços de saúde articulados em níveis de complexidade crescente, com a finalidade de garantir a integralidade da assistência (art. 2º, VI). As demais trocam as definições do art. 2º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-820":{"cognitivo":{"motivo":"Treinar regiões — referência para transferências — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"transferências de recursos"},"comentario":{"resolucao":"D. As Regiões de Saúde são referência para as transferências de recursos entre os entes federativos (art. 6º). Erros: os entes PODEM criar novas Portas de Entrada, com justificativa técnica e pactuação (A); o cronograma das Regiões é pactuado nas Comissões Intergestores (B); os serviços especiais de acesso aberto atendem agravos ou situações laborais específicas (C); limites e população são definidos pelos entes federativos, não pelo Ministério (E).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-821":{"cognitivo":{"motivo":"Treinar regiões — referência para transferências — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"novas Portas de Entrada"},"comentario":{"resolucao":"CERTO. É o parágrafo único do art. 9º: a lista de portas não é fechada.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-822":{"cognitivo":{"motivo":"Treinar regiões — referência para transferências — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"entes federativos definem"},"comentario":{"resolucao":"ERRADO. Esses elementos são definidos pelos ENTES FEDERATIVOS (art. 7º, parágrafo único), e as Regiões são instituídas pelo Estado em articulação com os Municípios, respeitadas as diretrizes da CIT (art. 4º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-823":{"cognitivo":{"motivo":"Treinar região — apenas itens mínimos — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"ambulatorial/hospitalar e vigilância"},"comentario":{"resolucao":"E. Atenção ambulatorial especializada e hospitalar e vigilância em saúde estão entre os requisitos mínimos. Pronto-socorro, psiquiatria, psicopedagogia e 'vigilância em segurança' não são os termos do art. 5º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-824":{"cognitivo":{"motivo":"Treinar conceito de Portas de Entrada — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"atendimento inicial no SUS"},"comentario":{"resolucao":"C. Portas de Entrada são os serviços de atendimento inicial à saúde do usuário no SUS (art. 2º, III).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-825":{"cognitivo":{"motivo":"Treinar cOAP — exceto — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"investimentos não são exclusivos dos municípios"},"comentario":{"resolucao":"D (exceto). O art. 36 prevê 'investimentos na rede de serviços e as respectivas responsabilidades' — sem restringi-los aos municípios. As demais estão no artigo.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-826":{"cognitivo":{"motivo":"Treinar requisitos — II a V — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"item I deformado"},"comentario":{"resolucao":"A (II, III, IV e V). Os itens II a V reproduzem o art. 5º; o item I, na redação proposta, não corresponde ao requisito da atenção primária.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-827":{"cognitivo":{"motivo":"Treinar rENAME e FTN — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"Formulário Terapêutico Nacional"},"comentario":{"resolucao":"B. A RENAME é acompanhada do Formulário Terapêutico Nacional (FTN), que subsidiará a prescrição, a dispensação e o uso dos seus medicamentos (art. 26).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-828":{"cognitivo":{"motivo":"Treinar rENAME e FTN — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"FTN"},"comentario":{"resolucao":"CERTO. Arts. 25 e 26. RENAME e RENASES têm atualização bienal.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-829":{"cognitivo":{"motivo":"Treinar rENAME e FTN — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"FTN acompanha a RENAME"},"comentario":{"resolucao":"ERRADO. O FTN acompanha a RENAME (medicamentos) e subsidia prescrição, dispensação e uso. A RENASES é a relação de AÇÕES E SERVIÇOS, sem formulário terapêutico.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-830":{"cognitivo":{"motivo":"Treinar regiões — F, F, V — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"entes definem a população usuária"},"comentario":{"resolucao":"D (F, F, V). Apenas a terceira está correta: os entes federativos definem, entre outros elementos, a população usuária das ações e serviços (art. 7º, parágrafo único).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-831":{"cognitivo":{"motivo":"Treinar regiões — incorreta (fronteira) — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"relações internacionais"},"comentario":{"resolucao":"B (incorreta). Nas fronteiras com outros países, respeitam-se as normas que regem as RELAÇÕES INTERNACIONAIS, não as delimitações municipais. As demais reproduzem os arts. 4º, 6º e 7º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-832":{"cognitivo":{"motivo":"Treinar regiões — incorreta (fronteira) — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"ato conjunto dos estados"},"comentario":{"resolucao":"CERTO. É o § 1º do art. 4º. Quem institui é o conjunto dos ESTADOS, em articulação com os municípios — não os municípios sozinhos nem a União.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-833":{"cognitivo":{"motivo":"Treinar requisitos — I, II e IV — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"odontológica não é requisito"},"comentario":{"resolucao":"A (I, II e IV). Atenção odontológica não está entre os requisitos mínimos do art. 5º.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-834":{"cognitivo":{"motivo":"Treinar cOAP — exceto (privados) — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"investimentos sem prioridade privada"},"comentario":{"resolucao":"D (exceto). O COAP prevê investimentos na rede e respectivas responsabilidades, e recursos financeiros de cada partícipe; não determina manter investimentos 'prioritariamente para os serviços privados'.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-835":{"cognitivo":{"motivo":"Treinar regiões interestaduais — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"municípios limítrofes"},"comentario":{"resolucao":"B. Municípios limítrofes, por ato conjunto dos respectivos estados em articulação com os municípios (art. 4º, § 1º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-836":{"cognitivo":{"motivo":"Treinar regiões interestaduais — redação — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"interestaduais, limítrofes, ato dos estados"},"comentario":{"resolucao":"B. A redação correta combina três elementos: regiões INTERESTADUAIS, municípios LIMÍTROFES e ato conjunto dos ESTADOS. As demais trocam um deles.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-837":{"cognitivo":{"motivo":"Treinar definição — Mapa da Saúde — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"descrição geográfica"},"comentario":{"resolucao":"D. Mapa da Saúde é a descrição geográfica da distribuição de recursos humanos e de ações e serviços ofertados pelo SUS e pela iniciativa privada. A é Porta de Entrada; B, Região de Saúde; C, COAP.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-838":{"cognitivo":{"motivo":"Treinar regiões — referência — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"transferências de recursos"},"comentario":{"resolucao":"B. As Regiões de Saúde serão referência para as transferências de recursos entre os entes federativos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-839":{"cognitivo":{"motivo":"Treinar humanização e metas — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"Contrato Organizativo"},"comentario":{"resolucao":"C. A humanização do atendimento do usuário será fator determinante para o estabelecimento das metas de saúde previstas no Contrato Organizativo de Ação Pública de Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-840":{"cognitivo":{"motivo":"Treinar humanização e metas — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"humanização e metas"},"comentario":{"resolucao":"CERTO. Previsão do decreto no capítulo do COAP, que também autoriza o Ministério da Saúde a instituir incentivos ao cumprimento das metas.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-841":{"cognitivo":{"motivo":"Treinar decreto 7.508 — o que faz — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"RAS, Mapa da Saúde e regionalização"},"comentario":{"resolucao":"B. O decreto organiza a Rede de Atenção à Saúde, institui o Mapa da Saúde e regulamenta a regionalização. Ele não substitui a Lei 8.080 (é regulamento), não cria conselhos (Lei 8.142) e não trata só de repasses.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-842":{"cognitivo":{"motivo":"Treinar atendimento inicial — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"Portas de Entrada"},"comentario":{"resolucao":"B. Portas de Entrada (art. 2º, III).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-843":{"cognitivo":{"motivo":"Treinar o que o decreto estabelece — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"articulação da atenção básica"},"comentario":{"resolucao":"C. Entre as alternativas, a única relacionada ao decreto é a organização da atenção básica — porta de entrada e ordenadora do acesso — e sua articulação com os demais níveis na rede. Planos privados, reforma financeira e criação de hospitais não são seu objeto.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-844":{"cognitivo":{"motivo":"Treinar atribuições do art. 13 — exceto — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"monitoramento não é exclusivo do MS"},"comentario":{"resolucao":"D (exceto). Cabe aos ENTES federativos, além de outras atribuições pactuadas, garantir transparência, integralidade e equidade no acesso; orientar e ordenar os fluxos; MONITORAR o acesso; e ofertar regionalmente as ações e serviços (art. 13). O monitoramento não é exclusivo do Ministério.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-845":{"cognitivo":{"motivo":"Treinar atribuições do art. 13 — exceto — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"cabe aos entes federativos"},"comentario":{"resolucao":"CERTO. São atribuições do art. 13, de todos os entes — e não só do Ministério da Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-846":{"cognitivo":{"motivo":"Treinar requisitos — exceto — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"atenção exclusivamente particular"},"comentario":{"resolucao":"D (exceto). 'Atenção exclusivamente particular' não é requisito da Região de Saúde; os cinco requisitos são de ações e serviços do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-847":{"cognitivo":{"motivo":"Treinar serviços Especiais de Acesso Aberto — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"agravo ou situação laboral"},"comentario":{"resolucao":"D. Serviços especiais de acesso aberto são serviços de saúde específicos para o atendimento da pessoa que, em razão de agravo ou de situação laboral, necessita de atendimento especial (art. 2º, IV). A é Região de Saúde; B, COAP; C, Porta de Entrada.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-848":{"cognitivo":{"motivo":"Treinar serviços Especiais de Acesso Aberto — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"agravo ou situação laboral"},"comentario":{"resolucao":"ERRADO. São serviços específicos para quem, em razão de AGRAVO ou de SITUAÇÃO LABORAL, necessita de atendimento especial (art. 2º, IV) — por exemplo, centros de referência em saúde do trabalhador e serviços de IST/HIV. E são portas de entrada, de acesso ABERTO, sem autorização prévia.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-849":{"cognitivo":{"motivo":"Treinar mapa da Saúde — finalidade — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"necessidades e oferta no território"},"comentario":{"resolucao":"D. O Mapa da Saúde identifica as necessidades de saúde e a oferta de ações e serviços em determinado território, orientando o planejamento integrado dos entes (art. 17). Ele não define recursos da União, não é elaborado só pelo Ministério e não é cadastro individual.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-850":{"cognitivo":{"motivo":"Treinar cOAP — incorreta (recursos) — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"recursos de cada partícipe"},"comentario":{"resolucao":"D (incorreta). O COAP prevê os recursos financeiros que serão disponibilizados por CADA UM dos partícipes, e investimentos com respectivas responsabilidades; não reserva à União o investimento nem atribui a manutenção só aos municípios.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-851":{"cognitivo":{"motivo":"Treinar portas de Entrada — todos — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"quatro portas"},"comentario":{"resolucao":"E. Atenção primária, especiais de acesso aberto, atenção psicossocial e urgência e emergência — as quatro Portas de Entrada (art. 9º).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-852":{"cognitivo":{"motivo":"Treinar descrição geográfica — nome — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"Mapa da Saúde"},"comentario":{"resolucao":"A. É o Mapa da Saúde (art. 2º, V).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-853":{"cognitivo":{"motivo":"Treinar definição — Mapa da Saúde (2) — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"Mapa da Saúde"},"comentario":{"resolucao":"C. Mapa da Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-854":{"cognitivo":{"motivo":"Treinar região de Saúde — definição — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"região de saúde"},"comentario":{"resolucao":"D. A descrição (agrupamento de municípios com os cinco grupos de serviços mínimos) é da REGIÃO DE SAÚDE.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-855":{"cognitivo":{"motivo":"Treinar portas de Entrada — incorreta — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"alta complexidade é referenciada"},"comentario":{"resolucao":"D (incorreta). Atenção hospitalar de alta complexidade não é Porta de Entrada: é referenciada a partir delas (art. 10).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-856":{"cognitivo":{"motivo":"Treinar informação aos órgãos de controle — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"todos os itens"},"comentario":{"resolucao":"D. O Ministério da Saúde informará aos órgãos de controle interno e externo, entre outros, o descumprimento injustificado de responsabilidades, a não apresentação do Relatório de Gestão, a não aplicação, malversação ou desvio de recursos e outros atos ilícitos de que tiver conhecimento.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-857":{"cognitivo":{"motivo":"Treinar informação aos órgãos de controle — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"órgãos de controle"},"comentario":{"resolucao":"CERTO. São hipóteses expressas do decreto, ao lado do descumprimento injustificado de responsabilidades e de outros atos ilícitos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Decreto 7.508: região → portas de entrada → rede → COAP.","erroComum":"Trocar números, listas e instâncias do decreto.","comoBancaPensa":"Literalidade do Decreto 7.508."}},"SUS-858":{"cognitivo":{"motivo":"Treinar comissão Intergestores Regional — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"CIR vinculada à SES"},"comentario":{"resolucao":"CERTO. São três as comissões: CIT (União, vinculada ao Ministério), CIB (estado, vinculada à SES) e CIR (região de saúde, vinculada à SES), esta última criada pelo decreto.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"CIT nacional; CIB estadual; CIR regional.","erroComum":"Esquecer a CIR ou vinculá-la ao Ministério.","comoBancaPensa":"Instância criada pelo decreto."}},"SUS-859":{"cognitivo":{"motivo":"Treinar comissões Intergestores — natureza — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"pactuação consensual"},"comentario":{"resolucao":"ERRADO. São instâncias de PACTUAÇÃO CONSENSUAL entre os entes federativos para definir as regras da gestão compartilhada do SUS (art. 2º, IV). Não votam por maioria, nem vinculam os conselhos, que exercem o controle social.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Comissão intergestores = consenso entre gestores.","erroComum":"Trocar consenso por maioria.","comoBancaPensa":"Natureza da instância."}},"SUS-860":{"cognitivo":{"motivo":"Treinar cOAP — fundamento — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"integração dos planos de saúde"},"comentario":{"resolucao":"CERTO. É o art. 34. O COAP define responsabilidades individuais e solidárias, indicadores, metas, critérios de avaliação e recursos financeiros dos entes de uma Região de Saúde.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"COAP = planos de saúde integrados + pactuação da CIT.","erroComum":"Achar que o COAP é contrato com prestadores privados.","comoBancaPensa":"Fundamento do contrato."}},"SUS-861":{"cognitivo":{"motivo":"Treinar cOAP — partes — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"entre entes federativos"},"comentario":{"resolucao":"ERRADO. O COAP é acordo de colaboração firmado entre ENTES FEDERATIVOS (art. 2º, II) para organizar e integrar as ações e serviços na rede regionalizada e hierarquizada. A contratação de privados é outro instrumento (contrato ou convênio, Lei 8.080, art. 24).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"COAP: entes públicos entre si.","erroComum":"Confundir com contrato de prestação.","comoBancaPensa":"Partes trocadas."}},"SUS-862":{"cognitivo":{"motivo":"Treinar requisitos do acesso à assistência farmacêutica — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"assistido por ações do SUS"},"comentario":{"resolucao":"CERTO. É o art. 28, que também exige prescrição conforme a RENAME e os PCDT (ou relação complementar) e dispensação em unidades indicadas pela direção do SUS.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Farmácia do SUS: usuário do SUS + prescritor do SUS + RENAME/PCDT + unidade indicada.","erroComum":"Achar que basta qualquer receita.","comoBancaPensa":"Requisitos cumulativos."}},"SUS-863":{"cognitivo":{"motivo":"Treinar rENAME — registro na Anvisa — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"registro na Anvisa"},"comentario":{"resolucao":"ERRADO. O decreto determina que a RENAME e as relações complementares SOMENTE poderão conter produtos com registro na Anvisa. A pactuação intergestores não supre o registro sanitário.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Relação de medicamentos: só com registro na Anvisa.","erroComum":"Achar que a pactuação dispensa registro.","comoBancaPensa":"Exceção inventada."}},"SUS-864":{"cognitivo":{"motivo":"Treinar quem institui a Região de Saúde — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"Estado em articulação com os Municípios"},"comentario":{"resolucao":"CERTO. É o caput do art. 4º. As regiões interestaduais exigem ato conjunto dos estados envolvidos.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Região: estado + municípios, diretrizes da CIT.","erroComum":"Atribuir à União ou só aos municípios.","comoBancaPensa":"Sujeito da instituição."}},"SUS-865":{"cognitivo":{"motivo":"Treinar acesso ordenado — onde se inicia — ponto de portas de Entrada e acesso (Decreto 7.508, arts. 8º a 14) que a banca transforma em item.","palavraCritica":"inicia-se pelas Portas de Entrada"},"comentario":{"resolucao":"ERRADO. O art. 8º diz o inverso: o acesso se INICIA pelas Portas de Entrada do SUS e se COMPLETA na rede regionalizada e hierarquizada, de acordo com a complexidade do serviço.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Entrada pelas portas → completa na rede.","erroComum":"Inverter o fluxo.","comoBancaPensa":"Ordem invertida."}},"SUS-866":{"cognitivo":{"motivo":"Treinar delimitação da Região de Saúde — ponto de regiões de Saúde (Decreto 7.508, arts. 4º a 7º) que a banca transforma em item.","palavraCritica":"identidades culturais, econômicas e sociais"},"comentario":{"resolucao":"ERRADO. A Região é instituída pelo ESTADO em articulação com os municípios (art. 4º) e delimitada a partir de identidades culturais, econômicas e sociais e de redes de comunicação e transportes compartilhados (art. 2º, I). O decreto não fixa piso populacional nem exige hospital de alta complexidade.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Região: estado + municípios; critérios de identidade e infraestrutura.","erroComum":"Inventar piso populacional.","comoBancaPensa":"Requisitos inventados."}},"SUS-867":{"cognitivo":{"motivo":"Treinar planejamento — sentido — ponto de planejamento e Mapa da Saúde (Decreto 7.508, arts. 15 a 19) que a banca transforma em item.","palavraCritica":"ascendente e integrado"},"comentario":{"resolucao":"ERRADO. O art. 15 define o planejamento como ASCENDENTE e integrado, do nível local até o federal, ouvidos os conselhos de saúde, que são instâncias deliberativas — o mesmo comando do art. 36 da Lei 8.080.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Planejamento: de baixo para cima.","erroComum":"Inverter o sentido.","comoBancaPensa":"Sentido trocado."}},"SUS-868":{"cognitivo":{"motivo":"Treinar rENASES — atualização e relações complementares — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"dois anos; relações complementares"},"comentario":{"resolucao":"ERRADO. Quem consolida e publica as atualizações é o MINISTÉRIO DA SAÚDE, a cada DOIS anos (art. 22), e estados, DF e municípios PODEM adotar relações específicas e complementares de ações e serviços, em consonância com a RENASES (art. 24).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"RENASES: MS, a cada 2 anos; relações complementares permitidas.","erroComum":"Trocar órgão, prazo e vedar complementos.","comoBancaPensa":"Tripla troca."}},"SUS-869":{"cognitivo":{"motivo":"Treinar rede de Atenção à Saúde — definição — ponto de definições e organização do SUS (Decreto 7.508, arts. 2º e 3º) que a banca transforma em item.","palavraCritica":"níveis de complexidade crescente"},"comentario":{"resolucao":"ERRADO. A RAS é o conjunto de ações e serviços de saúde articulados em níveis de complexidade CRESCENTE, com a finalidade de garantir a integralidade da assistência (art. 2º, VI) — inclui a atenção primária, que ordena o acesso (art. 11).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"RAS: todos os níveis articulados, a partir da APS.","erroComum":"Reduzir a rede ao hospital.","comoBancaPensa":"Definição deformada."}},"SUS-870":{"cognitivo":{"motivo":"Treinar cIT × CIB — atribuições — ponto de comissões Intergestores e COAP (Decreto 7.508, arts. 30 a 41) que a banca transforma em item.","palavraCritica":"CIB pactua o planejamento municipal"},"comentario":{"resolucao":"ERRADO. Inverteu as comissões: diretrizes de âmbito nacional são pactuadas na CIT, e as etapas e prazos do planejamento municipal, em consonância com os planejamentos estadual e nacional, são pactuados na CIB (art. 19).","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"Nacional → CIT; planejamento municipal → CIB.","erroComum":"Inverter as comissões.","comoBancaPensa":"Troca de instância."}},"SUS-871":{"cognitivo":{"motivo":"Treinar protocolo Clínico e Diretriz Terapêutica — ponto de rENASES e RENAME (Decreto 7.508, arts. 20 a 29) que a banca transforma em item.","palavraCritica":"documento a ser seguido pelos gestores"},"comentario":{"resolucao":"ERRADO. O PCDT é o documento que estabelece critérios para o diagnóstico da doença ou do agravo, o tratamento preconizado, com medicamentos e produtos apropriados, posologias, mecanismos de controle clínico e de acompanhamento e verificação dos resultados, a ser seguido pelos GESTORES do SUS (art. 2º, VIII). Não é bula nem documento do fabricante.","fundamento":"Edital SESAU-AL, Legislação Aplicada ao SUS, item 5 — Decreto nº 7.508/2011 (regulamenta a Lei nº 8.080/1990). Base: Estratégia, Legislação SUS, Aula 08.","macete":"PCDT: diagnóstico + tratamento + acompanhamento, para os gestores.","erroComum":"Confundir PCDT com bula.","comoBancaPensa":"Definição trocada."}}});
